public class ChangeDamageMultiplierAfterDistanceTravelled : MonoBehaviour
{
	public float muiltiplier = 2f;

	public float distance = 10f;

	private ProjectileHit hit;

	private MoveTransform move;

	private TrailRenderer trail;

	private void Awake()
	{
		trail = GetComponentInChildren<TrailRenderer>();
	}

	private void Start()
	{
		hit = GetComponent<ProjectileHit>();
		move = GetComponent<MoveTransform>();
	}

	private void Update()
	{
		if (move.distanceTravelled > distance)
		{
			hit.damage *= muiltiplier;
			hit.shake *= muiltiplier;
			if ((bool)trail)
			{
				trail.widthMultiplier *= 2f;
			}
			UnityEngine.Object.Destroy(this);
		}
	}
}
public class CharacterData : MonoBehaviour
{
	public Vector3 aimDirection;

	public List<CardInfo> currentCards;

	public float sinceGroundedMultiplierWhenWallGrab = 0.2f;

	public PlayerActions playerActions;

	public ParticleSystem[] landParts;

	public int jumps = 1;

	public int currentJumps = 1;

	public bool isPlaying;

	public bool dead;

	public bool isStunned;

	public bool isSilenced;

	public float stunTime;

	public float silenceTime;

	public float health = 100f;

	public float maxHealth = 100f;

	public AnimationCurve slamCurve;

	public Vector3 wallPos;

	public Vector2 wallNormal;

	public Vector3 groundPos;

	public Transform hand;

	public float sinceWallGrab = float.PositiveInfinity;

	public bool isWallGrab;

	public float wallDistance = 1f;

	private bool wasWallGrabLastFrame;

	public float sinceGrounded;

	public bool isGrounded = true;

	private bool wasGroundedLastFrame = true;

	public Player player;

	public float sinceJump = 1f;

	public PlayerVelocity playerVel;

	public HealthHandler healthHandler;

	public GeneralInput input;

	public PlayerMovement movement;

	public PlayerJump jump;

	public Block block;

	public CharacterStatModifiers stats;

	public WeaponHandler weaponHandler;

	public StunHandler stunHandler;

	public SilenceHandler silenceHandler;

	public Player lastSourceOfDamage;

	public Player master;

	public Player lastDamagedPlayer;

	public Collider2D mainCol;

	public PlayerSounds playerSounds;

	private Transform wobblePos;

	private LayerMask groundMask;

	public PhotonView view;

	private CrownPos crownPos;

	public Rigidbody2D standOnRig;

	public Action<float, Vector3, Vector3, Transform> TouchGroundAction;

	public Action<float, Vector3, Vector3> TouchWallAction;

	public float HealthPercentage
	{
		get
		{
			return health / maxHealth;
		}
		internal set
		{
		}
	}

	private void Awake()
	{
		crownPos = GetComponentInChildren<CrownPos>();
		view = GetComponent<PhotonView>();
		mainCol = GetComponent<Collider2D>();
		wobblePos = GetComponentInChildren<PlayerWobblePosition>().transform;
		stats = GetComponent<CharacterStatModifiers>();
		player = GetComponent<Player>();
		weaponHandler = GetComponent<WeaponHandler>();
		block = GetComponent<Block>();
		input = GetComponent<GeneralInput>();
		movement = GetComponent<PlayerMovement>();
		jump = GetComponent<PlayerJump>();
		stunHandler = GetComponent<StunHandler>();
		silenceHandler = GetComponent<SilenceHandler>();
		hand = GetComponentInChildren<HandPos>().transform;
		playerVel = GetComponent<PlayerVelocity>();
		healthHandler = GetComponent<HealthHandler>();
		playerSounds = GetComponent<PlayerSounds>();
	}

	internal Vector3 GetCrownPos()
	{
		if ((bool)crownPos)
		{
			return crownPos.transform.position + Vector3.up * crownPos.GetOffset();
		}
		Debug.LogError("NO CROWN POS!?");
		return Vector3.up * 1000f;
	}

	private void Start()
	{
		groundMask = LayerMask.GetMask("Default");
		if (!view.IsMine)
		{
			PlayerManager.RegisterPlayer(player);
		}
	}

	private void Update()
	{
		if (!playerVel.simulated)
		{
			sinceGrounded = 0f;
		}
		sinceJump += TimeHandler.deltaTime;
		Wall();
	}

	private void FixedUpdate()
	{
		Ground();
	}

	private void Ground()
	{
		if (!isPlaying)
		{
			return;
		}
		if (!isGrounded)
		{
			sinceGrounded += TimeHandler.fixedDeltaTime * ((isWallGrab && wallDistance < 0.7f) ? sinceGroundedMultiplierWhenWallGrab : 1f);
			if (sinceGrounded < 0f)
			{
				sinceGrounded = Mathf.Lerp(sinceGrounded, 0f, TimeHandler.fixedDeltaTime * 15f);
			}
		}
		if (!wasGroundedLastFrame)
		{
			isGrounded = false;
		}
		wasGroundedLastFrame = false;
	}

	private void Wall()
	{
		if (!isWallGrab)
		{
			sinceWallGrab += TimeHandler.deltaTime;
		}
		if (!wasWallGrabLastFrame)
		{
			isWallGrab = false;
		}
		wasWallGrabLastFrame = false;
	}

	public void TouchGround(Vector3 pos, Vector3 groundNormal, Rigidbody2D groundRig, Transform groundTransform = null)
	{
		if (sinceJump > 0.2f)
		{
			currentJumps = jumps;
		}
		if (TouchGroundAction != null)
		{
			TouchGroundAction(sinceGrounded, pos, groundNormal, groundTransform);
		}
		if (groundRig == null)
		{
			standOnRig = null;
		}
		else if (!groundRig.GetComponent<NetworkPhysicsObject>())
		{
			standOnRig = groundRig;
		}
		if (playerVel.velocity.y < -20f && !isGrounded)
		{
			for (int i = 0; i < landParts.Length; i++)
			{
				landParts[i].transform.localScale = Vector3.one * Mathf.Clamp((0f - playerVel.velocity.y) / 40f, 0.5f, 1f) * 0.5f;
				landParts[i].transform.position = new Vector3(base.transform.position.x + playerVel.velocity.x * 0.03f, pos.y, 5f);
				landParts[i].transform.rotation = Quaternion.LookRotation(groundNormal);
				landParts[i].Play();
			}
			GamefeelManager.instance.AddGameFeel(Vector2.down * Mathf.Clamp((sinceGrounded - 0.5f) * 1f, 0f, 4f));
		}
		groundPos = pos;
		wasGroundedLastFrame = true;
		isGrounded = true;
		sinceGrounded = 0f;
	}

	public void TouchWall(Vector2 normal, Vector3 pos)
	{
		if (isGrounded)
		{
			return;
		}
		wallNormal = normal;
		wallPos = pos;
		groundPos = pos;
		wallDistance = Vector2.Distance(base.transform.position, pos);
		if (!(sinceJump < 0.15f))
		{
			currentJumps = jumps;
			if (TouchWallAction != null)
			{
				TouchWallAction(sinceWallGrab, pos, normal);
			}
			_ = sinceWallGrab;
			_ = 0.15f;
			sinceWallGrab = 0f;
			wasWallGrabLastFrame = true;
			isWallGrab = true;
		}
	}

	public bool ThereIsGroundBelow(Vector3 pos, float range = 5f)
	{
		RaycastHit2D raycastHit2D = Physics2D.Raycast(pos, Vector2.down, range, groundMask);
		if ((bool)raycastHit2D.transform && raycastHit2D.distance > 0.1f)
		{
			return true;
		}
		return false;
	}

	public void SetAI(Player aiMaster = null)
	{
		master = aiMaster;
		input.controlledElseWhere = true;
		GetComponent<PlayerAPI>().enabled = true;
	}

	public void SetWobbleObjectChild(Transform obj)
	{
		obj.transform.SetParent(wobblePos, worldPositionStays: true);
	}
}
public class CharacterStatModifiers : MonoBehaviour
{
	[Header("Sounds")]
	public SoundEvent soundCharacterSlowFreeze;

	private float soundSlowTime;

	private float soundSlowSpeedSec = 0.3f;

	[Header("Settings")]
	public GameObject AddObjectToPlayer;

	[HideInInspector]
	public List<GameObject> objectsAddedToPlayer;

	[Header("Multiply")]
	public float sizeMultiplier = 1f;

	public float health = 1f;

	public float movementSpeed = 1f;

	public float jump = 1f;

	public float gravity = 1f;

	public float slow;

	public float slowSlow;

	public float fastSlow;

	[Header("Add")]
	public float secondsToTakeDamageOver;

	public int numberOfJumps;

	public float regen;

	public float lifeSteal;

	public bool refreshOnDamage;

	public bool automaticReload = true;

	public int respawns;

	[HideInInspector]
	public int remainingRespawns;

	[HideInInspector]
	public float tasteOfBloodSpeed = 1f;

	[HideInInspector]
	public float rageSpeed = 1f;

	public float attackSpeedMultiplier = 1f;

	private WasDealtDamageEffect[] wasDealtDamageEffects;

	private DealtDamageEffect[] dealtDamageEffects;

	private CharacterData data;

	public ParticleSystem slowPart;

	private float soundBigThreshold = 1.5f;

	public Action<Vector2, bool> DealtDamageAction;

	public Action<Vector2, bool> WasDealtDamageAction;

	public Action<int> OnReloadDoneAction;

	public Action<int> OutOfAmmpAction;

	internal float sinceDealtDamage;

	public bool SoundTransformScaleThresholdReached()
	{
		if (base.transform.localScale.x > soundBigThreshold)
		{
			return true;
		}
		return false;
	}

	private void Start()
	{
		data = GetComponent<CharacterData>();
	}

	public float GetSlow()
	{
		return Mathf.Clamp(slow, 0f, 0.9f);
	}

	private void Update()
	{
		attackSpeedMultiplier = tasteOfBloodSpeed * rageSpeed;
		sinceDealtDamage += TimeHandler.deltaTime;
		if ((bool)data && !data.isPlaying)
		{
			sinceDealtDamage = 100f;
		}
		slow = slowSlow;
		if (fastSlow > slowSlow)
		{
			slow = fastSlow;
		}
		if (slowSlow > 0f)
		{
			slowSlow = Mathf.Clamp(slowSlow - TimeHandler.deltaTime * 0.3f, 0f, 10f);
		}
		if (fastSlow > 0f)
		{
			fastSlow = Mathf.Clamp(fastSlow - TimeHandler.deltaTime * 2f, 0f, 1f);
		}
	}

	public void DealtDamage(Vector2 damage, bool selfDamage, Player damagedPlayer = null)
	{
		if (lifeSteal != 0f && !selfDamage)
		{
			GetComponent<HealthHandler>().Heal(damage.magnitude * lifeSteal);
		}
		if (refreshOnDamage)
		{
			GetComponent<Holding>().holdable.GetComponent<Weapon>().sinceAttack = float.PositiveInfinity;
		}
		if (DealtDamageAction != null)
		{
			DealtDamageAction(damage, selfDamage);
		}
		if ((bool)damagedPlayer)
		{
			data.lastDamagedPlayer = damagedPlayer;
		}
		if (!selfDamage)
		{
			sinceDealtDamage = 0f;
		}
		if (dealtDamageEffects != null)
		{
			for (int i = 0; i < dealtDamageEffects.Length; i++)
			{
				dealtDamageEffects[i].DealtDamage(damage, selfDamage, damagedPlayer);
			}
		}
	}

	internal void ResetStats()
	{
		for (int i = 0; i < objectsAddedToPlayer.Count; i++)
		{
			UnityEngine.Object.Destroy(objectsAddedToPlayer[i]);
		}
		objectsAddedToPlayer.Clear();
		data.health = 100f;
		data.maxHealth = 100f;
		sizeMultiplier = 1f;
		health = 1f;
		movementSpeed = 1f;
		jump = 1f;
		gravity = 1f;
		slow = 0f;
		slowSlow = 0f;
		fastSlow = 0f;
		secondsToTakeDamageOver = 0f;
		numberOfJumps = 0;
		regen = 0f;
		lifeSteal = 0f;
		respawns = 0;
		refreshOnDamage = false;
		automaticReload = true;
		tasteOfBloodSpeed = 1f;
		rageSpeed = 1f;
		attackSpeedMultiplier = 1f;
		WasUpdated();
		ConfigureMassAndSize();
	}

	public void WasDealtDamage(Vector2 damage, bool selfDamage)
	{
		if (WasDealtDamageAction != null)
		{
			WasDealtDamageAction(damage, selfDamage);
		}
		if (wasDealtDamageEffects != null)
		{
			for (int i = 0; i < wasDealtDamageEffects.Length; i++)
			{
				wasDealtDamageEffects[i].WasDealtDamage(damage, selfDamage);
			}
		}
	}

	public void WasUpdated()
	{
		GetComponent<ForceMultiplier>().multiplier = 1f / base.transform.root.localScale.x;
		wasDealtDamageEffects = GetComponentsInChildren<WasDealtDamageEffect>();
		dealtDamageEffects = GetComponentsInChildren<DealtDamageEffect>();
	}

	public void AddSlowAddative(float slowToAdd, float maxValue = 1f, bool isFastSlow = false)
	{
		if (data.block.IsBlocking())
		{
			return;
		}
		DoSlowDown(slowToAdd);
		if (isFastSlow)
		{
			if (fastSlow < maxValue)
			{
				fastSlow += slowToAdd;
				fastSlow = Mathf.Clamp(slow, 0f, maxValue);
			}
		}
		else if (slowSlow < maxValue)
		{
			slowSlow += slowToAdd;
			slowSlow = Mathf.Clamp(slowSlow, 0f, maxValue);
		}
	}

	[PunRPC]
	public void RPCA_AddSlow(float slowToAdd, bool isFastSlow = false)
	{
		DoSlowDown(slowToAdd);
		if (isFastSlow)
		{
			fastSlow = Mathf.Clamp(fastSlow, slowToAdd, 1f);
		}
		else
		{
			slowSlow = Mathf.Clamp(slowSlow, slowToAdd, 10f);
		}
	}

	private void DoSlowDown(float newSlow)
	{
		if (soundSlowTime + soundSlowSpeedSec < Time.time)
		{
			soundSlowTime = Time.time;
			SoundManager.Instance.Play(soundCharacterSlowFreeze, base.transform);
		}
		float num = Mathf.Clamp(newSlow - slow, 0f, 1f);
		slowPart.Emit((int)Mathf.Clamp((newSlow * 0.1f + num * 0.7f) * 50f, 1f, 50f));
		data.playerVel.velocity *= 1f - num * 1f;
		data.sinceGrounded *= 1f - num * 1f;
	}

	internal void ConfigureMassAndSize()
	{
		base.transform.localScale = Vector3.one * 1.2f * Mathf.Pow(data.maxHealth / 100f * 1.2f, 0.2f) * sizeMultiplier;
		data.playerVel.mass = 100f * Mathf.Pow(data.maxHealth / 100f * 1.2f, 0.8f) * sizeMultiplier;
	}

	internal void OnReload(int bulletsReloaded)
	{
		if (OnReloadDoneAction != null)
		{
			OnReloadDoneAction(bulletsReloaded);
		}
	}

	internal void OnOutOfAmmp(int maxAmmo)
	{
		if (OutOfAmmpAction != null)
		{
			OutOfAmmpAction(maxAmmo);
		}
	}
}
public class ChargeFeedback : MonoBehaviour
{
	private Gun gun;

	public float drag = 1f;

	public float spring = 1f;

	public float angle = 45f;

	public float chargeAngle = 15f;

	private float currentAngle;

	private float velocity;

	public float charge;

	private void Start()
	{
		gun = GetComponentInParent<Gun>();
		gun.AddAttackAction(Shoot);
	}

	private void Update()
	{
		charge = 0f;
		if (!gun.IsReady(0.15f))
		{
			charge = 1f;
		}
		velocity += (charge * chargeAngle - currentAngle) * CappedDeltaTime.time * spring;
		velocity -= velocity * CappedDeltaTime.time * drag;
		currentAngle += CappedDeltaTime.time * velocity;
		base.transform.localEulerAngles = new Vector3(currentAngle, 0f, 0f);
	}

	public void Shoot()
	{
		velocity += (0f - angle) * 1000f * (gun.damage / 55f);
	}
}
public class ChomaticAberrationFeeler : GameFeeler
{
	public float force = 10f;

	public float damper = 0.95f;

	public float damperSpring = 0.95f;

	public float threshold;

	private PostProcessVolume postProcessVolume;

	private ChromaticAberration chromaticAberration;

	private float intensity;

	private float velocity;

	private float targetIntensity;

	public override void OnAwake()
	{
		postProcessVolume = GetComponent<PostProcessVolume>();
		if (!postProcessVolume.profile.TryGetSettings<ChromaticAberration>(out chromaticAberration))
		{
			Debug.LogError("No ChromaticAberration in post!");
		}
		else
		{
			targetIntensity = chromaticAberration.intensity.value;
		}
	}

	public override void OnGameFeel(Vector2 feelDirection)
	{
		feelDirection = Vector2.ClampMagnitude(feelDirection, 50f);
		if (feelDirection.magnitude < threshold)
		{
			feelDirection = feelDirection.normalized * threshold * 0.3f;
		}
		velocity += feelDirection.sqrMagnitude * 0.2f * force;
	}

	private void Update()
	{
		velocity *= damper;
		intensity *= damperSpring;
		intensity += velocity * Mathf.Clamp(TimeHandler.deltaTime, 0f, 0.02f);
		chromaticAberration.intensity.value = intensity + targetIntensity;
	}

	private void FixedUpdate()
	{
		intensity *= 0.9f;
	}

	public override void OnUIGameFeel(Vector2 feelDirection)
	{
	}
}
public class Cluster : MonoBehaviour
{
	public float distanceToTravel = 8f;

	public float spread;

	public float velocitySpread;

	public int clusters = 3;

	private MoveTransform move;

	private void Start()
	{
		move = GetComponentInParent<MoveTransform>();
	}

	private void Update()
	{
		if (!(move.distanceTravelled > distanceToTravel))
		{
			return;
		}
		for (int i = 0; i < clusters; i++)
		{
			GameObject obj = UnityEngine.Object.Instantiate(base.transform.root.gameObject, base.transform.root.position, base.transform.root.rotation);
			Cluster componentInChildren = obj.GetComponentInChildren<Cluster>();
			if ((bool)componentInChildren)
			{
				UnityEngine.Object.Destroy(componentInChildren);
			}
			MoveTransform component = obj.GetComponent<MoveTransform>();
			if ((bool)component)
			{
				component.DontRunStart = true;
				component.velocity = base.transform.root.GetComponent<MoveTransform>().velocity;
				component.multiplier = base.transform.root.GetComponent<MoveTransform>().multiplier;
				component.velocity += base.transform.right * UnityEngine.Random.Range(0f - spread, spread);
				component.velocity *= UnityEngine.Random.Range(1f - velocitySpread * 0.01f, 1f + velocitySpread * 0.01f);
			}
		}
		UnityEngine.Object.Destroy(this);
	}
}
