public enum CurveAnimationUse
{
	In,
	Out,
	Boop
}
public enum CurveAnimationType
{
	Scale,
	Position,
	RectPosition,
	Rotation
}
[Serializable]
public class CurveAnimationInstance
{
	[FoldoutGroup("$animationUse", 0)]
	public CurveAnimationType animationType;

	[FoldoutGroup("$animationUse", 0)]
	public CurveAnimationUse animationUse;

	[ShowIf("animationUse", CurveAnimationUse.In, true)]
	[FoldoutGroup("$animationUse", 0)]
	public AnimationCurve inCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	[ShowIf("animationUse", CurveAnimationUse.Out, true)]
	[FoldoutGroup("$animationUse", 0)]
	public AnimationCurve outCurve = AnimationCurve.Linear(0f, 1f, 1f, 0f);

	[ShowIf("animationUse", CurveAnimationUse.Boop, true)]
	[FoldoutGroup("$animationUse", 0)]
	public AnimationCurve boopCurve = AnimationCurve.Linear(0f, 1f, 1f, 1f);

	[HideIf("animationType", CurveAnimationType.Scale, true)]
	[FoldoutGroup("$animationUse", 0)]
	public Vector3 animDirection;

	[FoldoutGroup("$animationUse/Settings", 0)]
	public bool loop;

	[FoldoutGroup("$animationUse/Settings", 0)]
	public bool playOnAwake;

	[FoldoutGroup("$animationUse/Settings", 0)]
	public float speed = 1f;

	[FoldoutGroup("$animationUse/Settings", 0)]
	public float multiplier = 1f;

	[FoldoutGroup("$animationUse/Events", 0)]
	public UnityEvent statEvent;

	[FoldoutGroup("$animationUse/Events", 0)]
	public UnityEvent endEvent;

	[FoldoutGroup("$animationUse/Events", 0)]
	public UnityEvent delayedEvent;

	[FoldoutGroup("$animationUse/Events", 0)]
	public float delay;

	[FoldoutGroup("$animationUse/Debug", 0, Order = 0, Expanded = false)]
	public bool isPlaying;

	[HideInInspector]
	public Coroutine animation;

	public AnimationCurve Curve()
	{
		if (animationUse == CurveAnimationUse.Boop)
		{
			return boopCurve;
		}
		if (animationUse != CurveAnimationUse.In)
		{
			return outCurve;
		}
		return inCurve;
	}
}
public class CurveAnimation : MonoBehaviour
{
	[Header("Sound")]
	public SoundAnimationPlay[] soundPlay = new SoundAnimationPlay[0];

	[Header("Settings")]
	public CurveAnimationInstance[] animations;

	[HideInInspector]
	public Vector3 startScale;

	[HideInInspector]
	public Vector3 startLocalPos;

	[HideInInspector]
	public Vector3 startAnchoredPos;

	[HideInInspector]
	public Vector3 startRotation;

	public CurveAnimationUse currentState = CurveAnimationUse.Out;

	private RectTransform rectTransform;

	[FoldoutGroup("Global settings", 0)]
	public bool useTimeScale = true;

	[FoldoutGroup("Global settings", 0)]
	public bool X = true;

	[FoldoutGroup("Global settings", 0)]
	public bool Y = true;

	[FoldoutGroup("Global settings", 0)]
	public bool Z = true;

	[FoldoutGroup("Global settings", 0)]
	public bool stopAllAnimations;

	private bool inited;

	private void Init()
	{
		if (!inited)
		{
			startScale = base.transform.localScale;
			startLocalPos = base.transform.localScale;
			rectTransform = GetComponent<RectTransform>();
			if ((bool)rectTransform)
			{
				startAnchoredPos = rectTransform.anchoredPosition;
			}
			startRotation = base.transform.localEulerAngles;
		}
	}

	private void Awake()
	{
		Init();
	}

	private void OnDisable()
	{
		StopAllCoroutines();
		ResetAnimationState();
		for (int i = 0; i < animations.Length; i++)
		{
			animations[i].isPlaying = false;
		}
	}

	private void OnEnable()
	{
		ResetAnimationState();
		for (int i = 0; i < animations.Length; i++)
		{
			if (animations[i].playOnAwake)
			{
				PlayAnimation(animations[i]);
			}
		}
	}

	[Button]
	public void PlayIn()
	{
		PlayAnimationWithUse(CurveAnimationUse.In);
	}

	[Button]
	public void PlayOut()
	{
		PlayAnimationWithUse(CurveAnimationUse.Out);
	}

	[Button]
	public void PlayBoop()
	{
		PlayAnimationWithUse(CurveAnimationUse.Boop);
	}

	[Button]
	public void Stop()
	{
		StopAllCoroutines();
	}

	private void ResetAnimationState()
	{
		ApplyAnimationFrame(GetAnimationWithUse(CurveAnimationUse.In), 0f);
	}

	private CurveAnimationInstance GetAnimationWithUse(CurveAnimationUse use)
	{
		for (int i = 0; i < animations.Length; i++)
		{
			if (animations[i].animationUse == use)
			{
				return animations[i];
			}
		}
		return animations[0];
	}

	public void PlayAnimation(CurveAnimationInstance animation)
	{
		for (int i = 0; i < soundPlay.Length; i++)
		{
			if (soundPlay[i] != null)
			{
				soundPlay[i].soundHasPlayed = false;
			}
		}
		if (stopAllAnimations)
		{
			StopAllCoroutines();
		}
		if (animation.isPlaying && animation.animation != null)
		{
			StopCoroutine(animation.animation);
		}
		animation.animation = StartCoroutine(DoAnimation(animation));
	}

	public void PlayAnimationWithUse(CurveAnimationUse animationUse)
	{
		for (int i = 0; i < soundPlay.Length; i++)
		{
			if (soundPlay[i] != null)
			{
				soundPlay[i].soundHasPlayed = false;
			}
		}
		if (stopAllAnimations)
		{
			StopAllCoroutines();
		}
		currentState = animationUse;
		for (int j = 0; j < animations.Length; j++)
		{
			if (animations[j].animationUse == animationUse)
			{
				if (animations[j].isPlaying && animations[j].animation != null)
				{
					StopCoroutine(animations[j].animation);
				}
				animations[j].animation = StartCoroutine(DoAnimation(animations[j]));
			}
		}
	}

	private IEnumerator DoAnimation(CurveAnimationInstance animation)
	{
		StartCoroutine(DelayEvent(animation.delay / animation.speed, animation.delayedEvent));
		animation.statEvent.Invoke();
		animation.isPlaying = true;
		float c = 0f;
		float t = animation.Curve().keys[animation.Curve().keys.Length - 1].time;
		while (c < t)
		{
			c += (useTimeScale ? (TimeHandler.deltaTime * animation.speed) : (Time.unscaledDeltaTime * animation.speed));
			for (int i = 0; i < soundPlay.Length; i++)
			{
				if (soundPlay[i] != null && soundPlay[i].soundEvent != null && c >= soundPlay[i].soundDelay && animation.animationUse == soundPlay[i].curveAnimationUse && !soundPlay[i].soundHasPlayed && (bool)SoundManager.Instance)
				{
					soundPlay[i].soundHasPlayed = true;
					SoundManager.Instance.Play(soundPlay[i].soundEvent, base.transform);
				}
			}
			ApplyAnimationFrame(animation, c);
			yield return null;
		}
		ApplyAnimationFrame(animation, t);
		animation.isPlaying = false;
		animation.endEvent.Invoke();
		if (animation.loop)
		{
			PlayAnimationWithUse(animation.animationUse);
		}
	}

	private IEnumerator DelayEvent(float seconds, UnityEvent eventToCall)
	{
		yield return new WaitForSeconds(seconds);
		eventToCall.Invoke();
	}

	private void ApplyAnimationFrame(CurveAnimationInstance anim, float time)
	{
		if (anim.animationType == CurveAnimationType.Scale)
		{
			Vector3 vector = startScale * anim.Curve().Evaluate(time) * anim.multiplier;
			Vector3 localScale = new Vector3(X ? vector.x : base.transform.localScale.x, Y ? vector.y : base.transform.localScale.y, Z ? vector.z : base.transform.localScale.z);
			base.transform.localScale = localScale;
		}
		else if (anim.animationType == CurveAnimationType.Position)
		{
			base.transform.localPosition = startLocalPos + anim.animDirection * anim.Curve().Evaluate(time) * anim.multiplier;
		}
		else if (anim.animationType == CurveAnimationType.RectPosition)
		{
			rectTransform.anchoredPosition = startAnchoredPos + anim.animDirection * anim.Curve().Evaluate(time) * anim.multiplier;
		}
		else if (anim.animationType == CurveAnimationType.Rotation)
		{
			base.transform.localEulerAngles = startRotation + anim.animDirection * anim.Curve().Evaluate(time) * anim.multiplier;
		}
	}

	public bool IsPlaying()
	{
		bool result = false;
		for (int i = 0; i < animations.Length; i++)
		{
			if (animations[i].isPlaying)
			{
				result = true;
			}
		}
		return result;
	}
}
public abstract class Damagable : MonoBehaviour
{
	public abstract void CallTakeDamage(Vector2 damage, Vector2 damagePosition, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true);

	public abstract void TakeDamage(Vector2 damage, Vector2 damagePosition, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false);

	public abstract void TakeDamage(Vector2 damage, Vector2 damagePosition, Color dmgColor, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false);
}
public class DamagableEvent : Damagable
{
	public bool networkedDamage;

	public bool disabled;

	[HideInInspector]
	public bool dead;

	public float currentHP = 100f;

	public float regenDelay = 1f;

	public float regenPerSecond;

	[HideInInspector]
	public float maxHP = 100f;

	public UnityEvent damageEvent;

	public UnityEvent deathEvent;

	private float sinceDamage = 1f;

	[HideInInspector]
	public Player lastPlayer;

	[HideInInspector]
	public GameObject lastWeapon;

	private PhotonView view;

	public Action<Vector2> DieAction;

	private void Start()
	{
		view = GetComponent<PhotonView>();
		maxHP = currentHP;
	}

	public override void TakeDamage(Vector2 damage, Vector2 damagePosition, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false)
	{
		if (disabled || dead)
		{
			return;
		}
		if (networkedDamage)
		{
			if ((bool)damagingPlayer)
			{
				if (!damagingPlayer.data.view.IsMine)
				{
					return;
				}
				view.RPC("RPCA_TakeDamage", RpcTarget.Others, damage, damagePosition);
			}
			else
			{
				if (!view.IsMine)
				{
					return;
				}
				view.RPC("RPCA_TakeDamage", RpcTarget.Others, damage, damagePosition);
			}
		}
		DoDamage(damage, damagePosition, damagingWeapon, damagingPlayer, lethal, ignoreBlock);
	}

	[PunRPC]
	public void RPCA_TakeDamage(Vector2 damage, Vector2 damagePosition)
	{
		DoDamage(damage, damagePosition);
	}

	private void DoDamage(Vector2 damage, Vector2 damagePosition, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false)
	{
		if ((bool)damagingPlayer)
		{
			lastPlayer = damagingPlayer;
		}
		if ((bool)damagingWeapon)
		{
			lastWeapon = damagingWeapon;
		}
		sinceDamage = 0f;
		currentHP -= damage.magnitude;
		if (currentHP <= 0f)
		{
			Die(damage);
		}
		else
		{
			damageEvent.Invoke();
		}
	}

	private void Die(Vector2 damage = default(Vector2))
	{
		if (!dead && !disabled)
		{
			DieAction?.Invoke(damage);
			deathEvent.Invoke();
			dead = true;
		}
	}

	private void Update()
	{
		if (!dead && !disabled)
		{
			sinceDamage += TimeHandler.deltaTime;
			if (sinceDamage > regenDelay && currentHP < maxHP)
			{
				currentHP += regenPerSecond * TimeHandler.deltaTime;
				currentHP = Mathf.Clamp(currentHP, float.NegativeInfinity, maxHP);
			}
		}
	}

	public override void TakeDamage(Vector2 damage, Vector2 damagePosition, Color dmgColor, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false)
	{
		TakeDamage(damage, damagePosition, damagingWeapon, damagingPlayer, lethal);
	}

	public override void CallTakeDamage(Vector2 damage, Vector2 damagePosition, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true)
	{
		TakeDamage(damage, damagePosition, Color.red, damagingWeapon, damagingPlayer, lethal);
	}
}
public class DamageBox : MonoBehaviour
{
	[Header("Sound")]
	public bool soundPlaySawDamage;

	public SoundEvent soundSawDamage;

	[Header("Settings")]
	public bool towardsCenterOfMap;

	public bool awayFromMe;

	public float damage = 25f;

	public float force;

	public float setFlyingFor;

	public float shake;

	public float cd = 0.3f;

	public bool ignoreBlock;

	public ParticleSystem dmgPart;

	private float time;

	private SpawnedAttack spawned;

	private void Start()
	{
		spawned = GetComponentInParent<SpawnedAttack>();
	}

	private void OnCollisionEnter2D(Collision2D collision)
	{
		Collide(collision);
	}

	private void OnCollisionStay2D(Collision2D collision)
	{
		Collide(collision);
	}

	private void Collide(Collision2D collision)
	{
		if (Time.time < time + cd)
		{
			return;
		}
		Vector3 vector = base.transform.root.forward;
		if (towardsCenterOfMap)
		{
			vector = -collision.contacts[0].point.normalized;
		}
		if (awayFromMe)
		{
			vector = (collision.transform.position - base.transform.position).normalized;
		}
		Damagable componentInParent = collision.transform.GetComponentInParent<Damagable>();
		if (!componentInParent)
		{
			return;
		}
		time = Time.time;
		HealthHandler component = componentInParent.GetComponent<HealthHandler>();
		CharacterData component2 = component.GetComponent<CharacterData>();
		if (!component2 || component2.view.IsMine)
		{
			if ((bool)component)
			{
				component.CallTakeForce(vector * force, ForceMode2D.Impulse, forceIgnoreMass: false, ignoreBlock, setFlyingFor);
			}
			componentInParent.CallTakeDamage(damage * vector, base.transform.position, null, (spawned != null) ? spawned.spawner : null);
			if (soundPlaySawDamage)
			{
				SoundManager.Instance.PlayAtPosition(soundSawDamage, SoundManager.Instance.GetTransform(), base.transform);
			}
			if ((bool)dmgPart)
			{
				Vector3 forward = vector;
				vector.z = 0f;
				dmgPart.transform.parent.rotation = Quaternion.LookRotation(forward);
				dmgPart.Play();
			}
			if (shake != 0f)
			{
				component2.player.Call_AllGameFeel(shake * (Vector2)vector);
			}
		}
	}
}
public class DamageOverTime : MonoBehaviour
{
	private HealthHandler health;

	private CharacterData data;

	private void Start()
	{
		health = GetComponent<HealthHandler>();
		data = GetComponent<CharacterData>();
	}

	public void TakeDamageOverTime(Vector2 damage, Vector2 position, float time, float interval, Color color, SoundEvent soundDamageOverTime, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true)
	{
		StartCoroutine(DoDamageOverTime(damage, position, time, interval, color, soundDamageOverTime, damagingWeapon, damagingPlayer, lethal));
	}

	private IEnumerator DoDamageOverTime(Vector2 damage, Vector2 position, float time, float interval, Color color, SoundEvent soundDamageOverTime, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true)
	{
		float damageDealt = 0f;
		float damageToDeal = damage.magnitude;
		float dpt = damageToDeal / time * interval;
		while (damageDealt < damageToDeal)
		{
			if (soundDamageOverTime != null && data.isPlaying && !data.dead)
			{
				SoundManager.Instance.Play(soundDamageOverTime, base.transform);
			}
			damageDealt += dpt;
			health.DoDamage(damage.normalized * dpt, position, color, damagingWeapon, damagingPlayer, healthRemoval: true, lethal);
			yield return new WaitForSeconds(interval / TimeHandler.timeScale);
		}
	}
}
public static class Extensions
{
	public static double NextGaussianDouble(this System.Random r)
	{
		double num;
		double num3;
		do
		{
			num = 2.0 * r.NextDouble() - 1.0;
			double num2 = 2.0 * r.NextDouble() - 1.0;
			num3 = num * num + num2 * num2;
		}
		while (num3 >= 1.0);
		double num4 = Math.Sqrt(-2.0 * Math.Log(num3) / num3);
		return num * num4;
	}
}
public class PlayerAIDavid : MonoBehaviour
{
	public static int[] topology = new int[4] { 2, 10, 16, 5 };

	[SerializeField]
	private bool m_useWeights;

	[SerializeField]
	private WeightDataAsset m_weightData;

	private PlayerAPI m_api;

	private NeuralNet m_neuralNet;

	private double[] m_cachedInput;

	private float m_startTime;

	private Vector2 m_movement = Vector2.zero;

	private float m_aiTimer;

	private void Awake()
	{
		m_api = GetComponentInParent<PlayerAPI>();
		m_cachedInput = new double[2];
		m_neuralNet = new NeuralNet(topology);
		if (m_weightData != null && m_useWeights)
		{
			m_neuralNet.SetWeights(m_weightData.m_weightDatas[m_weightData.m_weightDatas.Count - 1].m_weights);
		}
		m_startTime = Time.time + 0.8f;
	}

	public void SetWeights(double[] weights)
	{
		m_neuralNet.SetWeights(new List<double>(weights));
	}

	public void SetWeights(List<double> weights)
	{
		m_neuralNet.SetWeights(weights);
	}

	private void Update()
	{
		if (Time.time < m_startTime)
		{
			return;
		}
		if (m_aiTimer >= 0.1f)
		{
			m_aiTimer -= 0.1f;
			Vector3 vector = m_api.OtherPlayerPosition() - m_api.PlayerPosition();
			m_cachedInput[0] = vector.x;
			m_cachedInput[1] = vector.y;
			m_neuralNet.FeedForward(m_cachedInput, 1.0);
			double[] results = m_neuralNet.GetResults();
			m_api.SetAimDirection(new Vector2((float)results[3], (float)results[4]));
			if (results[0] > 0.5)
			{
				m_api.Jump();
			}
			if (results[1] > 0.5)
			{
				m_api.Attack();
			}
			Vector2 zero = Vector2.zero;
			if (results[2] > 0.5)
			{
				zero.x = 1f;
			}
			else if (results[2] < -0.5)
			{
				zero.x = -1f;
			}
			m_movement = zero;
		}
		m_api.Move(m_movement);
		m_aiTimer += TimeHandler.deltaTime;
	}
}
