[Serializable]
public class DynamicParticleSet
{
	public ObjectsToSpawn objectsToSpawn;

	public float dmg;
}
public class DynamicParticles : MonoBehaviour
{
	public static DynamicParticles instance;

	public DynamicParticleSet[] bulletHit;

	private int spawnsThisFrame;

	private void Start()
	{
		instance = this;
	}

	private void Update()
	{
		spawnsThisFrame = 0;
	}

	public void PlayBulletHit(float damage, Transform spawnerTransform, HitInfo hit, Color projectielColor)
	{
		if ((float)spawnsThisFrame > 5f)
		{
			return;
		}
		spawnsThisFrame++;
		int num = 0;
		for (int i = 1; i < bulletHit.Length && !(bulletHit[i].dmg > damage); i++)
		{
			num = i;
		}
		GameObject[] array = ObjectsToSpawn.SpawnObject(base.transform, hit, bulletHit[num].objectsToSpawn, null, null);
		if (!(projectielColor != Color.black))
		{
			return;
		}
		for (int j = 0; j < array.Length; j++)
		{
			for (int k = 0; k < array[j].transform.childCount; k++)
			{
				ChangeColor componentInChildren = array[j].transform.GetChild(k).GetComponentInChildren<ChangeColor>();
				if ((bool)componentInChildren)
				{
					componentInChildren.GetComponent<ParticleSystemRenderer>().material.color = projectielColor;
				}
			}
		}
	}
}
public class Empower : MonoBehaviour
{
	public SoundEvent soundEmpowerSpawn;

	public GameObject addObjectToBullet;

	public float dmgMultiplier = 2f;

	public float speedMultiplier = 2f;

	public Color empowerColor;

	private CharacterData data;

	private ParticleSystem[] parts;

	private Transform particleTransform;

	private bool empowered;

	private bool isOn;

	private void Start()
	{
		particleTransform = base.transform.GetChild(0);
		data = GetComponentInParent<CharacterData>();
		parts = GetComponentsInChildren<ParticleSystem>();
		HealthHandler healthHandler = GetComponentInParent<Player>().data.healthHandler;
		healthHandler.reviveAction = (Action)Delegate.Combine(healthHandler.reviveAction, new Action(ResetEmpower));
		Gun gun = data.weaponHandler.gun;
		gun.ShootPojectileAction = (Action<GameObject>)Delegate.Combine(gun.ShootPojectileAction, new Action<GameObject>(Attack));
		Block componentInParent = GetComponentInParent<Block>();
		componentInParent.BlockAction = (Action<BlockTrigger.BlockTriggerType>)Delegate.Combine(componentInParent.BlockAction, new Action<BlockTrigger.BlockTriggerType>(Block));
	}

	private void OnDestroy()
	{
		HealthHandler healthHandler = GetComponentInParent<Player>().data.healthHandler;
		healthHandler.reviveAction = (Action)Delegate.Remove(healthHandler.reviveAction, new Action(ResetEmpower));
		Gun gun = data.weaponHandler.gun;
		gun.ShootPojectileAction = (Action<GameObject>)Delegate.Remove(gun.ShootPojectileAction, new Action<GameObject>(Attack));
		Block componentInParent = GetComponentInParent<Block>();
		componentInParent.BlockAction = (Action<BlockTrigger.BlockTriggerType>)Delegate.Remove(componentInParent.BlockAction, new Action<BlockTrigger.BlockTriggerType>(Block));
	}

	private void ResetEmpower()
	{
		empowered = false;
	}

	public void Block(BlockTrigger.BlockTriggerType trigger)
	{
		if (trigger != BlockTrigger.BlockTriggerType.Echo && trigger != BlockTrigger.BlockTriggerType.Empower && trigger != BlockTrigger.BlockTriggerType.ShieldCharge)
		{
			empowered = true;
		}
	}

	public void Attack(GameObject projectile)
	{
		SpawnedAttack component = projectile.GetComponent<SpawnedAttack>();
		if (!component)
		{
			return;
		}
		if (empowered)
		{
			ProjectileHit component2 = projectile.GetComponent<ProjectileHit>();
			MoveTransform component3 = projectile.GetComponent<MoveTransform>();
			component.SetColor(empowerColor);
			component2.damage *= dmgMultiplier;
			component3.localForce *= speedMultiplier;
			if ((bool)addObjectToBullet)
			{
				UnityEngine.Object.Instantiate(addObjectToBullet, projectile.transform.position, projectile.transform.rotation, projectile.transform);
			}
		}
		empowered = false;
	}

	private void Update()
	{
		if (empowered)
		{
			particleTransform.transform.position = data.weaponHandler.gun.transform.position;
			particleTransform.transform.rotation = data.weaponHandler.gun.transform.rotation;
			if (!isOn)
			{
				SoundManager.Instance.PlayAtPosition(soundEmpowerSpawn, SoundManager.Instance.GetTransform(), base.transform);
				for (int i = 0; i < parts.Length; i++)
				{
					parts[i].Play();
				}
				isOn = true;
			}
		}
		else if (isOn)
		{
			for (int j = 0; j < parts.Length; j++)
			{
				parts[j].Stop();
			}
			isOn = false;
		}
	}
}
public class EnsnareEffect : MonoBehaviour
{
	[Header("Sounds")]
	public SoundEvent soundEnsnare;

	public SoundEvent soundEnsnareBreak;

	public bool soundEnsnareJumpChange;

	public float range = 1f;

	private float seconds = 1f;

	public float force = 2000f;

	public float breakDistance = 2f;

	public float drag = 0.98f;

	private CharacterData target;

	private Vector2 startPos;

	public bool startPosIsMyPos;

	private float scale = 1f;

	private LineEffect line;

	[FoldoutGroup("SNAP", 0)]
	public float snapCapLineTime = 0.5f;

	[FoldoutGroup("SNAP", 0)]
	public float snapCapTimeTime = 0.5f;

	private bool done;

	private bool doneDone;

	private void Start()
	{
		scale *= base.transform.localScale.x;
		range *= (1f + base.transform.localScale.x) * 0.5f;
		Player closestPlayer = PlayerManager.instance.GetClosestPlayer(base.transform.position, needVision: true);
		if ((bool)closestPlayer && Vector3.Distance(base.transform.position, closestPlayer.transform.position) < range)
		{
			target = closestPlayer.data;
			startPos = target.transform.position;
			if (startPosIsMyPos)
			{
				startPos = base.transform.position;
			}
			float bezierOffset = 1f;
			if (startPosIsMyPos)
			{
				bezierOffset = 0f;
			}
			line = GetComponentInChildren<LineEffect>(includeInactive: true);
			line.Play(base.transform, closestPlayer.transform, bezierOffset);
			if (soundEnsnare != null)
			{
				SoundManager.Instance.Play(soundEnsnare, target.transform);
			}
			if (soundEnsnareJumpChange)
			{
				target.playerSounds.AddEnsnareEffect(this);
			}
		}
	}

	private void FixedUpdate()
	{
		if (!target || !(line.currentWidth > 0f))
		{
			return;
		}
		target.sinceGrounded = 0f;
		target.playerVel.velocity *= Mathf.Pow(drag, scale);
		target.playerVel.AddForce(Vector2.ClampMagnitude(startPos - (Vector2)target.transform.position, 60f) * scale * force, ForceMode2D.Force);
		if (!done && Vector2.Distance(startPos, target.transform.position) > breakDistance)
		{
			done = true;
			line.counter = Mathf.Clamp(line.counter, snapCapLineTime, float.PositiveInfinity);
			if (soundEnsnareJumpChange)
			{
				target.playerSounds.RemoveEnsnareEffect(this);
			}
			if (soundEnsnareBreak != null)
			{
				SoundManager.Instance.Play(soundEnsnareBreak, target.transform);
			}
		}
	}
}
[Serializable]
public class DelayedEvent
{
	public UnityEvent eventTrigger;

	public float delay;

	public int cycles = 1;

	public int cyclesPerLvl;
}
public class EventSequence : MonoBehaviour
{
	public bool playOnAwake = true;

	public bool useTimeScale = true;

	public DelayedEvent[] events;

	private int level;

	private void Start()
	{
		level = GetComponentInParent<AttackLevel>().attackLevel;
		if (playOnAwake)
		{
			Go();
		}
	}

	public void Go()
	{
		StartCoroutine(DoSequence());
	}

	private IEnumerator DoSequence()
	{
		for (int i = 0; i < events.Length; i++)
		{
			float num = 0f;
			for (int j = 0; j < events[i].cycles + events[i].cyclesPerLvl * level; j++)
			{
				num += events[i].delay;
				if (num > TimeHandler.deltaTime)
				{
					if (useTimeScale)
					{
						yield return new WaitForSeconds(num);
					}
					else
					{
						yield return new WaitForSecondsRealtime(num);
					}
					num = 0f;
				}
				events[i].eventTrigger.Invoke();
			}
		}
	}
}
public class Explosion : MonoBehaviour
{
	[Header("Sounds")]
	public SoundEvent soundDamage;

	[Header("Settings")]
	public float slow;

	public float silence;

	public bool fastSlow;

	public float stun;

	public float force = 2000f;

	public float objectForceMultiplier = 1f;

	public bool forceIgnoreMass;

	public float damage = 25f;

	public Color dmgColor = Color.black;

	public float range = 2f;

	public float flyingFor;

	public bool auto = true;

	public bool ignoreTeam;

	public bool ignoreWalls;

	public bool staticRangeMultiplier;

	[FoldoutGroup("Scaling", 0)]
	public bool scaleSlow = true;

	[FoldoutGroup("Scaling", 0)]
	public bool scaleSilence = true;

	[FoldoutGroup("Scaling", 0)]
	public bool scaleDmg = true;

	[FoldoutGroup("Scaling", 0)]
	public bool scaleRadius = true;

	[FoldoutGroup("Scaling", 0)]
	public bool scaleStun = true;

	[FoldoutGroup("Scaling", 0)]
	public bool scaleForce = true;

	[FoldoutGroup("Immunity", 0)]
	public float immunity;

	private SpawnedAttack spawned;

	public bool locallySimulated;

	public Action<Damagable> DealDamageAction;

	public Action<Damagable> DealHealAction;

	public Action<Damagable, float> HitTargetAction;

	private PhotonView view;

	public Action<CharacterData, float> hitPlayerAction;

	private void Start()
	{
		spawned = GetComponent<SpawnedAttack>();
		view = GetComponent<PhotonView>();
		if (auto)
		{
			Explode();
		}
	}

	private void DoExplosionEffects(Collider2D hitCol, float rangeMultiplier, float distance)
	{
		float num = (scaleDmg ? base.transform.localScale.x : 1f);
		float num2 = (scaleForce ? base.transform.localScale.x : 1f);
		float num3 = (scaleSlow ? base.transform.localScale.x : 1f);
		float num4 = (scaleSilence ? base.transform.localScale.x : 1f);
		float num5 = (scaleStun ? ((1f + base.transform.localScale.x) * 0.5f) : 1f);
		Damagable componentInParent = hitCol.gameObject.GetComponentInParent<Damagable>();
		CharacterData characterData = null;
		if ((bool)componentInParent)
		{
			characterData = hitCol.gameObject.GetComponentInParent<CharacterData>();
			if ((immunity > 0f && (bool)characterData && characterData.GetComponent<PlayerImmunity>().IsImune(immunity, num * damage * rangeMultiplier, base.gameObject.name)) || (!ignoreWalls && (bool)characterData && !PlayerManager.instance.CanSeePlayer(base.transform.position, characterData.player).canSee))
			{
				return;
			}
			if (slow != 0f && (bool)componentInParent.GetComponent<CharacterStatModifiers>())
			{
				if (locallySimulated)
				{
					if (spawned.IsMine() && !characterData.block.IsBlocking())
					{
						characterData.stats.RPCA_AddSlow(slow * rangeMultiplier * num3, fastSlow);
					}
				}
				else if (spawned.IsMine() && !characterData.block.IsBlocking())
				{
					characterData.view.RPC("RPCA_AddSlow", RpcTarget.All, slow * rangeMultiplier * num3, fastSlow);
				}
			}
			if (silence != 0f && (bool)componentInParent.GetComponent<SilenceHandler>() && spawned.IsMine() && !characterData.block.IsBlocking())
			{
				characterData.view.RPC("RPCA_AddSilence", RpcTarget.All, silence * rangeMultiplier * num4);
			}
			if ((bool)spawned)
			{
				_ = spawned.spawner;
			}
			hitPlayerAction?.Invoke(characterData, rangeMultiplier);
			if (damage < 0f)
			{
				if ((bool)characterData)
				{
					characterData.healthHandler.Heal(0f - damage);
				}
				if (DealHealAction != null)
				{
					DealHealAction(componentInParent);
				}
			}
			else if (damage > 0f)
			{
				if (soundDamage != null && characterData != null)
				{
					SoundManager.Instance.Play(soundDamage, characterData.transform);
				}
				Vector2 vector = ((Vector2)hitCol.bounds.ClosestPoint(base.transform.position) - (Vector2)base.transform.position).normalized;
				if (vector == Vector2.zero)
				{
					vector = Vector2.up;
				}
				if (spawned.IsMine())
				{
					componentInParent.CallTakeDamage(num * damage * rangeMultiplier * vector, base.transform.position, null, spawned.spawner);
				}
				if (DealDamageAction != null)
				{
					DealDamageAction(componentInParent);
				}
			}
		}
		if ((bool)characterData)
		{
			if (HitTargetAction != null)
			{
				HitTargetAction(componentInParent, distance);
			}
			if (force != 0f)
			{
				if (locallySimulated)
				{
					characterData.healthHandler.TakeForce(((Vector2)hitCol.bounds.ClosestPoint(base.transform.position) - (Vector2)base.transform.position).normalized * rangeMultiplier * force * num2, ForceMode2D.Impulse, forceIgnoreMass);
				}
				else if (spawned.IsMine())
				{
					characterData.healthHandler.CallTakeForce(((Vector2)hitCol.bounds.ClosestPoint(base.transform.position) - (Vector2)base.transform.position).normalized * rangeMultiplier * force * num2, ForceMode2D.Impulse, forceIgnoreMass, ignoreBlock: false, flyingFor * rangeMultiplier);
				}
			}
			if (stun > 0f)
			{
				characterData.stunHandler.AddStun(stun * num5);
			}
		}
		else if ((bool)hitCol.attachedRigidbody)
		{
			hitCol.attachedRigidbody.AddForce(((Vector2)hitCol.bounds.ClosestPoint(base.transform.position) - (Vector2)base.transform.position).normalized * rangeMultiplier * force * num2, ForceMode2D.Impulse);
		}
	}

	public void Explode()
	{
		float num = (scaleRadius ? base.transform.localScale.x : 1f);
		Collider2D[] array = Physics2D.OverlapCircleAll(base.transform.position, range * num);
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].gameObject.layer != 19)
			{
				Damagable componentInParent = array[i].gameObject.GetComponentInParent<Damagable>();
				float num2 = Vector2.Distance(base.transform.position, array[i].bounds.ClosestPoint(base.transform.position));
				float value = 1f - num2 / (range * num);
				if (staticRangeMultiplier)
				{
					value = 1f;
				}
				value = Mathf.Clamp(value, 0f, 1f);
				NetworkPhysicsObject component = array[i].GetComponent<NetworkPhysicsObject>();
				if ((bool)component && component.photonView.IsMine)
				{
					float num3 = (scaleForce ? base.transform.localScale.x : 1f);
					component.BulletPush((Vector2)(component.transform.position - base.transform.position).normalized * objectForceMultiplier * 1f * value * force * num3, Vector2.zero, null);
				}
				if (((bool)componentInParent || (bool)array[i].attachedRigidbody) && (!ignoreTeam || !spawned || !(spawned.spawner.gameObject == array[i].transform.gameObject)))
				{
					DoExplosionEffects(array[i], value, num2);
				}
			}
		}
	}
}
