public class FollowLocalPos : MonoBehaviour
{
	private Vector3 relative;

	private Vector3 relativeForward;

	private Vector3 relativeUp;

	public Transform target;

	public Player targetPlayer;

	private void Start()
	{
		if ((bool)target && relative == Vector3.zero)
		{
			Follow(target);
		}
	}

	private void LateUpdate()
	{
		if ((bool)target && target.gameObject.activeInHierarchy)
		{
			base.transform.position = target.TransformPoint(relative);
			base.transform.rotation = Quaternion.LookRotation(target.TransformDirection(relativeForward), target.TransformDirection(relativeUp));
		}
		else
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	public void Follow(Transform targetTransform)
	{
		if ((bool)targetTransform)
		{
			target = targetTransform;
			Player component = target.transform.root.GetComponent<Player>();
			Vector3 position = base.transform.position;
			if ((bool)component)
			{
				targetPlayer = component;
				base.transform.position -= base.transform.forward * 2f;
				Vector3 position2 = target.position;
				Vector3 vector = (base.transform.position - target.position).normalized * 1.1f;
				position = position2 + vector;
				base.transform.position = new Vector3(base.transform.position.x, base.transform.position.y, component.transform.position.z);
			}
			relative = targetTransform.InverseTransformPoint(position);
			relativeForward = targetTransform.InverseTransformDirection(base.transform.forward);
			relativeUp = targetTransform.InverseTransformDirection(base.transform.up);
		}
	}
}
public class FollowPlayer : MonoBehaviour
{
	public enum Target
	{
		Self,
		Other
	}

	public Target target;

	public bool inheritScale = true;

	private Vector3 startScale;

	private Player ownPlayer;

	private void Start()
	{
		startScale = base.transform.localScale;
		ownPlayer = GetComponentInParent<Player>();
		if (!ownPlayer)
		{
			ownPlayer = GetComponentInParent<SpawnedAttack>().spawner;
		}
	}

	private void LateUpdate()
	{
		Player player = null;
		player = ((target != Target.Other) ? ownPlayer : PlayerManager.instance.GetOtherPlayer(ownPlayer));
		if (inheritScale)
		{
			base.transform.localScale = new Vector3(player.transform.localScale.x * startScale.x, player.transform.localScale.y * startScale.y, player.transform.localScale.z * startScale.z);
		}
		base.transform.position = player.transform.position;
		base.transform.rotation = player.transform.rotation;
	}
}
public class FollowRandomPlayer : MonoBehaviour
{
	public bool X = true;

	public bool Y = true;

	private Transform targetPlayer;

	public bool snap;

	private void Start()
	{
	}

	private void Update()
	{
		if (!targetPlayer)
		{
			GetNewPlayer();
		}
		else if (snap)
		{
			base.transform.position = new Vector3(X ? targetPlayer.position.x : base.transform.position.x, Y ? targetPlayer.position.y : base.transform.position.y, 0f);
		}
		else
		{
			base.transform.position = Vector3.Lerp(base.transform.position, new Vector3(X ? targetPlayer.position.x : base.transform.position.x, Y ? targetPlayer.position.y : base.transform.position.y, 0f), TimeHandler.deltaTime * 5f);
		}
	}

	private void GetNewPlayer()
	{
		if (PlayerManager.instance.players.Count > 0)
		{
			targetPlayer = PlayerManager.instance.players[UnityEngine.Random.Range(0, PlayerManager.instance.players.Count)].transform;
		}
	}
}
