		GetComponentInChildren<GunAmmo>().maxAmmo = 3;
		GetComponentInChildren<GunAmmo>().ReDrawTotalBullets();
		projectileColor = Color.black;
	}

	private void Start()
	{
		gunAmmo = GetComponentInChildren<GunAmmo>();
		Gun[] componentsInChildren = base.transform.root.GetComponentsInChildren<Gun>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (componentsInChildren[i] == this)
			{
				gunID = i;
			}
		}
		if (!player)
		{
			player = GetComponentInParent<Player>();
		}
		if (!player)
		{
			ProjectileHit componentInParent = GetComponentInParent<ProjectileHit>();
			if ((bool)componentInParent)
			{
				player = componentInParent.ownPlayer;
			}
		}
		if (!player)
		{
			SpawnedAttack component = base.transform.root.GetComponent<SpawnedAttack>();
			if ((bool)component)
			{
				player = component.spawner;
			}
		}
		holdable = GetComponent<Holdable>();
		defaultCooldown = usedCooldown;
		ShootPos componentInChildren = GetComponentInChildren<ShootPos>();
		if ((bool)componentInChildren)
		{
			shootPosition = componentInChildren.transform;
		}
		else
		{
			shootPosition = base.transform;
		}
		rig = GetComponent<Rigidbody2D>();
		soundGun.SetGun(this);
		soundGun.SetGunTransform(base.transform);
		soundGun.RefreshSoundModifiers();
	}

	private void Update()
	{
		if ((bool)holdable && (bool)holdable.holder && (bool)holdable.holder.player)
		{
			player = holdable.holder.player;
		}
		sinceAttack += TimeHandler.deltaTime * attackSpeedMultiplier;
		if (!GameManager.instance.battleOngoing || (player != null && (!player.data.isPlaying || player.data.dead)))
		{
			soundGun.StopAutoPlayTail();
		}
	}

	private void OnDestroy()
	{
		soundGun.StopAutoPlayTail();
	}

	public bool IsReady(float readuIn = 0f)
	{
		return sinceAttack + readuIn * attackSpeedMultiplier > usedCooldown;
	}

	public float ReadyAmount()
	{
		return sinceAttack / usedCooldown;
	}

	public override bool Attack(float charge, bool forceAttack = false, float damageM = 1f, float recoilM = 1f, bool useAmmo = true)
	{
		if (sinceAttack < usedCooldown && !forceAttack)
		{
			return false;
		}
		if (isReloading && !forceAttack)
		{
			return false;
		}
		sinceAttack = 0f;
		int attacks = Mathf.Clamp(Mathf.RoundToInt(0.5f * charge / attackSpeed), 1, 10);
		if (lockGunToDefault)
		{
			attacks = 1;
		}
		StartCoroutine(DoAttacks(charge, forceAttack, damageM, attacks, recoilM, useAmmo));
		return true;
	}

	private IEnumerator DoAttacks(float charge, bool forceAttack = false, float damageM = 1f, int attacks = 1, float recoilM = 1f, bool useAmmo = true)
	{
		for (int i = 0; i < attacks; i++)
		{
			DoAttack(charge, forceAttack, damageM, recoilM, useAmmo);
			yield return new WaitForSeconds(0.3f / (float)attacks);
		}
	}

	private void DoAttack(float charge, bool forceAttack = false, float damageM = 1f, float recoilM = 1f, bool useAmmo = true)
	{
		float num = 1f * (1f + charge * chargeRecoilTo) * recoilM;
		if ((bool)rig)
		{
			rig.AddForce(rig.mass * recoil * Mathf.Clamp(usedCooldown, 0f, 1f) * -base.transform.up, ForceMode2D.Impulse);
		}
		_ = (bool)holdable;
		if (attackAction != null)
		{
			attackAction();
		}
		StartCoroutine(FireBurst(charge, forceAttack, damageM, recoilM, useAmmo));
	}

	private bool CheckIsMine()
	{
		bool result = false;
		if ((bool)holdable && (bool)holdable.holder)
		{
			result = holdable.holder.player.data.view.IsMine;
		}
		else
		{
			Player componentInParent = GetComponentInParent<Player>();
			if ((bool)componentInParent)
			{
				result = componentInParent.data.view.IsMine;
			}
		}
		return result;
	}

	private IEnumerator FireBurst(float charge, bool forceAttack = false, float damageM = 1f, float recoilM = 1f, bool useAmmo = true)
	{
		int currentNumberOfProjectiles = (lockGunToDefault ? 1 : (numberOfProjectiles + Mathf.RoundToInt(chargeNumberOfProjectilesTo * charge)));
		if (!lockGunToDefault)
		{
			_ = currentNumberOfProjectiles;
		}
		if (timeBetweenBullets == 0f)
		{
			GamefeelManager.GameFeel(base.transform.up * shake);
			soundGun.PlayShot(currentNumberOfProjectiles);
		}
		for (int ii = 0; ii < Mathf.Clamp(bursts, 1, 100); ii++)
		{
			for (int i = 0; i < projectiles.Length; i++)
			{
				for (int j = 0; j < currentNumberOfProjectiles; j++)
				{
					if (CheckIsMine())
					{
						spawnPos = base.transform.position;
						if ((bool)player)
						{
							player.GetComponent<PlayerAudioModifyers>().SetStacks();
							if ((bool)holdable)
							{
								spawnPos = player.transform.position;
							}
						}
						GameObject gameObject = PhotonNetwork.Instantiate(projectiles[i].objectToSpawn.gameObject.name, spawnPos, getShootRotation(j, currentNumberOfProjectiles, charge), 0);
						if ((bool)holdable)
						{
							if (useAmmo)
							{
								if (PhotonNetwork.OfflineMode)
								{
									gameObject.GetComponent<ProjectileInit>().OFFLINE_Init(holdable.holder.player.playerID, currentNumberOfProjectiles, damageM, UnityEngine.Random.Range(0f, 1f));
								}
								else
								{
									gameObject.GetComponent<PhotonView>().RPC("RPCA_Init", RpcTarget.All, holdable.holder.view.OwnerActorNr, currentNumberOfProjectiles, damageM, UnityEngine.Random.Range(0f, 1f));
								}
							}
							else if (PhotonNetwork.OfflineMode)
							{
								gameObject.GetComponent<ProjectileInit>().OFFLINE_Init_noAmmoUse(holdable.holder.player.playerID, currentNumberOfProjectiles, damageM, UnityEngine.Random.Range(0f, 1f));
							}
							else
							{
								gameObject.GetComponent<PhotonView>().RPC("RPCA_Init_noAmmoUse", RpcTarget.All, holdable.holder.view.OwnerActorNr, currentNumberOfProjectiles, damageM, UnityEngine.Random.Range(0f, 1f));
							}
						}
						else if (PhotonNetwork.OfflineMode)
						{
							gameObject.GetComponent<ProjectileInit>().OFFLINE_Init_SeparateGun(GetComponentInParent<Player>().playerID, gunID, currentNumberOfProjectiles, damageM, UnityEngine.Random.Range(0f, 1f));
						}
						else
						{
							gameObject.GetComponent<PhotonView>().RPC("RPCA_Init_SeparateGun", RpcTarget.All, GetComponentInParent<CharacterData>().view.OwnerActorNr, gunID, currentNumberOfProjectiles, damageM, UnityEngine.Random.Range(0f, 1f));
						}
					}
					if (timeBetweenBullets != 0f)
					{
						GamefeelManager.GameFeel(base.transform.up * shake);
						soundGun.PlayShot(currentNumberOfProjectiles);
					}
				}
			}
			if (bursts > 1 && ii + 1 == Mathf.Clamp(bursts, 1, 100))
			{
				soundGun.StopAutoPlayTail();
			}
			if (timeBetweenBullets > 0f)
			{
				yield return new WaitForSeconds(timeBetweenBullets);
			}
		}
	}

	public void BulletInit(GameObject bullet, int usedNumberOfProjectiles, float damageM, float randomSeed, bool useAmmo = true)
	{
		spawnedAttack = bullet.GetComponent<SpawnedAttack>();
		if (!spawnedAttack)
		{
			spawnedAttack = bullet.AddComponent<SpawnedAttack>();
		}
		if (!bullet.GetComponentInChildren<DontChangeMe>())
		{
			ApplyProjectileStats(bullet, usedNumberOfProjectiles, damageM, randomSeed);
		}
		if (soundDisableRayHitBulletSound)
		{
			RayHitBulletSound component = bullet.GetComponent<RayHitBulletSound>();
			if (component != null)
			{
				component.disableImpact = true;
			}
		}
		ApplyPlayerStuff(bullet);
		if (ShootPojectileAction != null)
		{
			ShootPojectileAction(bullet);
		}
		if (useAmmo && (bool)gunAmmo)
		{
			gunAmmo.Shoot(bullet);
		}
	}

	private Quaternion getShootRotation(int bulletID, int numOfProj, float charge)
	{
		Vector3 forward = shootPosition.forward;
		if (forceShootDir != Vector3.zero)
		{
			forward = forceShootDir;
		}
		float num = multiplySpread * Mathf.Clamp(1f + charge * chargeSpreadTo, 0f, float.PositiveInfinity);
		float num2 = UnityEngine.Random.Range(0f - spread, spread);
		num2 /= (1f + projectileSpeed * 0.5f) * 0.5f;
		forward += Vector3.Cross(forward, Vector3.forward) * num2 * num;
		return Quaternion.LookRotation(lockGunToDefault ? shootPosition.forward : forward);
	}

	private void ApplyPlayerStuff(GameObject obj)
	{
		ProjectileHit component = obj.GetComponent<ProjectileHit>();
		component.ownWeapon = base.gameObject;
		if ((bool)player)
		{
			component.ownPlayer = player;
		}
		spawnedAttack.spawner = player;
		spawnedAttack.attackID = attackID;
	}

	private void ApplyProjectileStats(GameObject obj, int numOfProj = 1, float damageM = 1f, float randomSeed = 0f)
	{
		ProjectileHit component = obj.GetComponent<ProjectileHit>();
		component.dealDamageMultiplierr *= bulletDamageMultiplier;
		component.damage *= damage * damageM;
		component.percentageDamage = percentageDamage;
		component.stun = component.damage / 150f;
		component.force *= knockback;
		component.movementSlow = slow;
		component.hasControl = CheckIsMine();
		component.projectileColor = projectileColor;
		component.unblockable = unblockable;
		RayCastTrail component2 = obj.GetComponent<RayCastTrail>();
		if (ignoreWalls)
		{
			component2.mask = component2.ignoreWallsMask;
		}
		if ((bool)component2)
		{
			component2.extraSize += size;
		}
		if ((bool)player)
		{
			PlayerSkin teamColor = (component.team = PlayerSkinBank.GetPlayerSkinColors(player.playerID));
			obj.GetComponent<RayCastTrail>().teamID = player.playerID;
			SetTeamColor.TeamColorThis(obj, teamColor);
		}
		List<ObjectsToSpawn> list = new List<ObjectsToSpawn>();
		for (int i = 0; i < objectsToSpawn.Length; i++)
		{
			list.Add(objectsToSpawn[i]);
			if (!objectsToSpawn[i].AddToProjectile || ((bool)objectsToSpawn[i].AddToProjectile.gameObject.GetComponent<StopRecursion>() && isProjectileGun))
			{
				continue;
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(objectsToSpawn[i].AddToProjectile, component.transform.position, component.transform.rotation, component.transform);
			gameObject.transform.localScale *= 1f * (1f - objectsToSpawn[i].scaleFromDamage) + component.damage / 55f * objectsToSpawn[i].scaleFromDamage;
			if (objectsToSpawn[i].scaleStacks)
			{
				gameObject.transform.localScale *= 1f + (float)objectsToSpawn[i].stacks * objectsToSpawn[i].scaleStackM;
			}
			if (!objectsToSpawn[i].removeScriptsFromProjectileObject)
			{
				continue;
			}
			MonoBehaviour[] componentsInChildren = gameObject.GetComponentsInChildren<MonoBehaviour>();
			for (int j = 0; j < componentsInChildren.Length; j++)
			{
				if (componentsInChildren[j].GetType().ToString() != "SoundImplementation.SoundUnityEventPlayer")
				{
					UnityEngine.Object.Destroy(componentsInChildren[j]);
				}
				Debug.Log(componentsInChildren[j].GetType().ToString());
			}
		}
		component.objectsToSpawn = list.ToArray();
		if (reflects > 0)
		{
			RayHitReflect rayHitReflect = obj.gameObject.AddComponent<RayHitReflect>();
			rayHitReflect.reflects = reflects;
			rayHitReflect.speedM = speedMOnBounce;
			rayHitReflect.dmgM = dmgMOnBounce;
		}
		if (!forceSpecificShake)
		{
			float num = component.damage / 100f * ((1f + usedCooldown) / 2f) / ((1f + (float)numOfProj) / 2f) * 2f;
			float num2 = Mathf.Clamp((0.2f + component.damage * (((float)numberOfProjectiles + 2f) / 2f) / 100f * ((1f + usedCooldown) / 2f)) * 1f, 0f, 3f);
			component.shake = num * shakeM;
			shake = num2;
		}
		MoveTransform component3 = obj.GetComponent<MoveTransform>();
		component3.localForce *= projectileSpeed;
		component3.simulationSpeed *= projectielSimulatonSpeed;
		component3.gravity *= gravity;
		component3.worldForce *= gravity;
		component3.drag = drag;
		component3.drag = Mathf.Clamp(component3.drag, 0f, 45f);
		component3.velocitySpread = Mathf.Clamp(spread * 50f, 0f, 50f);
		component3.dragMinSpeed = dragMinSpeed;
		component3.localForce *= Mathf.Lerp(1f - component3.velocitySpread * 0.01f, 1f + component3.velocitySpread * 0.01f, randomSeed);
		component3.selectedSpread = 0f;
		if (damageAfterDistanceMultiplier != 1f)
		{
			obj.AddComponent<ChangeDamageMultiplierAfterDistanceTravelled>().muiltiplier = damageAfterDistanceMultiplier;
		}
		if (cos > 0f)
		{
			obj.gameObject.AddComponent<Cos>().multiplier = cos;
		}
		if (destroyBulletAfter != 0f)
		{
			obj.GetComponent<RemoveAfterSeconds>().seconds = destroyBulletAfter;
		}
		if ((bool)spawnedAttack && projectileColor != Color.black)
		{
			spawnedAttack.SetColor(projectileColor);
		}
	}

	public void AddAttackAction(Action action)
	{
		attackAction = (Action)Delegate.Combine(attackAction, action);
	}

	internal void RemoveAttackAction(Action action)
	{
		attackAction = (Action)Delegate.Remove(attackAction, action);
	}
}
public class HandPos : MonoBehaviour
{
}
public class HealthHandler : Damagable
{
	[Header("Sounds")]
	public SoundEvent soundDie;

	public SoundEvent soundHeal;

	public SoundEvent soundDamagePassive;

	public SoundEvent soundDamageLifeSteal;

	public SoundEvent soundBounce;

	[Header("Settings")]
	public SpriteRenderer hpSprite;

	public GameObject deathEffect;

	public float regeneration;

	private CharacterData data;

	private CodeAnimation anim;

	private Player player;

	private CharacterStatModifiers stats;

	public ParticleSystem healPart;

	private DamageOverTime dot;

	private Vector3 startHealthSpriteScale;

	public float flyingFor;

	private float lastDamaged;

	public Action delayedReviveAction;

	public Action reviveAction;

	[HideInInspector]
	public bool DestroyOnDeath;

	public bool isRespawning;

	public GameObject deathEffectPhoenix;

	private void Awake()
	{
		dot = GetComponent<DamageOverTime>();
		data = GetComponent<CharacterData>();
		anim = GetComponentInChildren<CodeAnimation>();
		player = GetComponent<Player>();
		stats = GetComponent<CharacterStatModifiers>();
	}

	private void Start()
	{
		startHealthSpriteScale = hpSprite.transform.localScale;
	}

	private void Update()
	{
		flyingFor -= TimeHandler.deltaTime;
		if (regeneration > 0f)
		{
			Heal(regeneration * TimeHandler.deltaTime);
		}
	}

	public void Heal(float healAmount)
	{
		if (healAmount != 0f && data.health != data.maxHealth)
		{
			SoundManager.Instance.Play(soundHeal, base.transform);
			data.health += healAmount;
			data.health = Mathf.Clamp(data.health, float.NegativeInfinity, data.maxHealth);
			healPart.Emit((int)Mathf.Clamp(healAmount * 0.2f, 1f, 10f));
		}
	}

	public void CallTakeForce(Vector2 force, ForceMode2D forceMode = ForceMode2D.Impulse, bool forceIgnoreMass = false, bool ignoreBlock = false, float setFlying = 0f)
	{
		if (data.isPlaying && (!data.block.IsBlocking() || ignoreBlock))
		{
			data.view.RPC("RPCA_SendTakeForce", RpcTarget.All, force, (int)forceMode, forceIgnoreMass, true, setFlying);
		}
	}

	[PunRPC]
	public void RPCA_SendTakeForce(Vector2 force, int forceMode, bool forceIgnoreMass = false, bool ignoreBlock = false, float setFlying = 0f)
	{
		TakeForce(force, (ForceMode2D)forceMode, forceIgnoreMass, ignoreBlock, setFlying);
		data.GetComponent<SyncPlayerMovement>().SetDontSyncFor((float)PhotonNetwork.GetPing() * 0.001f + 0.2f);
	}

	[PunRPC]
	public void RPCA_SendForceOverTime(Vector2 force, float time, int forceMode, bool forceIgnoreMass = false, bool ignoreBlock = false)
	{
		StartCoroutine(IForceOverTime(force, time, forceMode, forceIgnoreMass, ignoreBlock));
	}

	private IEnumerator IForceOverTime(Vector2 force, float time, int forceMode, bool forceIgnoreMass = false, bool ignoreBlock = false)
	{
		for (float i = 0f; i < time; i += TimeHandler.deltaTime)
		{
			TakeForce(force, (ForceMode2D)forceMode, forceIgnoreMass, ignoreBlock);
			data.GetComponent<SyncPlayerMovement>().SetDontSyncFor((float)PhotonNetwork.GetPing() * 0.001f + 0.2f);
			yield return new WaitForFixedUpdate();
		}
	}

	[PunRPC]
	public void RPCA_SendForceTowardsPointOverTime(float force, float drag, float clampDistancce, Vector2 point, float time, int forceMode, bool forceIgnoreMass = false, bool ignoreBlock = false)
	{
		StartCoroutine(IForceTowardsPointOverTime(force, drag, clampDistancce, point, time, forceMode, forceIgnoreMass, ignoreBlock));
	}

	private IEnumerator IForceTowardsPointOverTime(float force, float drag, float clampDistancce, Vector2 point, float time, int forceMode, bool forceIgnoreMass = false, bool ignoreBlock = false)
	{
		for (float i = 0f; i < time; i += TimeHandler.fixedDeltaTime)
		{
			Vector2 vector = point - (Vector2)base.transform.position;
			vector = Vector2.ClampMagnitude(vector, clampDistancce);
			Vector2 vector2 = data.playerVel.velocity * (0f - drag) * TimeHandler.fixedDeltaTime;
			TakeForce(force * vector + vector2 * drag * TimeHandler.timeScale, (ForceMode2D)forceMode, forceIgnoreMass, ignoreBlock);
			data.GetComponent<SyncPlayerMovement>().SetDontSyncFor((float)PhotonNetwork.GetPing() * 0.001f + 0.2f);
			yield return new WaitForFixedUpdate();
		}
	}

	public void TakeForce(Vector2 force, ForceMode2D forceMode = ForceMode2D.Impulse, bool forceIgnoreMass = false, bool ignoreBlock = false, float setFlying = 0f)
	{
		if (!data.isPlaying || !data.playerVel.simulated)
		{
			return;
		}
		bool flag = data.block.IsBlocking();
		if (flag && !ignoreBlock)
		{
			return;
		}
		if (!flag)
		{
			if (setFlying > flyingFor && setFlying > 0.25f)
			{
				flyingFor = setFlying;
				SoundManager.Instance.Play(soundBounce, base.transform);
			}
		}
		if (forceIgnoreMass)
		{
			force *= data.playerVel.mass / 100f;
		}
		data.playerVel.AddForce(force, forceMode);
		if (force.y > 0f)
		{
			if (!forceIgnoreMass)
			{
				force.y /= data.playerVel.mass / 100f;
			}
			if (forceMode == ForceMode2D.Force)
			{
				force *= 0.003f;
			}
			data.sinceGrounded -= force.y * 0.003f;
		}
		data.sinceGrounded = Mathf.Clamp(data.sinceGrounded, -0.5f, 100f);
	}

	public override void CallTakeDamage(Vector2 damage, Vector2 position, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true)
	{
		if (!(damage == Vector2.zero) && !data.block.IsBlocking())
		{
			data.view.RPC("RPCA_SendTakeDamage", RpcTarget.All, damage, position, lethal, (damagingPlayer != null) ? damagingPlayer.playerID : (-1));
		}
	}

	[PunRPC]
	public void RPCA_SendTakeDamage(Vector2 damage, Vector2 position, bool lethal = true, int playerID = -1)
	{
		if (!(damage == Vector2.zero))
		{
			Player playerWithID = PlayerManager.instance.GetPlayerWithID(playerID);
			GameObject damagingWeapon = null;
			if ((bool)playerWithID)
			{
				damagingWeapon = playerWithID.data.weaponHandler.gun.gameObject;
			}
			TakeDamage(damage, position, damagingWeapon, playerWithID, lethal, ignoreBlock: true);
		}
	}

	public override void TakeDamage(Vector2 damage, Vector2 position, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false)
	{
		if (!(damage == Vector2.zero))
		{
			TakeDamage(damage, position, Color.white * 0.85f, damagingWeapon, damagingPlayer, lethal, ignoreBlock);
		}
	}

	public override void TakeDamage(Vector2 damage, Vector2 position, Color dmgColor, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true, bool ignoreBlock = false)
	{
		if (!(damage == Vector2.zero) && data.isPlaying && data.playerVel.simulated && !data.dead && (!data.block.IsBlocking() || ignoreBlock))
		{
			if (dmgColor == Color.black)
			{
				dmgColor = Color.white * 0.85f;
			}
			if (stats.secondsToTakeDamageOver == 0f)
			{
				DoDamage(damage, position, dmgColor, damagingWeapon, damagingPlayer, healthRemoval: false, lethal, ignoreBlock);
			}
			else
			{
				TakeDamageOverTime(damage, position, stats.secondsToTakeDamageOver, 0.25f, dmgColor, damagingWeapon, damagingPlayer, lethal);
			}
		}
	}

	public void DoDamage(Vector2 damage, Vector2 position, Color blinkColor, GameObject damagingWeapon = null, Player damagingPlayer = null, bool healthRemoval = false, bool lethal = true, bool ignoreBlock = false)
	{
		if (damage == Vector2.zero || !data.isPlaying || data.dead || (data.block.IsBlocking() && !ignoreBlock) || isRespawning)
		{
			return;
		}
		if ((bool)damagingPlayer)
		{
			damagingPlayer.GetComponent<CharacterStatModifiers>().DealtDamage(damage, damagingPlayer != null && damagingPlayer.transform.root == base.transform, data.player);
		}
		StopAllCoroutines();
		DisplayDamage(blinkColor);
		data.lastSourceOfDamage = damagingPlayer;
		data.health -= damage.magnitude;
		stats.WasDealtDamage(damage, damagingPlayer != null && damagingPlayer.transform.root == base.transform);
		if (!lethal)
		{
			data.health = Mathf.Clamp(data.health, 1f, data.maxHealth);
		}
		if (data.health < 0f && !data.dead)
		{
			if (data.stats.remainingRespawns > 0)
			{
				data.view.RPC("RPCA_Die_Phoenix", RpcTarget.All, damage);
			}
			else
			{
				data.view.RPC("RPCA_Die", RpcTarget.All, damage);
			}
		}
		if (lastDamaged + 0.15f < Time.time && damagingPlayer != null && damagingPlayer.data.stats.lifeSteal != 0f)
		{
			SoundManager.Instance.Play(soundDamageLifeSteal, base.transform);
		}
		lastDamaged = Time.time;
	}

	public void TakeDamageOverTime(Vector2 damage, Vector2 position, float time, float interval, Color color, GameObject damagingWeapon = null, Player damagingPlayer = null, bool lethal = true)
	{
		dot.TakeDamageOverTime(damage, position, time, interval, color, soundDamagePassive, damagingWeapon, damagingPlayer, lethal);
	}

	private void DisplayDamage(Color blinkColor)
	{
		GetComponentInChildren<PlayerSkinHandler>().BlinkColor(blinkColor);
	}

	private IEnumerator DelayReviveAction()
	{
		yield return new WaitForSecondsRealtime(2f);
		delayedReviveAction?.Invoke();
	}

	public void Revive(bool isFullRevive = true)
	{
		reviveAction?.Invoke();
		if (base.gameObject.activeInHierarchy)
		{
			StartCoroutine(DelayReviveAction());
		}
		flyingFor = 0f;
		if (isFullRevive)
		{
			data.stats.remainingRespawns = data.stats.respawns;
		}
		data.healthHandler.isRespawning = false;
		data.health = data.maxHealth;
		data.playerVel.velocity = Vector2.zero;
		data.playerVel.angularVelocity = 0f;
		data.stunTime = 0f;
		data.block.ResetCD(soundPlay: false);
		data.weaponHandler.gun.GetComponentInChildren<GunAmmo>().ReloadAmmo(playSound: false);
		data.GetComponent<PlayerCollision>().IgnoreWallForFrames(5);
		base.gameObject.SetActive(value: true);
		if ((bool)deathEffect && data.dead)
		{
			anim.PlayIn();
		}
		data.dead = false;
		hpSprite.color = PlayerSkinBank.GetPlayerSkinColors(player.playerID).color;
		data.stunHandler.StopStun();
		data.silenceHandler.StopSilence();
		GetComponent<CharacterStatModifiers>().slow = 0f;
		GetComponent<CharacterStatModifiers>().slowSlow = 0f;
		GetComponent<CharacterStatModifiers>().fastSlow = 0f;
		GetComponent<WeaponHandler>().isOverHeated = false;
		GetComponent<Block>().sinceBlock = float.PositiveInfinity;
		dot.StopAllCoroutines();
	}

	[PunRPC]
	private void RPCA_Die(Vector2 deathDirection)
	{
		if (data.isPlaying && !data.dead)
		{
			SoundManager.Instance.Play(soundDie, base.transform);
			data.dead = true;
			if (!DestroyOnDeath)
			{
				base.gameObject.SetActive(value: false);
				GamefeelManager.GameFeel(deathDirection.normalized * 3f);
				UnityEngine.Object.Instantiate(deathEffect, base.transform.position, base.transform.rotation).GetComponent<DeathEffect>().PlayDeath(PlayerSkinBank.GetPlayerSkinColors(player.playerID).color, data.playerVel, deathDirection);
				dot.StopAllCoroutines();
				data.stunHandler.StopStun();
				data.silenceHandler.StopSilence();
				PlayerManager.instance.PlayerDied(player);
			}
			else
			{
				UnityEngine.Object.Destroy(base.transform.root.gameObject);
			}
		}
	}

	[PunRPC]
	private void RPCA_Die_Phoenix(Vector2 deathDirection)
	{
		if (data.isPlaying && !data.dead)
		{
			data.stats.remainingRespawns--;
			isRespawning = true;
			SoundManager.Instance.Play(soundDie, base.transform);
			if (!DestroyOnDeath)
			{
				base.gameObject.SetActive(value: false);
				GamefeelManager.GameFeel(deathDirection.normalized * 3f);
				UnityEngine.Object.Instantiate(deathEffectPhoenix, base.transform.position, base.transform.rotation).GetComponent<DeathEffect>().PlayDeath(PlayerSkinBank.GetPlayerSkinColors(player.playerID).color, data.playerVel, deathDirection, player.playerID);
				dot.StopAllCoroutines();
				data.stunHandler.StopStun();
				data.silenceHandler.StopSilence();
			}
		}
	}
}
