public class Homing : MonoBehaviour
{
	[Header("Sound")]
	public SoundEvent soundHomingFound;

	private bool soundHomingCanPlay = true;

	[Header("Settings")]
	public float amount = 1f;

	public float scalingDrag = 1f;

	public float drag = 1f;

	public float spread = 1f;

	private MoveTransform move;

	private bool isOn;

	public RotSpring rot1;

	public RotSpring rot2;

	private FlickerEvent[] flicks;

	private PhotonView view;

	private void Start()
	{
		move = GetComponentInParent<MoveTransform>();
		flicks = GetComponentsInChildren<FlickerEvent>();
		view = GetComponentInParent<PhotonView>();
		GetComponentInParent<SyncProjectile>().active = true;
	}

	private void Update()
	{
		Player closestPlayer = PlayerManager.instance.GetClosestPlayer(base.transform.position, needVision: true);
		if ((bool)closestPlayer)
		{
			Vector3 vector = closestPlayer.transform.position + base.transform.right * move.selectedSpread * Vector3.Distance(base.transform.position, closestPlayer.transform.position) * spread;
			float num = Vector3.Angle(base.transform.root.forward, vector - base.transform.position);
			if (num < 70f)
			{
				move.velocity -= move.velocity * num * TimeHandler.deltaTime * scalingDrag;
				move.velocity -= move.velocity * TimeHandler.deltaTime * drag;
				move.velocity += Vector3.ClampMagnitude(vector - base.transform.position, 1f) * TimeHandler.deltaTime * move.localForce.magnitude * 0.025f * amount;
				move.velocity.z = 0f;
				move.velocity += Vector3.up * TimeHandler.deltaTime * move.gravity * move.multiplier;
				if (!isOn)
				{
					move.simulateGravity++;
					if (soundHomingCanPlay)
					{
						soundHomingCanPlay = false;
						SoundManager.Instance.PlayAtPosition(soundHomingFound, SoundManager.Instance.GetTransform(), base.transform);
					}
				}
				isOn = true;
				for (int i = 0; i < flicks.Length; i++)
				{
					flicks[i].isOn = true;
				}
				rot1.target = 10f;
				rot2.target = -10f;
			}
			else
			{
				if (isOn)
				{
					move.simulateGravity--;
					soundHomingCanPlay = true;
				}
				isOn = false;
				for (int j = 0; j < flicks.Length; j++)
				{
					flicks[j].isOn = false;
				}
				rot1.target = 50f;
				rot2.target = -50f;
			}
		}
		else
		{
			if (isOn)
			{
				move.simulateGravity--;
				soundHomingCanPlay = true;
			}
			isOn = false;
			for (int k = 0; k < flicks.Length; k++)
			{
				flicks[k].isOn = false;
			}
			rot1.target = 50f;
			rot2.target = -50f;
		}
	}
}
public class IKArmMove : MonoBehaviour
{
	private CharacterData data;

	private PlayerVelocity rig;

	public Transform target;

	private Vector3 startPos;

	private Holding holding;

	private bool isActive;

	private Vector3 velolcity;

	private float sinceRaise = 10f;

	private void Start()
	{
		data = GetComponentInParent<CharacterData>();
		rig = GetComponentInParent<PlayerVelocity>();
		startPos = target.localPosition;
		holding = GetComponentInParent<Holding>();
	}

	private void Update()
	{
		isActive = false;
		sinceRaise += TimeHandler.deltaTime;
		if ((bool)holding.holdable && (bool)holding.holdable.rig && holding.holdable.rig.transform.position.x > rig.transform.position.x == base.transform.position.x > rig.transform.position.x)
		{
			target.position = holding.holdable.rig.transform.position;
			velolcity = Vector3.zero;
			isActive = true;
			return;
		}
		Vector3 vector = base.transform.parent.TransformPoint(startPos) + ((sinceRaise < 0.3f) ? Vector3.up : Vector3.zero);
		Vector3 vector2 = rig.velocity;
		vector2.x *= 0.3f;
		velolcity = FRILerp.Lerp(velolcity, (vector - target.position) * 15f, 15f);
		target.position += velolcity * TimeHandler.deltaTime;
		target.position += vector2 * -0.3f * TimeHandler.deltaTime;
	}

	public void RaiseHands()
	{
		if (!isActive)
		{
			sinceRaise = 0f;
			velolcity += Vector3.up * 20f;
		}
	}
}
public class IkLeg : MonoBehaviour
{
	[Header("Sounds")]
	[SerializeField]
	private SoundEvent soundCharacterStep;

	[SerializeField]
	private SoundEvent soundCharacterStepBig;

	private SoundParameterIntensity soundParameterIntensity = new SoundParameterIntensity();

	private CharacterData data;

	private float legLenth;

	public Transform legRoot;

	public Transform footTarget;

	public LayerMask mask;

	public AnimationCurve upCurve;

	public AnimationCurve forwardCurve;

	public Transform moveDeltaTransform;

	[HideInInspector]
	public float stepTime;

	public float stepSpeed = 1f;

	private float footDownTime;

	[HideInInspector]
	public bool footDown = true;

	public IkLeg otherLeg;

	private Vector2 restPosition;

	private Vector2 startOffset;

	private Vector2 legRootOffset;

	private float scale = 1f;

	public float prediction = 1f;

	private Vector2 raycastPosLocal;

	private Vector2 raycastPosWorld;

	private Vector2 previousRaycastPosLocal;

	private Vector2 previousRaycastPosWorld;

	private Transform raycastTransform;

	private Transform previousRaycastTransform;

	private Vector2 footPosition;

	private Vector2 deltaPos;

	private Vector2 lastPos;

	private void Start()
	{
		data = GetComponentInParent<CharacterData>();
		legLenth = Vector3.Distance(base.transform.position, footTarget.position);
		startOffset = footTarget.position - data.transform.position;
		legRootOffset = legRoot.position - data.transform.position;
	}

	private void FixedUpdate()
	{
		if ((bool)data)
		{
			SetValuesFixed();
		}
	}

	private void LateUpdate()
	{
		if ((bool)data)
		{
			DoRayCast();
			UpdateRayCastWorldPos();
			DoStep();
			UpdatePreviousRayCastWorldPos();
			UpdateMiscVariables();
			SetFootPos();
			Apply();
		}
	}

	private void AirFootMovement()
	{
		footPosition = Vector3.Lerp(footPosition, restPosition + data.playerVel.velocity * 0.08f, TimeHandler.deltaTime * 15f);
		raycastTransform = null;
	}

	private bool stepWasLost()
	{
		if (Vector3.Distance(footPosition, legRoot.position) > legLenth * 0.5f)
		{
			return true;
		}
		return false;
	}

	private void DoStep()
	{
		if (footDown)
		{
			footDownTime += TimeHandler.deltaTime * stepSpeed / scale;
			if (!(footDownTime > 1f) || !otherLeg.footDown || (!(Mathf.Abs(data.playerVel.velocity.x) > 1f) && !stepWasLost()))
			{
				return;
			}
			StartStep();
			footDownTime = 0f;
			footDown = false;
			if (!data.dead && data.isPlaying && data.isGrounded && !data.isWallGrab)
			{
				soundParameterIntensity.intensity = Mathf.Abs(data.playerVel.velocity.x);
				if (data.stats.SoundTransformScaleThresholdReached())
				{
					SoundManager.Instance.Play(soundCharacterStepBig, data.transform, soundParameterIntensity);
				}
				else
				{
					SoundManager.Instance.Play(soundCharacterStep, data.transform, soundParameterIntensity);
				}
			}
		}
		else
		{
			stepTime += TimeHandler.deltaTime * stepSpeed / scale;
			if (stepTime > 1f)
			{
				EndStep();
				stepTime = 0f;
				footDown = true;
			}
		}
	}

	private void EndStep()
	{
		if ((bool)raycastTransform)
		{
			previousRaycastTransform = raycastTransform;
			previousRaycastPosLocal = raycastPosLocal;
		}
	}

	private void StartStep()
	{
	}

	private void SetFootPos()
	{
		if (data.isGrounded)
		{
			if ((bool)raycastTransform)
			{
				if (footDown)
				{
					footPosition = previousRaycastPosWorld;
				}
				else
				{
					footPosition = Vector3.Lerp(previousRaycastPosWorld, raycastPosWorld, forwardCurve.Evaluate(stepTime)) + Vector3.up * upCurve.Evaluate(stepTime);
				}
			}
		}
		else
		{
			AirFootMovement();
		}
	}

	private void Apply()
	{
		legRoot.position = (Vector2)data.transform.position + legRootOffset * scale;
		footTarget.position = footPosition;
	}

	private void DoRayCast()
	{
		Vector2 vector = deltaPos * prediction;
		Vector2 origin = data.transform.position + base.transform.right * base.transform.localPosition.x;
		Vector2 direction = Vector2.down + vector;
		float distance = legLenth * 1.5f * scale + vector.magnitude;
		RaycastHit2D[] array = Physics2D.RaycastAll(origin, direction, distance, mask);
		RaycastHit2D hit = default(RaycastHit2D);
		for (int i = 0; i < array.Length; i++)
		{
			if (!(array[i].transform.root == data.transform) && (bool)array[i].transform)
			{
				if (!hit.transform)
				{
					hit = array[i];
				}
				else if (array[i].distance < hit.distance)
				{
					hit = array[i];
				}
			}
		}
		if ((bool)hit.transform)
		{
			HitGround(hit);
		}
		else
		{
			HitNothing();
		}
	}

	private void HitNothing()
	{
	}

	private void HitGround(RaycastHit2D hit)
	{
		bool flag = false;
		if (!raycastTransform && (bool)hit.transform)
		{
			flag = true;
		}
		if ((bool)raycastTransform && raycastTransform != hit.transform)
		{
			MigrateGroundHit(raycastTransform, hit.transform, hit);
		}
		raycastTransform = hit.transform;
		raycastPosLocal = raycastTransform.InverseTransformPoint(hit.point);
		if (flag)
		{
			Land(hit);
		}
	}

	private void MigrateGroundHit(Transform from, Transform to, RaycastHit2D hit)
	{
	}

	private void Land(RaycastHit2D hit)
	{
		EndStep();
		UpdatePreviousRayCastWorldPos();
	}

	private void UpdateRayCastWorldPos()
	{
		if ((bool)raycastTransform)
		{
			raycastPosWorld = raycastTransform.TransformPoint(raycastPosLocal);
		}
	}

	private void UpdatePreviousRayCastWorldPos()
	{
		if ((bool)previousRaycastTransform)
		{
			previousRaycastPosWorld = previousRaycastTransform.TransformPoint(previousRaycastPosLocal);
		}
	}

	private void UpdateMiscVariables()
	{
		scale = data.transform.localScale.x;
		restPosition = (Vector2)data.transform.position + startOffset * 0.7f * scale;
	}

	private void SetValuesFixed()
	{
		if ((bool)moveDeltaTransform)
		{
			deltaPos = Vector3.Lerp(deltaPos, (Vector2)moveDeltaTransform.position - lastPos, TimeHandler.deltaTime * 15f);
			lastPos = moveDeltaTransform.position;
			deltaPos.y = 0f;
		}
	}
}
public class IKLegMove : MonoBehaviour
{
	private Rigidbody2D rig;

	public bool touchesGround;

	public IKLegMove otherLeg;

	public Transform target;

	public Transform foot;

	private Vector3 transformGroundPos;

	private Vector3 currentTransformGroundPos;

	private Vector3 previousTransformGroundPos;

	private Transform hitTransform;

	private Transform currentHitTransform;

	[HideInInspector]
	public float allowedFootDistance;

	private float defaultAllowedFootDistance;

	public AnimationCurve footCurveUp;

	private float distanceToFoot;

	public LayerMask mask;

	[HideInInspector]
	public float animationTime = 1f;

	private Vector3 velocity;

	private CharacterData data;

	private float animationLength;

	private bool hasLanded;

	private void Start()
	{
		rig = GetComponentInParent<Rigidbody2D>();
		data = GetComponentInParent<CharacterData>();
		defaultAllowedFootDistance = Vector3.Distance(base.transform.position, foot.position);
	}

	private void LateUpdate()
	{
		allowedFootDistance = (defaultAllowedFootDistance = base.transform.root.localScale.x);
		animationLength = footCurveUp.keys[footCurveUp.keys.Length - 1].time;
		if (!data.isGrounded)
		{
			animationTime = 1f;
			hasLanded = false;
		}
		distanceToFoot = Vector3.Distance(base.transform.position + (Vector3)rig.velocity * 0.01f, target.position);
		velocity = rig.velocity;
		if (velocity.y > 0f)
		{
			velocity.y *= -1f;
		}
		animationTime += TimeHandler.deltaTime;
		RayCastForFootPosition();
		touchesGround = footCurveUp.Evaluate(animationTime) < 0.1f;
		DoSteps();
		MoveFoot();
	}

	private void DoSteps()
	{
		float num = 0f;
		if (target.position.x > base.transform.position.x == rig.velocity.x > 0f)
		{
			num += Mathf.Abs(rig.velocity.x) * 0.25f;
		}
		float num2 = Mathf.Clamp(animationTime * 0.4f - 0.23f, 0f, 0.2f);
		if ((distanceToFoot > allowedFootDistance + num - num2 && data.isGrounded && (otherLeg.animationTime > animationLength * 0.5f || animationLength > 2f) && animationTime > animationLength) || !hasLanded)
		{
			hasLanded = true;
			currentHitTransform = hitTransform;
			previousTransformGroundPos = currentTransformGroundPos;
			currentTransformGroundPos = transformGroundPos;
			animationTime = 0f;
		}
		else
		{
			Vector3 vector = transformGroundPos - currentTransformGroundPos;
			vector *= Mathf.Clamp(footCurveUp.Evaluate(animationTime) * 1f, 0f, 1f);
			previousTransformGroundPos += vector;
			currentTransformGroundPos += vector;
		}
	}

	private void MoveFoot()
	{
		if (!data.isGrounded)
		{
			target.position = Vector3.Lerp(target.position, base.transform.position + Vector3.down * allowedFootDistance * 0.5f, TimeHandler.deltaTime * 1f);
			target.position += (Vector3)rig.velocity * 0.1f * TimeHandler.deltaTime;
		}
		else if ((bool)currentHitTransform)
		{
			Vector3 vector = currentHitTransform.TransformPoint(currentTransformGroundPos);
			Vector3 a = currentHitTransform.TransformPoint(previousTransformGroundPos);
			Vector3 vector2 = vector;
			float num = 0f;
			if (animationTime < animationLength)
			{
				vector2 = Vector3.Lerp(a, vector, animationTime / animationLength);
				num = footCurveUp.Evaluate(animationTime);
			}
			target.position = vector2 + Vector3.up * num;
		}
	}

	private void RayCastForFootPosition()
	{
		RaycastHit2D[] array = Physics2D.RaycastAll(base.transform.position, Vector3.down + velocity * 0.2f, 3f, mask);
		RaycastHit2D raycastHit2D = default(RaycastHit2D);
		float num = float.PositiveInfinity;
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].transform.root != base.transform.root && array[i].distance < num)
			{
				raycastHit2D = array[i];
				num = array[i].distance;
			}
		}
		if ((bool)raycastHit2D.transform)
		{
			hitTransform = raycastHit2D.transform;
			transformGroundPos = hitTransform.InverseTransformPoint(raycastHit2D.point);
		}
	}
}
public class KillBox : MonoBehaviour
{
	public bool alwaysOn;

	public float toggleTime = 0.3f;

	private float timeActivated = -10f;

	public bool readyToKill;

	private BoxCollider2D box;

	private void Start()
