public class LegRaycasters : MonoBehaviour
{
	public LayerMask mask;

	public float force;

	public float drag;

	public Transform[] legCastPositions;

	public AnimationCurve animationCurve;

	private PlayerVelocity rig;

	private CharacterData data;

	public AnimationCurve wobbleCurve;

	public AnimationCurve forceCurve;

	private IkLeg[] legs;

	private float totalStepTime;

	private void Awake()
	{
		legs = base.transform.root.GetComponentsInChildren<IkLeg>();
	}

	private void Start()
	{
		rig = GetComponentInParent<PlayerVelocity>();
		data = GetComponentInParent<CharacterData>();
	}

	private void FixedUpdate()
	{
		totalStepTime = 0f;
		for (int i = 0; i < legs.Length; i++)
		{
			if (!legs[i].footDown)
			{
				totalStepTime += legs[i].stepTime;
			}
		}
		for (int j = 0; j < legCastPositions.Length; j++)
		{
			RaycastHit2D[] array = Physics2D.RaycastAll(legCastPositions[j].transform.position + Vector3.up * 0.5f, Vector2.down, 1f * base.transform.root.localScale.x, mask);
			for (int k = 0; k < array.Length; k++)
			{
				if ((bool)array[k].transform && array[k].transform.root != base.transform.root)
				{
					HitGround(legCastPositions[j], array[k]);
					break;
				}
			}
		}
	}

	private void HitGround(Transform leg, RaycastHit2D hit)
	{
		if (!(data.sinceJump < 0.2f) && !(Vector3.Angle(Vector3.up, hit.normal) > 70f))
		{
			data.TouchGround(hit.point, hit.normal, hit.rigidbody);
			Vector3 vector = ((Vector3)hit.point - leg.transform.position) / base.transform.root.localScale.x;
			if (data.input.direction.x != 0f)
			{
				vector.y += wobbleCurve.Evaluate(totalStepTime) * base.transform.root.localScale.x;
				rig.AddForce(Vector3.up * forceCurve.Evaluate(totalStepTime) * rig.mass);
			}
			rig.AddForce(animationCurve.Evaluate(Mathf.Abs(vector.y)) * Vector3.up * rig.mass * force);
			rig.AddForce(animationCurve.Evaluate(Mathf.Abs(vector.y)) * (0f - rig.velocity.y) * Vector2.up * rig.mass * drag);
		}
	}
}
public class LegRenderer : MonoBehaviour
{
	public Transform start;

	public Transform mid;

	public Transform end;

	public int segmentCount = 10;

	public GameObject segment;

	public float segmentLength = 1f;

	private List<Transform> segments = new List<Transform>();

	private void Awake()
	{
		for (int i = 0; i < segmentCount; i++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(segment, base.transform);
			gameObject.SetActive(value: true);
			segments.Add(gameObject.transform);
			if (i == segmentCount - 1)
			{
				gameObject.transform.localScale *= 0f;
			}
		}
	}

	private void LateUpdate()
	{
		for (int i = 0; i < segments.Count; i++)
		{
			float t = (float)i / ((float)segments.Count - 1f);
			_ = Vector3.zero;
			if (i == 0)
			{
				_ = segments[i + 1].position - segments[i].position;
			}
			else if (i == segments.Count - 1)
			{
				_ = segments[i].position - segments[i - 1].position;
			}
			else
			{
				Vector3 vector = segments[i].position - segments[i - 1].position;
				Vector3 vector2 = segments[i + 1].position - segments[i].position;
				_ = (vector + vector2) * 0.5f;
			}
			segments[i].position = BezierCurve.QuadraticBezier(start.position, mid.position, end.position, t);
		}
		for (int j = 0; j < segments.Count; j++)
		{
			_ = (float)j / ((float)segments.Count - 1f);
			Vector3 zero = Vector3.zero;
			if (j == 0)
			{
				zero = segments[j + 1].position - segments[j].position;
			}
			else if (j == segments.Count - 1)
			{
				zero = segments[j].position - segments[j - 1].position;
			}
			else
			{
				Vector3 vector3 = segments[j].position - segments[j - 1].position;
				Vector3 vector4 = segments[j + 1].position - segments[j].position;
				zero = (vector3 + vector4) * 0.5f;
			}
			segments[j].rotation = Quaternion.LookRotation(Vector3.forward, zero);
		}
	}
}
public class LegRotator : MonoBehaviour
{
	private PlayerVelocity rig;

	private void Start()
	{
		rig = GetComponentInParent<PlayerVelocity>();
	}

	private void Update()
	{
		if ((bool)rig)
		{
			if (rig.velocity.x < 0f)
			{
				base.transform.localEulerAngles = Vector3.Lerp(base.transform.localEulerAngles, new Vector3(0f, 0f, 0f), TimeHandler.deltaTime * 15f * Mathf.Clamp(Mathf.Abs(rig.velocity.x), 0f, 1f));
			}
			else
			{
				base.transform.localEulerAngles = Vector3.Lerp(base.transform.localEulerAngles, new Vector3(0f, 180f, 0f), TimeHandler.deltaTime * 15f * Mathf.Clamp(Mathf.Abs(rig.velocity.x), 0f, 1f));
			}
		}
	}
}
public class LevelMapper : MonoBehaviour
{
	private CharacterData data;

	private PlayerJump jump;

	private PlayerMovement movement;

	private bool isJumping;

	private bool isRunning;

	public GameObject node;

	public GameObject line;

	public GameObject line2;

	private Vector3 jumpPos;

	private Vector3 landPos;

	private Vector3 startRunPos;

	private Vector3 leaveGroundPos;

	private void Start()
	{
		data = GetComponentInParent<CharacterData>();
		jump = data.jump;
		movement = data.movement;
		PlayerJump playerJump = jump;
		playerJump.JumpAction = (Action)Delegate.Combine(playerJump.JumpAction, new Action(Jump));
		CharacterData characterData = data;
		characterData.TouchGroundAction = (Action<float, Vector3, Vector3, Transform>)Delegate.Combine(characterData.TouchGroundAction, new Action<float, Vector3, Vector3, Transform>(Ground));
		CharacterData characterData2 = data;
		characterData2.TouchWallAction = (Action<float, Vector3, Vector3>)Delegate.Combine(characterData2.TouchWallAction, new Action<float, Vector3, Vector3>(Wall));
	}

	private void Update()
	{
		if (!data.isGrounded)
		{
			LeaveGround();
		}
	}

	private void Jump()
	{
		isJumping = true;
		jumpPos = base.transform.position;
	}

	private void Wall(float sinceWall, Vector3 pos, Vector3 normal)
	{
		if (!data.isWallGrab)
		{
			if (data.sinceJump < 0.1f)
			{
				isJumping = false;
			}
			else
			{
				Land();
			}
		}
	}

	private void Ground(float sinceGround, Vector3 pos, Vector3 groundNormal, Transform groundTransform = null)
	{
		if (!isRunning)
		{
			startRunPos = pos;
			isRunning = true;
		}
		if (!data.isGrounded)
		{
			if (data.sinceJump < 0.1f)
			{
				isJumping = false;
			}
			else
			{
				Land();
			}
		}
	}

	private void Land()
	{
		landPos = base.transform.position;
		if (Vector3.Distance(landPos, jumpPos) > 3f && isJumping)
		{
			SaveJump();
		}
		isJumping = false;
	}

	private void LeaveGround()
	{
		if (isRunning)
		{
			leaveGroundPos = data.groundPos;
			SaveRun();
			isRunning = false;
		}
	}

	private void SaveJump()
	{
		UnityEngine.Object.Instantiate(node, jumpPos, Quaternion.identity).GetComponent<SpriteRenderer>().color = Color.green;
		UnityEngine.Object.Instantiate(node, landPos, Quaternion.identity).GetComponent<SpriteRenderer>().color = Color.red;
		LineRenderer component = UnityEngine.Object.Instantiate(line, Vector3.zero, Quaternion.identity).GetComponent<LineRenderer>();
		component.SetPosition(0, jumpPos);
		component.SetPosition(1, landPos);
	}

	private void SaveRun()
	{
		if (!(Vector3.Distance(startRunPos, jumpPos) < 2f))
		{
			UnityEngine.Object.Instantiate(node, startRunPos, Quaternion.identity).GetComponent<SpriteRenderer>().color = Color.blue;
			UnityEngine.Object.Instantiate(node, leaveGroundPos, Quaternion.identity).GetComponent<SpriteRenderer>().color = Color.blue;
			LineRenderer component = UnityEngine.Object.Instantiate(line2, Vector3.zero, Quaternion.identity).GetComponent<LineRenderer>();
			component.SetPosition(0, startRunPos);
			component.SetPosition(1, leaveGroundPos);
		}
	}
}
public class LifeSteal : DealtDamageEffect
{
