public class MapManager : MonoBehaviour
{
	[SerializeField]
	public string[] levels;

	public int currentLevelID;

	public static MapManager instance;

	[HideInInspector]
	public bool isTestingMap;

	public MapWrapper currentMap;

	private PhotonView view;

	internal int otherPlayersMostRecentlyLoadedLevel = -1;

	public string forceMap = "";

	private bool callInNextMap;

	private void Awake()
	{
		instance = this;
		view = GetComponent<PhotonView>();
	}

	internal void ReportMapLoaded(int levelID)
	{
		view.RPC("RPCA_ReportMapLoaded", RpcTarget.Others, levelID);
	}

	[PunRPC]
	internal void RPCA_ReportMapLoaded(int levelID)
	{
		otherPlayersMostRecentlyLoadedLevel = levelID;
	}

	private string GetRandomMap()
	{
		if (forceMap != "")
		{
			return forceMap;
		}
		int num = UnityEngine.Random.Range(0, levels.Length);
		while (num == currentLevelID && levels.Length > 1)
		{
			num = UnityEngine.Random.Range(0, levels.Length);
		}
		return levels[num];
	}

	public void LoadNextLevel(bool callInImidetly = false, bool forceLoad = false)
	{
		if (forceLoad || PhotonNetwork.IsMasterClient || PhotonNetwork.OfflineMode)
		{
			view.RPC("RPCA_SetCallInNextMap", RpcTarget.All, callInImidetly);
			view.RPC("RPCA_LoadLevel", RpcTarget.All, GetRandomMap());
		}
	}

	[PunRPC]
	private void RPCA_SetCallInNextMap(bool toSet)
	{
		callInNextMap = toSet;
	}

	public void LoadLevelFromID(int ID, bool onlyMaster = false, bool callInImidetly = false)
	{
		if (!(!PhotonNetwork.IsMasterClient && onlyMaster))
		{
			callInNextMap = callInImidetly;
			RPCA_LoadLevel(levels[ID]);
		}
	}

	[PunRPC]
	public void RPCA_CallInNewMapAndMovePlayers(int mapID)
	{
		StartCoroutine(WaitForMapToBeLoaded(mapID));
	}

	private IEnumerator WaitForMapToBeLoaded(int mapID)
	{
		while (currentLevelID != mapID)
		{
			yield return null;
		}
		Debug.Log("CALL IN NEW MAP AND MOVE PLAYERS");
		if (currentMap != null)
		{
			MapTransition.instance.Enter(currentMap.Map);
		}
		MapTransition.instance.ClearObjects();
		PlayerManager.instance.RPCA_MovePlayers();
	}

	public void CallInNewMapAndMovePlayers(int mapID)
	{
		if (PhotonNetwork.IsMasterClient || PhotonNetwork.OfflineMode)
		{
			view.RPC("RPCA_CallInNewMapAndMovePlayers", RpcTarget.All, mapID);
		}
	}

	[PunRPC]
	public void RPCA_CallInNewMap()
	{
		if (currentMap != null)
		{
			MapTransition.instance.Enter(currentMap.Map);
		}
		MapTransition.instance.ClearObjects();
	}

	public void CallInNewMap()
	{
		if (PhotonNetwork.IsMasterClient || PhotonNetwork.OfflineMode)
		{
			view.RPC("RPCA_CallInNewMap", RpcTarget.All);
		}
	}

	public SpawnPoint[] GetSpawnPoints()
	{
		return currentMap.Map.GetComponentsInChildren<SpawnPoint>();
	}

	private void OnLevelFinishedLoading(Scene scene, LoadSceneMode mode)
	{
		Map map = null;
		for (int i = 0; i < scene.GetRootGameObjects().Length; i++)
		{
			map = scene.GetRootGameObjects()[i].GetComponent<Map>();
			if ((bool)map)
			{
				break;
			}
		}
		if (!map)
		{
			Debug.LogError("NO MAP WAS FOUND WHEN LOADING NEW MAP");
		}
		map.wasSpawned = true;
		SceneManager.sceneLoaded -= OnLevelFinishedLoading;
		if (currentMap != null)
		{
			StartCoroutine(UnloadAfterSeconds(currentMap.Scene));
			MapTransition.instance.Exit(currentMap.Map);
		}
		MapTransition.instance.SetStartPos(map);
		map.levelID = currentLevelID;
		currentMap = new MapWrapper(map, scene);
		currentLevelID = GetIDFromScene(scene);
		if (callInNextMap)
		{
			CallInNewMap();
			callInNextMap = false;
		}
		Debug.Log("FINISHED LOADING SCENE");
	}

	private int GetIDFromScene(Scene scene)
	{
		int result = -1;
		for (int i = 0; i < levels.Length; i++)
		{
			if (levels[i] == scene.name)
			{
				result = i;
			}
		}
		return result;
	}

	[PunRPC]
	public void RPCA_LoadLevel(string sceneName)
	{
		Debug.Log("LOADING SCENE");
		SceneManager.LoadScene(sceneName, LoadSceneMode.Additive);
		SceneManager.sceneLoaded += OnLevelFinishedLoading;
	}

	private IEnumerator UnloadAfterSeconds(Scene scene)
	{
		yield return new WaitForSecondsRealtime(2f);
		SceneManager.UnloadSceneAsync(scene);
	}

	public void UnloadScene(Scene scene)
	{
		SceneManager.UnloadSceneAsync(scene);
	}
}
public class MapTransition : MonoBehaviour
{
	[Header("Settings")]
	public UnityEvent switchMapEvent;

	public AnimationCurve curve;

	public AnimationCurve gravityCurve;

	public static MapTransition instance;

	private const float mapPadding = 90f;

	public static bool isTransitioning;

	private void Awake()
	{
		instance = this;
	}

	private void Start()
	{
	}

	public void SetStartPos(Map map)
	{
		map.transform.position = Vector3.right * 90f;
	}

	public void Enter(Map map)
	{
		MoveObject(map.gameObject, Vector3.zero);
		StartCoroutine(DelayEvent(0.1f));
		SoundPlayerStatic.Instance.PlayLevelTransitionIn();
		SoundMusicManager.Instance.PlayIngame(isCard: false);
	}

	public void Exit(Map map)
	{
		SoundPlayerStatic.Instance.PlayLevelTransitionOut();
		map.MapMoveOut();
		MoveObject(map.gameObject, Vector3.right * -90f);
		StartCoroutine(ClearObjectsAfterSeconds(1f));
	}

	private void MoveObject(GameObject target, Vector3 targetPos)
	{
		for (int i = 0; i < target.transform.childCount; i++)
		{
			Toggle(target.transform.GetChild(i).gameObject, enabled: false);
			StartCoroutine(Move(target.transform.GetChild(i).gameObject, targetPos - target.transform.position, (i == 0) ? target.GetComponent<Map>() : null));
		}
	}

	private void Toggle(GameObject obj, bool enabled)
	{
		Rigidbody2D component = obj.GetComponent<Rigidbody2D>();
		if ((bool)component)
		{
			component.simulated = enabled;
			if (enabled)
			{
				StartCoroutine(LerpDrag(component));
			}
		}
		Collider2D component2 = obj.GetComponent<Collider2D>();
		if ((bool)component2)
		{
			component2.enabled = enabled;
		}
		CodeAnimation component3 = obj.GetComponent<CodeAnimation>();
		if ((bool)component3)
		{
			component3.enabled = enabled;
		}
	}

	private IEnumerator DelayEvent(float delay)
	{
		yield return new WaitForSecondsRealtime(delay);
		switchMapEvent.Invoke();
	}

	private IEnumerator Move(GameObject target, Vector3 distance, Map targetMap = null)
	{
		isTransitioning = true;
		float maxRandomDelay = 0.25f;
		float randomDelay = UnityEngine.Random.Range(0f, maxRandomDelay);
		yield return new WaitForSecondsRealtime(randomDelay);
		Vector3 targetStartPos = target.transform.position;
		float t = curve.keys[curve.keys.Length - 1].time;
		float c = 0f;
		while (c < t)
		{
			c += Time.unscaledDeltaTime;
			target.transform.position = targetStartPos + distance * curve.Evaluate(c);
			yield return null;
		}
		target.transform.position = targetStartPos + distance;
		Toggle(target, enabled: true);
		yield return new WaitForSecondsRealtime(maxRandomDelay - randomDelay);
		isTransitioning = false;
		if ((bool)targetMap)
		{
			targetMap.hasEntered = true;
		}
	}

	private IEnumerator LerpDrag(Rigidbody2D target)
	{
		target.gravityScale = 0f;
		float t = gravityCurve.keys[gravityCurve.keys.Length - 1].time;
		float c = 0f;
		while (c < t && (bool)target)
		{
			target.gravityScale = gravityCurve.Evaluate(c);
			c += Time.unscaledDeltaTime;
			yield return null;
		}
		if ((bool)target)
		{
			target.gravityScale = 1f;
		}
	}

	private IEnumerator ClearObjectsAfterSeconds(float time)
	{
		yield return new WaitForSecondsRealtime(time);
		ClearObjects();
	}

	public void ClearObjects()
	{
		RemoveAfterSeconds[] array = UnityEngine.Object.FindObjectsOfType<RemoveAfterSeconds>();
		for (int i = 0; i < array.Length; i++)
		{
			UnityEngine.Object.Destroy(array[i].gameObject);
		}
	}
}
