public class Movement : MonoBehaviour
{
	public float jumpForce;

	public float force;

	public float torque;

	public float drag = 1f;

	public float Angulardrag = 1f;

	public ParticleSystem[] jumpPart;

	private GeneralInput input;

	private Rigidbody2D rig;

	private CharacterData data;

	private CharacterStatModifiers stats;

	public Vector2 knockBack;

	private HealthHandler health;

	private Vector3 moveDir;

	private Vector3 idleForce;

	private void Start()
	{
		rig = GetComponent<Rigidbody2D>();
		input = GetComponent<GeneralInput>();
		data = GetComponent<CharacterData>();
		stats = GetComponent<CharacterStatModifiers>();
		health = GetComponent<HealthHandler>();
	}

	private void FixedUpdate()
	{
		if (input.direction != Vector3.zero)
		{
			moveDir = input.direction;
			idleForce = Vector3.Lerp(idleForce, moveDir, Time.fixedDeltaTime * 6f);
		}
		else if (data.isGrounded || data.isWallGrab)
		{
			idleForce = Vector3.Lerp(idleForce, Vector3.zero, 15f * Time.fixedDeltaTime);
		}
		else
		{
			idleForce = Vector3.Lerp(idleForce, Vector3.zero, 3f * Time.fixedDeltaTime);
		}
		if (input.direction == Vector3.zero)
		{
			moveDir = idleForce;
		}
		if (data.isGrounded || data.isWallGrab)
		{
			knockBack = Vector3.Lerp(knockBack, Vector3.zero, 10f * Time.fixedDeltaTime);
		}
		else
		{
			knockBack = Vector3.Lerp(knockBack, Vector3.zero, 7f * Time.fixedDeltaTime);
		}
		rig.AddForce(knockBack * 0.1f * rig.mass, ForceMode2D.Force);
		if (moveDir.y > 0f)
		{
			moveDir.y = 0f;
		}
		rig.AddForce(-rig.velocity * 0.01f * drag * rig.mass, ForceMode2D.Force);
		rig.AddTorque((0f - rig.angularVelocity) * 0.01f * Angulardrag * rig.mass, ForceMode2D.Force);
		if (input.jumpIsPressed)
		{
			rig.AddForce(Vector2.up * 20f * rig.mass, ForceMode2D.Force);
		}
		rig.AddForce(moveDir * force * (1f - stats.GetSlow()) * rig.mass, ForceMode2D.Force);
	}

	private void Update()
	{
		if (input.jumpWasPressed)
		{
			Jump();
		}
		if (data.isGrounded && data.sinceJump > 0.2f)
		{
			data.currentJumps = data.jumps;
		}
	}

	private void Jump()
	{
		if (data.sinceJump < 0.15f)
		{
			return;
		}
		Vector3 vector = Vector3.up;
		Vector3 vector2 = data.groundPos;
		if (data.sinceGrounded < 0.1f)
		{
			if (data.sinceGrounded > 0.05f)
			{
				vector2 = base.transform.position;
			}
			data.currentJumps = data.jumps;
		}
		else if (data.sinceWallGrab < 0.1f)
		{
			vector = Vector2.up + data.wallNormal;
			vector2 = data.wallPos;
			data.currentJumps = data.jumps;
		}
		else
		{
			if (data.currentJumps <= 0)
			{
				return;
			}
			vector2 = base.transform.position;
		}
		data.currentJumps--;
		rig.velocity = new Vector3(rig.velocity.x, 0f);
		health.TakeForce(Vector2.up * jumpForce * 1f * (1f - stats.GetSlow()) * rig.mass);
		data.sinceJump = 0f;
		data.sinceGrounded = 0f;
		for (int i = 0; i < jumpPart.Length; i++)
		{
			jumpPart[i].transform.position = new Vector3(vector2.x, vector2.y, 5f) - vector * 0f;
			jumpPart[i].transform.rotation = Quaternion.LookRotation(rig.velocity);
			jumpPart[i].Play();
		}
	}
}
public class MoveSequence : MonoBehaviour
{
	private int targetID;

	public Vector2[] positions;

	public float drag = 1f;

	public float spring = 1f;

	public float cap = 1f;

	public float threshold = 1f;

	public float timeAtPos;

	private float counter;

	private Vector2 startPos;

	private Vector2 velocity;

	private Rigidbody2D rig;

	private Map map;

	private string myKey;

	private void Start()
	{
		base.gameObject.layer = 17;
		startPos = base.transform.localPosition;
		rig = GetComponent<Rigidbody2D>();
		map = GetComponentInParent<Map>();
		myKey = "MapObect " + GetComponentInParent<Map>().levelID + " " + base.transform.GetSiblingIndex();
		MapManager.instance.GetComponent<ChildRPC>().childRPCsInt.Add(myKey, RPCA_SetTargetID);
	}

	private void OnDestroy()
	{
		if ((bool)MapManager.instance)
		{
			MapManager.instance.GetComponent<ChildRPC>().childRPCsInt.Remove(myKey);
		}
	}

	private void OnDrawGizmos()
	{
		for (int i = 0; i < positions.Length; i++)
		{
			Gizmos.DrawSphere((Vector2)base.transform.position + positions[i], 0.25f + (float)i * 0.15f);
		}
	}

	private void Update()
	{
		if (MapTransition.isTransitioning || !map.hasEntered)
		{
			return;
		}
		Vector2 vector = positions[targetID] + startPos;
		Vector2 vector2 = vector - (Vector2)base.transform.position;
		vector2 = Vector3.ClampMagnitude(vector2, cap);
		if ((bool)rig)
		{
			rig.gravityScale = 0f;
			rig.AddForce(vector2 * spring * CappedDeltaTime.time * rig.mass);
		}
		else
		{
			velocity += vector2 * spring * CappedDeltaTime.time;
			velocity -= velocity * drag * CappedDeltaTime.time;
			base.transform.position += (Vector3)velocity * TimeHandler.deltaTime;
		}
		if (!PhotonNetwork.IsMasterClient || !(Vector2.Distance(base.transform.position, vector) < threshold))
		{
			return;
		}
		counter += TimeHandler.deltaTime;
		if (counter > timeAtPos)
		{
			targetID++;
			if (targetID >= positions.Length)
			{
				targetID = 0;
			}
			MapManager.instance.GetComponent<ChildRPC>().CallFunction(myKey, targetID);
			counter = 0f;
		}
	}

	private void RPCA_SetTargetID(int setValue)
	{
		targetID = setValue;
	}
}
public class MoveTransform : MonoBehaviour
{
	public float gravity = 30f;

	public float drag;

	public float dragMinSpeed = 1f;

	public float velocitySpread;

	public float spread;

	public Vector3 localForce;

	public Vector3 worldForce;

	public float multiplier = 1f;

	public Vector3 velocity;

	[HideInInspector]
	public float distanceTravelled;

	[HideInInspector]
	public bool DontRunStart;

	public float selectedSpread;

	public bool allowStop;

	public int simulateGravity;

	private int randomSeed;

	[HideInInspector]
	internal float simulationSpeed = 1f;

	private void Start()
	{
		if (!DontRunStart)
		{
			velocity += base.transform.TransformDirection(localForce) + worldForce;
			base.transform.rotation = Quaternion.LookRotation(velocity, Vector3.forward);
			if (spread != 0f)
			{
				velocity += base.transform.up * selectedSpread;
			}
		}
	}

	private void Update()
	{
		float num = Mathf.Clamp(TimeHandler.deltaTime, 0f, 0.02f);
		float deltaTime = TimeHandler.deltaTime;
		num *= simulationSpeed;
		deltaTime *= simulationSpeed;
		if (simulateGravity == 0)
		{
			velocity += gravity * Vector3.down * deltaTime * multiplier;
		}
		if ((velocity.magnitude > 2f || allowStop) && velocity.magnitude > dragMinSpeed)
		{
			velocity -= velocity * Mathf.Clamp(drag * num * Mathf.Clamp(multiplier, 0f, 1f), 0f, 1f);
		}
		base.transform.position += velocity * deltaTime * multiplier;
		distanceTravelled += velocity.magnitude * deltaTime * multiplier;
		base.transform.rotation = Quaternion.LookRotation(velocity, Vector3.forward);
	}

	public float GetUpwardsCompensation(Vector2 start, Vector2 end)
	{
		start.y = 0.5f;
		end.y = 0.5f;
		return Mathf.Pow(Vector3.Distance(start, end), 2.06f) * gravity / velocity.magnitude * 0.012f;
	}
}
