public class ObjectPool
{
	private Stack<GameObject> m_availableObjects = new Stack<GameObject>();

	private List<GameObject> m_usedObjects = new List<GameObject>();

	private GameObject m_objectPrefab;

	private Transform m_objectRoot;

	private int testCounter = 1;

	public ObjectPool(GameObject prefab, int initSpawn = 0, Transform parent = null)
	{
		m_objectPrefab = prefab;
		m_objectRoot = new GameObject(prefab.name + "_root").transform;
		m_objectRoot.transform.position = parent.position;
		m_objectRoot.transform.rotation = parent.rotation;
		m_objectRoot.transform.SetParent(parent, worldPositionStays: true);
		m_objectRoot.transform.localScale = Vector3.one;
		for (int i = 0; i < initSpawn; i++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(m_objectPrefab, m_objectRoot);
			gameObject.SetActive(value: false);
			m_availableObjects.Push(gameObject);
		}
	}

	public GameObject GetObject()
	{
		if (m_availableObjects.Count > 0)
		{
			GameObject gameObject = m_availableObjects.Pop();
			m_usedObjects.Add(gameObject);
			gameObject.SetActive(value: true);
			return gameObject;
		}
		GameObject gameObject2 = UnityEngine.Object.Instantiate(m_objectPrefab, m_objectRoot);
		m_usedObjects.Add(gameObject2);
		gameObject2.SetActive(value: true);
		return gameObject2;
	}

	public bool ReleaseObject(GameObject obj)
	{
		bool num = m_usedObjects.Remove(obj);
		if (num)
		{
			m_availableObjects.Push(obj);
			obj.SetActive(value: false);
		}
		return num;
	}

	public void ClearPool()
	{
		while (m_availableObjects.Count > 0)
		{
			UnityEngine.Object.Destroy(m_availableObjects.Pop());
		}
		for (int i = 0; i < m_usedObjects.Count; i++)
		{
			UnityEngine.Object.Destroy(m_usedObjects[i]);
		}
		m_usedObjects.Clear();
	}
}
public class ObjectShake : MonoBehaviour
{
	public float globalMultiplier = 1f;

	public float interval = 0.1f;

	public float movementMultiplier = 1f;

	public float rotationMultiplier = 1f;

	private float counter;

	private void Start()
	{
	}

	private void Update()
	{
		counter += TimeHandler.deltaTime;
		if (counter > interval)
		{
			base.transform.localPosition = UnityEngine.Random.insideUnitCircle * movementMultiplier * globalMultiplier * 0.1f;
			base.transform.localEulerAngles = new Vector3(base.transform.localEulerAngles.x, base.transform.localEulerAngles.y, (float)UnityEngine.Random.Range(-10, 10) * globalMultiplier * rotationMultiplier);
			counter = 0f;
		}
	}
}
public class OutOfBoundsHandler : MonoBehaviour
{
	private bool outOfBounds;

	private bool almostOutOfBounds;

	private Camera mainCam;

	private CharacterData data;

	public ParticleSystem wall;

	public ParticleSystem burst;

	public ParticleSystem burstBig;

	public ParticleSystem warning;

	public ParticleSystem shieldWall;

	public ParticleSystem shieldBurst;

	public ParticleSystem shieldBurstBig;

	private ChildRPC rpc;

	private float counter;

	private float warningPercentage = 0.1f;

	private void Start()
	{
		base.transform.position = Vector3.up * 200f;
		data = base.transform.root.GetComponent<CharacterData>();
		rpc = data.GetComponent<ChildRPC>();
		rpc.childRPCs.Add("OutOfBounds", RPCA_DisplayOutOfBounds);
		rpc.childRPCs.Add("ShieldOutOfBounds", RPCA_DisplayOutOfBoundsShield);
		mainCam = MainCam.instance.transform.GetComponent<Camera>();
		base.transform.SetParent(null);
	}

	private void LateUpdate()
	{
		if (!data)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			if (!data.playerVel.simulated || !data.isPlaying)
			{
				return;
			}
			float x = Mathf.InverseLerp(-35.56f, 35.56f, data.transform.position.x);
			float y = Mathf.InverseLerp(-20f, 20f, data.transform.position.y);
			Vector3 vector = new Vector3(x, y, 0f);
			vector = new Vector3(Mathf.Clamp(vector.x, 0f, 1f), Mathf.Clamp(vector.y, 0f, 1f), vector.z);
			almostOutOfBounds = false;
			outOfBounds = false;
			if (vector.x <= 0f || vector.x >= 1f || vector.y >= 1f || vector.y <= 0f)
			{
				outOfBounds = true;
			}
			else if (vector.x < warningPercentage || vector.x > 1f - warningPercentage || vector.y > 1f - warningPercentage || vector.y < warningPercentage)
			{
				almostOutOfBounds = true;
				if (vector.x < warningPercentage)
				{
					vector.x = 0f;
				}
				if (vector.x > 1f - warningPercentage)
				{
					vector.x = 1f;
				}
				if (vector.y < warningPercentage)
				{
					vector.y = 0f;
				}
				if (vector.y > 1f - warningPercentage)
				{
					vector.y = 1f;
				}
			}
			counter += TimeHandler.deltaTime;
			if (almostOutOfBounds && !data.dead)
			{
				base.transform.position = GetPoint(vector);
				base.transform.rotation = Quaternion.LookRotation(Vector3.forward, -(data.transform.position - base.transform.position));
				if (counter > 0.1f)
				{
					counter = 0f;
					warning.Play();
				}
			}
			if (!outOfBounds || data.dead)
			{
				return;
			}
			data.sinceGrounded = 0f;
			base.transform.position = GetPoint(vector);
			base.transform.rotation = Quaternion.LookRotation(Vector3.forward, -(data.transform.position - base.transform.position));
			if (counter > 0.1f && data.view.IsMine)
			{
				counter = 0f;
				if (data.block.IsBlocking())
				{
					rpc.CallFunction("ShieldOutOfBounds");
					data.playerVel.velocity *= 0f;
					data.healthHandler.CallTakeForce(base.transform.up * 400f * data.playerVel.mass, ForceMode2D.Impulse, forceIgnoreMass: false, ignoreBlock: true);
					data.transform.position = base.transform.position;
				}
				else
				{
					rpc.CallFunction("OutOfBounds");
					data.healthHandler.CallTakeForce(base.transform.up * 200f * data.playerVel.mass, ForceMode2D.Impulse, forceIgnoreMass: false, ignoreBlock: true);
					data.healthHandler.CallTakeDamage(51f * base.transform.up, data.transform.position);
				}
			}
		}
	}

	private Vector3 GetPoint(Vector3 p)
	{
		float x = Mathf.Lerp(-35.56f, 35.56f, p.x);
		float y = Mathf.Lerp(-20f, 20f, p.y);
		return new Vector3(x, y, 0f);
	}

	private void RPCA_DisplayOutOfBounds()
	{
		SoundManager.Instance.Play(data.playerSounds.soundCharacterDamageScreenEdge, data.transform);
		burst.Play();
		wall.Play();
		burstBig.Play();
		data.sinceGrounded = 0f;
	}

	private void RPCA_DisplayOutOfBoundsShield()
	{
		SoundManager.Instance.Play(data.playerSounds.soundCharacterDamageScreenEdge, data.transform);
		shieldBurst.Play();
		shieldWall.Play();
		shieldBurstBig.Play();
		data.sinceGrounded = 0f;
	}
}
public class ParticleExplosionModifier : MonoBehaviour
{
	public AnimationCurve curve;

	public float speed = 1f;

	private ParticleSystem effect;

	private ParticleSystem.MainModule main;

	private Coroutine corutine;

	private void Start()
	{
		effect = GetComponent<ParticleSystem>();
		main = effect.main;
		Explosion componentInParent = GetComponentInParent<Explosion>();
		componentInParent.DealDamageAction = (Action<Damagable>)Delegate.Combine(componentInParent.DealDamageAction, new Action<Damagable>(DealDamage));
		Explosion componentInParent2 = GetComponentInParent<Explosion>();
		componentInParent2.DealHealAction = (Action<Damagable>)Delegate.Combine(componentInParent2.DealHealAction, new Action<Damagable>(DealDamage));
	}

	public void DealDamage(Damagable damagable)
	{
		if (corutine != null)
		{
			StopCoroutine(corutine);
		}
		corutine = StartCoroutine(DoCurve());
	}

	private IEnumerator DoCurve()
	{
		float c = 0f;
		float t = curve.keys[curve.keys.Length - 1].time;
		while (c < t)
		{
			ParticleSystem.MinMaxCurve startSize = main.startSize;
			startSize.constantMin = curve.Evaluate(c) * 0.5f;
			startSize.constantMax = curve.Evaluate(c);
			main.startSize = startSize;
			c += TimeHandler.deltaTime * speed;
			yield return null;
		}
	}
}
public class ParticlePlayer : MonoBehaviour
{
	public static ParticlePlayer instance;

	private int spawnsThisFrame;

	private void Awake()
	{
		instance = this;
	}

	private void Update()
	{
		spawnsThisFrame = 0;
	}

	public void PlayEffect(string effectName, Vector3 position, Quaternion rotation, float scale = 1f, Transform followTransform = null)
	{
		if ((float)spawnsThisFrame > 5f)
		{
			return;
		}
		spawnsThisFrame++;
		Transform transform = base.transform.Find(effectName);
		if (!transform)
		{
			return;
		}
		if ((bool)followTransform)
		{
			transform = UnityEngine.Object.Instantiate(transform.gameObject, null).transform;
		}
		transform.transform.position = position;
		transform.transform.localScale = scale * Vector3.one;
		transform.transform.rotation = rotation;
		if ((bool)followTransform)
		{
			transform.gameObject.AddComponent<FollowLocalPos>().Follow(followTransform);
		}
		ParticleSystem[] componentsInChildren = transform.GetComponentsInChildren<ParticleSystem>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if ((bool)followTransform)
			{
				ParticleSystem.MainModule main = componentsInChildren[i].main;
				main.simulationSpace = ParticleSystemSimulationSpace.Local;
			}
			componentsInChildren[i].Play();
		}
	}
}
public class PlayerAIPhilip : MonoBehaviour
{
	private enum BattleMorale : byte
	{
		Blood,
		Coward,
		Defend
	}

	private enum BattleBehaviour : byte
	{
		Attack,
		HighGround,
		MoveSegments
	}

	private PlayerAPI m_PlayerAPI;

	private Player m_Enemy;

	private BattleMorale m_CurrentMorale;

	private BattleBehaviour m_CurrentBehaviour;

	private Vector2 m_Direction;

	private Vector2 m_TargetPos;

	private Vector2[] m_Boundaries;

	private Vector2[] m_Segments;

	private int m_CurrentSegment;

	private float m_Tick;

	private int m_BehaviourChangeTick;

	private int m_BehaviourTimeMin = 3;

	private int m_BehaviourTimeMax = 8;

	private float m_AttackDistance = 15f;

	private void Awake()
	{
		InitReferences();
		MakeBoundaries();
		NextBehaviour();
	}

	private void InitReferences()
	{
		m_PlayerAPI = GetComponentInParent<PlayerAPI>();
	}

	private void MakeBoundaries()
	{
		int num = 20;
		int num2 = 35;
		Vector2 vector = new Vector2(num2, num);
		Vector2 vector2 = new Vector2(-num2, num);
		Vector2 vector3 = new Vector2(num2, -num);
		Vector2 vector4 = new Vector2(-num2, -num);
		m_Boundaries = new Vector2[4] { vector, vector2, vector3, vector4 };
		m_Segments = new Vector2[4]
		{
			vector / 2f,
			vector2 / 2f,
			vector3 / 2f,
			vector4 / 2f
		};
	}

	private bool CheckForValidEnemy()
	{
		m_Enemy = m_PlayerAPI.GetOtherPlayer();
		return m_Enemy != null;
	}

	private void Start()
	{
		CheckForValidEnemy();
	}

	private void Update()
	{
		if (CheckForValidEnemy())
		{
			CheckMorale();
			CheckDirection();
			CheckGround();
			Move();
			Jump();
			DoAim();
			ShouldAttack();
			ShouldBlock();
			TickBehaviour();
		}
	}

	private void SeedBehaviourChange()
	{
		m_BehaviourChangeTick = UnityEngine.Random.Range(m_BehaviourTimeMin, m_BehaviourTimeMax);
	}

	private void TickBehaviour()
	{
		m_Tick += TimeHandler.deltaTime;
		if (m_Tick >= (float)m_BehaviourChangeTick)
		{
			NextBehaviour();
		}
	}

	private void NextBehaviour()
	{
		ResetTick();
		int length = Enum.GetValues(typeof(BattleBehaviour)).Length;
		m_CurrentBehaviour = (BattleBehaviour)UnityEngine.Random.Range(0, length);
		SeedBehaviourChange();
		CheckBehaviour();
	}

	private void ResetTick()
	{
		m_Tick = 0f;
	}

	private void ShouldBlock()
	{
		if (CheckIncommingBullets())
		{
			m_PlayerAPI.Block();
		}
	}

	private bool CheckIncommingBullets()
	{
		Vector3 vector = m_PlayerAPI.PlayerPosition();
		Vector2 a = new Vector2(vector.x, vector.y);
		float num = 1.5f;
		List<BulletWrapper> allBullets = m_PlayerAPI.GetAllBullets();
		int count = allBullets.Count;
		for (int i = 0; i < count; i++)
		{
			Vector2 vector2 = allBullets[i].projectileHit.transform.position;
			float num2 = Vector2.Distance(a, vector2);
			if (num2 <= num && Vector2.Distance(a, vector2 + allBullets[i].velocity.normalized) < num2)
			{
				return true;
			}
		}
		return false;
	}

	private void ShouldAttack()
	{
		if (CanSee() && Vector3.Distance(m_PlayerAPI.PlayerPosition(), m_PlayerAPI.OtherPlayerPosition()) <= m_AttackDistance)
		{
			m_PlayerAPI.Attack();
		}
	}

	private bool CanSee()
	{
		Vector2 vector = m_PlayerAPI.TowardsOtherPlayer();
		Vector3 vector2 = new Vector3(vector.x, vector.y, 0f);
		vector2.Normalize();
		Collider2D collider = Physics2D.Raycast(base.transform.position + vector2, vector2, 20f).collider;
		if ((bool)collider && (bool)collider.GetComponent<Player>())
		{
			return true;
		}
		return false;
	}

	private void DoAim()
	{
		m_PlayerAPI.SetAimDirection(m_PlayerAPI.TowardsOtherPlayer() + m_PlayerAPI.GetOtherPlayer().data.playerVel.velocity * 0.1f);
	}

	private void Move()
	{
		m_PlayerAPI.Move(m_Direction);
	}

	private void Jump()
	{
		m_PlayerAPI.Jump();
	}

	private void CheckGround()
	{
		Vector2 vector = m_PlayerAPI.PlayerPosition();
		if (!(vector.y < 0f) || m_PlayerAPI.CheckGroundBelow(vector + Vector2.down * 0.5f, 10f))
		{
			return;
		}
		m_Direction = Vector2.right;
		float num = float.PositiveInfinity;
		RaycastHit2D raycastHit2D = Physics2D.Raycast(base.transform.position + Vector3.right, Vector2.right, 5f);
		if ((bool)raycastHit2D.collider)
		{
			num = raycastHit2D.distance;
		}
		raycastHit2D = Physics2D.Raycast(base.transform.position + Vector3.left, Vector2.left, 5f);
		if ((bool)raycastHit2D.collider)
		{
			if (raycastHit2D.distance < num)
			{
				m_Direction = Vector2.left;
			}
		}
		else
		{
			m_Direction = Vector2.right;
		}
	}

	private void CheckDirection()
	{
		if (m_CurrentBehaviour == BattleBehaviour.Attack)
		{
			switch (m_CurrentMorale)
			{
			case BattleMorale.Blood:
				m_Direction = m_PlayerAPI.TowardsOtherPlayer();
				break;
			case BattleMorale.Coward:
				m_Direction = -m_PlayerAPI.TowardsOtherPlayer();
				break;
			case BattleMorale.Defend:
				m_Direction = -m_PlayerAPI.TowardsOtherPlayer();
				break;
			}
		}
		else
		{
			Vector3 vector = m_PlayerAPI.PlayerPosition();
			Vector2 vector2 = new Vector2(vector.x, vector.y);
			m_Direction = m_TargetPos - vector2;
		}
	}

	private void CheckBehaviour()
	{
		switch (m_CurrentBehaviour)
		{
		case BattleBehaviour.HighGround:
			m_TargetPos = m_Segments[0];
			break;
		case BattleBehaviour.MoveSegments:
		{
			int max = m_Segments.Length;
			int num;
			for (num = UnityEngine.Random.Range(0, max); num == m_CurrentSegment; num = UnityEngine.Random.Range(0, max))
			{
			}
			m_CurrentSegment = num;
			m_TargetPos = m_Segments[m_CurrentSegment];
			break;
		}
		case BattleBehaviour.Attack:
			break;
		}
	}

	private void CheckMorale()
	{
		if (m_PlayerAPI.CanShoot())
		{
			m_CurrentMorale = BattleMorale.Blood;
		}
	}
}
public class PhysicsFunctions : MonoBehaviour
{
	private static LayerMask mask = LayerMask.GetMask("Default", "IgnorePlayer", "IgnoreMap");

	public static Vector2 ObstructionPoint(Vector2 from, Vector2 to)
	{
		RaycastHit2D raycastHit2D = Physics2D.Raycast(from, to - from, Vector2.Distance(from, to), mask);
		if ((bool)raycastHit2D.transform)
		{
			return raycastHit2D.point;
		}
		return to;
	}
}
public class Player : MonoBehaviour
{
	public int playerID;

	public int teamID;

	[HideInInspector]
	public CharacterData data;

	public PlayerSkinBank colors;

	private void Awake()
	{
		data = GetComponent<CharacterData>();
	}

	private void Start()
	{
		if (!data.view.IsMine)
		{
			ReadPlayerID();
			ReadTeamID();
			PlayerAssigner.instance.OtherPlayerWasCreated();
		}
		else
		{
			int num = 0;
			if (!PhotonNetwork.OfflineMode)
			{
				try
				{
					num = 0;
					PlayerFace playerFace = CharacterCreatorHandler.instance.selectedPlayerFaces[num];
					data.view.RPC("RPCA_SetFace", RpcTarget.All, playerFace.eyeID, playerFace.eyeOffset, playerFace.mouthID, playerFace.mouthOffset, playerFace.detailID, playerFace.detailOffset, playerFace.detail2ID, playerFace.detail2Offset);
				}
				catch
				{
				}
			}
			else if (GM_ArmsRace.instance != null)
			{
				GM_ArmsRace instance = GM_ArmsRace.instance;
				instance.StartGameAction = (Action)Delegate.Combine(instance.StartGameAction, new Action(GetFaceOffline));
			}
		}
		PlayerManager.instance.PlayerJoined(this);
	}

	public void GetFaceOffline()
	{
		PlayerFace playerFace = CharacterCreatorHandler.instance.selectedPlayerFaces[playerID];
		data.view.RPC("RPCA_SetFace", RpcTarget.All, playerFace.eyeID, playerFace.eyeOffset, playerFace.mouthID, playerFace.mouthOffset, playerFace.detailID, playerFace.detailOffset, playerFace.detail2ID, playerFace.detail2Offset);
	}

	[PunRPC]
	public void RPCA_SetFace(int eyeID, Vector2 eyeOffset, int mouthID, Vector2 mouthOffset, int detailID, Vector2 detailOffset, int detail2ID, Vector2 detail2Offset)
	{
		PlayerFace face = PlayerFace.CreateFace(eyeID, eyeOffset, mouthID, mouthOffset, detailID, detailOffset, detail2ID, detail2Offset);
		GetComponentInChildren<CharacterCreatorItemEquipper>().EquipFace(face);
	}

	internal void Call_AllGameFeel(Vector2 vector2)
	{
		data.view.RPC("RPCA_AllGameFeel", RpcTarget.All, vector2);
	}

	[PunRPC]
	internal void RPCA_AllGameFeel(Vector2 vector2)
	{
		GamefeelManager.instance.AddGameFeel(vector2);
	}

	public void AssignPlayerID(int ID)
	{
		playerID = ID;
		SetColors();
		if (!PhotonNetwork.OfflineMode)
		{
			ExitGames.Client.Photon.Hashtable customProperties = PhotonNetwork.LocalPlayer.CustomProperties;
			if (customProperties.ContainsKey("PlayerID"))
			{
				customProperties["PlayerID"] = playerID;
			}
			else
			{
				customProperties.Add("PlayerID", playerID);
			}
			PhotonNetwork.LocalPlayer.SetCustomProperties(customProperties);
		}
	}

	internal float GetRadius()
	{
		return 5f;
	}

	private void ReadPlayerID()
	{
		if (!PhotonNetwork.OfflineMode)
		{
			playerID = (int)data.view.Owner.CustomProperties["PlayerID"];
			SetColors();
		}
	}

	public void AssignTeamID(int ID)
	{
		teamID = ID;
		if (!PhotonNetwork.OfflineMode)
		{
			ExitGames.Client.Photon.Hashtable customProperties = PhotonNetwork.LocalPlayer.CustomProperties;
			if (customProperties.ContainsKey("TeamID"))
			{
				customProperties["TeamID"] = playerID;
			}
			else
			{
				customProperties.Add("TeamID", teamID);
			}
			PhotonNetwork.LocalPlayer.SetCustomProperties(customProperties);
		}
	}

	private void ReadTeamID()
	{
		if (!PhotonNetwork.OfflineMode)
		{
			teamID = (int)data.view.Owner.CustomProperties["TeamID"];
		}
	}

	public void SetColors()
	{
		SetTeamColor.TeamColorThis(base.gameObject, PlayerSkinBank.GetPlayerSkinColors(playerID));
	}

	public PlayerSkin GetTeamColors()
	{
		return PlayerSkinBank.GetPlayerSkinColors(playerID);
	}

	internal void FullReset()
	{
		data.weaponHandler.NewGun();
		data.stats.ResetStats();
		data.block.ResetStats();
	}
}
