	public Vector2 velocity;

	public ProjectileHit projectileHit;

	public MoveTransform projectileMovement;
}
public class PlayerAPI : MonoBehaviour
{
	public Player player;

	public CharacterData data;

	private GeneralInput input;

	private bool movedThisFrame;

	private bool attackedThisFrame;

	private bool blockedThisFrame;

	private void Awake()
	{
		player = GetComponent<Player>();
		data = GetComponent<CharacterData>();
		input = GetComponent<GeneralInput>();
	}

	public void Move(Vector2 direction)
	{
		direction = Vector2.ClampMagnitude(direction, 1f);
		movedThisFrame = true;
		data.input.direction = direction;
	}

	public void Jump()
	{
		data.jump.Jump();
	}

	public void Attack()
	{
		attackedThisFrame = true;
		data.input.shootWasPressed = true;
		data.input.shootIsPressed = true;
	}

	public void Block()
	{
		data.input.shieldWasPressed = true;
	}

	public void SetAimDirection(Vector2 direction)
	{
		data.input.aimDirection = direction;
	}

	public void AimForOtherPlayer()
	{
		Player otherPlayer = PlayerManager.instance.GetOtherPlayer(player);
		if ((bool)otherPlayer)
		{
			data.input.aimDirection = otherPlayer.transform.position - base.transform.position;
		}
	}

	public Vector2 TowardsOtherPlayer()
	{
		if (PlayerManager.instance.players.Count < 2)
		{
			return Vector2.zero;
		}
		return PlayerManager.instance.GetOtherPlayer(player).transform.position - base.transform.position;
	}

	public RaycastHit2D RayCastDirection(Vector2 direction, float distance)
	{
		return Physics2D.Raycast(base.transform.position, direction, distance);
	}

	public bool CheckGroundBelow(Vector2 pos, float range)
	{
		return data.ThereIsGroundBelow(pos, range);
	}

	public bool CanBlock()
	{
		return !data.block.IsOnCD();
	}

	public Player GetOtherPlayer()
	{
		return PlayerManager.instance.GetOtherPlayer(player);
	}

	public Vector3 OtherPlayerPosition()
	{
		Player otherPlayer = PlayerManager.instance.GetOtherPlayer(player);
		if ((bool)otherPlayer)
		{
			return otherPlayer.transform.position;
		}
		return Vector3.zero;
	}

	public Vector3 PlayerPosition()
	{
		return base.transform.position;
	}

	public List<BulletWrapper> GetAllBullets()
	{
		List<BulletWrapper> list = new List<BulletWrapper>();
		ProjectileHit[] array = UnityEngine.Object.FindObjectsOfType<ProjectileHit>();
		for (int i = 0; i < array.Length; i++)
		{
			BulletWrapper bulletWrapper = new BulletWrapper();
			bulletWrapper.projectileHit = array[i].GetComponent<ProjectileHit>();
			bulletWrapper.projectileMovement = array[i].GetComponent<MoveTransform>();
			bulletWrapper.damage = bulletWrapper.projectileHit.damage;
			bulletWrapper.velocity = bulletWrapper.projectileMovement.velocity;
			list.Add(bulletWrapper);
		}
		return list;
	}

	public SpawnedAttack[] GetAllSpawnedAttacks()
	{
		return UnityEngine.Object.FindObjectsOfType<SpawnedAttack>();
	}

	public bool CanShoot()
	{
		return player.data.weaponHandler.gun.IsReady();
	}

	public BulletWrapper GetMyBullet()
	{
		BulletWrapper bulletWrapper = new BulletWrapper();
		GameObject objectToSpawn = player.data.weaponHandler.gun.projectiles[0].objectToSpawn;
		MoveTransform component = objectToSpawn.GetComponent<MoveTransform>();
		ProjectileHit component2 = objectToSpawn.GetComponent<ProjectileHit>();
		bulletWrapper.projectileMovement = component;
		bulletWrapper.projectileHit = component2;
		bulletWrapper.damage = component2.damage;
		bulletWrapper.velocity = player.data.aimDirection.normalized * component.localForce.magnitude + component.worldForce;
		return bulletWrapper;
	}

	private void Update()
	{
		if (blockedThisFrame)
		{
			blockedThisFrame = false;
		}
		else
		{
			data.input.shieldWasPressed = false;
		}
		if (movedThisFrame)
		{
			movedThisFrame = false;
		}
		else
		{
			data.input.direction = Vector3.zero;
		}
		if (attackedThisFrame)
		{
			attackedThisFrame = false;
			return;
		}
		data.input.shootWasPressed = false;
		data.input.shootIsPressed = false;
	}
}
public class PlayerAssigner : MonoBehaviour
{
	public GameObject player1AI;

	public GameObject player2AI;

	public static PlayerAssigner instance;

	public GameObject playerPrefab;

	public int maxPlayers = 4;

	public List<CharacterData> players = new List<CharacterData>(4);

	private bool playersCanJoin;

	private int playerIDToSet = -1;

	private int teamIDToSet = -1;

	private bool waitingForRegisterResponse;

	private bool hasCreatedLocalPlayer;

	private void Awake()
	{
		instance = this;
	}

	internal void SetPlayersCanJoin(bool canJoin)
	{
		playersCanJoin = canJoin;
	}

	private void Start()
	{
		InputManager.OnDeviceDetached += OnDeviceDetached;
	}

	private void LateUpdate()
	{
		if (!playersCanJoin || players.Count >= maxPlayers || DevConsole.isTyping)
		{
			return;
		}
		if (Input.GetKeyDown(KeyCode.B) && !GameManager.lockInput)
		{
			StartCoroutine(CreatePlayer(null, isAI: true));
		}
		if (Input.GetKey(KeyCode.Space))
		{
			bool flag = true;
			for (int i = 0; i < players.Count; i++)
			{
				if (players[i].playerActions.Device == null)
				{
					flag = false;
				}
			}
			if (flag)
			{
				StartCoroutine(CreatePlayer(null));
			}
		}
		for (int j = 0; j < InputManager.ActiveDevices.Count; j++)
		{
			InputDevice inputDevice = InputManager.ActiveDevices[j];
			if (JoinButtonWasPressedOnDevice(inputDevice) && ThereIsNoPlayerUsingDevice(inputDevice))
			{
				StartCoroutine(CreatePlayer(inputDevice));
			}
		}
	}

	private bool JoinButtonWasPressedOnDevice(InputDevice inputDevice)
	{
		if (!inputDevice.Action1.WasPressed && !inputDevice.Action2.WasPressed && !inputDevice.Action3.WasPressed)
		{
			return inputDevice.Action4.WasPressed;
		}
		return true;
	}

	private CharacterData FindPlayerUsingDevice(InputDevice inputDevice)
	{
		int count = players.Count;
		for (int i = 0; i < count; i++)
		{
			CharacterData characterData = players[i];
			if (characterData.playerActions.Device == inputDevice)
			{
				return characterData;
			}
		}
		return null;
	}

	public void ClearPlayers()
	{
		players.Clear();
	}

	private bool ThereIsNoPlayerUsingDevice(InputDevice inputDevice)
	{
		return FindPlayerUsingDevice(inputDevice) == null;
	}

	private void OnDeviceDetached(InputDevice inputDevice)
	{
		CharacterData characterData = FindPlayerUsingDevice(inputDevice);
		if (characterData != null)
		{
			RemovePlayer(characterData);
		}
	}

	[PunRPC]
	public void RPCM_RequestTeamAndPlayerID(int askingPlayer)
	{
		int count = PlayerManager.instance.players.Count;
		int num = ((count % 2 != 0) ? 1 : 0);
		GetComponent<PhotonView>().RPC("RPC_ReturnPlayerAndTeamID", PhotonNetwork.CurrentRoom.GetPlayer(askingPlayer), count, num);
		waitingForRegisterResponse = true;
	}

	[PunRPC]
	public void RPC_ReturnPlayerAndTeamID(int teamId, int playerID)
	{
		waitingForRegisterResponse = false;
		playerIDToSet = playerID;
		teamIDToSet = teamId;
	}

	public void OtherPlayerWasCreated()
	{
		waitingForRegisterResponse = false;
	}

	public IEnumerator CreatePlayer(InputDevice inputDevice, bool isAI = false)
	{
		if (waitingForRegisterResponse || (!PhotonNetwork.OfflineMode && hasCreatedLocalPlayer) || players.Count >= maxPlayers)
		{
			yield break;
		}
		if (!PhotonNetwork.OfflineMode && !PhotonNetwork.IsMasterClient)
		{
			GetComponent<PhotonView>().RPC("RPCM_RequestTeamAndPlayerID", RpcTarget.MasterClient, PhotonNetwork.LocalPlayer.ActorNumber);
			waitingForRegisterResponse = true;
		}
		while (waitingForRegisterResponse)
		{
			yield return null;
		}
		if (!PhotonNetwork.OfflineMode)
		{
			if (PhotonNetwork.IsMasterClient)
			{
				playerIDToSet = PlayerManager.instance.players.Count;
				teamIDToSet = ((playerIDToSet % 2 != 0) ? 1 : 0);
			}
		}
		else
		{
			playerIDToSet = PlayerManager.instance.players.Count;
			teamIDToSet = ((playerIDToSet % 2 != 0) ? 1 : 0);
		}
		hasCreatedLocalPlayer = true;
		SoundPlayerStatic.Instance.PlayPlayerAdded();
		Vector3 position = Vector3.up * 100f;
		CharacterData component = PhotonNetwork.Instantiate(playerPrefab.name, position, Quaternion.identity, 0).GetComponent<CharacterData>();
		if (isAI)
		{
			GameObject original = player1AI;
			if (players.Count > 0)
			{
				original = player2AI;
			}
			component.GetComponent<CharacterData>().SetAI();
			UnityEngine.Object.Instantiate(original, component.transform.position, component.transform.rotation, component.transform);
		}
		else
		{
			if (inputDevice != null)
			{
				component.input.inputType = GeneralInput.InputType.Controller;
				component.playerActions = PlayerActions.CreateWithControllerBindings();
			}
			else
			{
				component.input.inputType = GeneralInput.InputType.Keyboard;
				component.playerActions = PlayerActions.CreateWithKeyboardBindings();
			}
			component.playerActions.Device = inputDevice;
		}
		players.Add(component);
		RegisterPlayer(component, teamIDToSet, playerIDToSet);
	}

	private void RegisterPlayer(CharacterData player, int teamID, int playerID)
	{
		PlayerManager.RegisterPlayer(player.player);
		player.player.AssignPlayerID(playerID);
		player.player.AssignTeamID(teamID);
	}

	private void RemovePlayer(CharacterData player)
	{
	}

	private void AssignPlayer(CharacterData player, InputDevice device)
	{
	}
}
[Serializable]
public class AudioModifyer
{
	public CardAudioModifier modifier;

	public int stacks;
}
public class PlayerAudioModifyers : MonoBehaviour
{
	public List<AudioModifyer> modifyers = new List<AudioModifyer>();

	public static List<CardAudioModifier> activeModifyer = new List<CardAudioModifier>();

	public void AddToStack(CardAudioModifier mod)
	{
		int num = -1;
		for (int i = 0; i < modifyers.Count; i++)
		{
			if (modifyers[i].modifier.stackName == mod.stackName)
			{
				num = i;
				break;
			}
		}
		if (num != -1)
		{
			modifyers[num].stacks++;
			return;
		}
		AudioModifyer audioModifyer = new AudioModifyer();
		audioModifyer.modifier = new CardAudioModifier();
		audioModifyer.modifier.stackName = mod.stackName;
		audioModifyer.modifier.stackType = mod.stackType;
		audioModifyer.stacks = 1;
		activeModifyer.Add(audioModifyer.modifier);
		modifyers.Add(audioModifyer);
	}

	public void SetStacks()
	{
		for (int i = 0; i < activeModifyer.Count; i++)
		{
			_ = activeModifyer[i].stackType;
			_ = 1;
			_ = activeModifyer[i].stackType;
		}
		for (int j = 0; j < modifyers.Count; j++)
		{
			_ = modifyers[j].modifier.stackType;
			_ = 1;
			_ = modifyers[j].modifier.stackType;
		}
	}
}
public class PlayerChat : MonoBehaviour
{
	public float spring = 15f;

	public float damper = 15f;

	public float impulse;

	public float targetScale;

	private TextMeshProUGUI messageText;

	private ScaleShake scaleShake;

	private float currentScale;

	private float vel;

	public Transform target;

	private Screenshaker shaker;

	private float sinceType;

	public float shakeAmount;

	public float shakeSpeed = 1f;

	private void Start()
	{
		messageText = target.GetComponentInChildren<TextMeshProUGUI>();
		shaker = target.GetComponentInChildren<Screenshaker>();
		target.transform.localScale = Vector3.zero;
	}

	private void Update()
	{
		sinceType -= Time.unscaledDeltaTime;
		if (sinceType < 0f)
		{
			targetScale = 0f;
		}
		else
		{
			targetScale = 1f;
		}
		vel = FRILerp.Lerp(vel, (targetScale - currentScale) * spring, damper);
		currentScale += Time.unscaledDeltaTime * vel;
		if (currentScale < 0f)
		{
			vel = 0f;
			currentScale = 0f;
		}
		target.transform.localScale = Vector3.one * currentScale;
	}

	public void Send(string message)
	{
		message = ChatFilter.instance.FilterMessage(message);
		messageText.text = message;
		if (sinceType > 0f)
		{
			vel += impulse;
		}
		sinceType = 2f + (float)message.Length * 0.05f;
		targetScale = 1f;
		if (message.ToUpper() == message)
		{
			StartCoroutine(ShakeOverTime(sinceType));
		}
	}

	private IEnumerator ShakeOverTime(float t)
	{
		float a = t;
		while (a > 0f)
		{
			shaker.OnUIGameFeel(shakeAmount * UnityEngine.Random.insideUnitCircle);
			a -= Time.unscaledDeltaTime * shakeSpeed;
			yield return null;
		}
	}
}
