public class PlayerInRangeTrigger : MonoBehaviour
{
	public enum TargetType
	{
		Any,
		OtherPlayer
	}

	public TargetType targetType;

	public float range = 5f;

	public float cooldown;

	public bool repeating;

	private float counter;

	private bool done;

	[HideInInspector]
	public bool inRange;

	public UnityEvent triggerEvent;

	[HideInInspector]
	public Player target;

	private Player ownPlayer;

	public bool scaleWithRange;

	private void Start()
	{
		ownPlayer = base.transform.root.GetComponent<Player>();
		if (!ownPlayer)
		{
			ownPlayer = base.transform.root.GetComponentInParent<SpawnedAttack>().spawner;
		}
		if (scaleWithRange)
		{
			range *= base.transform.localScale.x;
		}
	}

	private void Update()
	{
		counter += TimeHandler.deltaTime;
		inRange = false;
		target = null;
		if (done)
		{
			return;
		}
		Player player = null;
		if (targetType == TargetType.OtherPlayer)
		{
			player = PlayerManager.instance.GetOtherPlayer(ownPlayer);
		}
		if (targetType == TargetType.Any)
		{
			player = PlayerManager.instance.GetClosestPlayer(base.transform.position);
		}
		if (PlayerManager.instance.CanSeePlayer(base.transform.position, player).canSee && Vector3.Distance(base.transform.position, player.transform.position) < range * base.transform.root.localScale.x && !player.data.dead && counter >= cooldown)
		{
			counter = 0f;
			triggerEvent.Invoke();
			inRange = true;
			target = player;
			if (!repeating)
			{
				done = true;
			}
		}
	}
}
public class PlayerJump : MonoBehaviour
{
	private CharacterData data;

	public float upForce;

	private CharacterStatModifiers stats;

	public ParticleSystem[] jumpPart;

	public float sideForce = 1f;

	public Action JumpAction;

	private void Start()
	{
		stats = GetComponent<CharacterStatModifiers>();
		data = GetComponent<CharacterData>();
	}

	private void Update()
	{
		if (data.input.jumpWasPressed)
		{
			Jump();
		}
		if (data.input.jumpIsPressed && data.sinceJump < 0.2f)
		{
			data.playerVel.AddForce(Vector2.up * TimeHandler.deltaTime * 2f * data.stats.jump * data.playerVel.mass * (1f - stats.GetSlow()) * upForce, ForceMode2D.Force);
		}
	}

	public void Jump(bool forceJump = false, float multiplier = 1f)
	{
		if (!forceJump && (data.sinceJump < 0.1f || (data.currentJumps <= 0 && data.sinceWallGrab > 0.1f)))
		{
			return;
		}
		Vector3 vector = Vector3.up;
		Vector3 vector2 = data.groundPos;
		if (JumpAction != null)
		{
			JumpAction();
		}
		bool flag = false;
		if (data.sinceWallGrab < 0.1f && !data.isGrounded)
		{
			vector = Vector2.up * 0.8f + data.wallNormal * 0.4f;
			vector2 = data.wallPos;
			data.currentJumps = data.jumps;
			flag = true;
		}
		else
		{
			if (data.sinceGrounded > 0.05f)
			{
				vector2 = base.transform.position;
			}
			data.currentJumps = data.jumps;
		}
		if (data.playerVel.velocity.y < 0f)
		{
			data.playerVel.velocity = new Vector2(data.playerVel.velocity.x, 0f);
		}
		data.sinceGrounded = 0f;
		data.sinceJump = 0f;
		data.isGrounded = false;
		data.isWallGrab = false;
		data.currentJumps--;
		data.playerVel.AddForce(vector * multiplier * 0.01f * data.stats.jump * data.playerVel.mass * (1f - stats.GetSlow()) * upForce, ForceMode2D.Impulse);
		if (!flag)
		{
			data.playerVel.AddForce(Vector2.right * multiplier * sideForce * 0.01f * data.stats.jump * data.playerVel.mass * (1f - stats.GetSlow()) * data.playerVel.velocity.x, ForceMode2D.Impulse);
		}
		for (int i = 0; i < jumpPart.Length; i++)
		{
			jumpPart[i].transform.position = new Vector3(vector2.x, vector2.y, 5f) - vector * 0f;
			jumpPart[i].transform.rotation = Quaternion.LookRotation(data.playerVel.velocity);
			jumpPart[i].Play();
		}
	}
}
public class CanSeeInfo
{
	public bool canSee;

	public Vector2 hitPoint;

	public float distance;
}
public class PlayerManager : MonoBehaviour
{
	[Header("Sounds")]
	public SoundEvent[] soundCharacterSpawn;

	public static PlayerManager instance;

	public LayerMask canSeePlayerMask;

	public List<Player> players = new List<Player>();

	public PhotonView view;

	private Action<Player, int> PlayerDiedAction;

	private bool playersShouldBeActive;

	public AnimationCurve playerMoveCurve;

	public Action<Player> PlayerJoinedAction { get; internal set; }

	private void Awake()
	{
		instance = this;
		view = GetComponent<PhotonView>();
	}

	public Player GetOtherPlayer(Player asker)
	{
		return GetClosestPlayerInTeam(asker.transform.position, GetOtherTeam(asker.teamID));
	}

	public Player GetClosestPlayer(Vector2 refPos, bool needVision = false)
	{
		Player result = null;
		float num = float.PositiveInfinity;
		for (int i = 0; i < players.Count; i++)
		{
			if (!players[i].data.dead)
			{
				float num2 = Vector2.Distance(refPos, players[i].data.playerVel.position);
				if ((!needVision || CanSeePlayer(refPos, players[i]).canSee) && num2 < num)
				{
					num = num2;
					result = players[i];
				}
			}
		}
		return result;
	}

	internal Player GetPlayerWithActorID(int actorID)
	{
		for (int i = 0; i < players.Count; i++)
		{
			if (players[i].data.view.OwnerActorNr == actorID)
			{
				return players[i];
			}
		}
		return null;
	}

	public Player GetClosestPlayerInTeam(Vector3 position, int team, bool needVision = false)
	{
		float num = float.MaxValue;
		Player[] playersInTeam = GetPlayersInTeam(team);
		Player result = null;
		for (int i = 0; i < playersInTeam.Length; i++)
		{
			if (!players[i].data.dead)
			{
				float num2 = Vector2.Distance(position, playersInTeam[i].transform.position);
				if ((!needVision || CanSeePlayer(position, playersInTeam[i]).canSee) && num2 < num)
				{
					num = num2;
					result = playersInTeam[i];
				}
			}
		}
		return result;
	}

	public Player GetClosestPlayer(Vector2 refPos, Vector2 forward)
	{
		Player result = null;
		float num = float.PositiveInfinity;
		for (int i = 0; i < players.Count; i++)
		{
			if (!players[i].data.dead && CanSeePlayer(refPos, players[i]).canSee)
			{
				float num2 = Vector2.Distance(refPos, players[i].data.playerVel.position);
				num2 += Vector2.Angle(forward, players[i].data.playerVel.position - refPos);
				if (num2 < num)
				{
					num = num2;
					result = players[i];
				}
			}
		}
		return result;
	}

	public CanSeeInfo CanSeePlayer(Vector2 from, Player player)
	{
		CanSeeInfo canSeeInfo = new CanSeeInfo();
		canSeeInfo.canSee = true;
		canSeeInfo.distance = float.PositiveInfinity;
		if (!player)
		{
			canSeeInfo.canSee = false;
			return canSeeInfo;
		}
		RaycastHit2D[] array = Physics2D.RaycastAll(from, (player.data.playerVel.position - from).normalized, Vector2.Distance(from, player.data.playerVel.position), canSeePlayerMask);
		for (int i = 0; i < array.Length; i++)
		{
			if ((bool)array[i].transform && !array[i].transform.root.GetComponent<SpawnedAttack>() && !array[i].transform.root.GetComponent<Player>() && array[i].distance < canSeeInfo.distance)
			{
				canSeeInfo.canSee = false;
				canSeeInfo.hitPoint = array[i].point;
				canSeeInfo.distance = array[i].distance;
			}
		}
		return canSeeInfo;
	}

	internal Player GetPlayerWithID(int playerID)
	{
		for (int i = 0; i < players.Count; i++)
		{
