		for (int i = 0; i < players.Count; i++)
		{
			if (players[i].teamID == 0 && !players[i].data.dead)
			{
				flag = true;
			}
			if (players[i].teamID == 1 && !players[i].data.dead)
			{
				flag2 = true;
			}
		}
		int num = 0;
		if (flag)
		{
			num++;
		}
		if (flag2)
