public class RayCastTrail : MonoBehaviour
{
	public LayerMask mask;

	public LayerMask playerMask;

	public LayerMask ignoreWallsMask;

	public int teamID = -1;

	private float timeAtSpawn;

	public float size;

	public float extraSize;

	private MoveTransform move;

	private Vector3 lastPos;

	private RayHit rayHit;

	private Rigidbody2D ignoredRig;

	private void Awake()
	{
		timeAtSpawn = Time.time;
	}

	private void Start()
	{
		rayHit = GetComponent<RayHit>();
		ProjectileHit component = GetComponent<ProjectileHit>();
		if ((bool)component)
		{
			size = Mathf.Clamp(Mathf.Pow(component.damage, 0.85f) / 400f, 0f, 100f) + 0.3f + extraSize;
		}
		move = GetComponent<MoveTransform>();
		lastPos = base.transform.position;
	}

	private void OnEnable()
	{
		lastPos = base.transform.position;
	}

	private void Update()
	{
		RaycastHit2D[] first = Physics2D.RaycastAll(lastPos, base.transform.position - lastPos, Vector3.Distance(base.transform.position, lastPos), mask);
		RaycastHit2D[] second = Physics2D.CircleCastAll(lastPos, size, base.transform.position - lastPos, Vector3.Distance(base.transform.position, lastPos), playerMask);
		RaycastHit2D[] array = first.Concat(second).ToArray();
		RaycastHit2D raycastHit2D = new RaycastHit2D
		{
			distance = float.PositiveInfinity
		};
		for (int i = 0; i < array.Length; i++)
		{
			if (!array[i] || array[i].transform.root == base.transform.root)
			{
				continue;
			}
			Player component = array[i].transform.root.GetComponent<Player>();
			if ((!component || component.playerID != teamID || !(timeAtSpawn + 0.2f >= Time.time)) && (!ignoredRig || !(ignoredRig == array[i].rigidbody)))
			{
				ProjectileHitSurface component2 = array[i].collider.GetComponent<ProjectileHitSurface>();
				if ((!component2 || component2.HitSurface(HitInfo.GetHitInfo(array[i]), base.gameObject) != ProjectileHitSurface.HasToStop.HasToStop) && array[i].distance < raycastHit2D.distance)
				{
					raycastHit2D = array[i];
				}
			}
		}
		if ((bool)raycastHit2D.transform)
		{
			rayHit.Hit(HitInfo.GetHitInfo(raycastHit2D));
		}
		if ((bool)GridVisualizer.instance)
		{
			GridVisualizer.instance.BulletCall(base.transform.position);
		}
		lastPos = base.transform.position;
	}

	public void WasBlocked()
	{
		timeAtSpawn = 0f;
	}

	public void MoveRay()
	{
		lastPos = base.transform.position;
	}

	public void IgnoreRigFor(Rigidbody2D rig, float time)
	{
		StartCoroutine(DoIgnoreRigFor(rig, time));
	}

	private IEnumerator DoIgnoreRigFor(Rigidbody2D rig, float time)
	{
		ignoredRig = rig;
		yield return new WaitForSeconds(time);
		ignoredRig = null;
	}
}
public abstract class RayHit : MonoBehaviour
{
	public abstract void Hit(HitInfo hit, bool forceCall = false);
}
public class RayHitBash : RayHitEffect
{
	public float triggerChancePerTenDamage = 0.1f;

	public float baseTriggerChance = 0.2f;

	[Space(15f)]
	public float stunMultiplier = 1f;

	public float stunTimePerTenDamage = 0.1f;

	public float baseStunTime = 1f;

	public bool cannotPermaStun;

	[Space(15f)]
	public float stunTimeThreshold = 0.2f;

	public float stunTimeExponent = 1f;

	public float multiplierPerTenMeterTravelled;

	private MoveTransform move;

	private float multiplier = 1f;

	private void Start()
	{
		move = GetComponentInParent<MoveTransform>();
		multiplier = base.transform.localScale.x;
	}

	public override HasToReturn DoHitEffect(HitInfo hit)
	{
		if (!hit.transform)
		{
			return HasToReturn.canContinue;
		}
		StunHandler component = hit.transform.GetComponent<StunHandler>();
		if ((bool)component)
		{
			ProjectileHit componentInParent = GetComponentInParent<ProjectileHit>();
			float num = 25f;
			if ((bool)componentInParent)
			{
				num = componentInParent.damage;
			}
			float num2 = triggerChancePerTenDamage * num * 0.1f;
			num2 += baseTriggerChance;
			if (UnityEngine.Random.value < num2)
			{
				float num3 = baseStunTime + stunTimePerTenDamage * num * 0.1f;
				SetMultiplier();
				num3 *= stunMultiplier;
				num3 = Mathf.Pow(num3, stunTimeExponent);
				num3 *= multiplier;
				if (cannotPermaStun)
				{
					num3 = Mathf.Clamp(num3, 0f, GetComponentInParent<SpawnedAttack>().spawner.data.weaponHandler.gun.attackSpeed * GetComponentInParent<SpawnedAttack>().spawner.data.stats.attackSpeedMultiplier + 0.3f);
				}
				if (num3 > stunTimeThreshold)
				{
					component.AddStun(num3);
				}
			}
		}
		return HasToReturn.canContinue;
	}

	private void SetMultiplier()
	{
		float distanceTravelled = move.distanceTravelled;
		if (multiplierPerTenMeterTravelled != 0f)
		{
			stunMultiplier = distanceTravelled * multiplierPerTenMeterTravelled * 0.1f;
		}
	}
}
public class RayHitBulletSound : RayHitEffect
{
	[Header("Sound Settings")]
	public bool disableImpact;

	public bool playLocalImpact;

	public SoundEvent soundLocalImpact;

	public bool localImpactVelocityToIntensity;

	private ProjectileHit projectileHit;

	private RayHitReflect rayHitReflect;

	private MoveTransform moveTransform;

	private SoundParameterIntensity soundIntensity = new SoundParameterIntensity();

	private void Start()
	{
		projectileHit = GetComponent<ProjectileHit>();
		rayHitReflect = GetComponent<RayHitReflect>();
		moveTransform = GetComponent<MoveTransform>();
	}

	public override HasToReturn DoHitEffect(HitInfo hit)
	{
		if (disableImpact)
		{
			return HasToReturn.canContinue;
		}
		if (localImpactVelocityToIntensity)
		{
			soundIntensity.intensity = moveTransform.velocity.magnitude;
		}
		if (playLocalImpact)
		{
			if (soundLocalImpact != null && hit.collider != null && hit.collider.tag != "Player")
			{
				if (localImpactVelocityToIntensity)
				{
					SoundManager.Instance.PlayAtPosition(soundLocalImpact, SoundManager.Instance.GetTransform(), hit.point, soundIntensity);
				}
				else
				{
					SoundManager.Instance.PlayAtPosition(soundLocalImpact, SoundManager.Instance.GetTransform(), hit.point);
				}
			}
		}
		else
		{
			projectileHit.ownPlayer.data.weaponHandler.gun.soundGun.PlayImpact(hit, rayHitReflect);
		}
		return HasToReturn.canContinue;
	}
}
public enum HasToReturn
{
	hasToReturn,
	canContinue,
	hasToReturnNow
}
public abstract class RayHitEffect : MonoBehaviour
{
	public int priority;

	public abstract HasToReturn DoHitEffect(HitInfo hit);
}
public class RayHitPoison : RayHitEffect
{
	[Header("Sounds")]
	public SoundEvent soundEventDamageOverTime;

	[Header("Settings")]
	public float time = 2f;

	public float interval = 0.5f;

	public Color color = Color.red;

	private void Start()
	{
		GetComponentInParent<ProjectileHit>().bulletCanDealDeamage = false;
	}

	public override HasToReturn DoHitEffect(HitInfo hit)
	{
		if (!hit.transform)
		{
			return HasToReturn.canContinue;
		}
		RayHitPoison[] componentsInChildren = base.transform.root.GetComponentsInChildren<RayHitPoison>();
		ProjectileHit componentInParent = GetComponentInParent<ProjectileHit>();
		DamageOverTime component = hit.transform.GetComponent<DamageOverTime>();
		if ((bool)component)
		{
			component.TakeDamageOverTime(componentInParent.damage * base.transform.forward / componentsInChildren.Length, base.transform.position, time, interval, color, soundEventDamageOverTime, GetComponentInParent<ProjectileHit>().ownWeapon, GetComponentInParent<ProjectileHit>().ownPlayer);
		}
		return HasToReturn.canContinue;
	}
}
public class RayHitReflect : RayHitEffect
{
	private MoveTransform move;

	private ProjectileHit projHit;

	public int reflects = 1;

	public float speedM = 1f;

	public float dmgM = 1f;

	[HideInInspector]
	public float timeOfBounce = -10000f;

	public Action<HitInfo> reflectAction;

	private void Start()
	{
		move = GetComponent<MoveTransform>();
		projHit = GetComponent<ProjectileHit>();
	}

	public override HasToReturn DoHitEffect(HitInfo hit)
	{
		if ((bool)hit.transform && (bool)hit.transform.GetComponent<Player>())
		{
			reflects -= 10;
		}
		if (reflects <= 0)
		{
			return HasToReturn.canContinue;
		}
		if (reflectAction != null)
		{
			reflectAction(hit);
		}
		move.velocity = Vector2.Reflect(move.velocity, hit.normal);
		move.velocity *= speedM;
		projHit.damage *= dmgM;
		projHit.shake *= dmgM;
		if (dmgM > 1f)
		{
			float num = dmgM - 1f;
			num *= 0.6f;
			dmgM = num + 1f;
			ScaleTrailFromDamage componentInChildren = GetComponentInChildren<ScaleTrailFromDamage>();
			if ((bool)componentInChildren)
			{
				componentInChildren.Rescale();
			}
		}
		timeOfBounce = Time.time;
		base.transform.position = (Vector3)hit.point + move.velocity.normalized * 0.1f;
		reflects--;
		return HasToReturn.hasToReturn;
	}
}
