public class RoundCounter : MonoBehaviour
{
	public int p1Rounds;

	public int p2Rounds;

	public int p1Points;

	public int p2Points;

	public Transform p1Parent;

	public Transform p2Parent;

	public Color offColor;

	public Populate p1Populate;

	public Populate p2Populate;

	private int roundsNeeded;

	private void Start()
	{
		p1Parent.gameObject.SetActive(value: true);
		p2Parent.gameObject.SetActive(value: true);
	}

	public void UpdateRounds(int r1, int r2)
	{
		p1Rounds = r1;
		p2Rounds = r2;
		ReDraw();
	}

	private void Clear()
	{
		for (int i = 0; i < p1Parent.childCount; i++)
		{
			if (p1Populate.transform.GetChild(i).gameObject.activeSelf)
			{
				UnityEngine.Object.Destroy(p1Populate.transform.GetChild(i).gameObject);
			}
		}
		for (int j = 0; j < p2Parent.childCount; j++)
		{
			if (p2Populate.transform.GetChild(j).gameObject.activeSelf)
			{
				UnityEngine.Object.Destroy(p2Populate.transform.GetChild(j).gameObject);
			}
		}
	}

	private void Populate()
	{
		p1Populate.times = roundsNeeded;
		p1Populate.DoPopulate();
		p2Populate.times = roundsNeeded;
		p2Populate.DoPopulate();
	}

	public void UpdatePoints(int p1, int p2)
	{
		p1Points = p1;
		p2Points = p2;
		ReDraw();
	}

	private void ReDraw()
	{
		for (int i = 0; i < p1Parent.childCount; i++)
		{
			if (p1Rounds + p1Points > i)
			{
				p1Parent.GetChild(i).GetComponentInChildren<Image>().color = PlayerSkinBank.GetPlayerSkinColors(0).winText;
				if (p1Rounds > i)
				{
					p1Parent.GetChild(i).localScale = Vector3.one;
				}
			}
			else
			{
				p1Parent.GetChild(i).GetComponentInChildren<Image>().color = offColor;
				p1Parent.GetChild(i).localScale = Vector3.one * 0.3f;
			}
		}
		for (int j = 0; j < p2Parent.childCount; j++)
		{
			if (p2Rounds + p2Points > j)
			{
				p2Parent.GetChild(j).GetComponentInChildren<Image>().color = PlayerSkinBank.GetPlayerSkinColors(1).winText;
				if (p2Rounds > j)
				{
					p2Parent.GetChild(j).localScale = Vector3.one;
				}
			}
			else
			{
				p2Parent.GetChild(j).GetComponentInChildren<Image>().color = offColor;
				p2Parent.GetChild(j).localScale = Vector3.one * 0.3f;
			}
		}
	}

	internal Vector3 GetPointPos(int teamID)
	{
		if (teamID == 0)
		{
			return p1Parent.GetChild(p1Rounds).transform.position;
		}
		return p2Parent.GetChild(p2Rounds).transform.position;
	}

	internal void SetNumberOfRounds(int roundsToWinGame)
	{
		roundsNeeded = roundsToWinGame;
		Clear();
		Populate();
		ReDraw();
	}
}
public class RunSmoke : MonoBehaviour
{
	private CharacterData data;

	private ParticleSystem part;

	private float c;

	private bool groundedLastFrame;

	private ParticleSystem.MainModule partVel;

	private bool didTryToEmit;

	private Vector3 vel;

	private void Start()
	{
		part = GetComponent<ParticleSystem>();
		data = GetComponentInParent<CharacterData>();
		partVel = part.main;
	}

	private void Update()
	{
		didTryToEmit = false;
		if (data.isGrounded && Mathf.Abs(data.playerVel.velocity.x) > 5f)
		{
			base.transform.position = new Vector3(data.transform.position.x, data.groundPos.y, 5f);
			Go();
		}
		else if (data.isWallGrab && data.wallDistance < 0.7f && data.playerVel.velocity.magnitude > 5f)
		{
			base.transform.position = new Vector3(data.wallPos.x, data.transform.position.y, 5f);
			Go();
		}
		if (didTryToEmit)
		{
			vel = Vector3.Lerp(vel, data.playerVel.velocity, TimeHandler.deltaTime * 2f);
		}
		else
		{
			vel = Vector3.Lerp(vel, Vector3.zero, TimeHandler.deltaTime * 10f);
		}
	}

	private void Go()
	{
		didTryToEmit = true;
		c += TimeHandler.deltaTime;
		if (c > 0.02f)
		{
			c = 0f;
			float num = 2f;
			part.transform.rotation = Quaternion.LookRotation(vel);
			partVel.startSpeedMultiplier = data.playerVel.velocity.magnitude * num;
			part.Emit(2);
		}
	}
}
public class Saw : MonoBehaviour
{
	public Player owner;

	public float range = 3f;

	public float damage = 10f;

	public float force;

	public float shake = 1f;

	public ParticleSystem[] parts;

	public Transform sparkTransform;

	private Vector3 forceDir;

	private void Start()
	{
		owner = base.transform.root.GetComponent<SpawnedAttack>().spawner;
	}

	private void Update()
	{
		Player player = null;
		for (int i = 0; i < PlayerManager.instance.players.Count; i++)
		{
			Player player2 = PlayerManager.instance.players[i];
			if (player2 != owner && Vector3.Distance(player2.transform.position, base.transform.transform.position) < range * base.transform.localScale.x)
			{
				player = player2;
			}
		}
		if ((bool)player && PlayerManager.instance.CanSeePlayer(base.transform.position, player).canSee)
		{
			Vector3 normalized = (player.transform.position - base.transform.position).normalized;
			if (damage != 0f)
			{
				player.data.healthHandler.TakeDamage(TimeHandler.deltaTime * damage * normalized, base.transform.position, null, owner);
			}
			if (force != 0f)
			{
				float num = Mathf.Clamp(1f - Vector2.Distance(base.transform.position, player.transform.position) / range, 0f, 1f);
				ForceMultiplier component = player.GetComponent<ForceMultiplier>();
				if ((bool)component)
				{
					num *= component.multiplier;
				}
				forceDir = normalized;
				forceDir.y *= 0.5f;
				player.data.playerVel.AddForce(forceDir * base.transform.localScale.x * num * TimeHandler.deltaTime * force, ForceMode2D.Force);
				player.data.healthHandler.TakeForce(forceDir * num * 0.0005f * TimeHandler.deltaTime * force);
			}
			for (int j = 0; j < parts.Length; j++)
			{
				if (!parts[j].isPlaying)
				{
					parts[j].Play();
				}
			}
			if ((bool)sparkTransform)
			{
				sparkTransform.transform.position = player.transform.position;
				if (normalized != Vector3.zero)
				{
					sparkTransform.rotation = Quaternion.LookRotation(normalized);
				}
			}
			GamefeelManager.GameFeel((normalized + UnityEngine.Random.onUnitSphere).normalized * shake * TimeHandler.deltaTime * 20f);
			return;
		}
		for (int k = 0; k < parts.Length; k++)
		{
			if (parts[k].isPlaying)
			{
				parts[k].Stop();
			}
		}
	}
}
public class ScaleShake : MonoBehaviour
{
	public bool useTimeScale = true;

	public float targetScale = 1f;

	public float multiplier = 1f;

	private float velocity;

	public float drag = 1f;

	public float spring = 1f;

	public float clampVelocity;

	internal float high;

	internal float low;

	private void Update()
	{
		float num = Mathf.Clamp(useTimeScale ? TimeHandler.deltaTime : Time.unscaledDeltaTime, 0f, 0.02f);
		if (clampVelocity != 0f)
		{
			velocity = Mathf.Clamp(velocity, 0f - clampVelocity, clampVelocity);
		}
		velocity += (targetScale - base.transform.localScale.x) * num * 50f * spring;
		velocity -= drag * velocity * 20f * num;
		base.transform.localScale += Vector3.one * (velocity * 10f * num);
	}

	public void AddForce(float force)
	{
		velocity += force * multiplier * 5f;
	}

	public void AddForce()
	{
		velocity += 1f * multiplier * 5f;
	}

	public void SetTarget(float target)
	{
		targetScale = target;
	}

	public void SetHigh()
	{
		targetScale = high;
	}

	public void SetLow()
	{
		targetScale = low;
	}

	public void ScaleOutRootPhoton()
	{
		StartCoroutine(GoAwayOutRootPhoton());
	}

	private IEnumerator GoAwayOutRootPhoton()
	{
		while (base.transform.localScale.x > 0f)
		{
			targetScale = 0f;
			yield return null;
		}
		PhotonNetwork.Destroy(base.transform.root.gameObject);
	}
}
public class ScaleTrailFromDamage : MonoBehaviour
{
	private float startWidth;

	private float startTime;

	private void Start()
	{
		float num = 55f;
		ProjectileHit componentInParent = GetComponentInParent<ProjectileHit>();
		GetComponentInParent<RayCastTrail>();
		if ((bool)componentInParent)
		{
			num = componentInParent.damage;
		}
		TrailRenderer componentInChildren = GetComponentInChildren<TrailRenderer>();
		startWidth = componentInChildren.widthMultiplier;
		startTime = componentInChildren.time;
		if ((bool)componentInChildren)
		{
			componentInChildren.widthMultiplier *= (1f + num / 55f) / 2f;
			componentInChildren.time *= Mathf.Clamp((1f + num / 55f) / 2f, 0f, 25f);
			if (num > 100f)
			{
				componentInChildren.numCapVertices = 5;
			}
			if (num > 500f)
			{
				componentInChildren.numCapVertices = 10;
			}
		}
	}

	public void Rescale()
	{
		float num = 55f;
		ProjectileHit componentInParent = GetComponentInParent<ProjectileHit>();
		RayCastTrail componentInParent2 = GetComponentInParent<RayCastTrail>();
		if ((bool)componentInParent)
		{
			num = componentInParent.damage;
		}
		TrailRenderer componentInChildren = GetComponentInChildren<TrailRenderer>();
		if ((bool)componentInChildren)
		{
			_ = componentInParent2.extraSize;
			componentInChildren.widthMultiplier = startWidth * ((1f + num / 55f) / 2f);
			componentInChildren.time = startTime * Mathf.Clamp((1f + num / 55f) / 2f, 0f, 25f);
			if (num > 100f)
			{
				componentInChildren.numCapVertices = 5;
			}
			if (num > 100f)
			{
				componentInChildren.numCapVertices = 10;
			}
		}
	}
}
