public class SpawnObjectEffect : MonoBehaviour
{
	public enum Dir
	{
		TowardsEnemy,
		DamageDirction,
		ReverseDamageDir,
		TowardsRecentlyDamaged
	}

	public Dir dir;

	[FoldoutGroup("Gun", 0)]
	public bool spawnAttack;

	[FoldoutGroup("Gun", 0)]
	public float bulletDamageMultiplier = 0.5f;

	[FoldoutGroup("Gun", 0)]
	public int numberOfattacks = 1;

	[FoldoutGroup("Gun", 0)]
	public float spread;

	[FoldoutGroup("Gun", 0)]
	public float gravityMultiplier = 1f;

	[FoldoutGroup("Gun", 0)]
	public float speedMultiplier = 1f;

	[FoldoutGroup("Gun", 0)]
	public float extraSpread;

	[FoldoutGroup("Gun", 0)]
	public float recoilMultiplier = 1f;

	[FoldoutGroup("Gun", 0)]
	public int maxBullets = 100;

	private Holding holding;

	private Gun gun;

	private Player player;

	private void Start()
	{
		holding = GetComponentInParent<Holding>();
		player = GetComponentInParent<Player>();
	}

	public void DoEffect(Vector2 dmg)
	{
		int num = 0;
		if (!spawnAttack)
		{
			return;
		}
		for (int i = 0; i < numberOfattacks; i++)
		{
			if (!gun && (bool)holding && (bool)holding.holdable)
			{
				gun = holding.holdable.GetComponent<Gun>();
			}
			if ((bool)gun)
			{
				Quaternion rotation = gun.transform.rotation;
				Vector3 vector = (PlayerManager.instance.GetOtherPlayer(player).transform.position - base.transform.position).normalized;
				if (dir == Dir.DamageDirction)
				{
					vector = dmg.normalized;
				}
				if (dir == Dir.ReverseDamageDir)
				{
					vector = -dmg.normalized;
				}
				if (dir == Dir.TowardsRecentlyDamaged)
				{
					vector = (player.data.lastDamagedPlayer.transform.position - base.transform.position).normalized;
				}
				gun.transform.rotation = Quaternion.LookRotation(Vector3.forward, vector + gun.transform.right * UnityEngine.Random.Range(0f - spread, spread));
				gun.projectileSpeed *= speedMultiplier;
				gun.gravity *= gravityMultiplier;
				gun.spread += extraSpread;
				gun.Attack(1f, forceAttack: true, bulletDamageMultiplier, recoilMultiplier);
				num += (int)((float)gun.numberOfProjectiles + gun.chargeNumberOfProjectilesTo);
				gun.projectileSpeed /= speedMultiplier;
				gun.gravity /= gravityMultiplier;
				gun.spread -= extraSpread;
				gun.transform.rotation = rotation;
				if (num > maxBullets)
				{
					break;
				}
			}
		}
	}
}
public class SpawnObjectOnDealDamage : DealtDamageEffect
{
	public UnityEvent triggerEvent;

	public float damageNeeded = 25f;

	public float cd = 0.2f;

	private float time;

	private float damageDealt;

	private SpawnObjectEffect spawn;

	private DamageEffect dmgEffect;

	public bool allowSelfDmg;

	private void Start()
	{
		spawn = GetComponent<SpawnObjectEffect>();
		dmgEffect = GetComponent<DamageEffect>();
	}

	public override void DealtDamage(Vector2 damage, bool selfDamage, Player damagedPlayer = null)
	{
		if (selfDamage && !allowSelfDmg)
		{
			return;
		}
		damageDealt += damage.magnitude;
		if (damageDealt > damageNeeded && Time.time > time + cd)
		{
			time = Time.time;
			damageDealt = 0f;
			if ((bool)spawn)
			{
				spawn.DoEffect(damage);
			}
			if ((bool)dmgEffect)
			{
				dmgEffect.DoDamageEffect(damage, selfDamage, damagedPlayer);
			}
			triggerEvent.Invoke();
		}
	}
}
public class SpawnObjectOnDealtDamage : WasDealtDamageEffect
{
	public float damageNeeded = 25f;

	public float cd = 0.2f;

	public bool allowSelfDamage;

	private float time;

	private float damageDealt;

	private SpawnObjectEffect spawn;

	private void Start()
	{
		spawn = GetComponent<SpawnObjectEffect>();
	}

	public override void WasDealtDamage(Vector2 damage, bool selfDamage)
	{
		if (!selfDamage || allowSelfDamage)
		{
			damageDealt += damage.magnitude;
			if (damageDealt > damageNeeded && Time.time > time + cd)
			{
				time = Time.time;
				damageDealt = 0f;
				spawn.DoEffect(damage);
			}
		}
	}
}
public class SpawnObjects : MonoBehaviour
{
	public enum SpawnRot
	{
		Identity,
		TransformRotation
	}

	public GameObject[] objectToSpawn;

	public SpawnRot spawnRot;

	public bool inheritScale;

	public bool destroyObject;

	public bool destroyRoot;

	private PhotonView view;

	public Action<GameObject> SpawnedAction;

	[HideInInspector]
	public GameObject mostRecentlySpawnedObject;

	private void ConfigureObject(GameObject go)
	{
		SpawnedAttack spawnedAttack = go.GetComponent<SpawnedAttack>();
		if (!spawnedAttack)
		{
			spawnedAttack = go.AddComponent<SpawnedAttack>();
		}
		spawnedAttack.spawner = base.transform.root.GetComponent<Player>();
		if (!spawnedAttack.spawner)
		{
			SpawnedAttack componentInParent = base.transform.GetComponentInParent<SpawnedAttack>();
			if ((bool)componentInParent)
			{
				componentInParent.CopySpawnedAttackTo(go);
			}
		}
		AttackLevel componentInParent2 = GetComponentInParent<AttackLevel>();
		if ((bool)componentInParent2)
		{
			spawnedAttack.attackLevel = componentInParent2.attackLevel;
		}
		if (inheritScale)
		{
			go.transform.localScale *= base.transform.localScale.x;
		}
		if (SpawnedAction != null)
		{
			SpawnedAction(go);
		}
	}

	public void Spawn()
	{
		for (int i = 0; i < objectToSpawn.Length; i++)
		{
			Quaternion rotation = Quaternion.identity;
			if (spawnRot == SpawnRot.TransformRotation)
			{
				rotation = base.transform.rotation;
			}
			GameObject go = UnityEngine.Object.Instantiate(objectToSpawn[i], base.transform.position, rotation);
			ConfigureObject(go);
			mostRecentlySpawnedObject = go;
		}
		if (destroyObject)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		if (destroyRoot)
		{
			UnityEngine.Object.Destroy(base.transform.root.gameObject);
		}
	}
}
