public class SwordArtMove : MonoBehaviour
{
	private MoveTransform move;

	public LayerMask mask;

	public AnimationCurve heightCurve;

	public AnimationCurve AwayCurve;

	private Vector3 startUp;

	private Vector3 startForward;

	private Vector3 startPos;

	public float multiplier = 1f;

	public float heightMultiplier = 1f;

	public float awayMultiplier = 1f;

	public float speed = 1f;

	private float counter;

	private ParticleSystem[] parts;

	private void Start()
	{
		parts = GetComponentsInChildren<ParticleSystem>();
		move = GetComponentInParent<MoveTransform>();
		move.enabled = false;
		startForward = base.transform.forward;
		startUp = Vector3.Cross(base.transform.forward, Vector3.forward);
		startPos = base.transform.position;
		awayMultiplier *= Mathf.Pow(move.localForce.magnitude / 40f * 2f, 0.45f);
		awayMultiplier /= 1f + move.drag * 0.05f;
		speed *= Mathf.Pow(awayMultiplier, 0.3f);
	}

	private void Update()
	{
		counter += TimeHandler.deltaTime * speed;
		Vector3 vector = startPos + (heightCurve.Evaluate(counter) * heightMultiplier * startUp + AwayCurve.Evaluate(counter) * awayMultiplier * startForward) * multiplier;
		RaycastHit2D raycastHit2D = Physics2D.Raycast(startPos, (vector - startPos).normalized, Vector3.Distance(vector, startPos), mask);
		if ((bool)raycastHit2D.transform && !raycastHit2D.collider.GetComponent<Damagable>())
		{
			vector = raycastHit2D.point + raycastHit2D.normal * 0.1f;
			for (int i = 0; i < parts.Length; i++)
			{
				parts[i].transform.position = (Vector3)raycastHit2D.point + Vector3.forward * 8f;
				parts[i].transform.rotation = Quaternion.LookRotation(raycastHit2D.normal);
				parts[i].Emit(1);
			}
		}
		base.transform.root.position = vector;
	}
}
public class TasteOfBlood : MonoBehaviour
{
	public AnimationCurve attackSpeedCurve;

	public float decaySpeed = 1f;

	private float damageValue;

	private CharacterStatModifiers stats;

	private ParticleSystem part;

	private CharacterData data;

	private bool isOn;

	private void Start()
	{
		part = GetComponentInChildren<ParticleSystem>();
		stats = GetComponentInParent<CharacterStatModifiers>();
		CharacterStatModifiers characterStatModifiers = stats;
		characterStatModifiers.DealtDamageAction = (Action<Vector2, bool>)Delegate.Combine(characterStatModifiers.DealtDamageAction, new Action<Vector2, bool>(DealtDamage));
		data = GetComponentInParent<CharacterData>();
	}

	public void DealtDamage(Vector2 damage, bool selfDamage)
	{
		if (!selfDamage)
		{
			damageValue += damage.magnitude;
		}
		damageValue = Mathf.Clamp(damageValue, 0f, 50f);
	}

	private void Update()
	{
		if (!data.isPlaying)
		{
			damageValue = 0f;
		}
		if (damageValue > 0f)
		{
			damageValue -= TimeHandler.deltaTime * decaySpeed;
			isOn = true;
		}
		else
		{
			isOn = false;
		}
		if (damageValue > 10f)
		{
			if (!part.isPlaying)
			{
				part.Play();
			}
		}
		else if (part.isPlaying)
		{
			part.Stop();
		}
		stats.tasteOfBloodSpeed = attackSpeedCurve.Evaluate(damageValue);
	}
}
public class Teleport : MonoBehaviour
{
	public ParticleSystem[] parts;

	public ParticleSystem[] remainParts;

	public float distance = 10f;

	public LayerMask mask;

	private CharacterData data;

	private AttackLevel level;

	private void Start()
	{
		parts = GetComponentsInChildren<ParticleSystem>();
		data = GetComponentInParent<CharacterData>();
		level = GetComponentInParent<AttackLevel>();
		Block componentInParent = GetComponentInParent<Block>();
		componentInParent.SuperFirstBlockAction = (Action<BlockTrigger.BlockTriggerType>)Delegate.Combine(componentInParent.SuperFirstBlockAction, new Action<BlockTrigger.BlockTriggerType>(Go));
	}

	private void OnDestroy()
	{
		Block componentInParent = GetComponentInParent<Block>();
		componentInParent.SuperFirstBlockAction = (Action<BlockTrigger.BlockTriggerType>)Delegate.Remove(componentInParent.SuperFirstBlockAction, new Action<BlockTrigger.BlockTriggerType>(Go));
	}

	public void Go(BlockTrigger.BlockTriggerType triggerType)
	{
		StartCoroutine(DelayMove(triggerType, base.transform.position));
	}

	private IEnumerator DelayMove(BlockTrigger.BlockTriggerType triggerType, Vector3 beforePos)
	{
		if (triggerType == BlockTrigger.BlockTriggerType.Empower)
		{
			yield return new WaitForSeconds(0f);
		}
		Vector3 position = base.transform.position;
		Vector3 position2 = base.transform.position;
		int num = 10;
		float num2 = distance * (float)level.attackLevel / (float)num;
		for (int i = 0; i < num; i++)
		{
			position += num2 * data.aimDirection;
			if (!Physics2D.OverlapCircle(position, 0.5f))
			{
				position2 = position;
			}
		}
		for (int j = 0; j < remainParts.Length; j++)
		{
			remainParts[j].transform.position = base.transform.root.position;
			remainParts[j].Play();
		}
		GetComponentInParent<PlayerCollision>().IgnoreWallForFrames(2);
		if (triggerType == BlockTrigger.BlockTriggerType.Empower)
		{
			position2 = beforePos;
		}
		base.transform.root.position = position2;
		for (int k = 0; k < parts.Length; k++)
		{
			parts[k].transform.position = position2;
			parts[k].Play();
		}
		data.playerVel.velocity *= 0f;
		data.sinceGrounded = 0f;
	}
}
