public class Unparent : MonoBehaviour
{
	public Transform parent;

	public bool follow;

	public float destroyDelay;

	private bool done;

	private void Start()
	{
		parent = base.transform.root;
	}

	private void LateUpdate()
	{
		if (!done)
		{
			if (base.transform.root != null)
			{
				base.transform.SetParent(null, worldPositionStays: true);
			}
			if (follow && (bool)parent)
			{
				base.transform.position = parent.transform.position;
			}
			if (!parent)
			{
				StartCoroutine(DelayRemove());
				done = true;
			}
		}
	}

	private IEnumerator DelayRemove()
	{
		yield return new WaitForSeconds(destroyDelay);
		UnityEngine.Object.Destroy(base.gameObject);
	}
}
public class UnparentOnHit : MonoBehaviour
{
	public float destroyAfterSeconds = 2f;

	public UnityEvent unparentEvent;

	private bool done;

	private void Start()
	{
		ProjectileHit componentInParent = GetComponentInParent<ProjectileHit>();
		if ((bool)componentInParent)
		{
			componentInParent.AddHitAction(Unparent);
		}
	}

	public void Unparent()
	{
		if (!done)
		{
			done = true;
			base.transform.SetParent(null, worldPositionStays: true);
			StartCoroutine(DelayDestroy());
			unparentEvent.Invoke();
		}
	}

	private IEnumerator DelayDestroy()
	{
		yield return new WaitForSeconds(destroyAfterSeconds);
		UnityEngine.Object.Destroy(base.gameObject);
	}
}
