public class GridBounceCircle : GridObject
{
	private float m_startSize;

	private bool isBlooping;

	private float currentDistance;

	private void Start()
	{
		m_startSize = base.transform.localScale.x;
	}

	public override void BopCall(float power)
	{
		if (!isBlooping || (isBlooping && power > currentDistance))
		{
			StopAllCoroutines();
			StartCoroutine(Blop(power));
		}
	}

	public override void OnSetSize(float size)
	{
		if (!isBlooping)
		{
			base.transform.localScale = Vector3.one * size * m_startSize;
		}
	}

	private IEnumerator Blop(float power)
	{
		isBlooping = true;
		currentDistance = power;
		float maxSize = Mathf.Lerp(1f * m_startSize, 3f * m_startSize, power);
		float timer = 0f;
		while (timer < 1f)
		{
			timer += TimeHandler.deltaTime * 10f;
			base.transform.localScale = Vector3.one * Mathf.Lerp(m_startSize, maxSize, timer);
			yield return null;
		}
		yield return new WaitForSeconds(0.2f);
		timer = 0f;
		while (timer < 1f)
		{
			timer += TimeHandler.deltaTime * 6f;
			base.transform.localScale = Vector3.one * Mathf.Lerp(maxSize, m_startSize, timer);
			yield return null;
		}
		base.transform.localScale = Vector3.one * m_startSize;
		isBlooping = false;
	}
}
public class GridLightBulb : GridObject
{
	private SpriteRenderer rend;

	public Color maxLightColor;

	private Color baseColor;

	private bool isLitUp;

	private float currentDistance;

	private void Start()
	{
		rend = GetComponent<SpriteRenderer>();
		baseColor = rend.color;
	}

	public override void BopCall(float distance)
	{
		distance = 1f - distance;
		if (!isLitUp || (isLitUp && distance > currentDistance))
		{
			StopAllCoroutines();
			StartCoroutine(LightUp(distance));
		}
	}

	private IEnumerator LightUp(float distance)
	{
		isLitUp = true;
		currentDistance = distance;
		Color lightColor = Color.Lerp(maxLightColor, baseColor, distance);
		rend.color = lightColor;
		yield return new WaitForSeconds(UnityEngine.Random.Range(0.5f, 2f));
		int blinks = UnityEngine.Random.Range(0, 8);
		bool isOn = true;
		for (int i = 0; i < blinks; i++)
		{
			if (isOn)
			{
				rend.color = baseColor;
			}
			else
			{
				rend.color = lightColor;
			}
			isOn = !isOn;
			yield return new WaitForSeconds(UnityEngine.Random.Range(0.05f, 0.1f));
		}
		rend.color = baseColor;
		isLitUp = false;
	}
}
