public class CharacterCreator : MonoBehaviour
{
	public PlayerFace currentPlayerFace;

	public GameObject objectToEnable;

	public int playerID;

	public int portraitID;

	public bool ready;

	public PlayerActions playerActions;

	public GeneralInput.InputType inputType;

	public MenuControllerHandler.MenuControl currentControl = MenuControllerHandler.MenuControl.Unassigned;

	public MenuControllerHandler.MenuControl lastControl = MenuControllerHandler.MenuControl.Unassigned;

	public Action<MenuControllerHandler.MenuControl> SwitchAction;

	public CharacterCreatorNavigation nav;

	private void Start()
	{
		nav = GetComponentInChildren<CharacterCreatorNavigation>();
	}

	private void Update()
	{
		if (currentControl != lastControl)
		{
			SwitchAction?.Invoke(currentControl);
		}
		lastControl = currentControl;
	}

	public void Close()
	{
		CharacterCreatorHandler.instance.ReleasePortrait(portraitID);
		if (playerActions == null)
		{
			base.gameObject.SetActive(value: false);
			MainMenuHandler.instance.Open();
		}
		else
		{
			objectToEnable.SetActive(value: true);
			base.gameObject.SetActive(value: false);
		}
	}

	public void Finish()
	{
		CharacterCreatorHandler.instance.ReleasePortrait(portraitID);
		CharacterCreatorHandler.instance.SetFacePreset(portraitID, currentPlayerFace);
		CharacterCreatorHandler.instance.SelectFace(0, currentPlayerFace, portraitID);
		if (playerActions == null)
		{
			base.gameObject.SetActive(value: false);
			MainMenuHandler.instance.Open();
		}
		else
		{
			objectToEnable.SetActive(value: true);
			base.gameObject.SetActive(value: false);
		}
	}

	internal void SetOffset(Vector2 offset, CharacterItemType itemType, int slotID)
	{
		if (itemType == CharacterItemType.Eyes)
		{
			currentPlayerFace.eyeOffset = offset;
		}
		if (itemType == CharacterItemType.Mouth)
		{
			currentPlayerFace.mouthOffset = offset;
		}
		if (itemType == CharacterItemType.Detail)
		{
			if (slotID == 0)
			{
				currentPlayerFace.detailOffset = offset;
			}
			if (slotID == 1)
			{
				currentPlayerFace.detail2Offset = offset;
			}
		}
	}

	internal void SpawnFace(PlayerFace currentFace)
	{
		GetComponentInChildren<CharacterCreatorItemEquipper>().SpawnPlayerFace(currentFace);
	}
}
public class CharacterCreatorButtonSpawner : MonoBehaviour
{
	public GameObject sourceButton;

	private CharacterCreatorItemLoader loader;

	private CharacterCreator creator;

	private void Start()
	{
		creator = GetComponent<CharacterCreator>();
		loader = CharacterCreatorItemLoader.instance;
		OpenMenu(CharacterItemType.Eyes, 0);
	}

	public void OpenMenu(int id)
	{
		if (id == 0)
		{
			OpenMenu(CharacterItemType.Eyes, 0);
		}
		if (id == 1)
		{
			OpenMenu(CharacterItemType.Mouth, 0);
		}
		if (id == 2)
		{
			OpenMenu(CharacterItemType.Detail, 0);
		}
		if (id == 3)
		{
			OpenMenu(CharacterItemType.Detail, 1);
		}
	}

	public void OpenMenu(CharacterItemType target, int slotNr)
	{
		CharacterItem[] array = null;
		if (target == CharacterItemType.Eyes)
		{
			array = loader.eyes;
		}
		if (target == CharacterItemType.Mouth)
		{
			array = loader.mouths;
		}
		if (target == CharacterItemType.Detail)
		{
			array = loader.accessories;
		}
		for (int i = 0; i < sourceButton.transform.parent.childCount; i++)
		{
			if (sourceButton.transform.parent.GetChild(i).gameObject.activeSelf)
			{
				UnityEngine.Object.Destroy(sourceButton.transform.parent.GetChild(i).gameObject);
			}
		}
		for (int j = 0; j < array.Length; j++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(sourceButton, sourceButton.transform.parent);
			gameObject.SetActive(value: true);
			Transform parent = gameObject.transform.Find("ItemParent");
			GameObject gameObject2 = UnityEngine.Object.Instantiate(array[j].gameObject, parent);
			gameObject.GetComponent<CharacterItemButton>().itemType = target;
			gameObject.GetComponent<CharacterItemButton>().slotNr = slotNr;
			gameObject.GetComponentInChildren<CharacterItem>().sprite = array[j].gameObject.GetComponent<SpriteRenderer>().sprite;
			gameObject2.GetComponentInChildren<CharacterItem>().GetComponent<SpriteRenderer>().sortingOrder = array[j].gameObject.GetComponent<SpriteRenderer>().sortingOrder;
			gameObject2.GetComponentInChildren<CharacterItem>().scale = array[j].scale;
			gameObject2.GetComponentInChildren<CharacterItem>().itemType = target;
			gameObject2.GetComponentInChildren<CharacterItem>().offset = array[j].offset;
			gameObject2.GetComponentInChildren<CharacterItem>().slotNr = slotNr;
			gameObject2.GetComponentInChildren<SpriteRenderer>().transform.localPosition = array[j].offset;
			gameObject2.GetComponentInChildren<SpriteRenderer>().transform.localScale = array[j].scale * Vector2.one;
			if (target == CharacterItemType.Eyes && j == creator.currentPlayerFace.eyeID)
			{
				gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
			}
			if (target == CharacterItemType.Mouth && j == creator.currentPlayerFace.mouthID)
			{
				gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
			}
			if (target == CharacterItemType.Detail && j == creator.currentPlayerFace.detailID && slotNr == 0)
			{
				gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
			}
			if (target == CharacterItemType.Detail && slotNr == 1 && j == creator.currentPlayerFace.detail2ID)
			{
				gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
			}
		}
	}

	public void SelectButton(CharacterItemType itemType, int slotNr)
	{
		for (int i = 0; i < sourceButton.transform.parent.childCount; i++)
		{
			GameObject gameObject = sourceButton.transform.parent.GetChild(i).gameObject;
			if (itemType == CharacterItemType.Eyes)
			{
				if (i - 1 == creator.currentPlayerFace.eyeID)
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
				}
				else
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: false);
				}
			}
			if (itemType == CharacterItemType.Mouth)
			{
				if (i - 1 == creator.currentPlayerFace.mouthID)
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
				}
				else
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: false);
				}
			}
			if (itemType == CharacterItemType.Detail)
			{
				if (i - 1 == creator.currentPlayerFace.detailID && slotNr == 0)
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
				}
				else
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: false);
				}
			}
			if (itemType == CharacterItemType.Detail && slotNr == 1)
			{
				if (i - 1 == creator.currentPlayerFace.detail2ID)
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: true);
				}
				else
				{
					gameObject.transform.Find("SelectedDot").gameObject.SetActive(value: false);
				}
			}
		}
	}
}
public class CharacterCreatorDragging : MonoBehaviour
{
	public Vector2 rightStick;

	private CharacterCreator creator;

	private Transform draggedObject;

	private Vector2 lastMouse = Vector3.zero;

	private void Start()
	{
		creator = GetComponentInParent<CharacterCreator>();
	}

	private void Update()
	{
		if (creator.inputType == GeneralInput.InputType.Keyboard || creator.inputType == GeneralInput.InputType.Either)
		{
			DoMouse();
		}
		if (creator.inputType == GeneralInput.InputType.Controller || creator.inputType == GeneralInput.InputType.Either)
		{
			DoController();
		}
	}

	private void DoController()
	{
		int num = -1;
		int barPos = creator.nav.barPos;
		for (int i = 0; i < base.transform.childCount; i++)
		{
			CharacterItem component = base.transform.GetChild(i).GetComponent<CharacterItem>();
			if (barPos == 0 && component.itemType == CharacterItemType.Eyes)
			{
				num = i;
			}
			if (barPos == 1 && component.itemType == CharacterItemType.Mouth)
			{
				num = i;
			}
			if (barPos == 2 && component.itemType == CharacterItemType.Detail && component.slotNr == 0)
			{
				num = i;
			}
			if (barPos == 3 && component.itemType == CharacterItemType.Detail && component.slotNr == 1)
			{
				num = i;
			}
		}
		if (num >= base.transform.childCount)
		{
			return;
		}
		Vector2 vector = Vector2.zero;
		if (creator.playerActions != null)
		{
			vector = creator.playerActions.Aim.Value;
		}
		else
		{
			for (int j = 0; j < InputManager.ActiveDevices.Count; j++)
			{
				vector = InputManager.ActiveDevices[j].RightStick.Value;
			}
		}
		base.transform.GetChild(num).transform.position += (Vector3)vector * Time.deltaTime * 3f;
		if (vector != Vector2.zero)
		{
			CharacterItem component2 = base.transform.GetChild(num).GetComponent<CharacterItem>();
			Vector2 offset = (Vector2)base.transform.GetChild(num).localPosition - component2.offset;
			creator.SetOffset(offset, component2.itemType, component2.slotNr);
		}
	}

	private void DoMouse()
	{
		Vector2 vector = MainCam.instance.cam.ScreenToWorldPoint(Input.mousePosition);
		if (Input.GetKeyDown(KeyCode.Mouse0))
		{
			float num = 2f;
			int num2 = -1;
			for (int i = 0; i < base.transform.childCount; i++)
			{
				float num3 = Vector2.Distance(vector, base.transform.GetChild(i).transform.position);
				Debug.DrawLine(vector, base.transform.GetChild(i).GetComponent<SpriteRenderer>().bounds.center, Color.red, 2f);
				if (num3 < num)
				{
					num = num3;
					num2 = i;
				}
			}
			if (num2 != -1)
			{
				draggedObject = base.transform.GetChild(num2);
			}
		}
		if (Input.GetKeyUp(KeyCode.Mouse0) && (bool)draggedObject)
		{
			CharacterItem component = draggedObject.GetComponent<CharacterItem>();
			Vector2 offset = (Vector2)draggedObject.transform.localPosition - component.offset;
			creator.SetOffset(offset, component.itemType, component.slotNr);
			draggedObject = null;
		}
		if ((bool)draggedObject)
		{
			draggedObject.transform.position += (Vector3)(vector - lastMouse);
			draggedObject.transform.localPosition = Vector2.ClampMagnitude(draggedObject.transform.localPosition, 4.5f);
		}
		lastMouse = vector;
	}
}
public class CharacterCreatorHandler : MonoBehaviour
{
	public static CharacterCreatorHandler instance;

	public PlayerFace[] playerFaces = new PlayerFace[10];

	public PlayerFace[] selectedPlayerFaces = new PlayerFace[4];

	public int[] selectedFaceID = new int[4];

	public List<int> lockedPortraits;

	public Action lockedPortraitAction;

	public Action<int> faceWasUpdatedAction;

	public void LockPortrait(int portrait)
	{
		lockedPortraits.Add(portrait);
		lockedPortraitAction?.Invoke();
	}

	public void ReleasePortrait(int porttrait)
	{
		for (int i = 0; i < lockedPortraits.Count; i++)
		{
			if (porttrait == lockedPortraits[i])
			{
				lockedPortraits.RemoveAt(i);
				break;
			}
		}
		lockedPortraitAction?.Invoke();
	}

	private void ReleaseAllPortraits()
	{
		lockedPortraits.Clear();
		lockedPortraitAction?.Invoke();
	}

	private void Awake()
	{
		instance = this;
		for (int i = 0; i < playerFaces.Length; i++)
		{
			playerFaces[i].LoadFace(i.ToString());
		}
		for (int j = 0; j < selectedFaceID.Length; j++)
		{
			selectedFaceID[j] = PlayerPrefs.GetInt("SelectedFace" + j);
			SelectFace(j, playerFaces[selectedFaceID[j]], selectedFaceID[j]);
		}
	}

	internal void SelectFace(int faceID, PlayerFace selectedFace, int faceSlot)
	{
		selectedFaceID[faceID] = faceSlot;
		PlayerPrefs.SetInt("SelectedFace" + faceID, selectedFaceID[faceID]);
		selectedPlayerFaces[faceID] = selectedFace;
	}

	public PlayerFace GetFacePreset(int faceID)
	{
		return playerFaces[faceID];
	}

	public bool SomeoneIsEditing()
	{
		for (int i = 0; i < base.transform.childCount; i++)
		{
			if (base.transform.GetChild(i).gameObject.activeSelf)
			{
				return true;
			}
		}
		return false;
	}

	internal void SetFacePreset(int faceID, PlayerFace currentPlayerFace)
	{
		playerFaces[faceID] = PlayerFace.CopyFace(currentPlayerFace);
		playerFaces[faceID].SaveFace(faceID.ToString());
		faceWasUpdatedAction?.Invoke(faceID);
	}

	public void EditCharacterLocalMultiplayer(int playerId, int portraitID, GameObject objectToEnable, PlayerFace currentFace)
	{
		LockPortrait(portraitID);
		CharacterCreator component = base.transform.GetChild(playerId + 1).GetComponent<CharacterCreator>();
		component.playerActions = PlayerManager.instance.players[playerId].data.playerActions;
		component.inputType = PlayerManager.instance.players[playerId].data.input.inputType;
		component.gameObject.SetActive(value: true);
		component.playerID = playerId;
		component.objectToEnable = objectToEnable;
		component.currentPlayerFace = currentFace;
		component.portraitID = portraitID;
		component.SpawnFace(currentFace);
	}

	public void EditCharacterPortrait(int portraitID, PlayerFace currentFace)
	{
		LockPortrait(portraitID);
		MainMenuHandler.instance.Close();
		CharacterCreator component = base.transform.GetChild(0).GetComponent<CharacterCreator>();
		component.inputType = GeneralInput.InputType.Either;
		component.currentPlayerFace = currentFace;
		component.gameObject.SetActive(value: true);
		component.playerID = 0;
		component.portraitID = portraitID;
		component.SpawnFace(currentFace);
	}

	public void CloseMenus()
	{
		for (int i = 0; i < base.transform.childCount; i++)
		{
			base.transform.GetChild(i).GetComponent<CharacterCreator>().Close();
		}
		ReleaseAllPortraits();
	}

	public void EndCustomization(int playerId = -1)
	{
		if (playerId == -1)
		{
			GetComponentInChildren<CharacterCreator>(includeInactive: true).Finish();
			base.transform.GetChild(0).gameObject.SetActive(value: false);
		}
	}
}
public class CharacterCreatorItemEquipper : MonoBehaviour
{
	public GameObject itemParent;

	public GameObject defaultEyes;

	public GameObject defaultMouth;

	private CharacterCreatorItemLoader itemLoader;

	private CharacterCreator creator;

	public float scaleM = 1f;

	private bool spawnedSpecific;

	private bool inited;

	private void Start()
	{
		Init();
		if ((bool)creator && !spawnedSpecific)
		{
			Equip(defaultEyes.GetComponent<CharacterItem>(), CharacterItemType.Eyes);
			Equip(defaultMouth.GetComponent<CharacterItem>(), CharacterItemType.Mouth);
		}
	}

	public void SpawnPlayerFace(PlayerFace newFace)
	{
		spawnedSpecific = true;
		EquipFace(newFace);
	}

	private void Init()
	{
		if (!inited)
		{
			inited = true;
			creator = GetComponent<CharacterCreator>();
			itemLoader = CharacterCreatorItemLoader.instance;
		}
	}

	[PunRPC]
	public void RPCA_SetFace(int eyeID, Vector2 eyeOffset, int mouthID, Vector2 mouthOffset, int detailID, Vector2 detailOffset, int detail2ID, Vector2 detail2Offset)
	{
		PlayerFace face = PlayerFace.CreateFace(eyeID, eyeOffset, mouthID, mouthOffset, detailID, detailOffset, detail2ID, detail2Offset);
		EquipFace(face);
	}

	public void EquipFace(PlayerFace face)
	{
		Init();
		Equip(itemLoader.GetItem(face.eyeID, CharacterItemType.Eyes), CharacterItemType.Eyes, face.eyeOffset);
		Equip(itemLoader.GetItem(face.mouthID, CharacterItemType.Mouth), CharacterItemType.Mouth, face.mouthOffset);
		Equip(itemLoader.GetItem(face.detailID, CharacterItemType.Detail), CharacterItemType.Detail, face.detailOffset);
		Equip(itemLoader.GetItem(face.detail2ID, CharacterItemType.Detail), CharacterItemType.Detail, face.detail2Offset, 1);
	}

	public void Equip(CharacterItem newSprite, CharacterItemType itemType, Vector2 offset = default(Vector2), int slotNr = 0)
	{
		if (newSprite == null)
		{
			return;
		}
		Init();
		if ((bool)creator)
		{
			if (itemType == CharacterItemType.Eyes)
			{
				creator.currentPlayerFace.eyeID = itemLoader.GetItemID(newSprite, itemType);
			}
			if (itemType == CharacterItemType.Mouth)
			{
				creator.currentPlayerFace.mouthID = itemLoader.GetItemID(newSprite, itemType);
			}
			if (itemType == CharacterItemType.Detail)
			{
				if (slotNr == 0)
				{
					creator.currentPlayerFace.detailID = itemLoader.GetItemID(newSprite, itemType);
				}
				if (slotNr == 1)
				{
					creator.currentPlayerFace.detail2ID = itemLoader.GetItemID(newSprite, itemType);
				}
			}
		}
		Clear(itemType, slotNr);
		SpawnItem(newSprite, itemType, offset, slotNr);
		CopyChildren[] componentsInChildren = GetComponentsInChildren<CopyChildren>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].DoUpdate();
		}
	}

	private void SpawnItem(CharacterItem newSprite, CharacterItemType itemType, Vector2 offset = default(Vector2), int slotNr = 0)
	{
		GameObject obj = UnityEngine.Object.Instantiate(newSprite.gameObject);
		obj.gameObject.SetActive(value: true);
		obj.transform.SetParent(itemParent.transform);
		obj.GetComponent<SpriteRenderer>().sprite = newSprite.GetComponent<CharacterItem>().sprite;
		obj.GetComponent<SpriteRenderer>().sortingOrder = newSprite.GetComponent<CharacterItem>().GetComponent<SpriteRenderer>().sortingOrder;
		obj.GetComponent<CharacterItem>().itemType = itemType;
		obj.GetComponent<SpriteRenderer>().color = newSprite.GetComponent<SpriteRenderer>().color;
		obj.GetComponentInChildren<CharacterItem>().offset = newSprite.GetComponent<CharacterItem>().offset;
		obj.GetComponentInChildren<CharacterItem>().sprite = newSprite.GetComponent<CharacterItem>().sprite;
		obj.GetComponentInChildren<CharacterItem>().slotNr = slotNr;
		obj.transform.localScale = newSprite.GetComponent<CharacterItem>().scale * Vector3.one * scaleM;
		obj.transform.localPosition = (newSprite.GetComponent<CharacterItem>().offset + offset) * scaleM;
		creator?.SetOffset(offset, itemType, slotNr);
	}

	private void Clear(CharacterItemType itemType, int slotNr = 0)
	{
		for (int i = 0; i < itemParent.transform.childCount; i++)
		{
			CharacterItem component = itemParent.transform.GetChild(i).GetComponent<CharacterItem>();
			if (component.itemType == itemType && component.slotNr == slotNr)
			{
				UnityEngine.Object.DestroyImmediate(itemParent.transform.GetChild(i).gameObject);
			}
		}
	}
}
[Serializable]
public class PlayerFace
{
	public int eyeID;

	public Vector2 eyeOffset;

	public int mouthID;

	public Vector2 mouthOffset;

	public int detailID;

	public Vector2 detailOffset;

	public int detail2ID;

	public Vector2 detail2Offset;

	public void LoadFace(string key)
	{
		eyeID = PlayerPrefs.GetInt("eyeID-" + key);
		eyeOffset.x = PlayerPrefs.GetFloat("eyeOffsetX-" + key);
		eyeOffset.y = PlayerPrefs.GetFloat("eyeOffsetY-" + key);
		mouthID = PlayerPrefs.GetInt("mouthID-" + key);
		mouthOffset.x = PlayerPrefs.GetFloat("mouthOffsetX-" + key);
		mouthOffset.y = PlayerPrefs.GetFloat("mouthOffsetY-" + key);
		detailID = PlayerPrefs.GetInt("detailID-" + key);
		detailOffset.x = PlayerPrefs.GetFloat("detailOffsetX-" + key);
		detailOffset.y = PlayerPrefs.GetFloat("detailOffsetY-" + key);
		detail2ID = PlayerPrefs.GetInt("detail2ID-" + key);
		detail2Offset.x = PlayerPrefs.GetFloat("detail2OffsetX-" + key);
		detail2Offset.y = PlayerPrefs.GetFloat("detail2OffsetY-" + key);
	}

	internal static PlayerFace CopyFace(PlayerFace currentPlayerFace)
	{
		return new PlayerFace
		{
			eyeID = currentPlayerFace.eyeID,
			eyeOffset = currentPlayerFace.eyeOffset,
			mouthID = currentPlayerFace.mouthID,
			mouthOffset = currentPlayerFace.mouthOffset,
			detailID = currentPlayerFace.detailID,
			detailOffset = currentPlayerFace.detailOffset,
			detail2ID = currentPlayerFace.detail2ID,
			detail2Offset = currentPlayerFace.detail2Offset
		};
	}

	internal static PlayerFace CreateFace(int eyeID, Vector2 eyeOffset, int mouthID, Vector2 mouthOffset, int detailID, Vector2 detailOffset, int detail2ID, Vector2 detail2Offset)
	{
		return new PlayerFace
		{
			eyeID = eyeID,
			eyeOffset = eyeOffset,
			mouthID = mouthID,
			mouthOffset = mouthOffset,
			detailID = detailID,
			detailOffset = detailOffset,
			detail2ID = detail2ID,
			detail2Offset = detail2Offset
		};
	}

	public void SaveFace(string key)
	{
		PlayerPrefs.SetInt("eyeID-" + key, eyeID);
		PlayerPrefs.SetFloat("eyeOffsetX-" + key, eyeOffset.x);
		PlayerPrefs.SetFloat("eyeOffsetY-" + key, eyeOffset.y);
		PlayerPrefs.SetInt("mouthID-" + key, mouthID);
		PlayerPrefs.SetFloat("mouthOffsetX-" + key, mouthOffset.x);
		PlayerPrefs.SetFloat("mouthOffsetY-" + key, mouthOffset.y);
		PlayerPrefs.SetInt("detailID-" + key, detailID);
		PlayerPrefs.SetFloat("detailOffsetX-" + key, detailOffset.x);
		PlayerPrefs.SetFloat("detailOffsetY-" + key, detailOffset.y);
		PlayerPrefs.SetInt("detail2ID-" + key, detail2ID);
		PlayerPrefs.SetFloat("detail2OffsetX-" + key, detail2Offset.x);
		PlayerPrefs.SetFloat("detail2OffsetY-" + key, detail2Offset.y);
	}
}
public class CharacterCreatorItemLoader : MonoBehaviour
{
	public CharacterItem[] eyes;

	public CharacterItem[] mouths;

	public CharacterItem[] accessories;

	public static CharacterCreatorItemLoader instance;

	private void Awake()
	{
		instance = this;
	}

	private void Update()
	{
	}

	internal CharacterItem GetItem(int itemID, CharacterItemType itemType)
	{
		try
		{
			return itemType switch
			{
				CharacterItemType.Eyes => eyes[itemID], 
				CharacterItemType.Mouth => mouths[itemID], 
				_ => accessories[itemID], 
			};
		}
		catch
		{
			return null;
		}
	}

	internal int GetItemID(CharacterItem newSprite, CharacterItemType itemType)
	{
		CharacterItem[] array = null;
		array = itemType switch
		{
			CharacterItemType.Eyes => eyes, 
			CharacterItemType.Mouth => mouths, 
			_ => accessories, 
		};
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].sprite == newSprite.sprite)
			{
				return i;
			}
		}
		return -1;
	}

	public void UpdateItems(CharacterItemType target, CharacterItem[] items)
	{
		for (int i = 0; i < items.Length; i++)
		{
			items[i].sprite = items[i].GetComponent<SpriteRenderer>().sprite;
		}
		if (target == CharacterItemType.Eyes)
		{
			eyes = items;
		}
		if (target == CharacterItemType.Mouth)
		{
			mouths = items;
		}
		if (target == CharacterItemType.Detail)
		{
			accessories = items;
		}
	}
}
public enum CharacterItemType
{
	Eyes,
	Mouth,
	Detail
}
public class CharacterCreatorNavigation : MonoBehaviour
{
	private int itemsInRow = 7;

	private CharacterCreator creator;

	private Transform grid;

	private Transform bar;

	private GameObject currentObject;

	private GameObject currentBarObject;

	private CharacterCreatorDragging dragging;

	public int x;

	public int y;

	public int barPos;

	private float cd;

	private void Awake()
	{
		creator = GetComponent<CharacterCreator>();
		dragging = GetComponentInChildren<CharacterCreatorDragging>();
		grid = base.transform.GetChild(0).GetChild(0);
		bar = base.transform.GetChild(0).GetChild(1);
	}

	private void Update()
	{
		if (creator.playerActions != null)
		{
			PlayerActionUpdate(creator.playerActions.Device);
		}
		else if (creator.playerActions == null)
		{
			creator.currentControl = MenuControllerHandler.menuControl;
			for (int i = 0; i < InputManager.ActiveDevices.Count; i++)
			{
				InputDevice device = InputManager.ActiveDevices[i];
				PlayerActionUpdate(device);
			}
		}
	}

	private void PlayerActionUpdate(InputDevice device)
	{
		cd += Time.unscaledDeltaTime;
		if (device != null)
		{
			if (device.CommandWasPressed)
			{
				creator.Finish();
			}
			dragging.rightStick = device.RightStick.Value;
			GridMovement(device);
			BarMovement(device);
		}
	}

	private void BarMovement(InputDevice device)
	{
		if (!currentBarObject)
		{
			MoveNav(0);
		}
		if (device.LeftTrigger.WasPressed)
		{
			MoveNav(-1);
		}
		if (device.RightTrigger.WasPressed)
		{
			MoveNav(1);
		}
	}

	private void MoveNav(int delta)
	{
		cd = 0f;
		if (delta > 0)
		{
			barPos++;
		}
		if (delta < 0)
		{
			barPos--;
		}
		VerifyBarPos();
	}

	private void VerifyBarPos()
	{
		if ((bool)currentBarObject)
		{
			currentBarObject.GetComponent<HoverEvent>().exitEvent.Invoke();
		}
		barPos = Mathf.Clamp(barPos, 0, 3);
		currentBarObject = bar.GetChild(barPos).gameObject;
		currentBarObject.GetComponent<HoverEvent>().enterEvent.Invoke();
		currentBarObject.GetComponent<Button>().onClick.Invoke();
	}

	private void GridMovement(InputDevice device)
	{
		if (!currentObject)
		{
			MoveNav(Vector2.zero);
		}
		if (device.LeftStick.Value.magnitude > 0.75f && cd > 0.1f)
		{
			MoveNav(device.LeftStick);
		}
		if (device.Action1.WasPressed)
		{
			currentObject.GetComponent<Button>().onClick.Invoke();
		}
	}

	private void MoveNav(Vector2 delta)
	{
		cd = 0f;
		if (delta.x > 0.5f)
		{
			x++;
		}
		if (delta.x < -0.5f)
		{
			x--;
		}
		if (delta.y > 0.5f)
		{
			y--;
		}
		if (delta.y < -0.5f)
		{
			y++;
		}
		VerifyPos();
	}

	private void VerifyPos()
	{
		if ((bool)currentObject)
		{
			currentObject.GetComponent<HoverEvent>().exitEvent.Invoke();
		}
		x = Mathf.Clamp(x, 1, itemsInRow);
		y = Mathf.Clamp(y, 0, Mathf.CeilToInt((grid.childCount - 2) / itemsInRow));
		x = Mathf.Clamp(x, 1, grid.childCount - y * itemsInRow - 1);
		int index = x + y * itemsInRow;
		currentObject = grid.GetChild(index).gameObject;
		currentObject.GetComponent<HoverEvent>().enterEvent.Invoke();
	}
}
public class CharacterCreatorPortrait : MonoBehaviour
{
	public int playerId = -1;

	public PlayerFace myFace;

	public GameObject selectedObj;

	public MenuControllerHandler.MenuControl controlType = MenuControllerHandler.MenuControl.Unassigned;

	private Color defColor;

	private HoverEvent hoverEvent;

	public GameObject lockedObj;

	private bool isLocked;

	private void Start()
	{
		defColor = base.transform.Find("BG").GetComponent<Image>().color;
		CharacterCreatorHandler instance = CharacterCreatorHandler.instance;
		instance.faceWasUpdatedAction = (Action<int>)Delegate.Combine(instance.faceWasUpdatedAction, new Action<int>(FaceUpdated));
		myFace = CharacterCreatorHandler.instance.GetFacePreset(base.transform.GetSiblingIndex());
		hoverEvent = GetComponent<HoverEvent>();
		GetComponentInChildren<CharacterCreatorItemEquipper>().EquipFace(myFace);
		if (CharacterCreatorHandler.instance.selectedFaceID[0] == base.transform.GetSiblingIndex())
		{
			ClickButton();
		}
		CharacterCreatorHandler instance2 = CharacterCreatorHandler.instance;
		instance2.lockedPortraitAction = (Action)Delegate.Combine(instance2.lockedPortraitAction, new Action(CheckLocked));
		CheckLocked();
	}

	private void CheckLocked()
	{
		isLocked = false;
		for (int i = 0; i < CharacterCreatorHandler.instance.lockedPortraits.Count; i++)
		{
			if (base.transform.GetSiblingIndex() == CharacterCreatorHandler.instance.lockedPortraits[i])
			{
				isLocked = true;
			}
		}
		if (isLocked)
		{
			lockedObj.SetActive(value: true);
		}
		else
		{
			lockedObj.SetActive(value: false);
		}
	}

	private void FaceUpdated(int faceID)
	{
		if (faceID == base.transform.GetSiblingIndex())
		{
			myFace = CharacterCreatorHandler.instance.GetFacePreset(faceID);
			GetComponent<CharacterCreatorItemEquipper>().EquipFace(myFace);
		}
	}

	public void ClickButton()
	{
		CharacterCreatorHandler.instance.SelectFace(Mathf.Clamp(playerId, 0, 10), myFace, base.transform.GetSiblingIndex());
		ShownFace();
	}

	private void ShownFace()
	{
		for (int i = 0; i < base.transform.parent.childCount; i++)
		{
			if (base.transform.parent.GetChild(i) == base.transform)
			{
				base.transform.parent.GetChild(i).Find("Frame").gameObject.SetActive(value: true);
			}
			else
			{
				base.transform.parent.GetChild(i).Find("Frame").gameObject.SetActive(value: false);
			}
		}
	}

	public void EditCharacter()
	{
		if (!isLocked)
		{
			ClickButton();
			if (playerId == -1)
			{
				CharacterCreatorHandler.instance.EditCharacterPortrait(base.transform.GetSiblingIndex(), myFace);
				return;
			}
			GameObject gameObject = base.transform.parent.parent.parent.gameObject;
			gameObject.SetActive(value: false);
			CharacterCreatorHandler.instance.EditCharacterLocalMultiplayer(playerId, base.transform.GetSiblingIndex(), gameObject, myFace);
		}
	}

	private void Update()
	{
		for (int i = 0; i < InputManager.ActiveDevices.Count; i++)
		{
			if (InputManager.ActiveDevices[i].Action4.WasPressed && hoverEvent.isSelected)
			{
				EditCharacter();
			}
		}
		if (Input.GetKeyDown(KeyCode.Mouse1) && controlType != MenuControllerHandler.MenuControl.Controller && hoverEvent.isHovered)
		{
			EditCharacter();
		}
	}
}
