public class Chase : MonoBehaviour
{
	public UnityEvent turnOnEvent;

	public UnityEvent turnOffEvent;

	public UnityEvent switchTargetEvent;

	private Player player;

	private LineEffect lineEffect;

	private bool isOn;

	private Player currentTarget;

	private void Start()
	{
		lineEffect = GetComponentInChildren<LineEffect>(includeInactive: true);
		player = GetComponentInParent<Player>();
	}

	private void Update()
	{
		Player player = PlayerManager.instance.GetClosestPlayerInTeam(base.transform.position, PlayerManager.instance.GetOtherTeam(this.player.teamID), needVision: true);
		if ((bool)player && (Vector2.Angle(player.transform.position - base.transform.position, this.player.data.input.direction) > 70f || this.player.data.input.direction == Vector3.zero))
		{
			player = null;
		}
		if ((bool)player)
		{
			if (currentTarget != this.player)
			{
				currentTarget = this.player;
				switchTargetEvent.Invoke();
				lineEffect.Play(base.transform, player.transform);
			}
			if (!isOn)
			{
				isOn = true;
				turnOnEvent.Invoke();
			}
		}
		else
		{
			if (isOn)
			{
				isOn = false;
				turnOffEvent.Invoke();
			}
			if (lineEffect.isPlaying)
			{
				lineEffect.Stop();
				lineEffect.gameObject.SetActive(value: false);
			}
			currentTarget = null;
		}
	}
}
public class ChatFilter : MonoBehaviour
{
	[TextArea]
	public string enterData;

	public string category;

	public static ChatFilter instance;

	public ChatFilterInstance[] filters;

	private void Awake()
	{
		instance = this;
	}

	[Button]
	private void EnterData()
	{
		string[] array = enterData.Replace('"', ' ').Trim().Split(',');
		ChatFilterInstance chatFilterInstance = null;
		for (int i = 0; i < filters.Length; i++)
		{
			if (filters[i].category == category)
			{
				chatFilterInstance = filters[i];
				break;
			}
		}
		if (chatFilterInstance == null)
		{
			UnityEngine.Debug.LogError("No valid category target!");
			return;
		}
		for (int j = 0; j < array.Length; j++)
		{
			array[j] = array[j].Trim();
			array[j] = array[j].ToUpper();
			if (array[j] == "")
			{
				continue;
			}
			bool flag = false;
			for (int k = 0; k < chatFilterInstance.words.Count; k++)
			{
				if (chatFilterInstance.words[k] == array[j])
				{
					flag = true;
				}
			}
			if (!flag)
			{
				chatFilterInstance.words.Add(array[j]);
			}
		}
	}

	public string FilterMessage(string message)
	{
		for (int i = 0; i < filters.Length; i++)
		{
			for (int j = 0; j < filters[i].words.Count; j++)
			{
				if (message.ToUpper().Contains(filters[i].words[j]))
				{
					return filters[i].replacement;
				}
			}
		}
		return message;
	}
}
[Serializable]
public class ChatFilterInstance
{
	public List<string> words = new List<string>();

	public string category;

	[TextArea]
	public string replacement;
}
