public class CooldownWindUp : MonoBehaviour
{
	public AnimationCurve multiplierCurve;

	private float currentMultiplier = 1f;

	private float startValue;

	private float currentValue;

	public float increasePerShot = 1f;

	private CooldownCondition cooldown;

	private void Start()
	{
		cooldown = GetComponent<CooldownCondition>();
		startValue = cooldown.cooldown;
	}

	private void Update()
	{
		currentMultiplier = multiplierCurve.Evaluate(currentValue);
		currentValue = Mathf.Clamp(currentValue, 0f, 100f);
		cooldown.cooldown = startValue / currentMultiplier;
	}

	public void Reset()
	{
		currentValue = 0f;
	}

	public void Add()
	{
		currentValue += increasePerShot / currentMultiplier;
	}
}
public class CopyChildren : MonoBehaviour
{
	public GameObject target;

	public void DoUpdate()
	{
		for (int num = base.transform.childCount - 1; num >= 0; num--)
		{
			UnityEngine.Object.Destroy(base.transform.GetChild(num).gameObject);
		}
		for (int i = 0; i < target.transform.childCount; i++)
		{
			Transform child = target.transform.GetChild(i);
			UnityEngine.Object.Instantiate(child.gameObject, base.transform.TransformPoint(child.localPosition), Quaternion.identity, base.transform).transform.localScale = child.localScale;
		}
	}

	private void Update()
	{
		DoUpdate();
	}
}
public class CounterUI : MonoBehaviour
{
	[Range(0f, 1f)]
	public float counter;

	public float timeToFill = 10f;

	public ProceduralImage outerRing;

	public ProceduralImage fill;

	public Transform rotator;

	public Transform still;

	private float remainingDuration;

	private bool isAbyssalForm;

	private bool done;

	public UnityEvent doneEvent;

	private void ResetStuff()
	{
		counter = 0f;
	}

	private void Update()
	{
		if (!done)
		{
			outerRing.fillAmount = counter;
			fill.fillAmount = counter;
			rotator.transform.localEulerAngles = new Vector3(0f, 0f, 0f - Mathf.Lerp(0f, 360f, counter));
			counter += TimeHandler.deltaTime / timeToFill;
			counter = Mathf.Clamp(counter, -0.1f / timeToFill, 1f);
			if (counter >= 1f)
			{
				done = true;
				doneEvent.Invoke();
			}
			if (counter <= 0f)
			{
				rotator.gameObject.SetActive(value: false);
				still.gameObject.SetActive(value: false);
			}
			else
			{
				rotator.gameObject.SetActive(value: true);
				still.gameObject.SetActive(value: true);
			}
		}
	}
}
