public class MenuControllerHandler : MonoBehaviour
{
	public enum MenuControl
	{
		Controller,
		Mouse,
		Unassigned
	}

	public static MenuControl menuControl;

	public MenuControl lastMenuControl;

	public Action<MenuControl> switchControlAction;

	public static MenuControllerHandler instance;

	private void Awake()
	{
		instance = this;
	}

	private void Start()
	{
		Switch();
	}

	private void Update()
	{
		if (Input.GetKeyDown(KeyCode.Mouse0))
		{
			menuControl = MenuControl.Mouse;
		}
		if (Input.GetKeyDown(KeyCode.Mouse1))
		{
			menuControl = MenuControl.Mouse;
		}
		for (int i = 0; i < InputManager.ActiveDevices.Count; i++)
		{
			InputDevice inputDevice = InputManager.ActiveDevices[i];
			if (!inputDevice.AnyButtonWasPressed && !(Mathf.Abs(inputDevice.LeftStick.Value.y) > 0.1f))
			{
				continue;
			}
			menuControl = MenuControl.Controller;
			if (EventSystem.current.currentSelectedGameObject.activeInHierarchy)
			{
				continue;
			}
			ListMenuButton[] array = UnityEngine.Object.FindObjectsOfType<ListMenuButton>();
			for (int j = 0; j < array.Length; j++)
			{
				if (array[j].enabled)
				{
					ListMenu.instance.SelectButton(array[j]);
				}
			}
		}
		if (menuControl != lastMenuControl)
		{
			Switch();
		}
		lastMenuControl = menuControl;
	}

	private void Switch()
	{
		switchControlAction?.Invoke(menuControl);
	}
}
public class MenuControllerToggler : MonoBehaviour
{
	public bool creatorControl;

	public GameObject controllerObject;

	public GameObject keyboardObject;

	private CharacterCreator creator;

	private void Awake()
	{
		CharacterCreator componentInParent = GetComponentInParent<CharacterCreator>();
		if (componentInParent.playerActions == null)
		{
			if (creatorControl)
			{
				componentInParent.SwitchAction = (Action<MenuControllerHandler.MenuControl>)Delegate.Combine(componentInParent.SwitchAction, new Action<MenuControllerHandler.MenuControl>(Switch));
				Switch(GetComponentInParent<CharacterCreator>().currentControl);
			}
			else
			{
				MenuControllerHandler instance = MenuControllerHandler.instance;
				instance.switchControlAction = (Action<MenuControllerHandler.MenuControl>)Delegate.Combine(instance.switchControlAction, new Action<MenuControllerHandler.MenuControl>(Switch));
				Switch(MenuControllerHandler.menuControl);
			}
		}
	}

	private void OnEnable()
	{
		CharacterCreator componentInParent = GetComponentInParent<CharacterCreator>();
		if (componentInParent.playerActions != null)
		{
			componentInParent.SwitchAction = (Action<MenuControllerHandler.MenuControl>)Delegate.Combine(componentInParent.SwitchAction, new Action<MenuControllerHandler.MenuControl>(Switch));
			if (componentInParent.inputType == GeneralInput.InputType.Controller)
			{
				Switch(MenuControllerHandler.MenuControl.Controller);
			}
			if (componentInParent.inputType == GeneralInput.InputType.Keyboard)
			{
				Switch(MenuControllerHandler.MenuControl.Mouse);
			}
		}
	}

	private void Switch(MenuControllerHandler.MenuControl control)
	{
		if (control == MenuControllerHandler.MenuControl.Controller)
		{
			if ((bool)controllerObject)
			{
				controllerObject.SetActive(value: true);
			}
			if ((bool)keyboardObject)
			{
				keyboardObject.SetActive(value: false);
			}
		}
		else
		{
			if ((bool)controllerObject)
			{
				controllerObject.SetActive(value: false);
			}
			if ((bool)keyboardObject)
			{
				keyboardObject.SetActive(value: true);
			}
		}
	}
}
public class MenuEffects : MonoBehaviour
{
	public static MenuEffects instance;

	public Color nopeColor;

	private void Awake()
	{
		instance = this;
	}

	public void ShakeObject(GameObject objectToShake, Vector3 defaultPos, float amount, float time)
	{
		StartCoroutine(DoShakeObject(objectToShake, defaultPos, amount, time));
	}

	private IEnumerator DoShakeObject(GameObject objectToShake, Vector3 defaultPos, float amount, float time)
	{
		float c = 0f;
		while (c < time)
		{
			Vector3 localPosition = defaultPos + UnityEngine.Random.onUnitSphere * amount * ((time - c) / time);
			localPosition.z = defaultPos.z;
			objectToShake.transform.localPosition = localPosition;
			c += Time.unscaledDeltaTime;
			yield return null;
		}
		objectToShake.transform.localPosition = defaultPos;
	}

	public void BlinkInColor(TextMeshProUGUI textToBlink, Color blinkColor, Color defaultColor, float seconds)
	{
		StartCoroutine(DoTextColorBlink(textToBlink, blinkColor, defaultColor, seconds));
	}

	private IEnumerator DoTextColorBlink(TextMeshProUGUI textToBlink, Color blinkColor, Color defaultColor, float seconds)
	{
		float c = 0f;
		while (c < seconds)
		{
			textToBlink.color = blinkColor;
			c += Time.unscaledDeltaTime;
			yield return null;
		}
		textToBlink.color = defaultColor;
	}
}
public class MoveTransformGravity : MonoBehaviour
{
	public float amount = 1f;

	public float pow = 1.5f;

	private MoveTransform move;

	private float counter;

	private void Start()
	{
		move = GetComponentInParent<MoveTransform>();
	}

	private void Update()
	{
		counter += TimeHandler.deltaTime;
		move.velocity += Vector3.down * Mathf.Pow(amount * counter, pow);
	}
}
public class MultiOptions : MonoBehaviour
{
	private GameObject source;

	private OptionsButton targetButton;

	private void Start()
	{
	}

	private void Update()
	{
		if (Input.GetKeyUp(KeyCode.Mouse0) || Input.GetKeyDown(KeyCode.Escape))
		{
			Close();
		}
	}

	internal void ClickRessButton(MultiOptionsButton buttonPressed)
	{
		targetButton.SetResolutionAndFullscreen(buttonPressed.currentRess, buttonPressed.currentFull);
		Close();
	}

	public void Open(OptionsButton.SettingsTarget settingsTarget, Vector3 pos, OptionsButton askingButton)
	{
		targetButton = askingButton;
		base.transform.position = pos;
		source = base.transform.GetChild(0).gameObject;
		if (settingsTarget == OptionsButton.SettingsTarget.Resolution)
		{
			PopulateRess(Screen.resolutions);
		}
		else
		{
			PopulateFullScreens(new Optionshandler.FullScreenOption[3]
			{
				Optionshandler.FullScreenOption.FullScreen,
				Optionshandler.FullScreenOption.WindowedFullScreen,
				Optionshandler.FullScreenOption.Windowed
			});
		}
		base.gameObject.SetActive(value: true);
		ListMenuButton[] componentsInChildren = base.transform.parent.GetComponentsInChildren<ListMenuButton>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (componentsInChildren[i].transform.parent != base.transform)
			{
				componentsInChildren[i].enabled = false;
			}
		}
		CanvasGroup[] componentsInChildren2 = base.transform.parent.GetComponentsInChildren<CanvasGroup>();
		for (int j = 0; j < componentsInChildren2.Length; j++)
		{
			componentsInChildren2[j].alpha = 0.05f;
			componentsInChildren2[j].interactable = false;
		}
		if (MenuControllerHandler.menuControl == MenuControllerHandler.MenuControl.Controller)
		{
			StartCoroutine(WaitFrame());
		}
		else
		{
			ListMenu.instance.ClearBar();
		}
	}

	private IEnumerator WaitFrame()
	{
		yield return new WaitForSecondsRealtime(0f);
		ListMenu.instance.SelectButton(GetComponentInChildren<ListMenuButton>());
	}

	public void Close()
	{
		base.gameObject.SetActive(value: false);
		ListMenuButton[] componentsInChildren = base.transform.parent.GetComponentsInChildren<ListMenuButton>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (componentsInChildren[i].transform.parent != base.transform)
			{
				componentsInChildren[i].enabled = true;
			}
		}
		CanvasGroup[] componentsInChildren2 = base.transform.parent.GetComponentsInChildren<CanvasGroup>();
		for (int j = 0; j < componentsInChildren2.Length; j++)
		{
			componentsInChildren2[j].alpha = 1f;
			componentsInChildren2[j].interactable = true;
		}
		if (MenuControllerHandler.menuControl == MenuControllerHandler.MenuControl.Controller)
		{
			ListMenu.instance.SelectButton(targetButton.transform.GetComponent<ListMenuButton>());
		}
		else
		{
			ListMenu.instance.ClearBar();
		}
	}

	private void PopulateRess(Resolution[] allRess)
	{
		for (int num = base.transform.childCount - 1; num > 0; num--)
		{
			UnityEngine.Object.Destroy(base.transform.GetChild(num).gameObject);
		}
		allRess = GetBestResolutions();
		for (int i = 0; i < allRess.Length; i++)
		{
			GameObject obj = UnityEngine.Object.Instantiate(source, source.transform.position, source.transform.rotation, source.transform.parent);
			obj.GetComponentInChildren<TextMeshProUGUI>().text = allRess[i].width + " x " + allRess[i].height;
			obj.GetComponent<MultiOptionsButton>().currentRess = allRess[i];
			obj.gameObject.SetActive(value: true);
		}
	}

	private Resolution[] GetBestResolutions()
	{
		List<Resolution> list = new List<Resolution>();
		for (int i = 0; i < Screen.resolutions.Length; i++)
		{
			if (IsBestRess(Screen.resolutions[i]))
			{
				list.Add(Screen.resolutions[i]);
			}
		}
		return list.ToArray();
	}

	private bool IsBestRess(Resolution newRess)
	{
		for (int i = 0; i < Screen.resolutions.Length; i++)
		{
			if (Screen.resolutions[i].width == newRess.width && Screen.resolutions[i].height == newRess.height && newRess.refreshRate < Screen.resolutions[i].refreshRate)
			{
				return false;
			}
		}
		return true;
	}

	private void PopulateFullScreens(Optionshandler.FullScreenOption[] allScreens)
	{
		for (int num = base.transform.childCount - 1; num > 0; num--)
		{
			UnityEngine.Object.Destroy(base.transform.GetChild(num).gameObject);
		}
		for (int i = 0; i < allScreens.Length; i++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(source, source.transform.position, source.transform.rotation, source.transform.parent);
			if (allScreens[i] == Optionshandler.FullScreenOption.WindowedFullScreen)
			{
				gameObject.GetComponentInChildren<TextMeshProUGUI>().text = "WINDOWED FULLSCREEN";
			}
			else
			{
				gameObject.GetComponentInChildren<TextMeshProUGUI>().text = allScreens[i].ToString().ToUpper();
			}
			gameObject.GetComponent<MultiOptionsButton>().currentFull = allScreens[i];
			gameObject.gameObject.SetActive(value: true);
		}
	}
}
