public class OptionsButton : MonoBehaviour
{
	public enum SettingsTarget
	{
		Resolution,
		Vol_Master,
		Vol_SFX,
		Vol_Music,
		CharacterPattern,
		MapPattern,
		leftStickAim,
		lockAimDirections,
		ShowCardStarts,
		FullScreen,
		FreeStickAim,
		Vsync
	}

	public enum SettingsType
	{
		Binary,
		Slider,
		MultiOption
	}

	public SettingsTarget settingsTarget;

	public SettingsType settingsType;

	public bool currentBoolValue;

	public Resolution currentResolutionValue;

	public Optionshandler.FullScreenOption currentFullscreenValue;

	public float currentFloatValue;

	private TextMeshProUGUI text;

	public Slider slider;

	private void Awake()
	{
		text = GetComponentsInChildren<TextMeshProUGUI>(includeInactive: true)[1];
		if (settingsType == SettingsType.Slider)
		{
			slider = GetComponentInChildren<Slider>(includeInactive: true);
			slider.onValueChanged.AddListener(SliderSlide);
		}
		else
		{
			GetComponent<Button>().onClick.AddListener(ClickButton);
		}
	}

	private void OnEnable()
	{
		switch (settingsTarget)
		{
		case SettingsTarget.Resolution:
			currentResolutionValue = Optionshandler.resolution;
			break;
		case SettingsTarget.Vol_Master:
			currentFloatValue = Optionshandler.vol_Master;
			break;
		case SettingsTarget.Vol_SFX:
			currentFloatValue = Optionshandler.vol_Sfx;
			break;
		case SettingsTarget.Vol_Music:
			currentFloatValue = Optionshandler.vol_Music;
			break;
		case SettingsTarget.CharacterPattern:
			currentBoolValue = Optionshandler.characterPattrens;
			break;
		case SettingsTarget.MapPattern:
			currentBoolValue = Optionshandler.mapPatterns;
			break;
		case SettingsTarget.leftStickAim:
			currentBoolValue = Optionshandler.leftStickAim;
			break;
		case SettingsTarget.lockAimDirections:
			currentBoolValue = Optionshandler.lockMouse;
			break;
		case SettingsTarget.FreeStickAim:
			currentBoolValue = Optionshandler.lockStick;
			break;
		case SettingsTarget.ShowCardStarts:
			currentBoolValue = Optionshandler.showCardStatNumbers;
			break;
		case SettingsTarget.FullScreen:
			currentFullscreenValue = Optionshandler.fullScreen;
			break;
		case SettingsTarget.Vsync:
			currentBoolValue = Optionshandler.vSync;
			break;
		}
		if (settingsType == SettingsType.Slider)
		{
			slider.value = currentFloatValue;
		}
		ReDraw();
	}

	public void SetResolutionAndFullscreen(Resolution newRess, Optionshandler.FullScreenOption fullScreen)
	{
		currentResolutionValue = newRess;
		currentFullscreenValue = fullScreen;
		ClickButton();
		if (settingsTarget == SettingsTarget.Resolution)
		{
			Optionshandler.instance.SetResolution(newRess);
		}
		if (settingsTarget == SettingsTarget.FullScreen)
		{
			Optionshandler.instance.SetFullScreen(fullScreen);
		}
	}

	public void SliderChanged()
	{
		currentFloatValue = slider.value;
	}

	private void SliderSlide(float newVal)
	{
		currentFloatValue = newVal;
		ClickButton();
	}

	public void ClickButton()
	{
		if (settingsType == SettingsType.Binary)
		{
			currentBoolValue = !currentBoolValue;
		}
		switch (settingsTarget)
		{
		case SettingsTarget.Resolution:
			base.transform.parent.parent.GetComponentInChildren<MultiOptions>(includeInactive: true).Open(settingsTarget, base.transform.GetChild(1).position, this);
			break;
		case SettingsTarget.Vol_Master:
			Optionshandler.instance.SetVolMaster(currentFloatValue);
			break;
		case SettingsTarget.Vol_SFX:
			Optionshandler.instance.SetVolSFX(currentFloatValue);
			break;
		case SettingsTarget.Vol_Music:
			Optionshandler.instance.SetVolMusic(currentFloatValue);
			break;
		case SettingsTarget.CharacterPattern:
			Optionshandler.instance.SetCharacterPatterns(currentBoolValue);
			break;
		case SettingsTarget.MapPattern:
			Optionshandler.instance.SetMapPatterns(currentBoolValue);
			break;
		case SettingsTarget.leftStickAim:
			Optionshandler.instance.SetLeftStickAim(currentBoolValue);
			break;
		case SettingsTarget.lockAimDirections:
			Optionshandler.instance.lockMouseAim(currentBoolValue);
			break;
		case SettingsTarget.FreeStickAim:
			Optionshandler.instance.lockStickAim(currentBoolValue);
			break;
		case SettingsTarget.ShowCardStarts:
			Optionshandler.instance.SetShowCardStatNumbers(currentBoolValue);
			break;
		case SettingsTarget.FullScreen:
			base.transform.parent.parent.GetComponentInChildren<MultiOptions>(includeInactive: true).Open(settingsTarget, base.transform.GetChild(1).position, this);
			break;
		case SettingsTarget.Vsync:
			Optionshandler.instance.SetVSync(currentBoolValue);
			break;
		}
		ReDraw();
	}

	private void ReDraw()
	{
		if (settingsType == SettingsType.Binary)
		{
			text.text = (currentBoolValue ? "YES" : "NO");
		}
		if (settingsType == SettingsType.MultiOption)
		{
			if (settingsTarget == SettingsTarget.Resolution)
			{
				text.text = currentResolutionValue.width + " X " + currentResolutionValue.height;
			}
			else if (currentFullscreenValue == Optionshandler.FullScreenOption.WindowedFullScreen)
			{
				text.text = "WINDOWED FULLSCREEN";
			}
			else
			{
				text.text = currentFullscreenValue.ToString().ToUpper();
			}
		}
	}
}
public class Optionshandler : MonoBehaviour
{
	public enum FullScreenOption
	{
		FullScreen,
		WindowedFullScreen,
		MaximizedWindow,
		Windowed
	}

	public static Resolution resolution;

	public static float vol_Master;

	public static float vol_Sfx;

	public static float vol_Music;

	public static FullScreenOption fullScreen;

	public static bool characterPattrens;

	public static bool mapPatterns;

	public static bool vSync;

	public static bool leftStickAim;

	public static bool lockMouse;

	public static bool showCardStatNumbers;

	public static bool lockStick;

	public static Optionshandler instance;

	private void Start()
	{
		instance = this;
		LoadOptions();
		ApplyOptions();
	}

	private void LoadOptions()
	{
		vol_Master = PlayerPrefs.GetFloat("Vol_Master", 1f);
		vol_Sfx = PlayerPrefs.GetFloat("vol_Sfx", 1f);
		vol_Music = PlayerPrefs.GetFloat("vol_Music", 1f);
		resolution.width = PlayerPrefs.GetInt("res_X", 0);
		resolution.height = PlayerPrefs.GetInt("res_Y", 0);
		fullScreen = (FullScreenOption)PlayerPrefs.GetInt("fullScreen", 1);
		characterPattrens = GetBool(PlayerPrefs.GetInt("characterPattrens", 1));
		mapPatterns = GetBool(PlayerPrefs.GetInt("mapPatterns", 1));
		leftStickAim = GetBool(PlayerPrefs.GetInt("leftStickAim", 1));
		vSync = GetBool(PlayerPrefs.GetInt("vSync", 0));
		lockStick = GetBool(PlayerPrefs.GetInt("lockStick", 0));
		lockMouse = GetBool(PlayerPrefs.GetInt("lockMouse", 0));
		showCardStatNumbers = GetBool(PlayerPrefs.GetInt("showCardStatNumbers", 0));
		if (resolution.height == 0 || resolution.width == 0)
		{
			resolution = Screen.currentResolution;
			SaveOptions();
		}
		else
		{
			ApplyOptions();
		}
	}

	private void SaveOptions()
	{
		PlayerPrefs.SetFloat("Vol_Master", vol_Master);
		PlayerPrefs.SetFloat("vol_Sfx", vol_Sfx);
		PlayerPrefs.SetFloat("vol_Music", vol_Music);
		PlayerPrefs.SetInt("res_X", resolution.width);
		PlayerPrefs.SetInt("res_Y", resolution.height);
		PlayerPrefs.SetInt("fullScreen", (int)fullScreen);
		PlayerPrefs.SetInt("characterPattrens", GetInt(characterPattrens));
		PlayerPrefs.SetInt("mapPatterns", GetInt(mapPatterns));
		PlayerPrefs.SetInt("leftStickAim", GetInt(leftStickAim));
		PlayerPrefs.SetInt("vSync", GetInt(vSync));
		PlayerPrefs.SetInt("lockMouse", GetInt(lockMouse));
		PlayerPrefs.SetInt("lockStick", GetInt(lockStick));
		PlayerPrefs.SetInt("showCardStatNumbers", GetInt(showCardStatNumbers));
		ApplyOptions();
	}

	private void ApplyOptions()
	{
		Screen.SetResolution(resolution.width, resolution.height, (FullScreenMode)fullScreen);
		QualitySettings.vSyncCount = (vSync ? 1 : 0);
		SoundVolumeManager.Instance.SetAudioMixerVolumes(vol_Master, vol_Music, vol_Sfx);
	}

	private bool GetBool(int value)
	{
		if (value != 1)
		{
			return false;
		}
		return true;
	}

	private int GetInt(bool value)
	{
		if (!value)
		{
			return 0;
		}
		return 1;
	}

	public void SetResolution(Resolution resolutionToSet)
	{
		resolution = resolutionToSet;
		SaveOptions();
	}

	public void SetVSync(bool vSyncToSet)
	{
		vSync = vSyncToSet;
		SaveOptions();
	}

	public void SetVolMaster(float vol_Master_ToSet)
	{
		vol_Master = vol_Master_ToSet;
		SaveOptions();
	}

	public void SetVolSFX(float vol_SFX_ToSet)
	{
		vol_Sfx = vol_SFX_ToSet;
		SaveOptions();
	}

	public void SetVolMusic(float vol_Music_ToSet)
	{
		vol_Music = vol_Music_ToSet;
		SaveOptions();
	}

	public void SetCharacterPatterns(bool characterPatternsToSet)
	{
		characterPattrens = characterPatternsToSet;
		SaveOptions();
	}

	public void SetMapPatterns(bool mapPatternsToSet)
	{
		mapPatterns = mapPatternsToSet;
		SaveOptions();
	}

	public void SetLeftStickAim(bool leftStickAimToSet)
	{
		leftStickAim = leftStickAimToSet;
		SaveOptions();
	}

	public void lockMouseAim(bool setLockMouse)
	{
		lockMouse = setLockMouse;
		SaveOptions();
	}

	public void lockStickAim(bool setLockStick)
	{
		lockStick = setLockStick;
		SaveOptions();
	}

	public void SetShowCardStatNumbers(bool showCardStatNumbersToSet)
	{
		showCardStatNumbers = showCardStatNumbersToSet;
		SaveOptions();
	}

	public void SetFullScreen(FullScreenOption fullscreenToSet)
	{
		fullScreen = fullscreenToSet;
		SaveOptions();
	}
}
public class Orbit : MonoBehaviour
