public class LowFrameRate : MonoBehaviourPunCallbacks
{
	public enum SlowWhat
	{
		Both,
		Server,
		Client
	}

	public SlowWhat slowWhat = SlowWhat.Server;

	public int targetFrameRate = 10;

	public override void OnJoinedRoom()
	{
		base.OnJoinedRoom();
		if (slowWhat == SlowWhat.Both || (PhotonNetwork.IsMasterClient && slowWhat == SlowWhat.Server) || (!PhotonNetwork.IsMasterClient && slowWhat == SlowWhat.Client))
		{
			Application.targetFrameRate = targetFrameRate;
			QualitySettings.vSyncCount = 0;
		}
		else
		{
			Application.targetFrameRate = 100;
		}
	}
}
public class SuperBasicController : NetComponent
{
	public bool is2D;

	[Range(0f, 300f)]
	public float turnSpeed = 150f;

	[Range(0f, 4f)]
	public float moveSpeed = 4f;

	public bool autoMove = true;

	private Vector3 targRotDelta;

	private Vector3 targPosDelta;

	private float appliedDeltaT;

	private Animator animator;

	private SyncAnimator syncAnimator;

	private SyncTransform syncTransform;

	private SyncCannon syncLauncher;

	private SyncContactScan syncHitscan;

	private bool triggerJump;

	private bool triggerFade;

	private bool triggerTurnLeft;

	private bool triggerUpperBodyRun;

	private bool triggerUpperBodyIdle;

	private bool triggerTeleport;

	private bool freakingOut;

	private bool triggerHitscan;

	private bool triggerProjectile;

	private bool triggerBlend;

	public override void OnAwake()
	{
		base.OnAwake();
		animator = base.transform.GetNestedComponentInChildren<Animator, NetObject>(includeInactive: true);
		syncAnimator = base.transform.GetNestedComponentInChildren<SyncAnimator, NetObject>(includeInactive: true);
		syncTransform = GetComponent<SyncTransform>();
		syncLauncher = base.transform.GetNestedComponentInChildren<SyncCannon, NetObject>(includeInactive: true);
		syncHitscan = base.transform.GetNestedComponentInChildren<SyncContactScan, NetObject>(includeInactive: true);
	}

	private void Update()
	{
		if (!base.IsMine)
		{
			return;
		}
		float t = (Time.time - Time.fixedTime) / Time.fixedDeltaTime;
		Interpolate(t);
		if (Input.GetKeyDown(KeyCode.Space))
		{
			triggerJump = true;
		}
		if (Input.GetKeyDown(KeyCode.Alpha2))
		{
			triggerFade = true;
		}
		if (Input.GetKeyDown(KeyCode.Alpha1))
		{
			triggerTurnLeft = true;
		}
		if (Input.GetKeyDown(KeyCode.Alpha4))
		{
			if (freakingOut)
			{
				triggerUpperBodyIdle = true;
			}
			else
			{
				triggerUpperBodyRun = true;
			}
			freakingOut = !freakingOut;
		}
		if (Input.GetKeyDown(KeyCode.F))
		{
			triggerProjectile = true;
		}
		if (Input.GetKeyDown(KeyCode.R))
		{
			triggerHitscan = true;
		}
		if (Input.GetKeyDown(KeyCode.T))
		{
			triggerTeleport = true;
		}
		if (Input.GetKeyDown(KeyCode.B))
		{
			triggerBlend = true;
		}
	}

	private void FixedUpdate()
	{
		if (!base.IsMine)
		{
			return;
		}
		Vector3 move = new Vector3(0f, 0f, 0f);
		Vector3 turn = new Vector3(0f, 0f, 0f);
		if ((bool)animator && animator.isActiveAndEnabled)
		{
			if (Input.GetKey(KeyCode.W))
			{
				animator.SetBool("walking", value: true);
				animator.SetFloat("speed", 1f);
			}
			else if (Input.GetKey(KeyCode.S))
			{
				animator.SetBool("walking", value: true);
				animator.SetFloat("speed", -0.5f);
			}
			else
			{
				animator.SetBool("walking", value: false);
				animator.SetFloat("speed", 0f);
			}
			if (triggerJump)
			{
				if ((bool)syncAnimator)
				{
					syncAnimator.SetTrigger("jump");
				}
				triggerJump = false;
			}
			else if (triggerTurnLeft)
			{
				if ((bool)syncAnimator)
				{
					syncAnimator.SetTrigger("turnLeft");
				}
				triggerTurnLeft = false;
			}
			if (triggerFade)
			{
				if ((bool)syncAnimator)
				{
					syncAnimator.CrossFadeInFixedTime("Jump", 0.25f);
				}
				triggerFade = false;
			}
			if (triggerBlend)
			{
				animator.SetFloat("blender", Mathf.Abs(Mathf.Sin(Time.time)));
			}
			else
			{
				animator.SetFloat("blender", -1f);
			}
			if (triggerUpperBodyRun)
			{
				if ((bool)syncAnimator)
				{
					syncAnimator.SetTrigger("upperBodyRun");
				}
				triggerUpperBodyRun = false;
			}
			else if (triggerUpperBodyIdle)
			{
				if ((bool)syncAnimator)
				{
					syncAnimator.SetTrigger("upperBodyIdle");
				}
				triggerUpperBodyIdle = false;
			}
		}
		if (!animator || !animator.applyRootMotion)
		{
			if (Input.GetKey(KeyCode.W))
			{
				move += Vector3.forward;
			}
			else if (Input.GetKey(KeyCode.S))
			{
				move -= Vector3.forward;
			}
		}
		if (Input.GetKey(KeyCode.A))
		{
			move -= Vector3.right;
		}
		if (Input.GetKey(KeyCode.D))
		{
			move += Vector3.right;
		}
		if (Input.GetKey(KeyCode.E))
		{
			turn += Vector3.up;
		}
		if (Input.GetKey(KeyCode.Q))
		{
			turn -= Vector3.up;
		}
		if (Input.touchCount > 0)
		{
			UnityEngine.Touch touch = Input.GetTouch(0);
			Vector2 vector = new Vector2(touch.rawPosition.x / (float)Screen.width, touch.rawPosition.y / (float)Screen.height);
			if (vector.y > 0.66f)
			{
				if (vector.x > 0.66f)
				{
					triggerHitscan = true;
				}
				else if (vector.x < 0.33f)
				{
					triggerJump = true;
				}
			}
			else if (vector.y < 0.33f)
			{
				if (vector.x > 0.66f)
				{
					move += Vector3.right;
				}
				else if (vector.x < 0.33f)
				{
					move -= Vector3.right;
				}
				else if ((bool)animator)
				{
					animator.SetBool("walking", value: true);
					animator.SetFloat("speed", -0.5f);
				}
			}
			else if (vector.x > 0.66f)
			{
				turn += Vector3.up;
			}
			else if (vector.x < 0.33f)
			{
				turn -= Vector3.up;
			}
			else if ((bool)animator)
			{
				animator.SetBool("walking", value: true);
				animator.SetFloat("speed", 1f);
			}
		}
		if (autoMove && !Application.isFocused)
		{
			turn += new Vector3(0f, Mathf.Sin(Time.time * 0.5f), 0f);
			if ((bool)animator)
			{
				animator.SetBool("walking", value: true);
				animator.SetFloat("speed", Mathf.Sin(Time.time) * 0.5f);
			}
		}
		Interpolate(1f);
		Move(move, turn);
		appliedDeltaT = 0f;
		if (triggerHitscan)
		{
			if ((bool)syncHitscan)
			{
				syncHitscan.QueueTrigger();
			}
			triggerHitscan = false;
		}
		if (triggerProjectile)
		{
			if ((bool)syncLauncher)
			{
				syncLauncher.QueueTrigger();
			}
			triggerProjectile = false;
		}
		if (triggerTeleport)
		{
			if ((bool)syncTransform)
			{
				syncTransform.FlagTeleport();
				base.transform.localPosition = default(Vector3);
				base.transform.localRotation = default(Quaternion);
			}
			triggerTeleport = false;
		}
	}

	private void OnAnimatorMove()
	{
		if (base.IsMine)
		{
			animator.ApplyBuiltinRootMotion();
			base.transform.rotation = animator.rootRotation;
			base.transform.position = animator.rootPosition;
		}
	}

	private void Move(Vector3 move, Vector3 turn)
	{
		if (is2D)
		{
			move = new Vector3(move.x, move.z, 0f);
			turn = new Vector3(0f, 0f, turn.y);
		}
		targRotDelta = turn * turnSpeed * Time.fixedDeltaTime;
		targPosDelta = move * moveSpeed * Time.fixedDeltaTime;
	}

	private void Interpolate(float t)
	{
		t -= appliedDeltaT;
		appliedDeltaT += t;
		base.transform.rotation = base.transform.rotation * Quaternion.Euler(targRotDelta * t);
		base.transform.position += base.transform.rotation * (targPosDelta * t);
	}
}
public class TickMover : MonoBehaviour, IOnPostSimulate
{
	private Vector3 rotationPerTick;

	private TextMesh tickText;

	private void Awake()
	{
		NetMasterCallbacks.RegisterCallbackInterfaces(this);
		rotationPerTick = new Vector3(0f, 0f, 360f * (Time.fixedDeltaTime * (float)TickEngineSettings.sendEveryXTick));
		tickText = GetComponentInChildren<TextMesh>();
		if (!tickText)
		{
			tickText = GetComponentInParent<TextMesh>();
		}
		if ((bool)tickText)
		{
			tickText.text = "";
		}
	}

	private void OnDestroy()
	{
		NetMasterCallbacks.RegisterCallbackInterfaces(this, register: false, delay: true);
	}

	public void OnPostSimulate(int frameId, int subFrameId, bool isNetTick)
	{
		if (isNetTick)
		{
			base.transform.eulerAngles -= rotationPerTick;
			if ((bool)tickText)
			{
				tickText.text = frameId.ToString();
			}
		}
	}
}
public class PhotonMapObject : MonoBehaviour
{
	private Map map;

	private bool photonSpawned;

	private float counter;

	private bool waitingToBeRemoved;

	private void Awake()
	{
		if (base.transform.parent != null)
		{
			UnityEngine.Object.DestroyImmediate(GetComponent<PhotonView>());
		}
	}

	private void Start()
	{
		Rigidbody2D component = GetComponent<Rigidbody2D>();
		component.isKinematic = true;
		component.simulated = false;
		if (base.transform.parent == null)
		{
			photonSpawned = true;
			base.transform.SetParent(MapManager.instance.currentMap.Map.transform, worldPositionStays: true);
			map = GetComponentInParent<Map>();
			map.missingObjects--;
			Map obj = map;
			obj.mapIsReadyAction = (Action)Delegate.Combine(obj.mapIsReadyAction, new Action(Go));
			if (map.hasRope && !GetComponent<PhotonView>().IsMine)
			{
				component.gravityScale = 0f;
			}
		}
		else
		{
			map = GetComponentInParent<Map>();
			Map obj2 = map;
			obj2.mapIsReadyEarlyAction = (Action)Delegate.Combine(obj2.mapIsReadyEarlyAction, new Action(GoEarly));
		}
	}

	private void GoEarly()
	{
		if (waitingToBeRemoved)
		{
			UnityEngine.Object.DestroyImmediate(base.gameObject);
		}
	}

	private void Go()
	{
		StartCoroutine(IGo());
	}

	private IEnumerator IGo()
	{
		Rigidbody2D rig = GetComponent<Rigidbody2D>();
		yield return new WaitForSeconds(0f);
		yield return new WaitForSeconds(0f);
		yield return new WaitForSeconds(0f);
		rig.isKinematic = false;
		rig.simulated = true;
		if ((bool)rig)
		{
			for (float i = 0f; i < 1f; i += Time.deltaTime * 1f)
			{
				rig.velocity -= rig.velocity * i * 0.05f;
				yield return null;
			}
		}
	}

	private void Update()
	{
		if (waitingToBeRemoved || photonSpawned)
		{
			return;
		}
		counter += Mathf.Clamp(Time.deltaTime, 0f, 0.1f);
		if ((PhotonNetwork.OfflineMode && counter > 1f && map.hasEntered) || ((bool)map && map.hasEntered && map.LoadedForAll()))
		{
			if (PhotonNetwork.IsMasterClient)
			{
				PhotonNetwork.Instantiate("4 Map Objects/" + base.gameObject.name.Split(char.Parse(" "))[0], base.transform.position, base.transform.rotation, 0);
			}
			map.missingObjects++;
			waitingToBeRemoved = true;
		}
	}
}
public class PlayerAIMinion : MonoBehaviour
{
	public AnimationCurve m_AimCompensastionCurve;

	public float range = 5f;

	private PlayerAPI api;

	private Vector2 moveDirection;

	private void Start()
	{
		api = GetComponentInParent<PlayerAPI>();
		moveDirection = api.data.master.data.aimDirection;
		if (moveDirection.x > 0.5f)
		{
			moveDirection.x = 1f;
		}
		else if (moveDirection.x < -0.5f)
		{
			moveDirection.x = -1f;
		}
		else
		{
			moveDirection.x = 0f;
		}
		moveDirection.y = 0f;
		base.transform.root.gameObject.AddComponent<RemoveAfterSeconds>().seconds = 4f;
	}

	private void Update()
	{
		Player otherPlayer = PlayerManager.instance.GetOtherPlayer(api.data.master);
		api.Move(moveDirection);
		if (api.data.isWallGrab)
		{
			api.Jump();
		}
		if (!api.data.isGrounded)
		{
			api.Jump();
		}
		if ((bool)otherPlayer)
		{
			api.SetAimDirection(GetAimDirForHitting(otherPlayer.transform.position));
			if (PlayerManager.instance.CanSeePlayer(base.transform.position, otherPlayer).canSee && Vector2.Distance(base.transform.position, otherPlayer.transform.position) < range)
			{
				api.Attack();
			}
		}
	}

	private Vector2 GetAimDirForHitting(Vector3 point)
	{
		Vector3 vector = point - base.transform.position;
		api.SetAimDirection(vector);
		api.GetMyBullet();
		float time = Mathf.Abs(point.x - base.transform.position.x);
		return point + Vector3.up * m_AimCompensastionCurve.Evaluate(time) - base.transform.position;
	}
}
public class PlayerAIPetter : MonoBehaviour
{
	private PlayerAPI api;

	public LayerMask m_layer;

	public AnimationCurve aimCurve;

	public float m_shootRandom = 0.9f;

	public float m_predDist = 1f;

	public float m_timeSinceGround = 0.1f;

	private BoxCollider2D m_collider;

	private void Start()
	{
		api = GetComponentInParent<PlayerAPI>();
		m_collider = api.GetComponentInChildren<BoxCollider2D>();
	}

	private void Update()
	{
		if ((double)UnityEngine.Random.Range(0f, 1f) > 0.9)
		{
			api.Move(api.TowardsOtherPlayer() * -1f);
		}
		else
		{
			api.Move(api.TowardsOtherPlayer());
		}
		PredictionHit();
		api.Attack();
		if ((double)UnityEngine.Random.Range(0f, 1f) > 0.9)
		{
			api.Jump();
		}
		AutoBlock();
	}

	private void AutoBlock()
	{
		foreach (BulletWrapper allBullet in api.GetAllBullets())
		{
			RaycastHit2D raycastHit2D = Physics2D.Raycast(allBullet.projectileMovement.transform.position, ((Vector2)allBullet.projectileMovement.velocity).normalized, allBullet.velocity.magnitude * 5f * TimeHandler.deltaTime, m_layer);
			if ((bool)raycastHit2D.transform && (!allBullet.projectileHit.ownPlayer || allBullet.projectileHit.ownPlayer != api.player) && raycastHit2D.transform.root == base.transform.root)
			{
				Debug.Log("BLICOK");
				api.Block();
			}
		}
	}

	private void PredictionHit()
	{
		if ((bool)api.GetOtherPlayer())
		{
			float magnitude = (api.OtherPlayerPosition() - base.transform.position).magnitude;
			Vector2 vector = api.GetOtherPlayer().data.playerVel.velocity * m_predDist * 0.1f * magnitude * 0.05f;
			api.SetAimDirection(api.TowardsOtherPlayer() + Vector2.up * aimCurve.Evaluate(magnitude) + vector);
		}
	}
}
public class PlayerAIZorro : MonoBehaviour
{
	public AnimationCurve m_AimCompensastionCurve;

	public LayerMask m_MapMask;

	public LayerMask m_PlayerMask;

	private PlayerAPI api;

	private Camera m_camera;

	private int framesSinceShot;

	private Vector3[] surfacesToHideOn;

	private Vector3 m_CurrentHidePos;

	private float tiemSpentOverDeath;

	private float timeSinceCouldShoot;

	private void Start()
	{
		api = GetComponentInParent<PlayerAPI>();
		m_camera = Camera.main;
		HealthHandler healthHandler = api.player.data.healthHandler;
		healthHandler.delayedReviveAction = (Action)Delegate.Combine(healthHandler.delayedReviveAction, new Action(Init));
	}

	public void Init()
	{
		StopAllCoroutines();
		BakeMapSurfaces();
		StartCoroutine(GetNewPos());
	}

	private void Update()
	{
		framesSinceShot++;
		if (api.CanShoot())
		{
			timeSinceCouldShoot += TimeHandler.deltaTime;
		}
		else
		{
			timeSinceCouldShoot = 0f;
		}
		Vector3 vector = api.OtherPlayerPosition() + (Vector3)api.GetOtherPlayer().data.playerVel.velocity * Vector3.Distance(base.transform.position, api.OtherPlayerPosition()) * 0.01f + Vector3.down * api.GetOtherPlayer().data.playerVel.velocity.y * Vector3.Distance(base.transform.position, api.OtherPlayerPosition()) * 0.005f;
		bool flag = false;
		if (Physics2D.Raycast(base.transform.position, Vector3.down, 18f, m_MapMask).transform == null)
		{
			flag = false;
			tiemSpentOverDeath += TimeHandler.deltaTime;
		}
		else
		{
			flag = true;
			tiemSpentOverDeath = 0f;
		}
		if (api.CanBlock() && Vector3.Distance(base.transform.position, api.OtherPlayerPosition()) > 5f && (flag || tiemSpentOverDeath < 0.25f))
		{
			api.Move(vector - base.transform.position + new Vector3(Mathf.PerlinNoise(Time.time, 0f) * 5f * Mathf.Sin(Time.time * 2f), 0f, 0f));
		}
		else
		{
			api.Move(m_CurrentHidePos - base.transform.position + new Vector3(Mathf.PerlinNoise(Time.time, 0f) * 8f * Mathf.Sin(Time.time * 3f), 0f, 0f));
		}
		api.Jump();
		ShootAt(vector);
		MakeSureToBlock();
	}

	public void MakeSureToBlock()
	{
		BulletWrapper[] array = api.GetAllBullets().ToArray();
		for (int i = 0; i < array.Length; i++)
		{
			float num = Vector3.Distance(array[i].projectileMovement.transform.position, base.transform.position);
			float num2 = Vector3.Angle(array[i].velocity.normalized, base.transform.position - array[i].projectileMovement.transform.position);
			if (num < 1.3f && num2 < 65f && framesSinceShot >= 4)
			{
				api.Block();
			}
		}
	}

	public BulletWrapper GetMostDangerousBullet(BulletWrapper[] bullets, out bool exsists)
	{
		float num = 999999f;
		int num2 = -1;
		for (int i = 0; i < bullets.Length; i++)
		{
			float num3 = Vector3.Distance(bullets[i].projectileMovement.transform.position, base.transform.position);
			if (num3 < num && num3 < 5f)
			{
				num = num3;
				num2 = i;
			}
		}
		if (num2 != -1)
		{
			exsists = true;
			return bullets[num2];
		}
		exsists = false;
		return new BulletWrapper();
	}

	public BulletWrapper[] GetAllBulletsComingAtMe()
	{
		List<BulletWrapper> list = new List<BulletWrapper>();
		BulletWrapper[] array = api.GetAllBullets().ToArray();
		for (int i = 0; i < array.Length; i++)
		{
			if (Vector3.Angle(array[i].velocity.normalized, base.transform.position - array[i].projectileMovement.transform.position) < 35f)
			{
				list.Add(array[i]);
			}
		}
		return list.ToArray();
	}

	public void ShootAt(Vector3 point)
	{
		api.SetAimDirection(GetAimDirForHitting(point));
		api.Attack();
	}

	private Vector2 GetAimDirForHitting(Vector3 point)
	{
		Vector3 vector = point - base.transform.position;
		api.SetAimDirection(vector);
		api.GetMyBullet();
		float time = Mathf.Abs(point.x - base.transform.position.x);
		Vector3 vector2 = point + Vector3.up * m_AimCompensastionCurve.Evaluate(time);
		Debug.DrawLine(point, vector2, Color.red, 0.2f);
		return vector2 - base.transform.position;
	}

	public void BakeMapSurfaces()
	{
		Vector2 vector = m_camera.ViewportToWorldPoint(new Vector3(1f, 1f));
		Vector2 vector2 = m_camera.ViewportToWorldPoint(new Vector3(0f, 1f));
		Vector2 vector3 = m_camera.ViewportToWorldPoint(new Vector3(1f, 0f));
		Vector2 vector4 = m_camera.ViewportToWorldPoint(new Vector3(0f, 0f));
		Vector3 v = m_camera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f));
		Debug.DrawLine(vector, v, Color.cyan);
		Debug.DrawLine(vector2, v, Color.cyan);
		Debug.DrawLine(vector3, v, Color.cyan);
		Debug.DrawLine(vector4, v, Color.cyan);
		List<Vector3> list = new List<Vector3>();
		for (int i = 0; i < 360; i++)
		{
			for (int j = 0; j < 40; j++)
			{
				RaycastHit2D raycastHit2D = Physics2D.Raycast(new Vector2(Mathf.Lerp(vector2.x, vector.x, (float)i / 359f), Mathf.Lerp(vector3.y, vector.y, (float)j / 39f)), Vector3.down, 6f, m_MapMask);
				if ((bool)raycastHit2D.transform)
				{
					list.Add(raycastHit2D.point);
				}
			}
		}
		List<Vector3> list2 = new List<Vector3>();
		for (int k = 0; k < list.Count; k++)
		{
			if (Physics2D.OverlapCircleAll(list[k] + Vector3.up * 0.26f, 0.1f, m_MapMask).Length != 0)
			{
				list2.Add(list[k]);
			}
		}
		for (int l = 0; l < list2.Count; l++)
		{
			list.Remove(list2[l]);
		}
		Debug.Log("Points: " + list.Count);
		for (int m = 0; m < list.Count; m++)
		{
			Debug.DrawLine(list[m], list[m] + Vector3.up * 0.2f, Color.magenta, 1000f);
		}
		surfacesToHideOn = list.ToArray();
	}

	private IEnumerator GetNewPos()
	{
		while (true)
		{
			m_CurrentHidePos = GetPosAwayFrom(api.OtherPlayerPosition());
			yield return new WaitForSeconds(4f);
		}
	}

	public Vector3 GetPosAwayFrom(Vector3 point)
	{
		Vector3 result;
		do
		{
			result = surfacesToHideOn[UnityEngine.Random.Range(0, surfacesToHideOn.Length)];
		}
		while (!(Mathf.Abs(result.x - point.x) > 13f));
		return result;
	}
}
public class PlayerCollision : MonoBehaviour
{
	[Header("Sounds")]
	public SoundEvent soundBounce;

	[Header("Settings")]
	public LayerMask mask;

	private Vector2 lastPos;

	public bool checkForGoThroughWall = true;

	private int ignoreWallFor;

	private Collider2D col;

	private CircleCollider2D cirCol;

	private PlayerVelocity vel;

	private CharacterData data;

	public Action<Vector2, Vector2, Player> collideWithPlayerAction;

	public float bounceTreshold = 1f;

	private bool isBounce;

	public void IgnoreWallForFrames(int frames)
	{
		ignoreWallFor = frames;
	}

	private void Start()
	{
		data = GetComponent<CharacterData>();
		col = GetComponent<Collider2D>();
		cirCol = GetComponent<CircleCollider2D>();
		vel = GetComponent<PlayerVelocity>();
	}

	private void FixedUpdate()
	{
		if (checkForGoThroughWall && ignoreWallFor <= 0)
		{
			RaycastHit2D raycastHit2D = default(RaycastHit2D);
			RaycastHit2D[] array = Physics2D.RaycastAll(lastPos, (Vector2)base.transform.position - lastPos, Vector2.Distance(base.transform.position, lastPos), mask);
			for (int i = 0; i < array.Length; i++)
			{
				if (!(array[i].transform.root == base.transform.root))
				{
					Debug.DrawLine(lastPos, array[i].point, Color.green, 1f);
					if (!(Vector2.Angle(array[i].normal, (Vector2)base.transform.position - lastPos) < 90f) && (!raycastHit2D.transform || array[i].distance < raycastHit2D.distance))
					{
						raycastHit2D = array[i];
					}
				}
			}
			if ((bool)raycastHit2D)
			{
				base.transform.position = raycastHit2D.point + raycastHit2D.normal * 0.5f;
				if (data.healthHandler.flyingFor > 0f)
				{
					DoBounce(raycastHit2D);
				}
			}
		}
		ignoreWallFor--;
		lastPos = base.transform.position;
		float num = cirCol.radius * base.transform.localScale.x;
		float num2 = cirCol.radius * base.transform.localScale.x * 0.75f;
		RaycastHit2D[] array2 = Physics2D.CircleCastAll(lastPos, num, (Vector2)base.transform.position - lastPos, Vector2.Distance(base.transform.position, lastPos), mask);
		for (int j = 0; j < array2.Length; j++)
		{
			if (array2[j].transform.root == base.transform.root)
			{
				continue;
			}
			Vector2 vector = base.transform.position;
			Vector2 point = array2[j].point;
			float num3 = Vector2.Distance(vector, point);
			Vector2 normalized = (vector - point).normalized;
			float value = num + (0f - num3);
			float value2 = num2 + (0f - num3);
			value = Mathf.Clamp(value, 0f, 10f);
			value2 = Mathf.Clamp(value2, 0f, 10f);
			NetworkPhysicsObject component = array2[j].transform.GetComponent<NetworkPhysicsObject>();
			if ((bool)component)
			{
				component.Push(data);
			}
			if (vel.simulated || !vel.isKinematic)
			{
				vel.transform.position += (Vector3)normalized * value2;
				if (Mathf.Abs(normalized.y) < 0.45f && Mathf.Abs(data.input.direction.x) > 0.1f && Vector3.Angle(data.input.direction, normalized) > 90f)
				{
					data.TouchWall(normalized, point);
				}
				vel.velocity += normalized * value * 10f * TimeHandler.timeScale;
				vel.velocity -= vel.velocity * value * 1f * TimeHandler.timeScale;
			}
			Player componentInParent = array2[j].transform.GetComponentInParent<Player>();
			if (componentInParent != null && collideWithPlayerAction != null)
			{
				collideWithPlayerAction(point, value * normalized, componentInParent);
			}
			if (data.healthHandler.flyingFor > 0f)
			{
				DoBounce(array2[j]);
			}
		}
		lastPos = base.transform.position;
	}

	private void DoBounce(RaycastHit2D hit)
	{
		if (!(Vector2.Angle(data.playerVel.velocity, hit.normal) < 90f) && !isBounce && data.view.IsMine && data.playerVel.velocity.magnitude > bounceTreshold)
		{
			data.view.RPC("RPCADoBounce", RpcTarget.All, hit.normal, base.transform.position);
		}
	}

	[PunRPC]
	private void RPCADoBounce(Vector2 hit, Vector3 playerPos)
	{
		base.transform.position = playerPos;
		StartCoroutine(IDoBounce(Vector2.Reflect(data.playerVel.velocity, hit)));
		SoundManager.Instance.Play(soundBounce, base.transform);
	}

	public IEnumerator IDoBounce(Vector2 targetVel)
	{
		isBounce = true;
		data.stunHandler.AddStun(0.2f);
		data.healthHandler.CallTakeDamage(targetVel.normalized * 5f, base.transform.position);
		GamefeelManager.instance.AddGameFeel(targetVel.normalized * 4f);
		yield return new WaitForSeconds(0.25f);
		data.playerVel.velocity = targetVel;
		isBounce = false;
	}

	private void OnDisable()
	{
		isBounce = false;
	}
}
