	}
}
public class RingHandler : MonoBehaviour
{
	public float timeBeforeRing = 30f;

	public static RingHandler instance;

	private CodeAnimation code;

	private float counter;

	private void Awake()
	{
		instance = this;
	}

	private void Start()
	{
		code = GetComponent<CodeAnimation>();
	}

	private void Update()
	{
		if (GameManager.instance.isPlaying)
		{
			if (code.currentState != CodeAnimationInstance.AnimationUse.In && counter > timeBeforeRing && !code.isPlaying)
			{
				code.PlayIn();
			}
			counter += TimeHandler.deltaTime;
		}
		else
		{
			if (code.currentState != CodeAnimationInstance.AnimationUse.Out && !code.isPlaying)
			{
				code.PlayOut();
			}
			counter = 0f;
		}
	}

	public Vector2 ClosestPoint(Vector2 pos)
	{
		return pos.normalized * Radius();
	}

	public float Radius()
	{
		return base.transform.localScale.x * 95f;
	}
}
public class RotSpring : MonoBehaviour
{
	public bool x;

	public bool y;

	public bool z;

	public float target;

	public float spring;

	public float damper;

	private float currentValue;

	private float vel;

	private void Start()
	{
		if (x)
		{
			currentValue = base.transform.localEulerAngles.x;
		}
		else if (y)
		{
			currentValue = base.transform.localEulerAngles.y;
		}
		else if (z)
		{
			currentValue = base.transform.localEulerAngles.z;
		}
	}

	private void Update()
	{
		vel = FRILerp.Lerp(vel, (target - currentValue) * spring, damper);
		currentValue += vel * TimeHandler.deltaTime;
		base.transform.localEulerAngles = new Vector3(x ? currentValue : 0f, y ? currentValue : 0f, z ? currentValue : 0f);
	}
}
