public class TracerRound : MonoBehaviour
{
	public GameObject bullet;

	public GameObject bulletSpawnPos;

	private TracerTarget target;

	private MoveTransform move;

	private bool done;

	private void Start()
	{
		move = GetComponent<MoveTransform>();
		bullet = UnityEngine.Object.Instantiate(bullet, bulletSpawnPos.transform.position, bulletSpawnPos.transform.rotation);
		bullet.GetComponent<ProjectileHit>().damage *= base.transform.localScale.x;
		GetComponentInParent<SpawnedAttack>().CopySpawnedAttackTo(bullet);
		target = bullet.GetComponent<TracerTarget>();
		GetComponentInParent<ProjectileHit>().AddHitActionWithData(Hit);
		bullet.GetComponentInParent<ProjectileHit>().AddHitActionWithData(Hit);
	}

	public void Hit(HitInfo hit)
	{
		if ((bool)hit.transform.root.GetComponent<Player>())
		{
			base.transform.SetParent(null);
			base.gameObject.AddComponent<RemoveAfterSeconds>().seconds = 10f;
			base.gameObject.AddComponent<FollowTransform>().target = hit.transform;
		}
	}

	private void Update()
	{
		if (target != null)
		{
			target.SetPos(base.transform.position, Vector3.Cross(Vector3.forward, base.transform.forward), move);
		}
		if (bullet == null && !done)
		{
			done = true;
			GetComponentInChildren<ParticleSystem>().Stop();
		}
	}
}
public class TracerTarget : MonoBehaviour
{
	private MoveTransform move;

	public bool hasPos;

	public float drag;

	public float spring;

	public AnimationCurve curve;

	public float cosScale = 1f;

	public float cosAmount;

	private float random;

	private float c;

	private bool done;

	private Vector3 tPos;

	private Vector3 upDir;

	private MoveTransform mTrans;

	private void Start()
	{
		move = GetComponent<MoveTransform>();
		random = UnityEngine.Random.Range(0f, 1000f);
		SetPos(base.transform.forward * 100f, base.transform.up, null);
	}

	private void Update()
	{
		float num = 1f;
		if ((bool)mTrans)
		{
			num += mTrans.velocity.magnitude * 0.1f;
		}
		if ((bool)mTrans && !done)
		{
			tPos += base.transform.forward + base.transform.forward * 10f;
		}
		c += TimeHandler.deltaTime;
		if (hasPos)
		{
			move.velocity += cosAmount * Mathf.Cos((Time.time + random) * cosScale) * upDir * CappedDeltaTime.time / num;
			move.velocity += (tPos - base.transform.position).normalized * spring * CappedDeltaTime.time * curve.Evaluate(c) * num;
			move.velocity -= move.velocity * CappedDeltaTime.time * drag * curve.Evaluate(c);
		}
	}

	public void SetPos(Vector3 targetPos, Vector3 up, MoveTransform move)
	{
		mTrans = move;
		hasPos = true;
		tPos = targetPos;
		upDir = up;
	}
}
public class TrickShot : MonoBehaviour
{
	[Header("Sound")]
	public SoundEvent soundGrowExplosion;

	public SoundEvent soundGrowWail;

	private bool soundGrowExplosionPlayed;

	private bool soundGrowWailPlayed;

	private SoundParameterIntensity soundIntensity = new SoundParameterIntensity(0f);

	[Header("Settings")]
	public float muiltiplier = 1f;

	public float removeAt = 30f;

	private ProjectileHit projectileHit;

	private MoveTransform move;

	private ScaleTrailFromDamage trail;

	private float lastDistanceTravelled;

	private void Awake()
	{
		trail = base.transform.root.GetComponentInChildren<ScaleTrailFromDamage>();
	}

	private void Start()
	{
		projectileHit = GetComponentInParent<ProjectileHit>();
		move = GetComponentInParent<MoveTransform>();
		if (projectileHit != null)
		{
			if (soundGrowExplosion != null)
			{
				projectileHit.AddHitActionWithData(SoundPlayGrowExplosion);
			}
			if (soundGrowWail != null)
			{
				soundGrowWailPlayed = true;
				SoundManager.Instance.Play(soundGrowWail, projectileHit.ownPlayer.transform);
			}
		}
	}

	public void SoundPlayGrowExplosion(HitInfo hit)
	{
		if (!soundGrowExplosionPlayed)
		{
			soundGrowExplosionPlayed = true;
			if (soundGrowExplosion != null)
			{
				SoundManager.Instance.PlayAtPosition(soundGrowExplosion, projectileHit.ownPlayer.transform, hit.point, soundIntensity);
			}
			if (soundGrowWailPlayed)
			{
				SoundManager.Instance.Stop(soundGrowWail, projectileHit.ownPlayer.transform);
			}
		}
	}

	private void Update()
	{
		if (move.distanceTravelled > removeAt)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		soundIntensity.intensity = move.distanceTravelled / removeAt;
		float num = move.distanceTravelled - lastDistanceTravelled;
		lastDistanceTravelled = move.distanceTravelled;
		float num2 = 1f + num * TimeHandler.deltaTime * base.transform.localScale.x * muiltiplier;
		projectileHit.damage *= num2;
		projectileHit.shake *= num2;
		if ((bool)trail)
		{
			trail.Rescale();
		}
	}
}
public class TwitchAudienceVisualizer : MonoBehaviour
{
	private const int MAXIMUM_MSG_PER_PLAYER_IN_AUDIENCE = 100;

	private const int MAXIMUM_MSG_PER_SECOND = 10;

	private float m_RecieveRate;

	private float m_LastRecievedTime;

	public float countDownSpeed = 2f;

	public float totalAmountOfTime = 30f;

	[SerializeField]
	private GameObject m_TwitchChatObject;

	public ProceduralImage border;

	public TextMeshProUGUI audioenceText;

	private Screenshaker shake;

	private bool m_IsAudition;

	private bool m_IsReadyToSpawnChatObjects;

	private ListMenuPage m_Page;

	public static TwitchAudienceVisualizer instance;

	private Dictionary<string, int> m_MsgsPerTwitchUser = new Dictionary<string, int>();

	private int currentViewerScore;

	private void Awake()
	{
		instance = this;
		m_RecieveRate = 0.1f;
	}

	private void Start()
	{
		m_Page = GetComponentInParent<ListMenuPage>();
		shake = GetComponentInChildren<Screenshaker>();
		TwitchUIHandler.Instance.AddMsgAction(Chat);
		StartAudition();
	}

	public void Chat(string msg, string from)
	{
		if (!m_IsAudition)
		{
			return;
		}
		if (!m_MsgsPerTwitchUser.ContainsKey(from))
		{
			m_MsgsPerTwitchUser.Add(from, 0);
		}
		if (m_MsgsPerTwitchUser[from] >= 100)
		{
			return;
		}
		m_MsgsPerTwitchUser[from]++;
		if (Time.unscaledTime >= m_LastRecievedTime + m_RecieveRate)
		{
			m_LastRecievedTime = Time.unscaledTime;
			if (m_IsReadyToSpawnChatObjects)
			{
				SpawnChatObject(msg, from);
			}
		}
		currentViewerScore += 100;
		shake.OnUIGameFeel(UnityEngine.Random.insideUnitCircle.normalized);
	}

	private void SpawnChatObject(string msg, string from)
	{
		UnityEngine.Object.Instantiate(m_TwitchChatObject).GetComponentInChildren<TextMeshProUGUI>().text = msg;
	}

	private void StartAudition()
	{
		m_IsAudition = true;
		m_MsgsPerTwitchUser = new Dictionary<string, int>();
		StartCoroutine(DoAudition());
	}

	private void Shake(float m = 1f)
	{
		shake.OnUIGameFeel(UnityEngine.Random.insideUnitCircle.normalized * m);
	}

	private IEnumerator DoAudition()
	{
		border.fillAmount = 0f;
		audioenceText.text = "";
		yield return new WaitForSecondsRealtime(1f / countDownSpeed);
		Shake(3f);
		audioenceText.text = "3";
		yield return new WaitForSecondsRealtime(1f / countDownSpeed);
		Shake(3f);
		audioenceText.text = "2";
		yield return new WaitForSecondsRealtime(1f / countDownSpeed);
		Shake(3f);
		audioenceText.text = "1";
		yield return new WaitForSecondsRealtime(1f / countDownSpeed);
		Shake(10f);
		audioenceText.text = "CHAT";
		yield return new WaitForSecondsRealtime(2f / countDownSpeed);
		Shake(10f);
		audioenceText.text = "MAKE";
		yield return new WaitForSecondsRealtime(1f / countDownSpeed);
		Shake(10f);
		audioenceText.text = "SOME";
		yield return new WaitForSecondsRealtime(1f / countDownSpeed);
		Shake(10f);
		audioenceText.text = "NOISE";
		float t = 0f;
		while (t < 1f)
		{
			t += Time.unscaledDeltaTime;
			Shake(3f - t);
			yield return null;
		}
		yield return new WaitForSecondsRealtime(0.5f / countDownSpeed);
		m_IsReadyToSpawnChatObjects = true;
		float c = totalAmountOfTime;
		while (c > 0f)
		{
			border.fillAmount = c / totalAmountOfTime;
			c -= Time.unscaledDeltaTime;
			audioenceText.text = currentViewerScore + "\n<size=50>AUDIENCE RATING</size>";
			yield return null;
		}
		m_IsAudition = false;
		m_IsReadyToSpawnChatObjects = false;
		m_Page.Close();
		NetworkConnectionHandler.instance.TwitchJoin(currentViewerScore);
	}
}
