		}

		public void OnPreSimulate(int frameId, int subFrameId)
		{
			if (photonView.IsMine)
			{
				rotation = (Mathf.Sin(Time.time) + 0.5f) * 120f;
				base.transform.localEulerAngles = new Vector3(0f, rotation, 0f);
			}
		}

		public void FixedUpdate()
		{
		}

		private void Update()
		{
		}

		public bool OnInterpolate(int snapFrameId, int targFrameId, float t)
		{
			if (!base.PhotonView.IsMine)
			{
				base.transform.localEulerAngles = new Vector3(0f, rotation, 0f);
			}
			return true;
		}
	}
}
namespace emotitron.Utilities
{
	public enum MarkerType
	{
		None,
		Custom,
		Default,
		Player,
		NPC
	}
	[Serializable]
	public struct MarkerNameType
	{
		[HideInInspector]
		public MarkerType type;

		[HideInInspector]
		public int hash;

		[HideInInspector]
		public string name;

		public static string[] enumNames = Enum.GetNames(typeof(MarkerType));

		public MarkerNameType(MarkerType vitalType)
		{
			type = vitalType;
			name = Enum.GetName(typeof(MarkerType), vitalType);
			hash = name.GetHashCode();
		}

		public MarkerNameType(string name)
		{
			type = (MarkerType)NameTypeUtils.GetVitalTypeForName(name, enumNames);
			this.name = name;
			hash = name.GetHashCode();
		}

		public override string ToString()
		{
			return string.Concat("NameType: ", type, " ", name, " ", hash);
		}
	}
	public static class NameTypeUtils
	{
		public static int GetVitalTypeForName(string name, string[] enumNames)
		{
			for (int i = 0; i < enumNames.Length; i++)
			{
				if (name == enumNames[i])
				{
					return i;
				}
			}
			return 1;
		}
	}
}
