namespace emotitron.Utilities.Example
{
	public class BasicController : MonoBehaviour
	{
		public enum Timing
		{
			Auto,
			Fixed,
			Update,
			LateUpdate
		}

		private PhotonView pv;

		private Rigidbody rb;

		private Rigidbody2D rb2D;

		[HideInInspector]
		public TransformCrusher TransformCrusherRef;

		private TransformCrusher tc;

		public Timing timing = Timing.Fixed;

		public bool moveRelative = true;

		[Space]
		public KeyCode moveLeft = KeyCode.A;

		public KeyCode moveRight = KeyCode.D;

		public KeyCode moveFwd = KeyCode.W;

		public KeyCode moveBwd = KeyCode.S;

		public KeyCode moveUp = KeyCode.Space;

		public KeyCode moveDn = KeyCode.Z;

		[Space]
		public KeyCode pitchPos = KeyCode.R;

		public KeyCode pitchNeg = KeyCode.C;

		public KeyCode yawPos = KeyCode.E;

		public KeyCode yawNeg = KeyCode.Q;

		public KeyCode rollPos = KeyCode.Alpha4;

		public KeyCode rollNeg = KeyCode.Alpha4;

		[Space]
		public bool clampToCrusher;

		public float moveSpeed = 5f;

		public float turnSpeed = 60f;

		public float moveForce = 12f;

		public float turnForce = 100f;

		public float scaleSpeed = 1f;

		private bool isMine;

		private bool IsMine
		{
			get
			{
				if (!(pv == null))
				{
					return pv.IsMine;
				}
				return true;
			}
		}

		private void Awake()
		{
			rb = GetComponent<Rigidbody>();
			rb2D = GetComponent<Rigidbody2D>();
			pv = GetComponent<PhotonView>();
		}

		private void Start()
		{
			if (GetComponent<IHasTransformCrusher>() != null)
			{
				tc = GetComponent<IHasTransformCrusher>().TC;
			}
			if (!IsMine)
			{
				if ((bool)rb)
				{
					rb.isKinematic = true;
				}
				if ((bool)rb2D)
				{
					rb2D.isKinematic = true;
				}
			}
		}

		private void FixedUpdate()
		{
			if (timing == Timing.Fixed || (timing == Timing.Auto && (bool)rb))
			{
				Apply();
			}
		}

		private void Update()
		{
			if (timing == Timing.Update || (timing == Timing.Auto && !rb))
			{
				Apply();
			}
		}

		private void LateUpdate()
		{
			if (timing == Timing.LateUpdate)
			{
				Apply();
			}
		}

		private void SumKeys(out Vector3 move, out Vector3 turn)
		{
			move = new Vector3(0f, 0f, 0f);
			if (Input.touchCount > 0)
			{
				Vector2 rawPosition = Input.GetTouch(0).rawPosition;
				if (rawPosition.x < (float)Screen.width * 0.333f)
				{
					move.x -= 1f;
				}
				else if (rawPosition.x > (float)Screen.width * 0.666f)
				{
					move.x += 1f;
				}
				if (rawPosition.y < (float)Screen.height * 0.333f)
				{
					move.z -= 1f;
				}
				else if (rawPosition.y > (float)Screen.height * 0.666f)
				{
					move.z += 1f;
				}
			}
			if (Input.GetKey(moveRight))
			{
				move.x += 1f;
			}
			if (Input.GetKey(moveLeft))
			{
				move.x -= 1f;
			}
			if (Input.GetKey(moveUp))
			{
				move.y += 1f;
			}
			if (Input.GetKey(moveDn))
			{
				move.y -= 1f;
			}
			if (Input.GetKey(moveFwd))
			{
				move.z += 1f;
			}
			if (Input.GetKey(moveBwd))
			{
				move.z -= 1f;
			}
			move = Vector3.ClampMagnitude(move, 1f);
			turn = new Vector3(0f, 0f, 0f);
			if (Input.GetKey(pitchPos))
			{
				turn.x += 1f;
			}
			if (Input.GetKey(pitchNeg))
			{
				turn.x -= 1f;
			}
			if (Input.GetKey(yawPos))
			{
				turn.y += 1f;
			}
			if (Input.GetKey(yawNeg))
			{
				turn.y -= 1f;
			}
			if (Input.GetKey(rollPos))
			{
				turn.z += 1f;
			}
			if (Input.GetKey(rollNeg))
			{
				turn.z -= 1f;
			}
		}

		private void Apply()
		{
			if (!IsMine)
			{
				return;
			}
			SumKeys(out var move, out var turn);
			if ((bool)rb && !rb.isKinematic)
			{
				if ((bool)rb && clampToCrusher && tc != null)
				{
					rb.MovePosition(tc.PosCrusher.Clamp(rb.position));
				}
				move *= moveForce * Time.deltaTime;
				if (moveRelative)
				{
					rb.AddRelativeForce(move, ForceMode.VelocityChange);
				}
				else
				{
					rb.AddForce(move, ForceMode.VelocityChange);
				}
			}
			else if ((bool)rb2D && !rb2D.isKinematic)
			{
				if ((bool)rb2D && clampToCrusher && tc != null)
				{
					rb2D.MovePosition(tc.PosCrusher.Clamp(rb2D.position));
				}
				move *= moveForce * Time.deltaTime;
				if (moveRelative)
				{
					rb2D.AddRelativeForce(move, ForceMode2D.Impulse);
				}
				else
				{
					rb2D.AddForce(move, ForceMode2D.Impulse);
				}
			}
			else
			{
				Vector3 vector = (rb ? rb.position : base.transform.position);
				if (moveRelative)
				{
					vector += base.transform.localRotation * move * moveSpeed * Time.deltaTime;
				}
				else
				{
					vector += move * moveSpeed * Time.deltaTime;
				}
				if (clampToCrusher && tc != null && tc.PosCrusher != null)
				{
					vector = tc.PosCrusher.Clamp(vector);
				}
				if ((bool)rb)
				{
					rb.MovePosition(vector);
				}
				else
				{
					base.transform.position = vector;
				}
			}
			if ((bool)rb && !rb.isKinematic)
			{
				turn *= turnForce * Time.deltaTime;
				rb.AddRelativeTorque(turn, ForceMode.VelocityChange);
			}
			else if (clampToCrusher && tc != null && tc.RotCrusher.TRSType != TRSType.Quaternion)
			{
				Vector3 localEulerAngles = tc.RotCrusher.Clamp(base.transform.eulerAngles += turn * turnSpeed * Time.deltaTime);
				base.transform.localEulerAngles = localEulerAngles;
			}
			else
			{
				base.transform.rotation *= Quaternion.Euler(turn * turnSpeed * Time.deltaTime);
			}
		}
	}
}
namespace Photon.Compression
{
	public enum SerializationFlags
	{
		None = 0,
		HasContent = 1,
		Force = 2,
		ForceReliable = 4,
		SendToSelf = 8,
		NewConnection = 0x10,
		IsComplete = 0x20
	}
	[Serializable]
	public abstract class LiteCrusher
	{
		[SerializeField]
		protected int bits;

		public static int GetBitsForMaxValue(uint maxvalue)
		{
			for (int i = 0; i < 32; i++)
			{
				if (maxvalue >> i == 0)
				{
					return i;
				}
			}
			return 32;
		}
	}
	[Serializable]
	public abstract class LiteCrusher<TComp, T> : LiteCrusher where TComp : struct where T : struct
	{
		public abstract TComp Encode(T val);

		public abstract T Decode(uint val);

		public abstract TComp WriteValue(T val, byte[] buffer, ref int bitposition);

		public abstract void WriteCValue(uint val, byte[] buffer, ref int bitposition);

		public abstract T ReadValue(byte[] buffer, ref int bitposition);

		public abstract TComp ReadCValue(byte[] buffer, ref int bitposition);
	}
	public enum LiteOutOfBoundsHandling
	{
		Clamp,
		Loop
	}
	public enum LiteFloatCompressType
	{
		Bits2 = 2,
		Bits3 = 3,
		Bits4 = 4,
		Bits5 = 5,
		Bits6 = 6,
		Bits7 = 7,
		Bits8 = 8,
		Bits9 = 9,
		Bits10 = 10,
		Bits12 = 12,
		Bits14 = 14,
		Half16 = 16,
		Full32 = 32
	}
	[Serializable]
	public class LiteFloatCrusher : LiteCrusher<ulong, float>
	{
		public enum Normalization
		{
			None,
			Positive,
			Negative
		}

		[SerializeField]
		public Normalization normalization;

		[SerializeField]
		protected float min;

		[SerializeField]
		protected float max;

		[SerializeField]
		public LiteFloatCompressType compressType = LiteFloatCompressType.Half16;

		[SerializeField]
		public LiteOutOfBoundsHandling outOfBoundsHandling;

		[SerializeField]
		private bool accurateCenter = true;

		[SerializeField]
		private float encoder;

		[SerializeField]
		private float decoder;

		[SerializeField]
		private ulong maxCVal;

		public LiteFloatCrusher()
		{
			compressType = LiteFloatCompressType.Half16;
			normalization = Normalization.Positive;
			min = 0f;
			max = 1f;
			accurateCenter = true;
			Recalculate(compressType, min, max, accurateCenter, this);
		}

		public LiteFloatCrusher(LiteFloatCompressType compressType, float min, float max, bool accurateCenter, LiteOutOfBoundsHandling outOfBoundsHandling = LiteOutOfBoundsHandling.Clamp)
		{
			this.compressType = compressType;
			normalization = Normalization.None;
			if (min == max)
			{
				max += 1f;
				Debug.LogWarning("Float crusher is being given min and max values that are the same. This likely is not intentional. Check your range values. Value is <i>" + min + "</i>, changing the max to " + max + " to avoid division by zero errors.");
			}
			if (min < max)
			{
				this.min = min;
				this.max = max;
			}
			else
			{
				this.min = max;
				this.max = min;
			}
			this.accurateCenter = accurateCenter;
			this.outOfBoundsHandling = outOfBoundsHandling;
			Recalculate(compressType, min, max, accurateCenter, this);
		}

		public LiteFloatCrusher(LiteFloatCompressType compressType, Normalization normalization = Normalization.None, LiteOutOfBoundsHandling outOfBoundsHandling = LiteOutOfBoundsHandling.Clamp)
		{
			this.compressType = compressType;
			this.normalization = normalization;
			switch (normalization)
			{
			case Normalization.None:
				min = 0f;
				max = 1f;
				accurateCenter = false;
				break;
			case Normalization.Positive:
				min = 0f;
				max = 1f;
				accurateCenter = false;
				break;
			case Normalization.Negative:
				min = -1f;
				max = 1f;
				accurateCenter = true;
				break;
			}
			this.outOfBoundsHandling = outOfBoundsHandling;
			Recalculate(compressType, min, max, accurateCenter, this);
		}

		public static void Recalculate(LiteFloatCompressType compressType, float min, float max, bool accurateCenter, LiteFloatCrusher crusher)
		{
			int num = (crusher.bits = (int)compressType);
			float num2 = max - min;
			ulong num3 = (ulong)((num == 64) ? (-1) : ((1L << num) - 1));
			if (accurateCenter && num3 != 0L)
			{
				num3--;
			}
			crusher.encoder = ((num2 == 0f) ? 0f : ((float)num3 / num2));
			crusher.decoder = ((num3 == 0L) ? 0f : (num2 / (float)num3));
			crusher.maxCVal = num3;
		}

		public static void Recalculate(LiteFloatCompressType compressType, float min, float max, bool accurateCenter, ref int bits, ref float encoder, ref float decoder, ref ulong maxCVal)
		{
			bits = (int)compressType;
			float num = max - min;
			ulong num2 = (ulong)((bits == 64) ? (-1) : ((1L << bits) - 1));
			if (accurateCenter && num2 != 0L)
			{
				num2--;
			}
			encoder = ((num == 0f) ? 0f : ((float)num2 / num));
			decoder = ((num2 == 0L) ? 0f : (num / (float)num2));
			maxCVal = num2;
		}

		public override ulong Encode(float val)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return Photon.Compression.HalfFloat.HalfUtilities.Pack(val);
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return ((ByteConverter)val).uint32;
			}
			float num = (val - min) * encoder + 0.5f;
			if (num < 0f)
			{
				if (outOfBoundsHandling == LiteOutOfBoundsHandling.Clamp)
				{
					return 0uL;
				}
				return maxCVal + (ulong)((long)num % 10);
			}
			if (num > (float)maxCVal)
			{
				if (outOfBoundsHandling == LiteOutOfBoundsHandling.Clamp)
				{
					return maxCVal;
				}
				return (ulong)(num % (float)maxCVal);
			}
			ulong num2 = (ulong)num;
			if (num2 <= maxCVal)
			{
				return num2;
			}
			return maxCVal;
		}

		public override float Decode(uint cval)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return Photon.Compression.HalfFloat.HalfUtilities.Unpack((ushort)cval);
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return ((ByteConverter)cval).float32;
			}
			if (cval == 0)
			{
				return min;
			}
			if (cval == maxCVal)
			{
				return max;
			}
			return (float)cval * decoder + min;
		}

		public override ulong WriteValue(float val, byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				ulong num = Photon.Compression.HalfFloat.HalfUtilities.Pack(val);
				buffer.Write(num, ref bitposition, 16);
				return num;
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				ulong num2 = ((ByteConverter)val).uint32;
				buffer.Write(num2, ref bitposition, 32);
				return num2;
			}
			ulong num3 = Encode(val);
			buffer.Write(num3, ref bitposition, (int)compressType);
			return num3;
		}

		public override void WriteCValue(uint cval, byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				buffer.Write(cval, ref bitposition, 16);
			}
			else if (compressType == LiteFloatCompressType.Full32)
			{
				buffer.Write(cval, ref bitposition, 32);
			}
			else
			{
				buffer.Write(cval, ref bitposition, (int)compressType);
			}
		}

		public override float ReadValue(byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return Photon.Compression.HalfFloat.HalfUtilities.Unpack((ushort)buffer.Read(ref bitposition, 16));
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return ((ByteConverter)(uint)buffer.Read(ref bitposition, 32)).float32;
			}
			uint val = (uint)buffer.Read(ref bitposition, (int)compressType);
			return Decode(val);
		}

		public override ulong ReadCValue(byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return (ushort)buffer.Read(ref bitposition, 16);
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return (uint)buffer.Read(ref bitposition, 32);
			}
			return (uint)buffer.Read(ref bitposition, (int)compressType);
		}
	}
	public enum LiteIntCompressType
	{
		PackSigned,
		PackUnsigned,
		Range
	}
	[Serializable]
	public class LiteIntCrusher : LiteCrusher<uint, int>
	{
		[SerializeField]
		public LiteIntCompressType compressType;

		[SerializeField]
		protected int min;

		[SerializeField]
		protected int max;

		[SerializeField]
		private int smallest;

		[SerializeField]
		private int biggest;

		public LiteIntCrusher()
		{
			compressType = LiteIntCompressType.PackSigned;
			min = -128;
			max = 127;
			if (compressType == LiteIntCompressType.Range)
			{
				Recalculate(min, max, ref smallest, ref biggest, ref bits);
			}
		}

		public LiteIntCrusher(LiteIntCompressType compType = LiteIntCompressType.PackSigned, int min = -128, int max = 127)
		{
			compressType = compType;
			this.min = min;
			this.max = max;
			if (compressType == LiteIntCompressType.Range)
			{
				Recalculate(min, max, ref smallest, ref biggest, ref bits);
			}
		}

		public override uint WriteValue(int val, byte[] buffer, ref int bitposition)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackUnsigned:
				buffer.WritePackedBytes((uint)val, ref bitposition, 32);
				return (uint)val;
			case LiteIntCompressType.PackSigned:
			{
				uint num2 = (uint)((val << 1) ^ (val >> 31));
				buffer.WritePackedBytes(num2, ref bitposition, 32);
				return num2;
			}
			case LiteIntCompressType.Range:
			{
				uint num = Encode(val);
				buffer.Write(num, ref bitposition, bits);
				return num;
			}
			default:
				return 0u;
			}
		}

		public override void WriteCValue(uint cval, byte[] buffer, ref int bitposition)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackUnsigned:
				buffer.WritePackedBytes(cval, ref bitposition, 32);
				break;
			case LiteIntCompressType.PackSigned:
				buffer.WritePackedBytes(cval, ref bitposition, 32);
				break;
			case LiteIntCompressType.Range:
				buffer.Write(cval, ref bitposition, bits);
				break;
			}
		}

		public override int ReadValue(byte[] buffer, ref int bitposition)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackUnsigned:
				return (int)buffer.ReadPackedBytes(ref bitposition, 32);
			case LiteIntCompressType.PackSigned:
				return buffer.ReadSignedPackedBytes(ref bitposition, 32);
			case LiteIntCompressType.Range:
			{
				uint val = (uint)buffer.Read(ref bitposition, bits);
				return Decode(val);
			}
			default:
				return 0;
			}
		}

		public override uint ReadCValue(byte[] buffer, ref int bitposition)
		{
			return compressType switch
			{
				LiteIntCompressType.PackUnsigned => (uint)buffer.ReadPackedBytes(ref bitposition, 32), 
				LiteIntCompressType.PackSigned => (uint)buffer.ReadPackedBytes(ref bitposition, 32), 
				LiteIntCompressType.Range => (uint)buffer.Read(ref bitposition, bits), 
				_ => 0u, 
			};
		}

		public override uint Encode(int value)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackSigned:
				return value.ZigZag();
			case LiteIntCompressType.PackUnsigned:
				return (uint)value;
			default:
				value = ((value > biggest) ? biggest : ((value < smallest) ? smallest : value));
				return (uint)(value - smallest);
			}
		}

		public override int Decode(uint cvalue)
		{
			return compressType switch
