		public static int HighestDifferentBit(uint a, uint b)
		{
			int result = 0;
			for (int i = 0; i < 32; i++)
			{
				uint num = (uint)(1 << i);
				if ((a & num) == (b & num))
				{
					result = i;
				}
			}
			return result;
		}

