	[ExecuteInEditMode]
	public class WorldBounds : MonoBehaviour
	{
		[SerializeField]
		[HideInInspector]
		private Bounds manualBounds = new Bounds(new Vector3(0f, 0f, 0f), new Vector3(600f, 40f, 600f));

		[Tooltip("Selects which WorldBounds group this object should be factored into.")]
		[WorldBoundsSelectAttribute]
		[SerializeField]
		[HideInInspector]
		public int worldBoundsGrp;

		[SerializeField]
		[HideInInspector]
		private bool includeChildren = true;

		[Tooltip("Awake/Destroy will consider element into the world size as long as it exists in the scene (You may need to wake it though). Enable/Disable only factors it in if it is active.")]
		[SerializeField]
		[HideInInspector]
		private BoundsTools.BoundsType factorIn;

		[HideInInspector]
		public Bounds myBounds;

		[HideInInspector]
		public int myBoundsCount;

		public Action OnWorldBoundsChange;

		public Bounds ManualBounds
		{
			get
			{
				return manualBounds;
			}
			set
			{
				manualBounds = value;
				CollectMyBounds();
			}
		}

		public BoundsTools.BoundsType FactorIn
		{
			get
			{
				return factorIn;
			}
			set
			{
				factorIn = value;
				CollectMyBounds();
			}
		}

		private void Awake()
		{
			CollectMyBounds();
		}

		public void CollectMyBounds()
		{
			WorldBoundsSettings single = SettingsScriptableObject<WorldBoundsSettings>.Single;
			if ((bool)single)
			{
				if (SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups.Count == 0)
				{
					SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups.Add(new WorldBoundsGroup());
				}
				if (worldBoundsGrp >= SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups.Count)
				{
					worldBoundsGrp = 0;
				}
				WorldBoundsGroup worldBoundsGroup = single.worldBoundsGroups[worldBoundsGrp];
				if (factorIn == BoundsTools.BoundsType.Manual)
				{
					myBounds = manualBounds;
					myBoundsCount = 1;
				}
				else
				{
					myBounds = base.gameObject.CollectMyBounds(factorIn, out myBoundsCount, includeChildren);
				}
				WorldBoundsSettings.RemoveWorldBoundsFromAll(this);
				if (myBoundsCount > 0 && base.enabled && !worldBoundsGroup.activeWorldBounds.Contains(this))
				{
					worldBoundsGroup.activeWorldBounds.Add(this);
					worldBoundsGroup.RecalculateWorldCombinedBounds();
				}
				if (OnWorldBoundsChange != null)
				{
					OnWorldBoundsChange();
				}
			}
		}

		private void Start()
		{
		}

		private void OnEnable()
		{
			FactorInBounds(b: true);
		}

		private void OnDisable()
		{
			FactorInBounds(b: false);
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.color = Color.magenta;
			Gizmos.DrawWireCube(SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups[worldBoundsGrp]._combinedWorldBounds.center, SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups[worldBoundsGrp]._combinedWorldBounds.size);
		}

		public void FactorInBounds(bool b)
		{
			if (this == null)
			{
				return;
			}
			if (worldBoundsGrp >= SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups.Count)
			{
				worldBoundsGrp = 0;
			}
			WorldBoundsGroup worldBoundsGroup = SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups[worldBoundsGrp];
			if (b)
			{
				if (!worldBoundsGroup.activeWorldBounds.Contains(this))
				{
					worldBoundsGroup.activeWorldBounds.Add(this);
				}
			}
			else
			{
				worldBoundsGroup.activeWorldBounds.Remove(this);
			}
			worldBoundsGroup.RecalculateWorldCombinedBounds();
		}
	}
	[Serializable]
	public class WorldBoundsGroup
	{
		public const string defaultName = "Default";

		public const string newAddName = "Unnamed";

		public string name = "Default";

		[NonSerialized]
		public Action OnWorldBoundChanged;

		public ElementCrusher crusher = GetUncompressedCrusher();

		[NonSerialized]
		public readonly List<WorldBounds> activeWorldBounds = new List<WorldBounds>();

		[NonSerialized]
		public Bounds _combinedWorldBounds;

		public int ActiveBoundsObjCount => activeWorldBounds.Count;

		public static ElementCrusher GetUncompressedCrusher()
		{
			return new ElementCrusher(TRSType.Position, enableTRSTypeSelector: false)
			{
				enableLocalSelector = false,
				hideFieldName = true,
				XCrusher = new FloatCrusher
				{
					axis = Axis.X,
					outOfBoundsHandling = OutOfBoundsHandling.Clamp,
					Resolution = 100uL,
					BitsDeterminedBy = BitsDeterminedBy.Uncompressed
				},
				YCrusher = new FloatCrusher
				{
					axis = Axis.Y,
					outOfBoundsHandling = OutOfBoundsHandling.Clamp,
					Resolution = 100uL,
					BitsDeterminedBy = BitsDeterminedBy.Uncompressed
				},
				ZCrusher = new FloatCrusher
				{
					axis = Axis.Z,
					outOfBoundsHandling = OutOfBoundsHandling.Clamp,
					Resolution = 100uL,
					BitsDeterminedBy = BitsDeterminedBy.Uncompressed
				}
			};
		}

		public void ResetActiveBounds()
		{
			activeWorldBounds.Clear();
		}

		public void RecalculateWorldCombinedBounds()
		{
			FloatCrusher xCrusher = crusher.XCrusher;
			FloatCrusher yCrusher = crusher.YCrusher;
			FloatCrusher zCrusher = crusher.ZCrusher;
			if (activeWorldBounds.Count == 0)
			{
				_combinedWorldBounds = default(Bounds);
			}
			else
			{
				if (xCrusher.BitsDeterminedBy > BitsDeterminedBy.Disabled || xCrusher.BitsDeterminedBy == BitsDeterminedBy.SetBits || xCrusher.BitsDeterminedBy == BitsDeterminedBy.Uncompressed || xCrusher.BitsDeterminedBy == BitsDeterminedBy.HalfFloat)
				{
					xCrusher.Resolution = 100uL;
					xCrusher.BitsDeterminedBy = BitsDeterminedBy.Resolution;
				}
				if (yCrusher.BitsDeterminedBy > BitsDeterminedBy.Disabled || yCrusher.BitsDeterminedBy == BitsDeterminedBy.SetBits || yCrusher.BitsDeterminedBy == BitsDeterminedBy.Uncompressed || yCrusher.BitsDeterminedBy == BitsDeterminedBy.HalfFloat)
				{
					yCrusher.Resolution = 100uL;
					yCrusher.BitsDeterminedBy = BitsDeterminedBy.Resolution;
				}
				if (zCrusher.BitsDeterminedBy > BitsDeterminedBy.Disabled || zCrusher.BitsDeterminedBy == BitsDeterminedBy.SetBits || zCrusher.BitsDeterminedBy == BitsDeterminedBy.Uncompressed || zCrusher.BitsDeterminedBy == BitsDeterminedBy.HalfFloat)
				{
					zCrusher.Resolution = 100uL;
					zCrusher.BitsDeterminedBy = BitsDeterminedBy.Resolution;
				}
				_combinedWorldBounds = activeWorldBounds[0].myBounds;
				for (int i = 1; i < activeWorldBounds.Count; i++)
				{
					_combinedWorldBounds.Encapsulate(activeWorldBounds[i].myBounds);
				}
				crusher.Bounds = _combinedWorldBounds;
			}
			if (OnWorldBoundChanged != null)
			{
				OnWorldBoundChanged();
			}
		}
	}
	public class WorldBoundsSelectAttributeAttribute : PropertyAttribute
	{
	}
	[CreateAssetMenu]
	public class WorldBoundsSettings : SettingsScriptableObject<WorldBoundsSettings>
	{
		[HideInInspector]
		public List<WorldBoundsGroup> worldBoundsGroups = new List<WorldBoundsGroup>();

		public static ElementCrusher defaultWorldBoundsCrusher;

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
		private static void Bootstrap()
		{
			WorldBoundsSettings worldBoundsSettings = SettingsScriptableObject<WorldBoundsSettings>.Single;
			List<WorldBoundsGroup> list = worldBoundsSettings.worldBoundsGroups;
			if (worldBoundsSettings != null && list.Count > 0)
			{
				defaultWorldBoundsCrusher = worldBoundsSettings.worldBoundsGroups[0].crusher;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (worldBoundsGroups.Count == 0)
			{
				worldBoundsGroups.Add(new WorldBoundsGroup());
			}
		}

		public override void Initialize()
		{
			base.Initialize();
			if (worldBoundsGroups.Count == 0)
			{
				worldBoundsGroups.Add(new WorldBoundsGroup());
			}
			defaultWorldBoundsCrusher = worldBoundsGroups[0].crusher;
			foreach (WorldBoundsGroup worldBoundsGroup in worldBoundsGroups)
			{
				worldBoundsGroup.RecalculateWorldCombinedBounds();
			}
		}

		public static void RemoveWorldBoundsFromAll(WorldBounds wb)
		{
			List<WorldBoundsGroup> list = SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups;
			for (int i = 0; i < list.Count; i++)
			{
				List<WorldBounds> activeWorldBounds = list[i].activeWorldBounds;
				if (activeWorldBounds.Contains(wb))
				{
					activeWorldBounds.Remove(wb);
					list[i].RecalculateWorldCombinedBounds();
				}
			}
		}

		public static int TallyBits(ref int index, BitCullingLevel bcl = BitCullingLevel.NoCulling)
		{
			List<WorldBoundsGroup> list = SettingsScriptableObject<WorldBoundsSettings>.Single.worldBoundsGroups;
			if (index >= list.Count)
			{
				index = 0;
			}
			ElementCrusher crusher = SettingsScriptableObject<WorldBoundsSettings>.single.worldBoundsGroups[index].crusher;
			return crusher.XCrusher.GetBits(bcl) + crusher.YCrusher.GetBits(bcl) + crusher.ZCrusher.GetBits(bcl);
		}
	}
