	public abstract class SettingsScriptableObjectBase : ScriptableObject
	{
		public abstract void Initialize();
	}
	public abstract class SettingsScriptableObject<T> : SettingsScriptableObjectBase where T : SettingsScriptableObjectBase
	{
		public static string AssetName = typeof(T).Name;

		public static Action OnSingletonReady;

		public static T single;

		public static T Single
		{
			get
			{
				if (!single)
				{
					single = Resources.Load<T>(AssetName);
					if ((bool)single)
					{
						single.Initialize();
					}
				}
				return single;
			}
		}

		protected virtual void Awake()
		{
			T val = single;
			Initialize();
			if (val == null && single != null && OnSingletonReady != null)
			{
				OnSingletonReady();
			}
		}

		protected virtual void OnEnable()
		{
			T val = single;
			Initialize();
			if (val == null && single != null && OnSingletonReady != null)
			{
				OnSingletonReady();
			}
		}

		public override void Initialize()
		{
			single = this as T;
		}
	}
	public static class BoundsTools
	{
		public enum BoundsType
		{
			Both,
			MeshRenderer,
			Collider,
			Manual
		}

		private static readonly List<MeshFilter> meshFilters = new List<MeshFilter>();

		private static readonly List<Renderer> meshRenderers = new List<Renderer>();

		private static readonly List<Collider> colliders = new List<Collider>();

		private static readonly List<Collider> validColliders = new List<Collider>();

		private static readonly List<SpriteRenderer> spriteRenderers = new List<SpriteRenderer>();

		private static readonly List<Collider2D> colliders2D = new List<Collider2D>();

		private static readonly List<Collider2D> validColliders2D = new List<Collider2D>();

		public static Bounds CollectMyBounds(this GameObject go, BoundsType factorIn, out int numOfBoundsFound, bool includeChildren = true, bool includeInactive = false)
		{
			if (!go.activeInHierarchy && includeInactive)
			{
				numOfBoundsFound = 0;
				return default(Bounds);
			}
			bool num = factorIn == BoundsType.Both;
			bool flag = num || factorIn == BoundsType.MeshRenderer;
			bool num2 = num || factorIn == BoundsType.Collider;
			meshFilters.Clear();
			meshRenderers.Clear();
			colliders.Clear();
			spriteRenderers.Clear();
			validColliders.Clear();
			validColliders2D.Clear();
			int num3 = 0;
			if (flag && go.activeInHierarchy)
			{
				if (includeChildren)
				{
					go.GetComponentsInChildren(includeInactive, meshRenderers);
					go.GetComponentsInChildren(includeInactive, meshFilters);
					go.GetComponentsInChildren(includeInactive, spriteRenderers);
				}
				else
				{
					go.GetComponents(meshRenderers);
					go.GetComponents(meshFilters);
					go.GetComponents(spriteRenderers);
				}
			}
			if (num2 && go.activeInHierarchy)
			{
				if (includeChildren)
				{
					go.GetComponentsInChildren(includeInactive, colliders);
					go.GetComponentsInChildren(includeInactive, colliders2D);
				}
				else
				{
					go.GetComponents(colliders);
					go.GetComponents(colliders2D);
				}
			}
			for (int i = 0; i < meshFilters.Count; i++)
			{
				Renderer component = meshFilters[i].GetComponent<Renderer>();
				if ((bool)component && (component.enabled || includeInactive) && !meshRenderers.Contains(component))
				{
					meshRenderers.Add(component);
				}
			}
			for (int j = 0; j < colliders.Count; j++)
			{
				if ((colliders[j].enabled || includeInactive) && (bool)colliders[j])
				{
					validColliders.Add(colliders[j]);
				}
			}
			for (int k = 0; k < colliders2D.Count; k++)
			{
				if ((((bool)colliders2D[k] && colliders2D[k].enabled) || includeInactive) && (bool)colliders2D[k])
				{
					validColliders2D.Add(colliders2D[k]);
				}
			}
			numOfBoundsFound = meshRenderers.Count + spriteRenderers.Count + validColliders.Count + validColliders2D.Count;
			if (numOfBoundsFound == 0)
			{
				return default(Bounds);
			}
			Bounds bounds;
			if (meshRenderers.Count > 0)
			{
				bounds = meshRenderers[0].bounds;
			}
			else if (validColliders.Count > 0)
			{
				bounds = validColliders[0].bounds;
			}
			else if (validColliders2D.Count > 0 && (bool)validColliders2D[0])
			{
				bounds = validColliders2D[0].bounds;
			}
			else
			{
				if (spriteRenderers.Count <= 0)
				{
					return default(Bounds);
				}
				bounds = spriteRenderers[0].bounds;
			}
			for (int l = 0; l < spriteRenderers.Count; l++)
			{
				num3++;
				bounds.Encapsulate(spriteRenderers[l].bounds);
			}
			for (int m = 0; m < meshRenderers.Count; m++)
			{
				num3++;
				bounds.Encapsulate(meshRenderers[m].bounds);
			}
			for (int n = 0; n < validColliders.Count; n++)
			{
				num3++;
				bounds.Encapsulate(validColliders[n].bounds);
			}
			for (int num4 = 0; num4 < validColliders2D.Count; num4++)
			{
				num3++;
				if ((bool)validColliders2D[num4])
				{
					bounds.Encapsulate(validColliders2D[num4].bounds);
				}
			}
			return bounds;
		}

		public static Bounds CollectMyBounds(GameObject go, BoundsType factorIn, bool includeChildren = true)
		{
			int numOfBoundsFound;
			return go.CollectMyBounds(factorIn, out numOfBoundsFound, includeChildren);
		}
	}
	[AttributeUsage(AttributeTargets.Field)]
	public class EnumMaskAttribute : PropertyAttribute
	{
		public bool definesZero;

		public Type castTo;

		public EnumMaskAttribute(bool definesZero = false, Type castTo = null)
		{
			this.castTo = castTo;
			this.definesZero = definesZero;
		}
	}
	public enum SmartVarTypeCode
	{
		None,
		Int,
		Uint,
		Bool,
		Float,
		Byte,
		Short,
		UShort,
		Char
	}
	[Serializable]
	[StructLayout(LayoutKind.Explicit)]
	public struct SmartVar
	{
		[FieldOffset(0)]
		public SmartVarTypeCode TypeCode;

		[FieldOffset(4)]
		public int Int;

		[FieldOffset(4)]
		public uint UInt;

		[FieldOffset(4)]
		public bool Bool;

		[FieldOffset(4)]
		public float Float;

		[FieldOffset(4)]
		public byte Byte8;

		[FieldOffset(4)]
		public short Short;

		[FieldOffset(4)]
		public ushort UShort;

		[FieldOffset(4)]
		public char Char;

		public static readonly SmartVar None = new SmartVar
		{
			TypeCode = SmartVarTypeCode.None
		};

		public static implicit operator SmartVar(int v)
		{
			return new SmartVar
			{
				Int = v,
				TypeCode = SmartVarTypeCode.Int
			};
		}

		public static implicit operator SmartVar(uint v)
		{
			return new SmartVar
			{
				UInt = v,
				TypeCode = SmartVarTypeCode.Uint
			};
		}

		public static implicit operator SmartVar(float v)
		{
			return new SmartVar
			{
				Float = v,
				TypeCode = SmartVarTypeCode.Float
			};
		}

		public static implicit operator SmartVar(bool v)
		{
			return new SmartVar
			{
				Bool = v,
				TypeCode = SmartVarTypeCode.Bool
			};
		}

		public static implicit operator SmartVar(byte v)
		{
			return new SmartVar
			{
				Byte8 = v,
				TypeCode = SmartVarTypeCode.Byte
			};
		}

		public static implicit operator SmartVar(short v)
		{
			return new SmartVar
			{
				Short = v,
				TypeCode = SmartVarTypeCode.Short
			};
		}

		public static implicit operator SmartVar(ushort v)
		{
			return new SmartVar
			{
				UShort = v,
				TypeCode = SmartVarTypeCode.UShort
			};
		}

		public static implicit operator SmartVar(char v)
		{
			return new SmartVar
			{
				Char = v,
				TypeCode = SmartVarTypeCode.Char
			};
		}

		public static implicit operator int(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Int)
			{
				return v.Int;
			}
			UnityEngine.Debug.Log(v.TypeCode);
			throw new InvalidCastException();
		}

		public static implicit operator uint(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Uint)
			{
				return v.UInt;
			}
			throw new InvalidCastException();
		}

		public static implicit operator float(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Float)
			{
				return v.Float;
			}
			UnityEngine.Debug.LogError(string.Concat("cant cast ", v.TypeCode, " to single float"));
			throw new InvalidCastException();
		}

		public static implicit operator bool(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Bool)
			{
				return v.Bool;
			}
			throw new InvalidCastException();
		}

		public static implicit operator byte(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Byte)
			{
				return v.Byte8;
			}
			throw new InvalidCastException();
		}

		public static implicit operator short(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Short)
			{
				return v.Short;
			}
			throw new InvalidCastException();
		}

		public static implicit operator ushort(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.UShort)
			{
				return v.UShort;
			}
			throw new InvalidCastException();
		}

		public static implicit operator char(SmartVar v)
		{
			if (v.TypeCode == SmartVarTypeCode.Char)
			{
				return v.Char;
			}
			throw new InvalidCastException();
		}

		public SmartVar Copy()
		{
			return new SmartVar
			{
				TypeCode = TypeCode,
				Int = Int
			};
		}

		public string ToStringVerbose()
		{
			string text = TypeCode.ToString() + " ";
			if (TypeCode == SmartVarTypeCode.None)
			{
				return text;
			}
			if (TypeCode == SmartVarTypeCode.Bool)
			{
				return text + Bool;
			}
			if (TypeCode == SmartVarTypeCode.Int)
			{
				return text + Int;
			}
			if (TypeCode == SmartVarTypeCode.Uint)
			{
				return text + UInt;
			}
			if (TypeCode == SmartVarTypeCode.Float)
			{
				return text + Float;
			}
			if (TypeCode == SmartVarTypeCode.Short)
			{
				return text + Short;
			}
			if (TypeCode == SmartVarTypeCode.UShort)
			{
				return text + UShort;
			}
			if (TypeCode == SmartVarTypeCode.Byte)
			{
				return text + Byte8;
			}
			if (TypeCode == SmartVarTypeCode.Char)
			{
				return text + Char;
			}
			return text;
		}

		public override string ToString()
		{
			if (TypeCode == SmartVarTypeCode.None)
			{
				return "";
			}
			if (TypeCode == SmartVarTypeCode.Bool)
			{
				return Bool.ToString();
			}
			if (TypeCode == SmartVarTypeCode.Int)
			{
				return Int.ToString();
			}
			if (TypeCode == SmartVarTypeCode.Uint)
			{
				return UInt.ToString();
			}
			if (TypeCode == SmartVarTypeCode.Float)
			{
				return Float.ToString();
			}
			if (TypeCode == SmartVarTypeCode.Short)
			{
				return Short.ToString();
			}
			if (TypeCode == SmartVarTypeCode.UShort)
			{
				return UShort.ToString();
			}
			if (TypeCode == SmartVarTypeCode.Byte)
			{
				return Byte8.ToString();
			}
			if (TypeCode == SmartVarTypeCode.Char)
			{
				return Char.ToString();
			}
			return "";
		}
	}
