namespace Photon.Pun.Simple
{
	public class AutoOwnerComponentEnable : NetComponent, IOnAuthorityChanged
	{
		public enum EnableIf
		{
			Ignore,
			Owner,
			Other
		}

		[Serializable]
		public class ComponentToggle
		{
			public Behaviour component;

			public EnableIf enableIfOwned = EnableIf.Owner;
		}

		public bool includeChildren = true;

		public bool includeUnity = true;

		public bool includePhoton;

		public bool includeSimple;

		[HideInInspector]
		[SerializeField]
		private List<ComponentToggle> componentToggles = new List<ComponentToggle>();

		[HideInInspector]
		[SerializeField]
		private List<Behaviour> componentLookup = new List<Behaviour>();

		public override void OnStart()
		{
			base.OnStart();
			SwitchAuth(base.IsMine);
		}

		public override void OnJoinedRoom()
		{
			base.OnJoinedRoom();
			SwitchAuth(base.IsMine);
		}

		public override void OnAuthorityChanged(bool isMine, bool controllerChanged)
		{
			base.OnAuthorityChanged(isMine, controllerChanged);
			SwitchAuth(isMine);
		}

		private void SwitchAuth(bool isMine)
		{
			for (int i = 0; i < componentToggles.Count; i++)
			{
				ComponentToggle componentToggle = componentToggles[i];
				if (componentToggle != null && componentToggle.enableIfOwned != EnableIf.Ignore && componentToggle.component != null)
				{
					componentToggle.component.enabled = ((componentToggle.enableIfOwned == EnableIf.Owner) ? isMine : (!isMine));
				}
			}
		}
	}
	public class AutoOwnerGameObjEnable : MonoBehaviour, IOnAuthorityChanged
	{
		public enum EnableIf
		{
			Owner,
			Other
		}

		public EnableIf enableIf;

		public void Start()
		{
			PhotonView componentInParent = GetComponentInParent<PhotonView>();
			if ((bool)componentInParent)
			{
				SwitchAuth(componentInParent.IsMine);
			}
		}

		public void OnAuthorityChanged(bool isMine, bool controllerChanged)
		{
			Debug.Log("AuthChanged");
			SwitchAuth(isMine);
		}

		private void SwitchAuth(bool isMine)
		{
			base.gameObject.SetActive((enableIf == EnableIf.Owner) ? isMine : (!isMine));
		}
	}
	public class ContactManager : MonoBehaviour
	{
		public List<IContactSystem> contactSystems = new List<IContactSystem>(0);

		public List<IContactTrigger> contactTriggers = new List<IContactTrigger>(0);

		public void Awake()
		{
			base.transform.GetNestedComponentsInChildren<IContactSystem, NetObject>(contactSystems);
			base.transform.GetNestedComponentsInChildren<IContactTrigger, NetObject>(contactTriggers);
			int count = contactSystems.Count;
			if (count > 255)
			{
				throw new IndexOutOfRangeException("NetObjects may not have more than 255 IContactSystem components on them.");
			}
			for (byte b = 0; b < count; b++)
			{
				contactSystems[b].SystemIndex = b;
			}
		}

		public IContactSystem GetContacting(int index)
		{
			return contactSystems[index];
		}
	}
	public class ContactProjectile : MonoBehaviour, IProjectile, IOnPreSimulate, IOnPreUpdate
	{
		protected IProjectileCannon owner;

		[NonSerialized]
		public Vector3 velocity;

		[NonSerialized]
		public int frameId;

		[NonSerialized]
		public int subFrameId;

		[SerializeField]
		[EnumMask(false, null)]
		protected RespondTo terminateOn = (RespondTo)14;

		[SerializeField]
		[EnumMask(false, null)]
		protected RespondTo damageOn = (RespondTo)14;

		protected Rigidbody rb;

		protected Rigidbody2D rb2d;

		protected bool _hasRigidBody;

		protected bool needsSnapshot;

		protected IContactTrigger localContactTrigger;

		protected bool useRbForces;

		protected bool useRb2dForces;

		protected bool useRBGravity;

		public List<IOnNetworkHit> onHit = new List<IOnNetworkHit>();

		public List<IOnTerminate> onTerminate = new List<IOnTerminate>();

		private Vector3 snapPos;

		private Vector3 targPos;

		private Quaternion snapRot;

		private Quaternion targRot;

		protected static List<NetObject> reusableNetObjects = new List<NetObject>();

		public IProjectileCannon Owner
		{
			get
			{
				return owner;
			}
			set
			{
				owner = value;
			}
		}

		public bool HasRigidbody => _hasRigidBody;

		public VitalNameType VitalNameType => new VitalNameType(VitalType.None);

		private void Reset()
		{
			localContactTrigger = GetComponent<IContactTrigger>();
			if (localContactTrigger == null)
			{
				localContactTrigger = base.gameObject.AddComponent<ContactTrigger>();
			}
		}

		private void Awake()
		{
			rb = GetComponentInParent<Rigidbody>();
			rb2d = GetComponentInParent<Rigidbody2D>();
			_hasRigidBody = (bool)rb || (bool)rb2d;
			useRbForces = (bool)rb && !rb.isKinematic;
			useRb2dForces = (bool)rb2d && !rb2d.isKinematic;
			useRBGravity = ((bool)rb && rb.useGravity) || ((bool)rb2d && rb.useGravity);
			needsSnapshot = !_hasRigidBody || ((bool)rb && rb.isKinematic) || ((bool)rb2d && rb2d.isKinematic);
			localContactTrigger = GetComponent<IContactTrigger>();
			if (needsSnapshot)
			{
				NetMasterCallbacks.RegisterCallbackInterfaces(this);
			}
			if (_hasRigidBody)
			{
				NetMasterCallbacks.onPreUpdates.Remove(this);
			}
			GetComponents(onHit);
			GetComponents(onTerminate);
		}

		private void OnDestroy()
		{
			NetMasterCallbacks.RegisterCallbackInterfaces(this, register: false, delay: true);
		}

		public virtual void LagCompensate(float timeshift)
		{
			snapPos = base.transform.position + velocity * timeshift;
			if ((bool)rb && rb.useGravity)
			{
				velocity += Physics.gravity * timeshift;
			}
			else if ((bool)rb2d)
			{
				velocity += Physics.gravity * timeshift;
			}
		}

		public void Initialize(IProjectileCannon owner, int frameId, int subFrameId, Vector3 localVelocity, RespondTo terminateOn, RespondTo damageOn, float timeshift = 0f)
		{
			this.owner = owner;
			velocity = base.transform.TransformDirection(localVelocity);
			this.terminateOn = terminateOn;
			this.damageOn = damageOn;
			this.frameId = frameId;
			this.subFrameId = subFrameId;
			if (timeshift != 0f)
			{
				LagCompensate(timeshift);
			}
			else
			{
				snapPos = base.transform.position;
			}
			if (useRbForces)
			{
				rb.MovePosition(snapPos);
				rb.velocity = velocity;
			}
			else if ((bool)rb2d)
			{
				rb2d.MovePosition(snapPos);
				rb2d.velocity = velocity;
			}
			else
			{
				base.transform.position = snapPos;
				targPos = snapPos + velocity * Time.fixedDeltaTime;
				base.transform.position = snapPos;
			}
			localContactTrigger.Proxy = owner.ContactTrigger;
		}

		public void OnPreSimulate(int frameId, int subFrameId)
		{
			if (!useRbForces && !useRb2dForces)
			{
				SimulateTime(Time.fixedDeltaTime);
			}
		}

		public virtual void SimulateTime(float t)
		{
			Vector3 vector = targPos;
			targPos = vector + velocity * t;
			snapPos = vector;
			if (useRb2dForces)
			{
				velocity += Physics.gravity * rb2d.gravityScale * t;
			}
			else
			{
				velocity += Physics.gravity * t;
			}
			Interpolate(0f);
		}

		public virtual void OnPreUpdate()
		{
			if (!useRbForces && !useRb2dForces)
			{
				Interpolate(NetMaster.NormTimeSinceFixed);
			}
		}

		protected void Interpolate(float t)
		{
			base.transform.position = Vector3.Lerp(snapPos, targPos, t);
		}

		protected virtual void Terminate()
		{
			Debug.Log("Terminate");
			int i = 0;
			for (int count = onTerminate.Count; i < count; i++)
			{
				onTerminate[i].OnTerminate();
			}
			base.gameObject.SetActive(value: false);
		}
	}
	public abstract class ContactReactorBase : NetComponent, IContactReactor
	{
		[HideInInspector]
		public ContactType triggerOn = (ContactType)15;

		protected SyncState syncState;

		protected int syncStateMountMask;

		public ContactType TriggerOn => triggerOn;

		public abstract bool IsPickup { get; }

		public override void OnAwakeInitialize(bool isNetObject)
		{
			if (isNetObject)
			{
				syncState = base.transform.GetNestedComponentInParent<SyncState, NetObject>();
				syncStateMountMask = (syncState ? syncState.mountableTo.mask : 0);
			}
			base.OnAwakeInitialize(isNetObject);
		}

		public virtual Consumption OnContactEvent(ContactEvent contactEvent)
		{
			ContactType contactType = contactEvent.contactType;
			if (triggerOn != ContactType.Undefined && (contactType & triggerOn) == 0)
			{
				return Consumption.None;
			}
			if (IsPickup)
			{
				int validMountsMask = contactEvent.contactSystem.ValidMountsMask;
				int num = syncState.mountableTo;
				if (validMountsMask != 0 && (validMountsMask & num) == 0)
				{
					return Consumption.None;
				}
			}
			return ProcessContactEvent(contactEvent);
		}

		protected abstract Consumption ProcessContactEvent(ContactEvent contactEvent);
	}
