	public static class ProjectileHelpers
	{
		public static GameObject prefab;

		public static GameObject GetPlaceholderProj()
		{
			if (prefab != null)
			{
				return prefab;
			}
			GameObject gameObject = new GameObject("Projectile Placeholder Prefab");
			gameObject.gameObject.SetActive(value: false);
			Rigidbody rigidbody = gameObject.AddComponent<Rigidbody>();
			rigidbody.useGravity = false;
			rigidbody.interpolation = RigidbodyInterpolation.Interpolate;
			rigidbody.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
			gameObject.AddComponent<ContactProjectile>();
			gameObject.AddComponent<ContactTrigger>();
			GameObject gameObject2 = GameObject.CreatePrimitive(PrimitiveType.Sphere);
			gameObject2.transform.parent = gameObject.transform;
			gameObject2.GetComponent<Collider>().isTrigger = true;
			gameObject2.GetComponent<Renderer>().material.color = Color.yellow;
			gameObject2.transform.localScale = new Vector3(0.1f, 0.1f, 0.1f);
			prefab = gameObject;
			return gameObject;
		}
	}
	public class SyncCannon : SyncShootBase, IProjectileCannon
	{
		[SerializeField]
		public GameObject projPrefab;

		[SerializeField]
		public Vector3 velocity = new Vector3(0f, 0f, 10f);

		[SerializeField]
		[EnumMask(false, null)]
		public RespondTo terminateOn = (RespondTo)12;

		[SerializeField]
		[EnumMask(false, null)]
		public RespondTo damageOn = (RespondTo)12;

		[Tooltip("Projectiles are advanced (lagCompensate * RTT) ms into the future on non-owner clients. This will better time align projectiles to the local players time frame (For example dodging a projectile locally is more likely to be how the shooter saw events as well). 0 = Fully in shooters time frame and 1 = Fully in the local players time frame.")]
		[Range(0f, 1f)]
		[SerializeField]
		public float lagCompensate = 1f;

		protected static List<NetObject> reusableNetObjects = new List<NetObject>();

		public override int ApplyOrder => 19;

		protected override void Reset()
		{
			base.Reset();
		}

		public override void OnAwake()
		{
			base.OnAwake();
			if (projPrefab == null)
			{
				projPrefab = ProjectileHelpers.GetPlaceholderProj();
				Pool.AddPrefabToPool(projPrefab, 8, 8, null, tidyUp: true);
			}
			else
			{
				Pool.AddPrefabToPool(projPrefab);
			}
		}

		protected override bool Trigger(Frame frame, int subFrameId, float timeshift = 0f)
		{
			Pool pool = Pool.Spawn(projPrefab, origin);
			pool.GetComponent<IContactTrigger>().Proxy = contactTrigger;
			IProjectile component = pool.GetComponent<IProjectile>();
			component.Initialize(this, frame.frameId, subFrameId, velocity, terminateOn, damageOn, lagCompensate * timeshift);
			component.Owner = this;
			return true;
		}
	}
	public class SyncContactScan : SyncShootBase, IOnSnapshot, IOnAuthorityChanged
	{
		public bool poke = true;

		public bool grab = true;

		public HitscanDefinition hitscanDefinition;

		[Tooltip("Render widgets that represent the shape of the hitscan when triggered.")]
		public bool visualizeHitscan = true;

		public override int ApplyOrder => 17;

		protected override bool Trigger(Frame frame, int subFrameId, float timeshift = 0f)
		{
			if ((bool)GetComponent<SyncContact>() && !photonView.IsMine)
			{
				hitscanDefinition.VisualizeHitscan(origin);
				return true;
			}
			int nearestIndex = -1;
			RaycastHit[] rayhits;
			Collider[] hits;
			int num = hitscanDefinition.GenericHitscanNonAlloc(origin, out rayhits, out hits, ref nearestIndex, visualizeHitscan);
			if (num <= 0)
			{
				return true;
			}
			for (int i = 0; i < num; i++)
			{
				IContactTrigger nestedComponentInParents = hits[i].transform.GetNestedComponentInParents<IContactTrigger, NetObject>();
				if (nestedComponentInParents != null && !(nestedComponentInParents.NetObj == contactTrigger.NetObj))
				{
					if (poke)
					{
						contactTrigger.OnContact(nestedComponentInParents, ContactType.Hitscan);
					}
					if (grab)
					{
						nestedComponentInParents.OnContact(contactTrigger, ContactType.Hitscan);
					}
				}
			}
			return true;
		}
	}
	public abstract class SyncShootBase : SyncObject<SyncShootBase.Frame>, IOnNetSerialize, IOnPostSimulate, IOnPreUpdate, IOnIncrementFrame, IOnSnapshot, IOnInterpolate
	{
		public class Frame : FrameBase
		{
			public uint triggerMask;

			public Frame()
			{
			}

			public Frame(int frameId)
				: base(frameId)
			{
			}

			public override void CopyFrom(FrameBase sourceFrame)
			{
				triggerMask = 0u;
			}

			public override void Clear()
			{
				base.Clear();
				triggerMask = 0u;
			}
		}

		[Tooltip("Specify the transform hitscans/projectiles will originate from. If null this gameObject will be used as the origin.")]
		[SerializeField]
		protected Transform origin;

		[SerializeField]
		public KeyCode triggerKey;

		protected IContactTrigger contactTrigger;

		protected bool hasSyncContact;

		protected bool triggerQueued;

		public IContactTrigger ContactTrigger => contactTrigger;

		public override int ApplyOrder => 17;

		public override void OnAwakeInitialize(bool isNetObject)
		{
			base.OnAwakeInitialize(isNetObject);
			contactTrigger = base.transform.GetNestedComponentInParents<IContactTrigger, NetObject>();
			hasSyncContact = contactTrigger.SyncContact != null;
			if (origin == null)
			{
				origin = base.transform;
			}
		}

		public virtual void OnPreUpdate()
		{
			if (base.IsMine && Input.GetKeyDown(triggerKey))
			{
				QueueTrigger();
			}
		}

		public virtual void QueueTrigger()
		{
			if (base.enabled && base.gameObject.activeInHierarchy)
			{
				triggerQueued = true;
			}
		}

		public virtual SerializationFlags OnNetSerialize(int frameId, byte[] buffer, ref int bitposition, SerializationFlags writeFlags)
		{
			Frame frame = frames[frameId];
			int sendEveryXTick = TickEngineSettings.sendEveryXTick;
			if (frame.triggerMask != 0)
			{
				buffer.WriteBool(b: true, ref bitposition);
				buffer.Write(frame.triggerMask, ref bitposition, sendEveryXTick);
				return SerializationFlags.HasContent;
			}
			buffer.WriteBool(b: false, ref bitposition);
			return SerializationFlags.None;
		}

		public virtual SerializationFlags OnNetDeserialize(int originFrameId, byte[] buffer, ref int bitposition, FrameArrival arrival)
		{
			Frame frame = frames[originFrameId];
			int sendEveryXTick = TickEngineSettings.sendEveryXTick;
			if (buffer.ReadBool(ref bitposition))
			{
				frame.triggerMask = buffer.ReadUInt32(ref bitposition, sendEveryXTick);
				frame.content = FrameContents.Complete;
				return SerializationFlags.HasContent;
			}
			frame.triggerMask = 0u;
			frame.content = FrameContents.Empty;
			return SerializationFlags.None;
		}

		public virtual void OnPostSimulate(int frameId, int subFrameId, bool isNetTick)
		{
			if (!base.IsMine)
			{
				return;
			}
			Frame frame = frames[frameId];
			if (subFrameId == 0)
			{
				frame.Clear();
			}
			if (triggerQueued)
			{
				frame.triggerMask |= (uint)(1 << subFrameId);
				if (Trigger(frame, subFrameId))
				{
					TriggerCosmetic(frame, subFrameId);
				}
				triggerQueued = false;
				frame.content = FrameContents.Complete;
			}
		}

		public virtual void OnIncrementFrame(int newFrameId, int newSubFrameId, int previousFrameId, int prevSubFrameId)
		{
			if (!base.IsMine && targFrame != null && targFrame.content == FrameContents.Complete)
			{
				int offset = ((newSubFrameId == 0) ? (TickEngineSettings.sendEveryXTick - 1) : (newSubFrameId - 1));
				ApplySubframe(newFrameId, newSubFrameId, offset);
			}
		}

		protected virtual void ApplySubframe(int newFrameId, int newSubFrameId, int offset)
		{
			if ((targFrame.triggerMask & (1 << offset)) != 0L && Trigger(targFrame, newSubFrameId, NetMaster.RTT))
			{
				TriggerCosmetic(targFrame, newSubFrameId, NetMaster.RTT);
			}
		}

		protected abstract bool Trigger(Frame frame, int subFrameId, float timeshift = 0f);

		protected virtual void TriggerCosmetic(Frame frame, int subFrameId, float timeshift = 0f)
		{
		}
	}
