		{
			if (isNetTick)
			{
				vitals.Simulate();
			}
		}

		public virtual void OnCaptureCurrentState(int frameId)
		{
			VitalData[] datas = frames[frameId].vitalsData.datas;
			for (int i = 0; i < vitalsCount; i++)
			{
				datas[i] = vitalArray[i].VitalData;
			}
		}

		public SerializationFlags OnNetSerialize(int frameId, byte[] buffer, ref int bitposition, SerializationFlags writeFlags)
		{
			if (!base.enabled)
			{
				buffer.WriteBool(b: false, ref bitposition);
				return SerializationFlags.None;
			}
			Frame frame = frames[frameId];
			buffer.WriteBool(b: true, ref bitposition);
			bool keyframe = IsKeyframe(frameId);
			return vitals.Serialize(frame.vitalsData, lastSentData, buffer, ref bitposition, keyframe);
		}

		public SerializationFlags OnNetDeserialize(int originFrameId, byte[] buffer, ref int bitposition, FrameArrival arrival)
		{
			Frame frame = (base.IsMine ? offtickFrame : frames[originFrameId]);
			if (!buffer.ReadBool(ref bitposition))
			{
				return SerializationFlags.None;
			}
			bool keyframe = IsKeyframe(originFrameId);
			SerializationFlags serializationFlags = vitals.Deserialize(frame.vitalsData, buffer, ref bitposition, keyframe);
			frame.content = (((serializationFlags & SerializationFlags.IsComplete) != SerializationFlags.None) ? FrameContents.Complete : (((serializationFlags & SerializationFlags.HasContent) != SerializationFlags.None) ? FrameContents.Partial : FrameContents.Empty));
			return serializationFlags;
		}

		[Obsolete("Use vitals.ApplyCharges() instead")]
		public double ApplyDamage(double damage)
		{
			if (!base.IsMine)
			{
				return damage;
			}
			if (damage == 0.0)
			{
				return damage;
			}
			return vitals.ApplyCharges(damage, allowOverload: false, propagate: true);
		}

		public void OnVitalValueChange(Vital vital)
		{
			if (vital.VitalData.Value <= 0.0)
			{
				RootVitalBecameZero(vital);
			}
			int i = 0;
			for (int count = OnVitalsValueChange.Count; i < count; i++)
			{
				OnVitalsValueChange[i].OnVitalValueChange(vital);
			}
		}

		public void OnVitalParamChange(Vital vital)
		{
			Debug.LogError("Not implemented");
			int i = 0;
			for (int count = OnVitalsParamChange.Count; i < count; i++)
			{
				OnVitalsParamChange[i].OnVitalParamChange(vital);
			}
		}

		protected virtual void RootVitalBecameZero(Vital vital)
		{
			int i = 0;
			for (int count = OnRootVitalBecameZero.Count; i < count; i++)
			{
				OnRootVitalBecameZero[i].OnRootVitalBecameZero(vital, null);
			}
			if (autoDespawn && (bool)syncState && rootVital == vital)
			{
				syncState.Despawn(immediate: false);
			}
		}

		public void OnStateChange(ObjState newState, ObjState previousState, Transform attachmentTransform, Mount attachTo = null, bool isReady = true)
		{
			if (wasDespawned && newState != ObjState.Despawned)
			{
				for (int i = 0; i < vitalsCount; i++)
				{
					vitalArray[i].ResetValues();
				}
			}
			wasDespawned = newState == ObjState.Despawned;
		}

		protected override void ApplySnapshot(Frame snapframe, Frame targframe, bool snapIsValid, bool targIsValid)
		{
			if (snapIsValid && snapframe.content >= FrameContents.Extrapolated)
			{
				vitals.Apply(snapFrame.vitalsData);
			}
		}

		protected override void InterpolateFrame(Frame targframe, Frame startframe, Frame endframe, float t)
		{
			targframe.CopyFrom(startframe);
		}

		protected override void ExtrapolateFrame(Frame prevframe, Frame snapframe, Frame targframe)
		{
			VitalData[] datas = snapframe.vitalsData.datas;
			VitalData[] datas2 = targframe.vitalsData.datas;
			for (int i = 0; i < vitalsCount; i++)
			{
				datas2[i] = vitalArray[i].VitalDef.Extrapolate(datas[i]);
			}
			targframe.content = FrameContents.Extrapolated;
		}
	}
	public abstract class VitalsUISrcBase : MonoBehaviour, IOnChangeOwnedVitals
	{
		public enum MonitorSource
		{
			Auto,
			Owned,
			Self,
			GameObject
		}

		[Tooltip("Where this VitalUI will look for Vitals data.")]
		[HideInInspector]
		public MonitorSource monitor;

		[Tooltip("Object that this VitalUI will search for an IVitalsSystem vitals data source.")]
		[HideInInspector]
		[SerializeField]
		public UnityEngine.Object vitalsSource;

		[NonSerialized]
		public Vitals vitals;

		public abstract void OnChangeOwnedVitals(IVitalsSystem added, IVitalsSystem removed);

		protected virtual void Reset()
		{
			ApplyVitalsSource(null);
		}

		public virtual IVitalsSystem ApplyVitalsSource(UnityEngine.Object srcObj)
		{
			if (monitor == MonitorSource.Auto)
			{
				if (srcObj == null)
				{
					srcObj = (UnityEngine.Object)GetComponentInParent<IVitalsSystem>();
					monitor = MonitorSource.Self;
				}
				if (srcObj == null)
				{
					srcObj = (UnityEngine.Object)OwnedIVitals.LastItem;
					monitor = MonitorSource.Owned;
				}
			}
			Component component;
			GameObject gameObject;
			if (monitor == MonitorSource.Owned)
			{
				component = OwnedIVitals.LastItem as Component;
				gameObject = null;
			}
			else if (monitor == MonitorSource.Self)
			{
				gameObject = base.gameObject;
				component = null;
			}
			else
			{
				vitalsSource = srcObj;
				gameObject = srcObj as GameObject;
				component = srcObj as Component;
			}
			IVitalsSystem vitalsSystem;
			if ((bool)gameObject)
			{
				vitalsSystem = FindIVitalComponentOnGameObj(gameObject);
				if (vitalsSystem != null)
				{
					vitalsSource = (vitalsSystem as Component).gameObject;
				}
			}
			else if ((bool)component)
			{
				vitalsSystem = component as IVitalsSystem;
				if (monitor == MonitorSource.GameObject)
				{
					vitalsSource = component.gameObject;
				}
			}
			else
			{
				vitalsSystem = null;
				vitalsSource = null;
			}
			return vitalsSystem;
		}

		private static IVitalsSystem FindIVitalComponentOnGameObj(GameObject go)
		{
			if ((bool)go)
			{
				IVitalsSystem vitalsSystem = go.GetComponentInParent<IVitalsSystem>();
				if (vitalsSystem == null)
				{
					vitalsSystem = go.GetComponentInChildren<IVitalsSystem>();
				}
				return vitalsSystem;
			}
			return null;
		}
	}
	public class VitalUI : VitalUIBase
	{
		protected static GameObject vitalBarDefaultPrefab;

		public bool autoOffset = true;

		[Tooltip("Found children elements are nudged (value * vitalIndex). This is to automatically stagger multiple VitalUIs")]
		public Vector3 offset = new Vector3(0f, 0.1f, 0f);

		public float widthMultiplier = 1f;

		[Tooltip("Search for UI elements in children of this GameObject.")]
		[HideInInspector]
		public bool searchChildren = true;

		[HideInInspector]
		public Text UIText;

		[HideInInspector]
		public Image UIImage;

		[HideInInspector]
		public TextMesh textMesh;

		[HideInInspector]
		public SpriteRenderer barSprite;

		[HideInInspector]
		public SpriteRenderer backSprite;

		[HideInInspector]
		public bool billboard = true;

		private const string PLACEHOLDER_CANVAS_NAME = "PLACEHOLDER_VITALS_CANVAS";

		private static List<SpriteRenderer> resuableFindSpriteRend = new List<SpriteRenderer>();

		protected override void Reset()
		{
			base.Reset();
			FindUIElements();
		}

		protected override void Awake()
		{
			base.Awake();
			FindUIElements();
			base.enabled = billboard;
		}

		public override void Recalculate()
		{
			AutoAlign();
			if ((bool)backSprite)
			{
				backSprite.size = new Vector2(widthMultiplier, backSprite.size.y);
			}
			UpdateGraphics(vital);
		}

		protected virtual void AutoAlign()
		{
			if (autoOffset && (bool)base.transform.parent)
			{
				base.transform.localPosition = offset * vitalIndex;
			}
		}

		public bool FindUIElements()
		{
			if (textMesh == null)
			{
				textMesh = (searchChildren ? GetComponentInChildren<TextMesh>() : GetComponent<TextMesh>());
			}
			if (searchChildren)
			{
				GetComponentsInChildren(resuableFindSpriteRend);
			}
			else
			{
				GetComponents(resuableFindSpriteRend);
			}
			if (resuableFindSpriteRend.Count > 0 && barSprite == null)
			{
				barSprite = resuableFindSpriteRend[0];
			}
			if (resuableFindSpriteRend.Count > 1 && backSprite == null)
			{
				backSprite = resuableFindSpriteRend[1];
			}
			if (UIText == null)
			{
				UIText = (searchChildren ? GetComponentInChildren<Text>() : GetComponent<Text>());
			}
			if (UIImage == null)
			{
				UIImage = (searchChildren ? GetComponentInChildren<Image>() : GetComponent<Image>());
			}
			if (!textMesh && !barSprite && !UIText)
			{
				return UIImage;
			}
			return true;
		}

		public override void UpdateGraphics(Vital vital)
		{
			if (vital == null)
			{
				return;
			}
			VitalDefinition vitalDef = vital.VitalDef;
			double num = ((targetField == TargetField.Value) ? vital.VitalData.Value : ((targetField == TargetField.Max) ? vitalDef.FullValue : vitalDef.MaxValue));
			if (num == double.NegativeInfinity)
			{
				return;
			}
			if ((bool)textMesh)
			{
				textMesh.text = ((int)num).ToString();
			}
			if ((bool)barSprite)
			{
				barSprite.size = new Vector2((float)(num / vitalDef.MaxValue * (double)widthMultiplier), barSprite.size.y);
			}
			if (UIText != null)
			{
				UIText.text = ((int)num).ToString();
			}
			if (UIImage != null)
			{
				double maxValue = vitalDef.MaxValue;
				if (UIImage.type == Image.Type.Filled && UIImage.sprite != null)
				{
					UIImage.fillAmount = (float)(num / maxValue * (double)widthMultiplier);
				}
				else
				{
					UIImage.rectTransform.localScale = new Vector3((float)(num / maxValue * (double)widthMultiplier), UIImage.rectTransform.localScale.y, UIImage.rectTransform.localScale.z);
				}
			}
		}

		public void LateUpdate()
		{
			Camera main = Camera.main;
			if ((bool)main)
			{
				base.transform.LookAt(main.transform, new Vector3(0f, 1f, 0f));
				Vector3 eulerAngles = base.transform.eulerAngles;
				base.transform.eulerAngles = new Vector3(0f, eulerAngles.y + 180f, 0f);
			}
		}
	}
	public abstract class VitalUIBase : VitalsUISrcBase, IOnVitalValueChange, IOnVitalChange, IOnChangeOwnedVitals
	{
		public enum TargetField
		{
			Value,
			Max,
			MaxOverload
		}

		[Tooltip("Which vital type will be monitored.")]
		[HideInInspector]
		public VitalNameType targetVital = new VitalNameType(VitalType.Health);

		[Tooltip("Which value to track. Typically this is value, but can be other VitalDefinition values like Max/Full.")]
		[HideInInspector]
		public TargetField targetField;

		[SerializeField]
		[HideInInspector]
		protected int vitalIndex = -1;

		[NonSerialized]
		protected Vital vital;

		public Vitals Vitals
		{
			get
			{
				return vitals;
			}
			set
			{
				vitals = value;
				if (value == null)
				{
					Vital = null;
				}
				else
				{
					Vital = vitals.GetVital(targetVital);
				}
			}
		}

		public Vital Vital
		{
			get
			{
				return vital;
			}
			private set
			{
				if (vital != null)
				{
					vital.RemoveIOnVitalChange(this);
				}
				value?.AddIOnVitalChange(this);
				vital = value;
				UpdateGraphics(vital);
			}
		}

		public override IVitalsSystem ApplyVitalsSource(UnityEngine.Object vs)
		{
			IVitalsSystem vitalsSystem = base.ApplyVitalsSource(vs);
			Vitals = vitalsSystem?.Vitals;
			vitalIndex = vitalsSystem?.Vitals.GetVitalIndex(targetVital) ?? (-1);
			return vitalsSystem;
		}

		public abstract void Recalculate();

		protected virtual void Awake()
		{
			ApplyVitalsSource(vitalsSource);
			if (monitor == MonitorSource.Auto || monitor == MonitorSource.Owned)
			{
				OwnedIVitals.iOnChangeOwnedVitals.Add(this);
			}
		}

		protected virtual void Start()
		{
			if (vital != null)
			{
				UpdateGraphics(vital);
			}
		}

		protected virtual void OnDestroy()
		{
			if (monitor == MonitorSource.Auto || monitor == MonitorSource.Owned)
			{
				OwnedIVitals.iOnChangeOwnedVitals.Remove(this);
			}
			if (vital != null)
			{
				vital.RemoveIOnVitalChange(this);
			}
		}

		public override void OnChangeOwnedVitals(IVitalsSystem added, IVitalsSystem removed)
		{
			if (added != null)
			{
				vitalsSource = added as Component;
				Vitals = added.Vitals;
			}
			else if (removed.Vitals == vitals)
			{
				IVitalsSystem lastItem = OwnedIVitals.LastItem;
				if (lastItem != null)
				{
					Vitals = lastItem.Vitals;
				}
			}
		}

		public void OnVitalParamChange(Vital vital)
		{
		}

		public virtual void OnVitalValueChange(Vital vital)
		{
			UpdateGraphics(vital);
		}

		public abstract void UpdateGraphics(Vital vital);
	}
	public class VitalsContactReactor : ContactReactorBase, IOnContactEvent, IVitalsContactReactor, IContactReactor, IOnStateChange
	{
		[SerializeField]
		[HideInInspector]
		protected VitalNameType vitalNameType = new VitalNameType(VitalType.Health);

		[HideInInspector]
		public double dischargeOnEnter = 20.0;

		[HideInInspector]
		public double dischargeOnExit = 20.0;

		[HideInInspector]
		public double dischargeOnScan = 20.0;

		[SerializeField]
		[HideInInspector]
		protected double dischargePerSec = 20.0;

		[Tooltip("Unconsumed values (remainders) should be passed through to the next vital in the stack of vitals.")]
		public bool propagate;

		public bool allowOverload;

		[SerializeField]
		protected bool isPickup = true;

		public bool useCharges;

		public double _charges = 50.0;

		[Tooltip("The Charges value that will be set on initialization, and whenever this object respawns.")]
		[SerializeField]
		protected double initialCharges = 50.0;

		public Consumption consumeDespawn;

		protected double valuePerFixed;

		public virtual VitalNameType VitalNameType => new VitalNameType(VitalType.None);

		public double DischargePerSec
		{
			get
			{
				return dischargePerSec;
			}
			internal set
			{
				valuePerFixed = value * (double)Time.fixedDeltaTime;
				dischargePerSec = value;
			}
		}

		public virtual bool Propagate
		{
			get
			{
				return propagate;
			}
			set
			{
				propagate = value;
			}
		}

		public virtual bool AllowOverload
		{
			get
			{
				return allowOverload;
			}
			set
			{
				allowOverload = value;
			}
		}

		public override bool IsPickup => isPickup;

		public virtual double Charges => _charges;

		public virtual Consumption ConsumeCharges(double amount)
		{
			if (amount == 0.0)
			{
				return Consumption.None;
			}
			double val = _charges - amount;
			double num = (_charges = ((initialCharges >= 0.0) ? Math.Max(val, 0.0) : Math.Min(val, 0.0)));
			if (num != initialCharges)
			{
				if (num != 0.0)
				{
					return Consumption.Partial;
				}
				return Consumption.All;
			}
			return Consumption.None;
		}

		protected virtual void Consume(Consumption consumed)
		{
			if (consumed != Consumption.None && consumeDespawn != Consumption.None && syncState != null)
			{
				if (consumed == Consumption.All)
				{
					syncState.Despawn(immediate: false);
				}
				else if (consumeDespawn == Consumption.Partial)
				{
					syncState.Despawn(immediate: false);
				}
			}
		}

		public override void OnAwakeInitialize(bool isNetObject)
		{
			base.OnAwakeInitialize(isNetObject);
			valuePerFixed = dischargePerSec * (double)Time.fixedDeltaTime;
		}

		protected override Consumption ProcessContactEvent(ContactEvent contactEvent)
		{
			if (!(contactEvent.contactSystem is IVitalsSystem vitalsSystem))
			{
				return Consumption.None;
			}
			double valueForTriggerType = GetValueForTriggerType(contactEvent.contactType);
			double num = vitalsSystem.Vitals.ApplyCharges(vitalNameType, valueForTriggerType, allowOverload, propagate);
			Consumption consumption;
			if (useCharges)
			{
				consumption = ConsumeCharges(num);
			}
			else
			{
				if (num == 0.0)
				{
					return Consumption.None;
				}
				consumption = ((num != valueForTriggerType) ? Consumption.Partial : Consumption.All);
				Consume(consumption);
			}
			if (isPickup && consumption != Consumption.None)
			{
				Mount mount = vitalsSystem.TryPickup(this, contactEvent);
				if ((bool)mount)
				{
					syncState.HardMount(mount);
				}
			}
			return consumption;
		}

		public void OnStateChange(ObjState newState, ObjState previousState, Transform attachmentTransform, Mount attachTo = null, bool isReady = true)
		{
			if (previousState == ObjState.Despawned && (newState & ObjState.Visible) != ObjState.Despawned)
			{
				_charges = initialCharges;
			}
		}

		public double DischargeValue(ContactType contactType = ContactType.Undefined)
		{
			double num = contactType switch
			{
				ContactType.Enter => dischargeOnEnter, 
				ContactType.Stay => dischargePerSec, 
				ContactType.Exit => dischargeOnExit, 
				ContactType.Hitscan => dischargeOnScan, 
				_ => 0.0, 
			};
			if (useCharges)
			{
				if (num >= 0.0)
				{
					return Math.Min(num, _charges);
				}
				return Math.Max(num, _charges);
			}
			return num;
		}

		protected double GetValueForTriggerType(ContactType collideType)
		{
			return collideType switch
			{
				ContactType.Enter => dischargeOnEnter, 
				ContactType.Stay => valuePerFixed, 
				ContactType.Exit => dischargeOnExit, 
				ContactType.Hitscan => dischargeOnScan, 
				_ => 0.0, 
			};
		}
	}
