	[AddComponentMenu("")]
	[DisallowMultipleComponent]
	public class MountsManager : MonoBehaviour, IOnAwake, IOnPreQuit
	{
		[NonSerialized]
		public Dictionary<int, Mount> mountIdLookup = new Dictionary<int, Mount>();

		[NonSerialized]
		public List<Mount> indexedMounts = new List<Mount>();

		[NonSerialized]
		public int bitsForMountId;

		public void OnAwake()
		{
			CollectMounts();
			bitsForMountId = ((indexedMounts.Count != 0) ? (indexedMounts.Count - 1).GetBitsForMaxValue() : 0);
		}

		public void OnPreQuit()
		{
			UnmountAll();
		}

		public List<Mount> CollectMounts(bool force = false)
		{
			indexedMounts.Clear();
			mountIdLookup.Clear();
			base.transform.GetNestedComponentsInChildren<Mount, NetObject>(indexedMounts);
			int i = 0;
			for (int count = indexedMounts.Count; i < count; i++)
			{
				Mount mount = indexedMounts[i];
				mount.componentIndex = i;
				int id = mount.mountType.id;
				if (!mountIdLookup.ContainsKey(id))
				{
					mountIdLookup.Add(id, mount);
				}
			}
			return indexedMounts;
		}

		public Mount GetMount(int mountId)
		{
			mountIdLookup.TryGetValue(mountId, out var value);
			return value;
		}

		public void UnmountAll()
		{
			int i = 0;
			for (int count = indexedMounts.Count; i < count; i++)
			{
				indexedMounts[i].DismountAll();
			}
		}
	}
	[RequireComponent(typeof(Mount))]
	public class MountThrow : NetComponent, IOnPreUpdate, IOnPreSimulate
	{
		public KeyCode throwKey;

		public Mount mount;

		public bool fromRoot = true;

		public bool inheritRBVelocity = true;

		public Vector3 offset = new Vector3(0f, 3f, 0f);

		public Vector3 velocity = new Vector3(0f, 1f, 5f);

		private bool throwQueued;

		public override void OnAwake()
		{
			base.OnAwake();
			if (mount == null)
			{
				mount = GetComponent<Mount>();
			}
		}

		public void OnPreUpdate()
		{
			if (base.IsMine && Input.GetKeyDown(throwKey))
			{
				throwQueued = true;
			}
		}

		public void OnPreSimulate(int frameId, int subFrameId)
		{
			if (!throwQueued)
			{
				return;
			}
			throwQueued = false;
			List<IMountable> mountedObjs = mount.mountedObjs;
			for (int i = 0; i < mountedObjs.Count; i++)
			{
				IMountable mountable = mountedObjs[i];
				Rigidbody rb = mountable.Rb;
				if ((bool)rb && mountable.IsThrowable)
				{
					SyncState syncState = mountable as SyncState;
					if ((bool)syncState)
					{
						Transform transform = (fromRoot ? mount.mountsLookup.transform : base.transform);
						Vector3 position = transform.TransformPoint(offset);
						Quaternion rotation = transform.rotation;
						Vector3 vector = ((inheritRBVelocity && (bool)rb) ? (rb.velocity + transform.TransformVector(velocity)) : transform.TransformVector(velocity));
						syncState.Throw(position, rotation, vector);
					}
				}
			}
		}
	}
	public enum PassThruType
	{
		SetTrigger,
		ResetTrigger,
		Play,
		PlayFixed,
		CrossFade,
		CrossFadeFixed
	}
	public struct AnimPassThru
	{
		public PassThruType passThruType;

		public int hash;

		public float normlTime;

		public float fixedTime;

		public float duration;

		public int layer;

		public LocalApplyTiming localApplyTiming;

		public AnimPassThru(PassThruType triggerType, int hash, int layer, float normTime, float otherTime, float duration, LocalApplyTiming localApplyTiming = LocalApplyTiming.OnSend)
		{
			passThruType = triggerType;
			this.hash = hash;
			normlTime = normTime;
			fixedTime = otherTime;
			this.duration = duration;
			this.layer = layer;
			this.localApplyTiming = localApplyTiming;
		}
	}
	public class SyncAnimator : SyncObject<SyncAnimator.Frame>, IOnSnapshot, IOnNetSerialize, IOnAuthorityChanged, ISyncAnimator, IReadyable, IUseKeyframes, IOnInterpolate, IOnCaptureState
	{
		public class Frame : FrameBase
		{
			public SyncAnimator syncAnimator;

			public SmartVar[] parameters;

			public int?[] stateHashes;

			public bool[] layerIsInTransition;

			public float[] normalizedTime;

			public float?[] layerWeights;

			public Queue<AnimPassThru> passThrus;

			public Frame()
			{
			}

			public Frame(SyncAnimator syncAnimator, int frameId)
				: base(frameId)
			{
				this.syncAnimator = syncAnimator;
				int layerCount = syncAnimator.layerCount;
				stateHashes = new int?[layerCount];
				layerIsInTransition = new bool[layerCount];
				normalizedTime = new float[layerCount];
				layerWeights = new float?[layerCount];
				passThrus = new Queue<AnimPassThru>(2);
				parameters = new SmartVar[syncAnimator.paramCount];
				int paramCount = syncAnimator.paramCount;
				for (int i = 0; i < paramCount; i++)
				{
					parameters[i] = syncAnimator.sharedParamSettings[i].defaultValue;
				}
			}

			public override void CopyFrom(FrameBase sourceFrame)
			{
				base.CopyFrom(sourceFrame);
				Frame frame = sourceFrame as Frame;
				if (syncAnimator.syncParams)
				{
					SmartVar[] array = frame.parameters;
					int num = array.Length;
					for (int i = 0; i < num; i++)
					{
						parameters[i] = array[i];
					}
				}
				if (syncAnimator.syncStates)
				{
					int num2 = frame.stateHashes.Length;
					for (int j = 0; j < num2; j++)
					{
						stateHashes[j] = frame.stateHashes[j];
						layerIsInTransition[j] = frame.layerIsInTransition[j];
						normalizedTime[j] = frame.normalizedTime[j];
						layerWeights[j] = frame.layerWeights[j];
					}
				}
			}

			public override void Clear()
			{
				base.Clear();
				int i = 0;
				for (int num = stateHashes.Length; i < num; i++)
				{
					stateHashes[i] = null;
				}
				passThrus.Clear();
				int j = 0;
				for (int num2 = layerWeights.Length; j < num2; j++)
				{
					layerWeights[j] = null;
					stateHashes[j] = null;
					normalizedTime[j] = 0f;
					layerWeights[j] = null;
				}
			}
		}

		private static Dictionary<int, Dictionary<int, int>> masterSharedTriggHashes = new Dictionary<int, Dictionary<int, int>>();

		private static Dictionary<int, List<int>> masterSharedTriggIndexes = new Dictionary<int, List<int>>();

		[HideInInspector]
		public List<int> sharedTriggIndexes = new List<int>();

		private Dictionary<int, int> sharedTriggHashes;

		private static Dictionary<int, Dictionary<int, int>> masterSharedStateHashes = new Dictionary<int, Dictionary<int, int>>();

		private static Dictionary<int, List<int>> masterSharedStateIndexes = new Dictionary<int, List<int>>();

		[HideInInspector]
		public List<int> sharedStateIndexes = new List<int>();

		private Dictionary<int, int> sharedStateHashes;

		[Tooltip("The Animator to sync. If null the first animator on this game object will be found and used.")]
		public Animator animator;

		[Tooltip("Disables applyRootMotion on any non-authority instances, to avoid a tug of war between the transform sync and root motion.")]
		public bool autoRootMotion = true;

		[HideInInspector]
		public bool syncPassThrus = true;

		[HideInInspector]
