		private void ExecutePassThruQueue(Frame frame)
		{
			Queue<AnimPassThru> passThrus = frame.passThrus;
			while (passThrus.Count > 0)
			{
				AnimPassThru pt = passThrus.Dequeue();
				ExecutePassThru(pt);
			}
		}

		private void ExecutePassThru(AnimPassThru pt)
		{
			int hash = pt.hash;
			switch (pt.passThruType)
			{
			case PassThruType.SetTrigger:
				animator.SetTrigger(pt.hash);
				break;
			case PassThruType.ResetTrigger:
				animator.ResetTrigger(pt.hash);
				break;
			case PassThruType.Play:
				animator.Play(hash, pt.layer, pt.normlTime);
				break;
			case PassThruType.PlayFixed:
				animator.PlayInFixedTime(hash, pt.layer, pt.fixedTime);
				break;
			case PassThruType.CrossFade:
				animator.CrossFade(hash, pt.duration, pt.layer, pt.normlTime);
				break;
			case PassThruType.CrossFadeFixed:
				animator.CrossFadeInFixedTime(hash, pt.duration, pt.layer, pt.fixedTime);
				break;
			}
		}

		private SerializationFlags WritePassThrus(Frame frame, byte[] buffer, ref int bitposition, bool isKeyframe)
		{
			Queue<AnimPassThru> passThrus = frame.passThrus;
			SerializationFlags result = ((passThrus.Count != 0) ? SerializationFlags.HasContent : SerializationFlags.None);
			while (passThrus.Count > 0)
			{
				AnimPassThru pt = passThrus.Dequeue();
				PassThruType passThruType = pt.passThruType;
				int hash = pt.hash;
				bool flag = passThruType == PassThruType.SetTrigger || passThruType == PassThruType.ResetTrigger;
				if (pt.localApplyTiming == LocalApplyTiming.OnSend)
				{
					ExecutePassThru(pt);
				}
				buffer.WriteBool(b: true, ref bitposition);
				buffer.Write((uint)passThruType, ref bitposition, 3);
				int value;
				bool flag2 = (flag ? sharedTriggHashes.TryGetValue(hash, out value) : sharedStateHashes.TryGetValue(pt.hash, out value));
				buffer.WriteBool(flag2, ref bitposition);
				if (flag2)
				{
					buffer.Write((uint)value, ref bitposition, flag ? bitsForTriggerIndex : bitsForStateIndex);
				}
				else
				{
					buffer.WriteSigned(pt.hash, ref bitposition, 32);
				}
				if (flag)
				{
					continue;
				}
				if (layerCount > 1)
				{
					buffer.Write((uint)(pt.layer + 1), ref bitposition, bitsForLayerIndex);
				}
				if (passThruType == PassThruType.Play || passThruType == PassThruType.CrossFade)
				{
					float normlTime = pt.normlTime;
					if (normlTime == 0f)
					{
						buffer.WriteBool(b: false, ref bitposition);
					}
					else
					{
						buffer.WriteBool(b: true, ref bitposition);
						buffer.WriteNorm(normlTime, ref bitposition, (int)passthruNormTimeCompress);
					}
				}
				else
				{
					float fixedTime = pt.fixedTime;
					if (fixedTime == 0f)
					{
						buffer.WriteBool(b: false, ref bitposition);
					}
					else
					{
						buffer.WriteBool(b: true, ref bitposition);
						buffer.WriteHalf(fixedTime, ref bitposition);
					}
				}
				if (passThruType == PassThruType.CrossFade || passThruType == PassThruType.CrossFadeFixed)
				{
					buffer.WriteHalf(pt.duration, ref bitposition);
				}
			}
			buffer.WriteBool(b: false, ref bitposition);
			return result;
		}

		private void CapturePassThrus(Frame frame)
		{
			if (syncPassThrus)
			{
				while (passThruQueue.Count > 0)
				{
					frame.passThrus.Enqueue(passThruQueue.Dequeue());
				}
			}
		}

		private void ReadPassThrus(Frame frame, byte[] buffer, ref int bitposition, bool isKeyframe)
		{
			while (buffer.ReadBool(ref bitposition))
			{
				PassThruType passThruType = (PassThruType)buffer.Read(ref bitposition, 3);
				bool flag = passThruType == PassThruType.SetTrigger || passThruType == PassThruType.ResetTrigger;
				int index;
				if (buffer.ReadBool(ref bitposition))
				{
					if (flag)
					{
						index = (int)buffer.Read(ref bitposition, bitsForTriggerIndex);
						index = sharedTriggIndexes[index];
					}
					else
					{
						index = (int)buffer.Read(ref bitposition, bitsForStateIndex);
						index = sharedStateIndexes[index];
					}
				}
				else
				{
					index = buffer.ReadSigned(ref bitposition, 32);
				}
				if (flag)
				{
					frame.passThrus.Enqueue(new AnimPassThru(passThruType, index, -1, -1f, -1f, -1f));
					continue;
				}
				int layer = ((layerCount > 1) ? ((int)buffer.Read(ref bitposition, bitsForLayerIndex) - 1) : (-1));
				float normTime;
				float otherTime;
				if (passThruType == PassThruType.Play || passThruType == PassThruType.CrossFade)
				{
					normTime = (buffer.ReadBool(ref bitposition) ? buffer.ReadNorm(ref bitposition, (int)passthruNormTimeCompress) : 0f);
					otherTime = -1f;
				}
				else
				{
					otherTime = (buffer.ReadBool(ref bitposition) ? buffer.ReadHalf(ref bitposition) : 0f);
					normTime = -1f;
				}
				float duration = ((passThruType == PassThruType.CrossFade || passThruType == PassThruType.CrossFadeFixed) ? buffer.ReadHalf(ref bitposition) : (-1f));
				frame.passThrus.Enqueue(new AnimPassThru(passThruType, index, layer, normTime, otherTime, duration));
			}
		}

		private void CaptureStates(Frame frame)
		{
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				frame.layerWeights[i] = animator.GetLayerWeight(i);
				if (animator.IsInTransition(i))
				{
					frame.layerIsInTransition[i] = true;
					continue;
				}
				AnimatorStateInfo currentAnimatorStateInfo = animator.GetCurrentAnimatorStateInfo(i);
				frame.layerIsInTransition[i] = false;
				frame.stateHashes[i] = currentAnimatorStateInfo.fullPathHash;
				float normalizedTime = currentAnimatorStateInfo.normalizedTime;
				if (normalizedTimeCompress == NormalizedFloatCompression.Full32 || normalizedTimeCompress == NormalizedFloatCompression.Half16)
				{
					frame.normalizedTime[i] = normalizedTime;
				}
				else if (currentAnimatorStateInfo.loop)
				{
					frame.normalizedTime[i] = ((normalizedTime > 1f) ? (normalizedTime % 1f) : normalizedTime);
				}
				else
				{
					frame.normalizedTime[i] = ((normalizedTime > 1f) ? 1f : ((normalizedTime < 0f) ? 0f : normalizedTime));
				}
			}
		}

		private SerializationFlags WriteStates(Frame frame, byte[] buffer, ref int bitposition, bool isKeyframe)
		{
			int?[] stateHashes = frame.stateHashes;
			float[] normalizedTime = frame.normalizedTime;
			float?[] layerWeights = frame.layerWeights;
			bool[] layerIsInTransition = frame.layerIsInTransition;
			SerializationFlags serializationFlags = SerializationFlags.None;
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				int? num2 = stateHashes[i];
				bool flag = !num2.HasValue || lastAnimationHash[i] != num2.Value;
				if (isKeyframe || flag)
				{
					buffer.WriteBool(b: true, ref bitposition);
					bool flag2 = layerIsInTransition[i];
					buffer.WriteBool(flag2, ref bitposition);
					if (!flag2)
					{
						bool flag3 = sharedStateIndexes.IndexOf(num2.Value) != -1;
						buffer.WriteBool(flag3, ref bitposition);
						if (flag3)
						{
							buffer.Write((uint)sharedStateIndexes.IndexOf(num2.Value), ref bitposition, bitsForStateIndex);
						}
						else
						{
							buffer.WriteSigned(num2.Value, ref bitposition, 32);
						}
						float value = (normalizedTime[i] + 1f) * 0.5f;
						buffer.WriteNorm(value, ref bitposition, (int)normalizedTimeCompress);
					}
					lastAnimationHash[i] = (num2.HasValue ? num2.Value : 0);
					serializationFlags |= SerializationFlags.HasContent;
				}
				else
				{
					buffer.WriteBool(b: false, ref bitposition);
				}
				if (!syncLayerWeights || i == 0)
				{
					continue;
				}
				float? num3 = layerWeights[i];
				if (num3 == 1f)
				{
					buffer.WriteBool(b: true, ref bitposition);
					serializationFlags |= SerializationFlags.HasContent;
					continue;
				}
				buffer.WriteBool(b: false, ref bitposition);
				if (num3 == 0f)
				{
					buffer.WriteBool(b: true, ref bitposition);
					serializationFlags |= SerializationFlags.HasContent;
					continue;
				}
				buffer.WriteBool(b: false, ref bitposition);
				int bits = (int)layerWeightCompress;
				uint num4 = num3.Value.CompressNorm(bits);
				if (isKeyframe || lastLayerWeight[i] != num4)
				{
					buffer.WriteBool(b: true, ref bitposition);
					buffer.Write(num4, ref bitposition, bits);
					lastLayerWeight[i] = num4;
					serializationFlags |= SerializationFlags.HasContent;
				}
				else
				{
					buffer.WriteBool(b: false, ref bitposition);
				}
			}
			return serializationFlags;
		}

		private void ReadStates(Frame frame, byte[] buffer, ref int bitposition, bool isKeyframe)
		{
			int?[] stateHashes = frame.stateHashes;
			float[] normalizedTime = frame.normalizedTime;
			float?[] layerWeights = frame.layerWeights;
			bool[] layerIsInTransition = frame.layerIsInTransition;
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				if (buffer.ReadBool(ref bitposition) && !(layerIsInTransition[i] = buffer.ReadBool(ref bitposition)))
				{
					bool num2 = buffer.ReadBool(ref bitposition);
					int num3 = (num2 ? ((int)buffer.Read(ref bitposition, bitsForStateIndex)) : buffer.ReadSigned(ref bitposition, 32));
					if (num2)
					{
						num3 = sharedStateIndexes[num3];
					}
					stateHashes[i] = num3;
					float num4 = buffer.ReadNorm(ref bitposition, (int)normalizedTimeCompress) * 2f - 1f;
					normalizedTime[i] = num4;
				}
				if (syncLayerWeights && i != 0)
				{
					if (buffer.ReadBool(ref bitposition))
					{
						layerWeights[i] = 1f;
					}
					else if (buffer.ReadBool(ref bitposition))
					{
						layerWeights[i] = 0f;
					}
					else if (buffer.ReadBool(ref bitposition))
					{
						layerWeights[i] = buffer.ReadNorm(ref bitposition, (int)layerWeightCompress);
					}
					else
					{
						layerWeights[i] = null;
					}
				}
			}
		}

		private void ApplyState(Frame applyFrame)
		{
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				int? num2 = applyFrame.stateHashes[i];
				bool flag = applyFrame.layerIsInTransition[i];
				if (!num2.HasValue)
				{
					continue;
				}
				if (!flag && num2.Value != 0)
				{
					animator.Play(num2.Value, i, applyFrame.normalizedTime[i]);
				}
				if (syncLayerWeights)
				{
					float? num3 = applyFrame.layerWeights[i];
					if (num3.HasValue)
					{
						animator.SetLayerWeight(i, num3.Value);
					}
				}
			}
		}

		private void CaptureLayerWeights(Frame frame)
		{
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				frame.layerWeights[i] = animator.GetLayerWeight(i);
			}
		}

		private SerializationFlags WriteLayerWeights(Frame frame, byte[] buffer, ref int bitposition, bool isKeyframe)
		{
			float?[] layerWeights = frame.layerWeights;
			SerializationFlags serializationFlags = SerializationFlags.None;
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				if (!syncLayerWeights || i == 0)
				{
					continue;
				}
				float? num2 = layerWeights[i];
				if (num2 == 1f)
				{
					buffer.WriteBool(b: true, ref bitposition);
					serializationFlags |= SerializationFlags.HasContent;
					continue;
				}
				buffer.WriteBool(b: false, ref bitposition);
				if (num2 == 0f)
				{
					buffer.WriteBool(b: true, ref bitposition);
					serializationFlags |= SerializationFlags.HasContent;
					continue;
				}
				buffer.WriteBool(b: false, ref bitposition);
				int bits = (int)layerWeightCompress;
				uint num3 = num2.Value.CompressNorm(bits);
				if (isKeyframe || lastLayerWeight[i] != num3)
				{
					buffer.WriteBool(b: true, ref bitposition);
					buffer.Write(num3, ref bitposition, bits);
					lastLayerWeight[i] = num3;
					serializationFlags |= SerializationFlags.HasContent;
				}
				else
				{
					buffer.WriteBool(b: false, ref bitposition);
				}
			}
			return serializationFlags;
		}

		private SerializationFlags ReadLayerWeights(Frame frame, byte[] buffer, ref int bitposition, bool isKeyframe)
		{
			float?[] layerWeights = frame.layerWeights;
			SerializationFlags serializationFlags = SerializationFlags.None;
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				if (syncLayerWeights && i != 0)
				{
					if (buffer.ReadBool(ref bitposition))
					{
						layerWeights[i] = 1f;
						serializationFlags |= SerializationFlags.HasContent;
					}
					else if (buffer.ReadBool(ref bitposition))
					{
						layerWeights[i] = 0f;
						serializationFlags |= SerializationFlags.HasContent;
					}
					else if (buffer.ReadBool(ref bitposition))
					{
						layerWeights[i] = buffer.ReadNorm(ref bitposition, (int)layerWeightCompress);
						serializationFlags |= SerializationFlags.HasContent;
					}
					else
					{
						layerWeights[i] = null;
					}
				}
			}
			return SerializationFlags.HasContent;
		}

		private void ApplyLayerWeights(Frame applyFrame)
		{
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				if (syncLayerWeights)
				{
					float? num2 = applyFrame.layerWeights[i];
					if (num2.HasValue)
					{
						animator.SetLayerWeight(i, num2.Value);
					}
				}
			}
		}

		public override bool OnSnapshot(int prevFrameId, int snapFrameId, int targFrameId, bool prevIsValid, bool snapIsValid, bool targIsValid)
		{
			if (snapFrame != null && snapFrame.content != FrameContents.Empty)
			{
				ApplyFrame(snapFrame);
			}
			if (!base.OnSnapshot(prevFrameId, snapFrameId, targFrameId, prevIsValid, snapIsValid, targIsValid))
			{
				return false;
			}
			CompleteTargetParameters();
			return true;
		}

		private void ApplyFrame(Frame frame)
		{
			if (syncStates)
			{
				ApplyState(frame);
			}
			if (syncLayerWeights)
			{
				ApplyLayerWeights(frame);
			}
			ExecutePassThruQueue(frame);
			InterpolateParams(0f);
		}

		public override bool OnInterpolate(int snapFrameId, int targFrameId, float t)
		{
			if (!base.OnInterpolate(snapFrameId, targFrameId, t))
			{
				return false;
			}
			if (targFrame == null)
			{
				return false;
			}
			if (targFrame.content == FrameContents.Empty)
			{
				return false;
			}
			if (syncParams)
			{
				InterpolateParams(t);
			}
			return true;
		}

		protected override void InterpolateFrame(Frame targframe, Frame startframe, Frame endframe, float t)
		{
			targframe.CopyFrom(endframe);
			InterpolateState(targframe, startframe, endframe, t);
		}

		protected override void ExtrapolateFrame(Frame prevframe, Frame snapframe, Frame targframe)
		{
			targframe.content = FrameContents.Partial;
			ExtrapolateParams(prevframe, snapframe, targframe);
			ExtrapolateState();
		}

		private void ExtrapolateState()
		{
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				targFrame.stateHashes[i] = null;
			}
		}

		private void InterpolateState(Frame targFrame, Frame strFrame, Frame endFrame, float t)
		{
			int num = ((!syncLayers) ? 1 : layerCount);
			for (int i = 0; i < num; i++)
			{
				int? num2 = strFrame.stateHashes[i];
				int? num3 = endFrame.stateHashes[i];
				targFrame.stateHashes[i] = num3;
				float num4 = strFrame.normalizedTime[i];
				float b = endFrame.normalizedTime[i];
				if (num2 != num3 && num4 != 0f)
				{
					targFrame.normalizedTime[i] = Mathf.LerpUnclamped(num4, b, t);
				}
				else
				{
					targFrame.normalizedTime[i] = num4;
				}
			}
		}
	}
	public class SyncAdditiveMover : NetComponent, ITransformController, IOnPreUpdate, IOnPreSimulate
	{
		[Serializable]
		public class TRSDefinition : TRSDefinitionBase
		{
			public Vector3 addVector = new Vector3(0f, 0f, 0f);
		}

		[HideInInspector]
		public TRSDefinition posDef = new TRSDefinition();

		[HideInInspector]
		public TRSDefinition rotDef = new TRSDefinition();

		[HideInInspector]
		public TRSDefinition sclDef = new TRSDefinition();

		public bool HandlesInterpolation => true;

		public bool HandlesExtrapolation => true;

		public void OnPreSimulate(int frameId, int subFrameId)
		{
			if (base.isActiveAndEnabled && (!photonView || photonView.IsMine))
			{
				AddVector();
			}
		}

		public void OnPreUpdate()
		{
			if (base.isActiveAndEnabled)
			{
				AddVector();
			}
		}

		private void AddVector()
		{
			float mixedDeltaTime = DoubleTime.mixedDeltaTime;
			base.transform.localScale += sclDef.addVector * mixedDeltaTime;
			if (rotDef.local)
			{
				base.transform.localEulerAngles += rotDef.addVector * mixedDeltaTime;
			}
			else
			{
				base.transform.eulerAngles += rotDef.addVector * mixedDeltaTime;
			}
			base.transform.Translate(posDef.addVector * mixedDeltaTime, posDef.local ? Space.Self : Space.World);
		}
	}
	[Serializable]
	public class TRSDefinitionBase
	{
		public bool local = true;
	}
	[Serializable]
	public abstract class SyncMoverBase<TTRSDef, TFrame> : SyncObject<TFrame>, ITransformController, IOnPreSimulate, IOnPreUpdate where TTRSDef : TRSDefinitionBase, new() where TFrame : FrameBase, new()
	{
		public enum MovementRelation
		{
			Absolute,
			Relative
		}

		[HideInInspector]
		public TTRSDef posDef = new TTRSDef();

		[HideInInspector]
		public TTRSDef rotDef = new TTRSDef();

		[HideInInspector]
		public TTRSDef sclDef = new TTRSDef();

		protected Rigidbody rb;

		protected Rigidbody2D rb2d;

		[NonSerialized]
		public SyncTransform syncTransform;

		public virtual bool HandlesInterpolation => true;

		public virtual bool HandlesExtrapolation => true;

		public override void OnAwakeInitialize(bool isNetObject)
		{
			if (!isNetObject)
			{
				NetMasterCallbacks.onPreSimulates.Add(this);
				NetMasterCallbacks.onPreUpdates.Add(this);
			}
			rb = GetComponent<Rigidbody>();
			rb2d = GetComponent<Rigidbody2D>();
			if (((bool)rb && !rb.isKinematic) || ((bool)rb2d && !rb2d.isKinematic))
			{
				Debug.LogWarning(GetType().Name + " doesn't work with non-kinematic rigidbodies. Setting to kinematic.");
				if ((bool)rb)
				{
					rb.isKinematic = true;
				}
				else
				{
					rb2d.isKinematic = true;
				}
			}
			syncTransform = GetComponent<SyncTransform>();
			Recalculate();
		}

		public override void OnStartInitialize(bool isNetObject)
		{
			InitializeTRS(posDef, TRS.Position);
			InitializeTRS(rotDef, TRS.Rotation);
			InitializeTRS(sclDef, TRS.Scale);
		}

		private void OnDestroy()
		{
			if (!netObj)
			{
				NetMasterCallbacks.onPreSimulates.Remove(this);
				NetMasterCallbacks.onPreUpdates.Remove(this);
			}
		}

		public virtual void Recalculate()
		{
		}

		protected abstract void InitializeTRS(TTRSDef def, TRS type);

		public abstract void OnPreSimulate(int frameId, int subFrameId);

		public abstract void OnPreUpdate();
	}
	public class SyncNodeMover : SyncMoverBase<SyncNodeMover.TRSDefinition, SyncNodeMover.Frame>, IOnPreUpdate, IOnPreSimulate, IOnCaptureState, IOnNetSerialize, IOnSnapshot, IOnInterpolate, IReadyable
	{
		public enum Movement
		{
			Oscillate,
			Trigger
		}

		[Serializable]
		public class Node
		{
			public Vector3[] trs = new Vector3[3]
			{
				new Vector3(0f, 0f, 0f),
				new Vector3(0f, 0f, 0f),
				new Vector3(1f, 1f, 1f)
			};

			public Vector3 Pos
			{
				get
				{
					return trs[0];
				}
				set
				{
					trs[0] = value;
				}
			}

			public Vector3 Rot
			{
				get
				{
					return trs[1];
				}
				set
				{
					trs[1] = value;
				}
			}

			public Vector3 Scl
			{
				get
				{
					return trs[2];
				}
				set
				{
					trs[2] = value;
				}
			}
		}

		[Serializable]
		public class TRSDefinition : TRSDefinitionBase
		{
			public AxisMask includeAxes = AxisMask.XYZ;

			public MovementRelation relation = MovementRelation.Relative;
		}

		public class Frame : FrameBase
		{
			public int targetNode;

			public float phase;

			public uint cphase;

			public Frame()
			{
			}

			public Frame(int frameId)
				: base(frameId)
			{
			}

			public override void CopyFrom(FrameBase sourceFrame)
			{
				base.CopyFrom(sourceFrame);
				Frame frame = sourceFrame as Frame;
				targetNode = frame.targetNode;
				phase = frame.phase;
				cphase = frame.cphase;
			}

			public override void Clear()
			{
				base.Clear();
				targetNode = -1;
				phase = -1f;
				cphase = 0u;
			}

			public bool Compare(Frame otherFrame)
			{
				if (targetNode != otherFrame.targetNode || phase != otherFrame.phase || cphase != otherFrame.cphase)
				{
					return false;
				}
				return true;
			}
		}

		[Range(0f, 2f)]
		public float predictWithRTT = 1f;

		[HideInInspector]
		public List<Node> nodes = new List<Node>
		{
			new Node(),
			new Node()
		};

		[HideInInspector]
		public Movement movement;

		[HideInInspector]
		public float oscillatePeriod = 1f;

		[HideInInspector]
		public AnimationCurve oscillateCurve = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(0.5f, 1f), new Keyframe(1f, 0f));

		[HideInInspector]
		public LiteFloatCrusher floatCrusher = new LiteFloatCrusher(LiteFloatCompressType.Bits10, LiteFloatCrusher.Normalization.Positive);

		protected float currentPhase;

		protected int queuedTargetNode;

		protected int targetNode;

		protected double timeoffset;

		protected float snapPhase;

		protected float targPhase;

		protected float accumulatedTime;

		public Node StartNode => nodes[0];

		public Node EndNode => nodes[nodes.Count - 1];

		protected override void Reset()
		{
			base.Reset();
			oscillateCurve = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(0.5f, 1f), new Keyframe(1f, 0f));
		}

		protected override void InitializeTRS(TRSDefinition def, TRS type)
		{
			if (movement != Movement.Oscillate)
			{
				def.relation = MovementRelation.Relative;
			}
			if ((def.relation == MovementRelation.Relative && movement == Movement.Oscillate) || movement == Movement.Trigger)
			{
				Vector3 vector = type switch
				{
					TRS.Position => def.local ? base.transform.localPosition : base.transform.position, 
					TRS.Rotation => def.local ? base.transform.localEulerAngles : base.transform.eulerAngles, 
					_ => def.local ? base.transform.localScale : base.transform.lossyScale, 
				};
				nodes[0].trs[(int)type] += vector;
				nodes[1].trs[(int)type] += vector;
			}
		}

		public override void OnPreSimulate(int frameId, int subFrameId)
		{
			if (base.isActiveAndEnabled && (!photonView || photonView.IsMine))
			{
				OwnerInterpolate();
			}
		}

		public override void OnPreUpdate()
		{
			if (base.isActiveAndEnabled && (!photonView || photonView.IsMine))
			{
				OwnerInterpolate();
			}
		}

		private void OwnerInterpolate()
		{
			if (timeoffset == 0.0)
			{
				timeoffset = DoubleTime.fixedTime;
			}
			if (movement == Movement.Oscillate)
			{
				currentPhase = TimeToPhase(DoubleTime.time - timeoffset);
				float lerpT = OscillatePhaseToLerpT(currentPhase);
				Oscillate(lerpT);
			}
		}

		public void Trigger(int targetNode)
		{
			queuedTargetNode = targetNode;
		}

		public void TriggerMin()
		{
		}

		public void TriggerMax()
		{
		}

		private void TriggerLerp()
		{
		}

		private void Oscillate(float lerpT)
		{
			Node node = nodes[0];
			Node node2 = nodes[1];
			Vector3 pos = ((posDef.includeAxes == AxisMask.None) ? new Vector3(0f, 0f, 0f) : Vector3.Lerp(node.trs[0], node2.trs[0], lerpT));
			Vector3 rot = ((rotDef.includeAxes == AxisMask.None) ? new Vector3(0f, 0f, 0f) : Vector3.Lerp(node.trs[1], node2.trs[1], lerpT));
			Vector3 scl = ((sclDef.includeAxes == AxisMask.None) ? new Vector3(1f, 1f, 1f) : Vector3.Lerp(node.trs[2], node2.trs[2], lerpT));
			ApplyOscillate(pos, rot, scl);
		}

		public void OnCaptureCurrentState(int frameId)
		{
			Frame obj = frames[frameId];
			obj.targetNode = targetNode;
			obj.phase = currentPhase;
			obj.cphase = (uint)floatCrusher.Encode(currentPhase);
		}

		public SerializationFlags OnNetSerialize(int frameId, byte[] buffer, ref int bitposition, SerializationFlags writeFlags)
		{
			Frame frame = frames[frameId];
			if (movement == Movement.Oscillate)
			{
				floatCrusher.WriteValue(frame.phase, buffer, ref bitposition);
			}
			return SerializationFlags.HasContent;
		}

		public SerializationFlags OnNetDeserialize(int originFrameId, byte[] buffer, ref int bitposition, FrameArrival arrival)
		{
			Frame frame = frames[originFrameId];
			frame.content = FrameContents.Complete;
			if (movement == Movement.Oscillate)
			{
				frame.cphase = (uint)floatCrusher.ReadCValue(buffer, ref bitposition);
				frame.phase = floatCrusher.Decode(frame.cphase);
			}
			return SerializationFlags.HasContent;
		}

		protected override void ApplySnapshot(Frame snapframe, Frame targframe, bool snapIsVaid, bool targIsValid)
		{
			if (snapIsVaid && snapframe.content == FrameContents.Complete && movement == Movement.Oscillate)
			{
				if (predictWithRTT != 0f)
				{
					float num = (NetMaster.RTT + TickEngineSettings.targetBufferInterval) * predictWithRTT;
					float num2 = snapframe.phase * oscillatePeriod + num;
					float num3 = targframe.phase * oscillatePeriod + num;
					snapPhase = TimeToPhase(num2);
					targPhase = TimeToPhase(num3);
				}
				else
				{
					snapPhase = snapframe.phase;
					targPhase = targframe.phase;
				}
				float lerpT = OscillatePhaseToLerpT(snapPhase);
				Oscillate(lerpT);
			}
		}

		public override bool OnInterpolate(int snapFrameId, int targFrameId, float t)
		{
			if (!base.OnInterpolate(snapFrameId, targFrameId, t))
			{
				return false;
			}
			switch (movement)
			{
			case Movement.Oscillate:
			{
				if (targPhase < snapPhase)
				{
					targPhase += 1f;
				}
				float num = Mathf.Lerp(snapPhase, targPhase, t);
				if (num >= 1f)
				{
					num -= 1f;
				}
				float lerpT = OscillatePhaseToLerpT(num);
				Oscillate(lerpT);
				return true;
			}
			default:
				return false;
			}
		}

		protected override void ConstructMissingFrame(Frame prevFrame, Frame snapframe, Frame targframe)
		{
			if (movement == Movement.Oscillate && snapframe.content == FrameContents.Complete)
			{
				float num = snapframe.phase * oscillatePeriod + TickEngineSettings.netTickInterval;
				targframe.phase = TimeToPhase(num);
				targframe.content = FrameContents.Complete;
			}
		}

		protected float OscillatePhaseToLerpT(float phase)
		{
			return oscillateCurve.Evaluate(phase);
		}

		protected float TimeToPhase(double time)
		{
			return (float)(time % (double)oscillatePeriod) / oscillatePeriod;
		}

		private void ApplyOscillate(Vector3 pos, Vector3 rot, Vector3 scl)
		{
			AxisMask includeAxes = posDef.includeAxes;
			AxisMask includeAxes2 = rotDef.includeAxes;
			AxisMask includeAxes3 = sclDef.includeAxes;
			if (includeAxes3 != AxisMask.None)
			{
				base.transform.localScale = new Vector3(((includeAxes3 & AxisMask.X) != AxisMask.None) ? scl.x : base.transform.localScale.x, ((includeAxes3 & AxisMask.Y) != AxisMask.None) ? scl.y : base.transform.localScale.y, ((includeAxes3 & AxisMask.Z) != AxisMask.None) ? scl.z : base.transform.localScale.z);
			}
			if (includeAxes2 != AxisMask.None)
			{
				if (rotDef.local)
				{
					base.transform.localEulerAngles = new Vector3(((includeAxes2 & AxisMask.X) != AxisMask.None) ? rot.x : base.transform.localEulerAngles.x, ((includeAxes2 & AxisMask.Y) != AxisMask.None) ? rot.y : base.transform.localEulerAngles.y, ((includeAxes2 & AxisMask.Z) != AxisMask.None) ? rot.z : base.transform.localEulerAngles.z);
				}
				else
				{
					base.transform.eulerAngles = new Vector3(((includeAxes2 & AxisMask.X) != AxisMask.None) ? rot.x : base.transform.eulerAngles.x, ((includeAxes2 & AxisMask.Y) != AxisMask.None) ? rot.y : base.transform.eulerAngles.y, ((includeAxes2 & AxisMask.Z) != AxisMask.None) ? rot.z : base.transform.eulerAngles.z);
				}
			}
			if (includeAxes != AxisMask.None)
			{
				if (posDef.local)
				{
					base.transform.localPosition = new Vector3(((includeAxes & AxisMask.X) != AxisMask.None) ? pos.x : base.transform.localPosition.x, ((includeAxes & AxisMask.Y) != AxisMask.None) ? pos.y : base.transform.localPosition.y, ((includeAxes & AxisMask.Z) != AxisMask.None) ? pos.z : base.transform.localPosition.z);
				}
				else
				{
					base.transform.position = new Vector3(((includeAxes & AxisMask.X) != AxisMask.None) ? pos.x : base.transform.position.x, ((includeAxes & AxisMask.Y) != AxisMask.None) ? pos.y : base.transform.position.y, ((includeAxes & AxisMask.Z) != AxisMask.None) ? pos.z : base.transform.position.z);
				}
			}
		}
	}
	public class AutoMountHitscan : HitscanComponent
	{
		protected SyncState syncState;

		private Queue<Mount> foundMounts = new Queue<Mount>();

		public SyncState SyncState => syncState;

		public override void OnAwake()
		{
			base.OnAwake();
			if ((bool)netObj)
			{
				syncState = netObj.GetComponent<SyncState>();
			}
		}

		public override void OnAuthorityChanged(bool isMine, bool controllerChanged)
		{
			base.OnAuthorityChanged(isMine, controllerChanged);
			List<IOnPreSimulate> onPreSimulateCallbacks = netObj.onPreSimulateCallbacks;
			bool flag = onPreSimulateCallbacks.Contains(this);
			base.OnAuthorityChanged(isMine, controllerChanged);
			if (isMine)
			{
				if (!flag)
				{
					onPreSimulateCallbacks.Add(this);
				}
			}
			else if (flag)
			{
				onPreSimulateCallbacks.Remove(this);
			}
		}

		public override void OnPreSimulate(int frameId, int subFrameId)
		{
			if (subFrameId != TickEngineSettings.sendEveryXTick - 1)
			{
				return;
			}
			triggerQueued = true;
			base.OnPreSimulate(frameId, subFrameId);
			if (foundMounts.Count != 0)
			{
				do
				{
					Mount attachTo = foundMounts.Dequeue();
					syncState.SoftMount(attachTo);
				}
				while (foundMounts.Count != 0);
			}
			else
			{
				syncState.SoftMount(null);
			}
		}

		public override bool ProcessHit(Collider hit)
		{
			Mount nestedComponentInParents = hit.transform.GetNestedComponentInParents<Mount, NetObject>();
			if ((bool)nestedComponentInParents)
			{
				foundMounts.Enqueue(nestedComponentInParents);
			}
			return false;
		}
	}
