		public bool OnSnapshot(int localTargFrameId)
		{
			if (!photonView)
			{
				return false;
			}
			if (!photonView.enabled)
			{
				return false;
			}
			if (!TickManager.perConnOffsets.TryGetValue(photonView.ControllerActorNr, out var value))
			{
				return false;
			}
			if (value == null)
			{
				return false;
			}
			if (!value.hadInitialSnapshot)
			{
				return false;
			}
			int advanceCount = value.advanceCount;
			if (advanceCount == 0)
			{
				return false;
			}
			int frameCount = TickEngineSettings.frameCount;
			int num = value.ConvertFrameLocalToOrigin(localTargFrameId);
			int num2 = num - 1;
			if (num2 < 0)
			{
				num2 += frameCount;
			}
			int num3 = num - 2;
			if (num3 < 0)
			{
				num3 += frameCount;
			}
			int frameCount2 = TickEngineSettings.frameCount;
			int i = 0;
			int num4 = num;
			for (; i < advanceCount; i++)
			{
				num4 = num + i;
				if (num4 >= frameCount2)
				{
					num4 -= frameCount2;
				}
				int num5 = num4 - TickEngineSettings.halfFrameCount;
				if (num5 < 0)
				{
					num5 += frameCount2;
				}
				bool flag = frameValidMask[num2];
				bool flag2 = frameValidMask[num4];
				int count = packObjects.Count;
				for (int j = 0; j < count; j++)
				{
					PackObjRecord packObjRecord = packObjects[j];
					PackFrame packFrame = packObjRecord.packFrames[num2];
					PackFrame packFrame2 = packObjRecord.packFrames[num4];
					packObjRecord.readyMask.OR(packObjRecord.info.defaultReadyMask);
					packObjRecord.readyMask.OR(packFrame.isCompleteMask);
					if (!flag2)
					{
						packObjRecord.info.CopyFrameToFrame(packFrame, packFrame2);
					}
					int maskOffset = 0;
					packObjRecord.info.SnapObject(packFrame, packFrame2, packObjRecord.component, ref packObjRecord.readyMask, ref maskOffset);
					if (flag)
					{
						maskOffset = 0;
						packObjRecord.info.CopyFrameToObj(packFrame, packObjRecord.component, ref packFrame.mask, ref maskOffset);
					}
					if (!packObjRecord.readyMask.Compare(packObjRecord.prevReadyMask))
					{
						BroadcastReadyMaskChange(packObjRecord);
					}
				}
				bool prevIsValid = frameValidMask[num3];
				bool snapIsValid = frameValidMask[num2];
				bool targIsValid = frameValidMask[num4];
				int k = 0;
				for (int count2 = onSnapshotCallbacks.Count; k < count2; k++)
				{
					onSnapshotCallbacks[k].OnSnapshot(num3, num2, num4, prevIsValid, snapIsValid, targIsValid);
				}
				num3 = num2;
				num2 = num4;
				frameValidMask[num5] = false;
			}
			return true;
		}

		private void BroadcastReadyMaskChange(PackObjRecord p)
		{
			OnPackObjReadyChange(p.component, p.readyMask.AllAreTrue ? ReadyStateEnum.Ready : ReadyStateEnum.Unready);
			p.onReadyCallback?.OnPackObjReadyChange(p.readyMask, p.readyMask.AllAreTrue);
			p.prevReadyMask.Copy(p.readyMask);
		}

		public bool OnInterpolate(int localSnapFrameId, int localTargFrameId, float t)
		{
			if (!TickManager.perConnOffsets.TryGetValue(photonView.ControllerActorNr, out var value))
			{
				return false;
			}
			if (value == null)
			{
				return false;
			}
			if (!value.hadInitialSnapshot)
			{
				return false;
			}
			int num = value.ConvertFrameLocalToOrigin(localSnapFrameId);
			int num2 = value.ConvertFrameLocalToOrigin(localTargFrameId);
			if (value.validFrameMask[num2])
			{
				int count = packObjects.Count;
				for (int i = 0; i < count; i++)
				{
					PackObjRecord packObjRecord = packObjects[i];
					PackFrame start = packObjRecord.packFrames[num];
					PackFrame end = packObjRecord.packFrames[num2];
					int maskOffset = 0;
					packObjRecord.info.InterpFrameToObj(start, end, packObjRecord.component, t, ref packObjRecord.readyMask, ref maskOffset);
				}
			}
			int j = 0;
			for (int count2 = onInterpolateCallbacks.Count; j < count2; j++)
			{
				IOnInterpolate onInterpolate = onInterpolateCallbacks[j];
				Behaviour behaviour = onInterpolate as Behaviour;
				if (behaviour.enabled && behaviour.gameObject.activeInHierarchy)
				{
					onInterpolate.OnInterpolate(num, num2, t);
				}
			}
			return true;
		}
	}
	public enum FrameContents
	{
		Empty,
		Partial,
		NoChange,
		Extrapolated,
		Complete
	}
	public abstract class FrameBase
	{
		public int frameId;

		public FrameContents content;

		public FrameBase()
		{
		}

		public FrameBase(int frameId)
		{
			this.frameId = frameId;
		}

		public static TFrame Instantiate<TFrame>(int frameId) where TFrame : FrameBase
		{
			TFrame obj = (TFrame)Activator.CreateInstance(typeof(TFrame));
			obj.frameId = frameId;
			return obj;
		}

		public virtual void CopyFrom(FrameBase sourceFrame)
		{
			content = sourceFrame.content;
		}

		public virtual void Clear()
		{
			content = FrameContents.Empty;
		}

		public static void PopulateFrames<TFrame>(ref TFrame[] frames) where TFrame : FrameBase
		{
			int frameCount = TickEngineSettings.frameCount;
			frames = new TFrame[frameCount + 1];
			for (int i = 0; i <= frameCount; i++)
			{
				TFrame val = Instantiate<TFrame>(i);
				frames[i] = val;
			}
		}
	}
	public enum ReadyStateEnum
	{
		Unready,
		Ready,
		Disabled
	}
	[HelpURL("https://doc.photonengine.com/en-us/pun/current/gameplay/simple/simplecoresynccomponents")]
	public abstract class SyncObject : NetComponent, IOnEnable, IOnDisable, IApplyOrder
	{
		public int _applyOrder = 13;

		[Tooltip("Every X Net Tick this object will serialize a full update, regardless of having changed or not.")]
		[Range(1f, 12f)]
		[HideInInspector]
		[SerializeField]
		protected int keyframeRate = 1;

		[Tooltip("When enabled, components will be instructed to check for changes and serialize them. When disabled, components will be instructed to ONLY send keyframes.")]
		[HideInInspector]
		[SerializeField]
		protected bool useDeltas = true;

		private const string ALWAYS_READY_TOOLTIP = "When true, the NetObject will not factor this SyncObj's ready state into firing IOnNetObjReady callbacks.";

		[ShowIfInterface(typeof(IReadyable), "When true, the NetObject will not factor this SyncObj's ready state into firing IOnNetObjReady callbacks.")]
		public bool _alwaysReady = true;

		private const string INCLUDE_SERIALIZATION_TOOLTIP = "When false, the NetObject will not serialize this SyncObj's state. This cannot be changed at runtime. Disable this component on the owner to disable sync at runtime instead.";

		[Tooltip("When false, the NetObject will not serialize this SyncObj's state. This cannot be changed at runtime. Disable this component on the owner to disable sync at runtime instead.")]
		[HideInInspector]
		public bool serializeThis = true;

		[NonSerialized]
		protected int syncObjIndex;

		protected ReadyStateEnum _readyState;

		public Action<SyncObject, ReadyStateEnum> onReadyCallbacks;

		public virtual int ApplyOrder => _applyOrder;

		public bool UseDeltas
		{
			get
			{
				return useDeltas;
			}
			set
			{
				useDeltas = value;
			}
		}

		public virtual bool AlwaysReady => _alwaysReady;

		public virtual bool IncludeInSerialization => serializeThis;

		public bool SkipWhenEmpty => false;

		public int SyncObjIndex
		{
			get
			{
				return syncObjIndex;
			}
			set
			{
				syncObjIndex = value;
			}
		}

		public ReadyStateEnum ReadyState
		{
			get
			{
				return _readyState;
			}
			set
			{
				if (_readyState != value)
				{
					_readyState = value;
					netObj.OnSyncObjReadyChange(this, _readyState);
					if (onReadyCallbacks != null)
					{
						onReadyCallbacks(this, value);
					}
				}
			}
		}

		public bool IsKeyframe(int frameId)
		{
			if (keyframeRate != 0)
			{
				if (frameId % keyframeRate != 0)
				{
					return frameId == TickEngineSettings.frameCount;
				}
				return true;
			}
			return false;
		}

		public virtual void ResetBuffers()
		{
		}

		public override void OnPostEnable()
		{
			base.OnPostEnable();
		}

		public override void OnAuthorityChanged(bool isMine, bool controllerChanged)
		{
			base.OnAuthorityChanged(isMine, controllerChanged);
			if (controllerChanged)
			{
				if (!(this is IReadyable { AlwaysReady: false }) || _readyState != ReadyStateEnum.Unready)
				{
					ReadyState = ReadyStateEnum.Ready;
				}
				else if (!base.isActiveAndEnabled)
				{
					ReadyState = ReadyStateEnum.Disabled;
				}
				else
				{
					ReadyState = ReadyStateEnum.Unready;
				}
			}
		}

		public override void OnPostDisable()
		{
			base.OnPostDisable();
			ReadyState = ReadyStateEnum.Disabled;
		}

		public override void OnAwake()
		{
			base.OnAwake();
		}

		protected virtual void OnEnable()
		{
		}

		protected int ConvertSecsToTicks(float seconds)
		{
			return (int)(seconds / (Time.fixedDeltaTime * (float)TickEngineSettings.sendEveryXTick));
		}
	}
	public abstract class SyncObject<TFrame> : SyncObject where TFrame : FrameBase
	{
		[NonSerialized]
		public TFrame[] frames;

		protected TFrame prevFrame;

		protected TFrame snapFrame;

		protected TFrame targFrame;

		protected TFrame offtickFrame;

		protected bool hadInitialSnapshot;

		public virtual bool AllowInterpolation => true;

		public virtual bool AllowReconstructionOfEmpty => true;

		public virtual bool AllowReconstructionOfPartial => true;

		public override void OnAwake()
		{
			if (keyframeRate > TickEngineSettings.MaxKeyframes)
			{
				keyframeRate = TickEngineSettings.MaxKeyframes;
				Debug.LogWarning(base.name + "/" + GetType().Name + " keyframe setting exceeds max allowed for the current " + SettingsScriptableObject<TickEngineSettings>.single.name + ".frameCount setting. Reducing to " + keyframeRate);
			}
			base.OnAwake();
			PopulateFrames();
			offtickFrame = frames[TickEngineSettings.frameCount];
		}

		public override void OnPostDisable()
		{
			base.OnPostDisable();
			hadInitialSnapshot = false;
		}

		public override void OnAuthorityChanged(bool isMine, bool controllerChanged)
		{
			base.OnAuthorityChanged(isMine, controllerChanged);
			if (controllerChanged)
			{
				int controllerActorNr = photonView.ControllerActorNr;
				int[] originHistory = netObj.originHistory;
				int i = 0;
				for (int frameCount = TickEngineSettings.frameCount; i < frameCount; i++)
				{
					if (controllerActorNr != originHistory[i])
					{
						frames[i].Clear();
					}
				}
			}
			hadInitialSnapshot = false;
		}

		protected virtual void PopulateFrames()
		{
			FrameBase.PopulateFrames(ref frames);
		}

		protected virtual void InitialCompleteSnapshot(TFrame frame)
		{
		}

		public virtual bool OnSnapshot(int prevFrameId, int snapFrameId, int targFrameId, bool prevIsValid, bool snapIsValid, bool targIsValid)
		{
			if (!base.enabled)
			{
				return false;
			}
			int frameCount = TickEngineSettings.frameCount;
			int halfFrameCount = TickEngineSettings.halfFrameCount;
			prevFrame = frames[prevFrameId];
			snapFrame = frames[snapFrameId];
			if (targFrameId < 0 || targFrameId >= frameCount)
			{
				Debug.Log("BAD FRAME ID " + targFrameId);
			}
			targFrame = frames[targFrameId];
			int num = snapFrameId + halfFrameCount;
			if (num >= frameCount)
			{
				num -= frameCount;
			}
			frames[num].Clear();
			if (targIsValid)
			{
				switch (targFrame.content)
				{
				case FrameContents.Empty:
					if (AllowReconstructionOfEmpty)
					{
						ReconstructEmptyFrame();
					}
					break;
				case FrameContents.Partial:
					if (AllowReconstructionOfPartial)
					{
						ReconstructIncompleteFrame();
					}
					break;
				case FrameContents.NoChange:
					targFrame.CopyFrom(snapFrame);
					break;
				}
			}
			else if (AllowReconstructionOfEmpty)
			{
				if (snapIsValid || snapFrame.content >= FrameContents.Extrapolated)
				{
					ConstructMissingFrame(prevFrame, snapFrame, targFrame);
				}
				else
				{
					targFrame.content = FrameContents.Empty;
				}
			}
			else
			{
				targFrame.content = FrameContents.Empty;
			}
			if (_readyState != ReadyStateEnum.Ready)
			{
				TFrame val = snapFrame;
				if (val.content == FrameContents.Complete)
				{
					InitialCompleteSnapshot(val);
					base.ReadyState = ReadyStateEnum.Ready;
				}
			}
			ApplySnapshot(snapFrame, targFrame, snapIsValid, targIsValid);
			return true;
		}

		protected virtual void ApplySnapshot(TFrame snapframe, TFrame targframe, bool snapIsValid, bool targIsValid)
		{
		}

		protected virtual void ReconstructEmptyFrame()
		{
			if (snapFrame.content == FrameContents.Extrapolated || snapFrame.content == FrameContents.Complete)
			{
				targFrame.content = FrameContents.Extrapolated;
				targFrame.CopyFrom(snapFrame);
			}
			else
			{
				targFrame.content = FrameContents.Empty;
			}
		}

		protected virtual void ReconstructIncompleteFrame()
		{
			targFrame.CopyFrom(snapFrame);
			targFrame.content = FrameContents.Partial;
		}

		protected virtual void ConstructMissingFrame(TFrame prevFrame, TFrame snapframe, TFrame targframe)
		{
			if (snapframe.content == FrameContents.Empty)
			{
				targframe.content = FrameContents.Empty;
				return;
			}
			if (!TickManager.perConnOffsets.TryGetValue(base.ControllerActorNr, out var _))
			{
				Debug.LogError("CONN " + base.ControllerActorNr + " NOT ESTABLISHED IN TICK MANAGER YET.");
			}
			int frameId = targframe.frameId;
			for (int i = 2; i <= 3; i++)
			{
				int num = frameId + i;
				if (num >= TickEngineSettings.frameCount)
				{
					num -= TickEngineSettings.frameCount;
				}
				TFrame val = frames[num];
				if (netObj.frameValidMask[num] && val.content == FrameContents.Complete)
				{
					float t = 1f / (float)i;
					InterpolateFrame(targframe, snapframe, val, t);
					if (targframe.content != FrameContents.Empty)
					{
						return;
					}
				}
			}
			targframe.content = FrameContents.Empty;
			ExtrapolateFrame(prevFrame, snapframe, targframe);
		}

		public virtual bool OnInterpolate(int snapFrameId, int targFrameId, float t)
		{
			if (!AllowInterpolation)
			{
				return false;
			}
			if (!base.isActiveAndEnabled)
			{
				return false;
			}
			if (base.IsMine)
			{
				return false;
			}
			return true;
		}

		protected virtual void InterpolateFrame(TFrame targframe, TFrame startframe, TFrame endframe, float t)
		{
			targframe.Clear();
		}

		protected virtual void ExtrapolateFrame(TFrame prevframe, TFrame snapframe, TFrame targframe)
		{
			targframe.Clear();
		}
	}
	public class TickEngineSettings : SettingsScriptableObject<TickEngineSettings>
	{
		public enum FrameCountEnum
		{
			FrameCount12 = 12,
			FrameCount30 = 30,
			FrameCount60 = 60,
			FrameCount120 = 120
		}

		public enum BufferCorrection
		{
			Manual,
			Auto
		}

		public enum LogInfoLevel
		{
			All,
			WarningsAndErrors,
			ErrorsOnly,
			None
		}

		[Space]
		[Tooltip("Enable/Disable for the NetMaster timing callbacks. This needs to be enabled for networking to work.")]
		public bool enableTickEngine = true;

		[Tooltip("Disable to pause sending Updates to Relay if no other Players are in the current Room. Default is false to save on data usage. Enable if your code requires updates to echo back to controller.")]
		public bool sendWhenSolo;

		[Header("Debugging")]
		[SerializeField]
		private LogInfoLevel logLevel = LogInfoLevel.WarningsAndErrors;

		[Tooltip("The size of the circular buffer.")]
		[SerializeField]
		[HideInInspector]
		private FrameCountEnum _frameCount = FrameCountEnum.FrameCount30;

		public static int frameCount;

		[SerializeField]
		[HideInInspector]
		private BufferCorrection _bufferCorrection;

		[Tooltip("Target size of the frame buffer. This is the number of frames in the buffer that is considered ideal. The lower the number the less latency, but with a greater risk of buffer underruns that lead to extrapolation/hitching.")]
		[SerializeField]
		[HideInInspector]
		private int _targetBufferSize = 2;

		public static int targetBufferSize;

		[Tooltip("Buffer sizes above this value wll be considered to be excessive, and will trigger multiple frames being processed to shrink the buffer.")]
		[SerializeField]
		[HideInInspector]
		private int _maxBufferSize = 3;

		public static int maxBufferSize;

		[Tooltip("Buffer sizes below this value will trigger the frames to hold for extra ticks in order to grow the buffer.")]
		[SerializeField]
		[HideInInspector]
		private int _minBufferSize = 1;

		public static int minBufferSize;

		[Tooltip("The number of ticks a buffer will be allowed to be below the the Min Buffer Size before starting to correct. This value prevents overreaction to network hiccups and allows for a few ticks before applying harsh corrections. Ideally this value will be larger than Ticks Before Shrink.")]
		[SerializeField]
		[HideInInspector]
		private int _ticksBeforeGrow = 8;

		public static int ticksBeforeGrow;

		[Tooltip("The number of ticks a buffer will be allowed to exceed Max Buffer Size before starting to correct. This value prevents overreaction to network hiccups and allows for a few ticks before applying harsh corrections. Ideally this value will be smaller than Ticks Before Grow.")]
		[SerializeField]
		[HideInInspector]
		private int _ticksBeforeShrink = 5;

		public static int ticksBeforeShrink;

		[Tooltip("States are sent post PhysX/FixedUpdate. Setting this to a value greater than one reduces these sends by only sending every X fixed tick.\n1 = Every Tick\n2 = Every Other\n3 = Every Third, etc.")]
		[SerializeField]
		[HideInInspector]
		private int _sendEveryXTick = 3;

		public static int sendEveryXTick = 3;

		[Space(4f)]
		public static int halfFrameCount;

		public static int thirdFrameCount;

		public static int quaterFrameCount;

		public static int frameCountBits;

		public static float netTickInterval;

		public static float netTickIntervalInv;

		public static float targetBufferInterval;

		private static float secondsOfBuffer;

		private static float secondsOfHalfBuffer;

		private static float bufferTargSecs;

		public static LogInfoLevel LogLevel => SettingsScriptableObject<TickEngineSettings>.Single.logLevel;

		public static int MaxKeyframes => (int)SettingsScriptableObject<TickEngineSettings>.Single._frameCount / 3;

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
		public static void Bootstrap()
		{
			SettingsScriptableObject<TickEngineSettings>.Single.CalculateBufferValues();
		}

		private void CalculateBufferValues()
		{
			if (_bufferCorrection == BufferCorrection.Manual)
			{
				minBufferSize = _minBufferSize;
				maxBufferSize = _maxBufferSize;
			}
			else
			{
				minBufferSize = _minBufferSize;
				maxBufferSize = _maxBufferSize;
			}
			frameCount = (int)_frameCount;
			halfFrameCount = frameCount / 2;
			thirdFrameCount = frameCount / 3;
			quaterFrameCount = frameCount / 4;
			frameCountBits = frameCount.GetBitsForMaxValue();
			netTickInterval = Time.fixedDeltaTime * (float)_sendEveryXTick;
			netTickIntervalInv = 1f / (Time.fixedDeltaTime * (float)_sendEveryXTick);
			targetBufferInterval = Time.fixedDeltaTime * (float)_sendEveryXTick * (float)_targetBufferSize;
			sendEveryXTick = _sendEveryXTick;
			targetBufferSize = _targetBufferSize;
			ticksBeforeGrow = _ticksBeforeGrow;
			ticksBeforeShrink = _ticksBeforeShrink;
			secondsOfBuffer = Time.fixedDeltaTime * (float)_sendEveryXTick * (float)frameCount;
			secondsOfHalfBuffer = secondsOfBuffer * 0.5f;
			bufferTargSecs = netTickInterval * (float)_targetBufferSize;
		}
	}
	public class ConnectionTickOffsets
	{
		public int connId;

		public int originToLocalFrame;

		public int localToOriginFrame;

		public int numOfSequentialFramesWithTooSmallBuffer;

		public int numOfSequentialFramesWithTooLargeBuffer;

		public bool frameArrivedTooLate;

		public bool hadInitialSnapshot;

		public int advanceCount;

		public float[] frameArriveTime;

		public float[] frameTimeBeforeConsumption;

		public FastBitMask128 validFrameMask;

		public int ConvertFrameLocalToOrigin(int localFrameId)
		{
			int frameCount = TickEngineSettings.frameCount;
			int num = localFrameId + localToOriginFrame;
			if (num >= frameCount)
			{
				num -= frameCount;
			}
			return num;
		}

		public int ConvertFrameOriginToLocal(int originFrameId)
		{
			int frameCount = TickEngineSettings.frameCount;
			int num = originFrameId + originToLocalFrame;
			if (num >= frameCount)
			{
				num -= frameCount;
			}
			return num;
		}

		public ConnectionTickOffsets(int connId, int originToLocal, int localToOrigin)
		{
			this.connId = connId;
			originToLocalFrame = originToLocal;
			localToOriginFrame = localToOrigin;
			int frameCount = TickEngineSettings.frameCount;
			validFrameMask = new FastBitMask128(frameCount + 1);
			frameArriveTime = new float[frameCount];
			frameTimeBeforeConsumption = new float[frameCount];
			for (int i = 0; i < frameCount; i++)
			{
				frameTimeBeforeConsumption[i] = float.PositiveInfinity;
			}
		}

		public void SnapshotAdvance()
		{
			int frameCount = TickEngineSettings.frameCount;
			int num = NetMaster.CurrentFrameId + localToOriginFrame;
			if (num >= frameCount)
			{
				num -= frameCount;
			}
			int num2 = validFrameMask.CountValidRange(num, TickEngineSettings.quaterFrameCount);
			if (!hadInitialSnapshot)
			{
				if (num2 == 0)
				{
					advanceCount = 0;
					return;
				}
				if (num2 > TickEngineSettings.targetBufferSize)
				{
					advanceCount = num2 - TickEngineSettings.targetBufferSize;
					return;
				}
			}
			if (num2 == 0)
			{
				if (frameArrivedTooLate)
				{
					numOfSequentialFramesWithTooLargeBuffer = 0;
					numOfSequentialFramesWithTooSmallBuffer = 0;
					frameArrivedTooLate = false;
					advanceCount = 0;
					return;
				}
				numOfSequentialFramesWithTooLargeBuffer = 0;
				advanceCount = 1;
			}
			else if (num2 < TickEngineSettings.minBufferSize)
			{
				numOfSequentialFramesWithTooLargeBuffer = 0;
				numOfSequentialFramesWithTooSmallBuffer += ((!frameArrivedTooLate) ? 1 : 2);
				frameArrivedTooLate = false;
				if (numOfSequentialFramesWithTooSmallBuffer >= TickEngineSettings.ticksBeforeGrow)
				{
					advanceCount = 0;
					return;
				}
				advanceCount = 1;
			}
			else if (num2 > TickEngineSettings.maxBufferSize)
			{
				numOfSequentialFramesWithTooSmallBuffer = 0;
				if (numOfSequentialFramesWithTooLargeBuffer > TickEngineSettings.ticksBeforeGrow)
				{
					advanceCount = num2 - TickEngineSettings.targetBufferSize + 1;
					numOfSequentialFramesWithTooLargeBuffer = 0;
				}
				else
				{
					advanceCount = 1;
					numOfSequentialFramesWithTooLargeBuffer++;
				}
			}
			else
			{
				numOfSequentialFramesWithTooLargeBuffer = 0;
				numOfSequentialFramesWithTooSmallBuffer = (frameArrivedTooLate ? 1 : 0);
				advanceCount = 1;
			}
			frameArrivedTooLate = false;
		}

		public void PostSnapshot()
		{
			int frameCount = TickEngineSettings.frameCount;
			int num = NetMaster.CurrentFrameId + localToOriginFrame;
			if (num >= frameCount)
			{
				num -= frameCount;
			}
			int num2 = num - TickEngineSettings.quaterFrameCount;
			if (num2 < 0)
			{
				num2 += frameCount;
			}
			validFrameMask.ClearBitsBefore(num2, TickEngineSettings.quaterFrameCount);
			if (advanceCount > 0)
			{
				hadInitialSnapshot = true;
			}
			if (advanceCount != 1)
			{
				localToOriginFrame += advanceCount - 1;
				if (localToOriginFrame < 0)
				{
					localToOriginFrame += frameCount;
				}
				else if (localToOriginFrame >= frameCount)
				{
					localToOriginFrame -= frameCount;
				}
				originToLocalFrame = frameCount - localToOriginFrame;
				if (originToLocalFrame < 0)
				{
					originToLocalFrame += frameCount;
				}
			}
		}
	}
	public class SimulateHealth : MonoBehaviour
	{
		private Vitals vitals;

		public VitalNameType vitalType = new VitalNameType(VitalType.Health);

		public KeyCode AddHealthKey = KeyCode.Alpha6;

		public KeyCode RemHealthKey = KeyCode.Alpha7;

		public KeyCode DamagehKey = KeyCode.Alpha8;

		public float amount = 20f;

		private void Start()
		{
			IVitalsSystem componentInChildren = GetComponentInChildren<IVitalsSystem>();
			if (componentInChildren == null || !(componentInChildren as SyncObject).PhotonView.IsMine)
			{
				UnityEngine.Object.Destroy(this);
			}
			else
			{
				vitals = componentInChildren.Vitals;
			}
		}

		private void Update()
		{
			if (Input.GetKeyDown(AddHealthKey))
			{
				vitals.ApplyCharges(vitalType, amount, allowOverload: false, propagate: false);
			}
			if (Input.GetKeyDown(RemHealthKey))
