	public static class NetObjColliderExt
	{
		public static readonly List<Component> reusableComponents = new List<Component>();

		public static readonly List<Collider> reusableColliders = new List<Collider>();

		public static readonly List<Collider2D> reusableColliders2D = new List<Collider2D>();

		public static void IndexColliders(this NetObject netObj)
		{
			List<Component> indexedColliders = netObj.indexedColliders;
			Dictionary<Component, int> colliderLookup = netObj.colliderLookup;
			colliderLookup.Clear();
			indexedColliders.Clear();
			netObj.transform.GetNestedComponentsInChildren<Component, NetObject>(reusableComponents);
			int count = reusableComponents.Count;
			for (int i = 0; i < count; i++)
			{
				Component component = reusableComponents[i];
				if ((bool)(component as Collider))
				{
					indexedColliders.Add(component);
				}
				else if ((bool)(component as Collider2D))
				{
					indexedColliders.Add(component);
				}
			}
			int j = 0;
			for (int count2 = indexedColliders.Count; j < count2; j++)
			{
				colliderLookup.Add(indexedColliders[j], j);
			}
			netObj.bitsForColliderIndex = (indexedColliders.Count - 1).GetBitsForMaxValue();
		}

		public static int GetFirstChildCollider(this Transform transform, ref Component firstFoundCollider, bool countTriggers, bool countNonTriggers)
		{
			if (!countTriggers && !countNonTriggers)
			{
				Debug.LogError("Counting Colliders, but args indicate to ignore everything. Set one to true.");
				firstFoundCollider = null;
				return 0;
			}
			transform.GetComponentsInChildren(includeInactive: true, reusableColliders);
			int count = reusableColliders.Count;
			if (count > 0)
			{
				if (countTriggers && countNonTriggers)
				{
					firstFoundCollider = reusableColliders[0];
					return count;
				}
				int num = 0;
				firstFoundCollider = null;
				for (int i = 0; i < count; i++)
				{
					Collider collider = reusableColliders[i];
					if (countTriggers ? collider.isTrigger : (!collider.isTrigger))
					{
						if (firstFoundCollider == null)
						{
							firstFoundCollider = collider;
						}
						num++;
					}
				}
				return num;
			}
			transform.GetComponentsInChildren(includeInactive: true, reusableColliders2D);
			int count2 = reusableColliders2D.Count;
			if (count2 > 0)
			{
				if (countTriggers && countNonTriggers)
				{
					firstFoundCollider = reusableColliders[0];
					return count;
				}
				int num2 = 0;
				firstFoundCollider = null;
				for (int j = 0; j < count2; j++)
				{
					Collider2D collider2D = reusableColliders2D[j];
					if (countTriggers ? collider2D.isTrigger : (!collider2D.isTrigger))
					{
						if (firstFoundCollider == null)
						{
							firstFoundCollider = collider2D;
						}
						num2++;
					}
				}
				return num2;
			}
			firstFoundCollider = null;
			return 0;
		}

		public static int CountChildCollider(this Transform transform, bool countTriggers, bool countNonTriggers)
		{
			if (!countTriggers && !countNonTriggers)
			{
				Debug.LogError("Counting Colliders, but args indicate to ignore everything. Set one to true.");
				return 0;
			}
			transform.GetComponentsInChildren(includeInactive: true, reusableColliders);
			int count = reusableColliders.Count;
			if (count > 0)
			{
				if (countTriggers && countNonTriggers)
				{
					return count;
				}
				int num = 0;
				for (int i = 0; i < count; i++)
				{
					Collider collider = reusableColliders[i];
					if (countTriggers ? collider.isTrigger : (!collider.isTrigger))
					{
						num++;
					}
				}
				return num;
			}
			transform.GetComponentsInChildren(includeInactive: true, reusableColliders2D);
			int count2 = reusableColliders2D.Count;
			if (count2 > 0)
			{
				if (countTriggers && countNonTriggers)
				{
					return count;
				}
				int num2 = 0;
				for (int j = 0; j < count2; j++)
				{
					Collider2D collider2D = reusableColliders2D[j];
					if (countTriggers ? collider2D.isTrigger : (!collider2D.isTrigger))
					{
						num2++;
					}
				}
				return num2;
			}
			return 0;
		}
	}
	public class TickManager : IInRoomCallbacks
	{
		public static readonly Dictionary<int, ConnectionTickOffsets> perConnOffsets = new Dictionary<int, ConnectionTickOffsets>();

		public static readonly List<int> connections = new List<int>();

		public static TickManager single;

		public static bool needToSendInitialForNewConn;

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
		public static void Bootstrap()
		{
			single = new TickManager();
			PhotonNetwork.NetworkingClient.AddCallbackTarget(single);
		}

		public void OnPlayerEnteredRoom(Photon.Realtime.Player newPlayer)
		{
			AddConnection(newPlayer.ActorNumber);
		}

		public void OnPlayerLeftRoom(Photon.Realtime.Player otherPlayer)
		{
			RemoveConnection(otherPlayer.ActorNumber);
		}

		public void OnRoomPropertiesUpdate(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
		{
		}

		public void OnPlayerPropertiesUpdate(Photon.Realtime.Player targetPlayer, ExitGames.Client.Photon.Hashtable changedProps)
		{
		}

		public void OnMasterClientSwitched(Photon.Realtime.Player newMasterClient)
		{
		}

		public static void PreSnapshot(int currentFrameId)
		{
			for (int i = 0; i < connections.Count; i++)
			{
				if (perConnOffsets[connections[i]] != null)
				{
					ConnectionTickOffsets connectionTickOffsets = perConnOffsets[connections[i]];
					int num = connectionTickOffsets.ConvertFrameLocalToOrigin(currentFrameId);
					float num2 = (connectionTickOffsets.validFrameMask[num] ? (Time.time - connectionTickOffsets.frameArriveTime[num]) : (-1f));
					connectionTickOffsets.frameTimeBeforeConsumption[num] = num2;
					connectionTickOffsets.SnapshotAdvance();
				}
			}
		}

		public static void PostSnapshot(int currentFrameId)
		{
			for (int i = 0; i < connections.Count; i++)
			{
				if (perConnOffsets[connections[i]] != null)
				{
					perConnOffsets[connections[i]].PostSnapshot();
				}
			}
		}

		public static ConnectionTickOffsets LogIncomingFrame(int connId, int originFrameId, out FrameArrival arrival)
		{
			int frameCount = TickEngineSettings.frameCount;
			if (!perConnOffsets.TryGetValue(connId, out var value) || value == null)
			{
				LogNewConnection(connId, originFrameId, frameCount, out value);
			}
			int num = originFrameId + value.originToLocalFrame;
			if (num >= frameCount)
			{
				num -= frameCount;
			}
			value.frameArriveTime[originFrameId] = Time.time;
			int currentFrameId = NetMaster.CurrentFrameId;
			int num2;
			if (num == currentFrameId)
			{
				num2 = 0;
			}
			else
			{
				num2 = currentFrameId - num;
				if (num2 < 0)
				{
					num2 += frameCount;
				}
				if (num2 >= TickEngineSettings.halfFrameCount)
				{
					num2 -= frameCount;
				}
			}
			if (num2 >= 0)
			{
				if (num2 != 0 && num2 != 1 && num2 < TickEngineSettings.halfFrameCount)
				{
				}
			}
			else
			{
				_ = -TickEngineSettings.halfFrameCount;
			}
			arrival = (FrameArrival)num2;
			bool flag = num2 <= 0;
			value.frameArrivedTooLate |= !flag;
			value.validFrameMask.Set(originFrameId, value: true);
			return value;
		}

		private static void LogNewConnection(int connId, int originFrameId, int frameCount, out ConnectionTickOffsets offsets)
		{
			int num;
			for (num = NetMaster.CurrentFrameId + TickEngineSettings.targetBufferSize; num >= frameCount; num -= frameCount)
			{
			}
			int num2 = num - originFrameId;
			if (num2 < 0)
			{
				num2 += frameCount;
			}
			int num3 = frameCount - num2;
			if (num3 < 0)
			{
				num3 += frameCount;
			}
			offsets = new ConnectionTickOffsets(connId, num2, num3);
			AddConnection(connId, offsets);
		}

		private static void AddConnection(int connId, ConnectionTickOffsets offsets = null)
		{
			if (PhotonNetwork.LocalPlayer.ActorNumber != connId)
			{
				if (!connections.Contains(connId))
				{
					perConnOffsets.Add(connId, offsets);
					connections.Add(connId);
					NetMsgSends.newPlayers.Add(connId);
					needToSendInitialForNewConn = true;
				}
				else
				{
					perConnOffsets[connId] = offsets;
				}
			}
		}

		public static void RemoveConnection(int connId)
		{
			if (perConnOffsets.ContainsKey(connId))
			{
				perConnOffsets.Remove(connId);
				connections.Remove(connId);
			}
		}
	}
	public static class CallbackUtilities
	{
		public static int RegisterInterface<T>(List<T> callbackList, object c, bool register) where T : class
		{
			if (callbackList == null)
			{
				callbackList = new List<T>();
			}
			if (!(c is T item))
			{
				return callbackList.Count;
			}
			if (register)
			{
				if (!callbackList.Contains(item))
				{
					callbackList.Add(item);
				}
			}
			else if (callbackList.Contains(item))
			{
				callbackList.Remove(item);
			}
			return callbackList.Count;
		}
	}
	public static class NetMsgCallbacks
	{
		public delegate void ByteBufferCallback(object conn, int connId, byte[] buffer);

		private class CallbackLists
		{
			public List<ByteBufferCallback> bufferCallbacks;
		}

		private static Dictionary<int, CallbackLists> callbacks = new Dictionary<int, CallbackLists>();

		public const byte DEF_MSG_ID = 215;

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
		private static void RegisterOnEventListener()
		{
			PhotonNetwork.NetworkingClient.EventReceived += OnEvent;
		}

		public static void OnEvent(EventData photonEvent)
		{
			byte code = photonEvent.Code;
			if (!callbacks.ContainsKey(code))
			{
				return;
			}
			bool useByteArraySlicePoolForEvents = PhotonNetwork.NetworkingClient.LoadBalancingPeer.UseByteArraySlicePoolForEvents;
			ByteArraySlice byteArraySlice;
			byte[] buffer;
			if (useByteArraySlicePoolForEvents)
			{
				byteArraySlice = photonEvent.CustomData as ByteArraySlice;
				buffer = byteArraySlice.Buffer;
			}
			else
			{
				byteArraySlice = null;
				buffer = photonEvent.CustomData as byte[];
			}
			CallbackLists callbackLists = callbacks[code];
			if (callbackLists.bufferCallbacks != null && callbackLists.bufferCallbacks.Count > 0)
			{
				foreach (ByteBufferCallback bufferCallback in callbackLists.bufferCallbacks)
				{
					bufferCallback(null, photonEvent.Sender, buffer);
				}
			}
			if (useByteArraySlicePoolForEvents)
			{
				byteArraySlice.Release();
			}
		}

		[Obsolete("Removed the asServer from UNET side, killing it here as well.")]
		public static void RegisterCallback(byte msgid, ByteBufferCallback callback, bool asServer)
		{
			if (!callbacks.ContainsKey(msgid))
			{
				callbacks.Add(msgid, new CallbackLists());
			}
			if (callbacks[msgid].bufferCallbacks == null)
			{
				callbacks[msgid].bufferCallbacks = new List<ByteBufferCallback>();
			}
			List<ByteBufferCallback> bufferCallbacks = callbacks[msgid].bufferCallbacks;
			if (!bufferCallbacks.Contains(callback))
			{
				bufferCallbacks.Add(callback);
			}
		}

		public static void RegisterCallback(ByteBufferCallback callback)
		{
			RegisterCallback(215, callback);
		}

		public static void RegisterCallback(byte msgid, ByteBufferCallback callback)
		{
			if (!callbacks.ContainsKey(msgid))
			{
				callbacks.Add(msgid, new CallbackLists());
			}
			if (callbacks[msgid].bufferCallbacks == null)
			{
				callbacks[msgid].bufferCallbacks = new List<ByteBufferCallback>();
			}
			List<ByteBufferCallback> bufferCallbacks = callbacks[msgid].bufferCallbacks;
			if (!bufferCallbacks.Contains(callback))
			{
				bufferCallbacks.Add(callback);
			}
		}

		[Obsolete("Removed the asServer from UNET side, killing it here as well.")]
		public static void UnregisterCallback(byte msgid, ByteBufferCallback callback, bool asServer)
		{
			if (callbacks.ContainsKey(msgid))
			{
				CallbackLists callbackLists = callbacks[msgid];
				callbackLists.bufferCallbacks.Remove(callback);
				if (callbackLists.bufferCallbacks.Count == 0)
				{
					callbacks.Remove(msgid);
				}
			}
		}

		public static void UnregisterCallback(ByteBufferCallback callback)
		{
			UnregisterCallback(215, callback);
		}

		public static void UnregisterCallback(byte msgid, ByteBufferCallback callback)
		{
			if (callbacks.ContainsKey(msgid))
			{
				CallbackLists callbackLists = callbacks[msgid];
				callbackLists.bufferCallbacks.Remove(callback);
				if (callbackLists.bufferCallbacks.Count == 0)
				{
					callbacks.Remove(msgid);
				}
			}
		}
	}
	public enum ReceiveGroup
	{
		Others,
		All,
		Master
	}
	public static class NetMsgSends
	{
		private static bool unreliableCapable;

		public static byte[] reusableBuffer = new byte[16384];

		public static byte[] reusableNetObjBuffer = new byte[4096];

		public static HashSet<int> newPlayers = new HashSet<int>();

		private static RaiseEventOptions[] opts = new RaiseEventOptions[3]
		{
			new RaiseEventOptions
			{
				Receivers = ReceiverGroup.Others
			},
			new RaiseEventOptions
			{
				Receivers = ReceiverGroup.All
			},
			new RaiseEventOptions
			{
				Receivers = ReceiverGroup.MasterClient
			}
		};

		public static bool ReadyToSend => PhotonNetwork.NetworkClientState == ClientState.Joined;

		public static bool AmActiveServer => false;

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
		private static void CacheSettings()
		{
			unreliableCapable = PhotonNetwork.NetworkingClient.LoadBalancingPeer.UsedProtocol == ConnectionProtocol.Udp;
		}

		public static void Send(this byte[] buffer, int bitposition, UnityEngine.Object refObj, SerializationFlags flags, bool flush = false)
		{
			Room currentRoom = PhotonNetwork.CurrentRoom;
			if (PhotonNetwork.OfflineMode || currentRoom == null || currentRoom.Players == null)
			{
				return;
			}
			bool flag = (flags & SerializationFlags.SendToSelf) != 0;
			if (flag || SettingsScriptableObject<TickEngineSettings>.single.sendWhenSolo || currentRoom.Players.Count > 1)
			{
				ReceiveGroup receiveGroup = (flag ? ReceiveGroup.All : ReceiveGroup.Others);
				int count = bitposition + 7 >> 3;
				LoadBalancingClient networkingClient = PhotonNetwork.NetworkingClient;
				DeliveryMode deliveryMode;
				if (newPlayers.Count > 0)
				{
					deliveryMode = DeliveryMode.Reliable;
					newPlayers.Clear();
				}
				else
				{
					bool flag2 = (flags & SerializationFlags.ForceReliable) != 0;
					deliveryMode = ((!unreliableCapable) ? DeliveryMode.Reliable : (flag2 ? DeliveryMode.ReliableUnsequenced : DeliveryMode.Unreliable));
				}
				SendOptions sendOptions = new SendOptions
				{
					DeliveryMode = deliveryMode
				};
				ByteArraySlice customEventContent = PhotonNetwork.NetworkingClient.LoadBalancingPeer.ByteArraySlicePool.Acquire(buffer, 0, count);
				networkingClient.OpRaiseEvent(215, customEventContent, opts[(int)receiveGroup], sendOptions);
				if (flush)
				{
					networkingClient.Service();
				}
			}
		}
	}
