	[Serializable]
	public class VersionInfo
	{
		public const byte Major = 1;

		public const byte Minor = 8;

		public const byte Release = 2;

		private static string StageSuffix = "";

		private static string TrialSuffix = "";

		[SerializeField]
		private int m_major;

		[SerializeField]
		private int m_minor;

		[SerializeField]
		private int m_release;

		public int Number => m_major * 100 + m_minor * 10 + m_release;

		public static string StaticToString()
		{
			return $"{(byte)1}.{(byte)8}.{(byte)2}" + StageSuffix + TrialSuffix;
		}

		public override string ToString()
		{
			return $"{m_major}.{m_minor}.{m_release}" + StageSuffix + TrialSuffix;
		}

		private VersionInfo()
		{
			m_major = 1;
			m_minor = 8;
			m_release = 2;
		}

		private VersionInfo(byte major, byte minor, byte release)
		{
			m_major = major;
			m_minor = minor;
			m_release = release;
		}

		public static VersionInfo Current()
		{
			return new VersionInfo(1, 8, 2);
		}

		public static bool Matches(VersionInfo version)
		{
			if (1 == version.m_major && 8 == version.m_minor)
			{
				return 2 == version.m_release;
			}
			return false;
		}
	}
	[Serializable]
	public class VolumeEffectField
	{
		public string fieldName;

		public string fieldType;

		public float valueSingle;

		public Color valueColor;

		public bool valueBoolean;

		public Vector2 valueVector2;

		public Vector3 valueVector3;

		public Vector4 valueVector4;

		public VolumeEffectField(string fieldName, string fieldType)
		{
			this.fieldName = fieldName;
			this.fieldType = fieldType;
		}

		public VolumeEffectField(FieldInfo pi, Component c)
			: this(pi.Name, pi.FieldType.FullName)
		{
			object value = pi.GetValue(c);
			UpdateValue(value);
		}

		public static bool IsValidType(string type)
		{
			switch (type)
			{
			case "System.Single":
			case "System.Boolean":
			case "UnityEngine.Color":
			case "UnityEngine.Vector2":
			case "UnityEngine.Vector3":
			case "UnityEngine.Vector4":
				return true;
			default:
				return false;
			}
		}

		public void UpdateValue(object val)
		{
			switch (fieldType)
			{
			case "System.Single":
				valueSingle = (float)val;
				break;
			case "System.Boolean":
				valueBoolean = (bool)val;
				break;
			case "UnityEngine.Color":
				valueColor = (Color)val;
				break;
			case "UnityEngine.Vector2":
				valueVector2 = (Vector2)val;
				break;
			case "UnityEngine.Vector3":
				valueVector3 = (Vector3)val;
				break;
			case "UnityEngine.Vector4":
				valueVector4 = (Vector4)val;
				break;
			}
		}
	}
	[Serializable]
	public class VolumeEffectComponent
	{
		public string componentName;

		public List<VolumeEffectField> fields;

		public VolumeEffectComponent(string name)
		{
			componentName = name;
			fields = new List<VolumeEffectField>();
		}

		public VolumeEffectField AddField(FieldInfo pi, Component c)
		{
			return AddField(pi, c, -1);
		}

		public VolumeEffectField AddField(FieldInfo pi, Component c, int position)
		{
			VolumeEffectField volumeEffectField = (VolumeEffectField.IsValidType(pi.FieldType.FullName) ? new VolumeEffectField(pi, c) : null);
			if (volumeEffectField != null)
			{
				if (position < 0 || position >= fields.Count)
				{
					fields.Add(volumeEffectField);
				}
				else
				{
					fields.Insert(position, volumeEffectField);
				}
			}
			return volumeEffectField;
		}

		public void RemoveEffectField(VolumeEffectField field)
		{
			fields.Remove(field);
		}

		public VolumeEffectComponent(Component c, VolumeEffectComponentFlags compFlags)
			: this(compFlags.componentName)
		{
			foreach (VolumeEffectFieldFlags componentField in compFlags.componentFields)
			{
				if (componentField.blendFlag)
				{
					FieldInfo field = c.GetType().GetField(componentField.fieldName);
					VolumeEffectField volumeEffectField = (VolumeEffectField.IsValidType(field.FieldType.FullName) ? new VolumeEffectField(field, c) : null);
					if (volumeEffectField != null)
					{
						fields.Add(volumeEffectField);
					}
				}
			}
		}

		public void UpdateComponent(Component c, VolumeEffectComponentFlags compFlags)
		{
			foreach (VolumeEffectFieldFlags fieldFlags in compFlags.componentFields)
			{
				if (fieldFlags.blendFlag && !fields.Exists((VolumeEffectField s) => s.fieldName == fieldFlags.fieldName))
				{
					FieldInfo field = c.GetType().GetField(fieldFlags.fieldName);
					VolumeEffectField volumeEffectField = (VolumeEffectField.IsValidType(field.FieldType.FullName) ? new VolumeEffectField(field, c) : null);
					if (volumeEffectField != null)
					{
						fields.Add(volumeEffectField);
					}
				}
			}
		}

		public VolumeEffectField FindEffectField(string fieldName)
		{
			for (int i = 0; i < fields.Count; i++)
			{
				if (fields[i].fieldName == fieldName)
				{
					return fields[i];
				}
			}
			return null;
		}

		public static FieldInfo[] ListAcceptableFields(Component c)
		{
			if (c == null)
			{
				return new FieldInfo[0];
			}
			return (from f in c.GetType().GetFields()
				where VolumeEffectField.IsValidType(f.FieldType.FullName)
				select f).ToArray();
		}

		public string[] GetFieldNames()
		{
			return fields.Select((VolumeEffectField r) => r.fieldName).ToArray();
		}
	}
	[Serializable]
	public class VolumeEffect
	{
		public AmplifyColorBase gameObject;

		public List<VolumeEffectComponent> components;

		public VolumeEffect(AmplifyColorBase effect)
		{
			gameObject = effect;
			components = new List<VolumeEffectComponent>();
		}

		public static VolumeEffect BlendValuesToVolumeEffect(VolumeEffectFlags flags, VolumeEffect volume1, VolumeEffect volume2, float blend)
		{
			VolumeEffect volumeEffect = new VolumeEffect(volume1.gameObject);
			foreach (VolumeEffectComponentFlags component in flags.components)
			{
				if (!component.blendFlag)
				{
					continue;
				}
				VolumeEffectComponent volumeEffectComponent = volume1.FindEffectComponent(component.componentName);
				VolumeEffectComponent volumeEffectComponent2 = volume2.FindEffectComponent(component.componentName);
				if (volumeEffectComponent == null || volumeEffectComponent2 == null)
				{
					continue;
				}
				VolumeEffectComponent volumeEffectComponent3 = new VolumeEffectComponent(volumeEffectComponent.componentName);
				foreach (VolumeEffectFieldFlags componentField in component.componentFields)
				{
					if (!componentField.blendFlag)
					{
						continue;
					}
					VolumeEffectField volumeEffectField = volumeEffectComponent.FindEffectField(componentField.fieldName);
					VolumeEffectField volumeEffectField2 = volumeEffectComponent2.FindEffectField(componentField.fieldName);
					if (volumeEffectField != null && volumeEffectField2 != null)
					{
						VolumeEffectField volumeEffectField3 = new VolumeEffectField(volumeEffectField.fieldName, volumeEffectField.fieldType);
						switch (volumeEffectField3.fieldType)
						{
						case "System.Single":
							volumeEffectField3.valueSingle = Mathf.Lerp(volumeEffectField.valueSingle, volumeEffectField2.valueSingle, blend);
							break;
						case "System.Boolean":
							volumeEffectField3.valueBoolean = volumeEffectField2.valueBoolean;
							break;
						case "UnityEngine.Vector2":
							volumeEffectField3.valueVector2 = Vector2.Lerp(volumeEffectField.valueVector2, volumeEffectField2.valueVector2, blend);
							break;
						case "UnityEngine.Vector3":
							volumeEffectField3.valueVector3 = Vector3.Lerp(volumeEffectField.valueVector3, volumeEffectField2.valueVector3, blend);
							break;
						case "UnityEngine.Vector4":
							volumeEffectField3.valueVector4 = Vector4.Lerp(volumeEffectField.valueVector4, volumeEffectField2.valueVector4, blend);
							break;
						case "UnityEngine.Color":
							volumeEffectField3.valueColor = Color.Lerp(volumeEffectField.valueColor, volumeEffectField2.valueColor, blend);
							break;
						}
						volumeEffectComponent3.fields.Add(volumeEffectField3);
					}
				}
				volumeEffect.components.Add(volumeEffectComponent3);
			}
			return volumeEffect;
		}

		public VolumeEffectComponent AddComponent(Component c, VolumeEffectComponentFlags compFlags)
		{
			if (compFlags == null)
			{
				VolumeEffectComponent volumeEffectComponent = new VolumeEffectComponent(string.Concat(c.GetType()));
				components.Add(volumeEffectComponent);
				return volumeEffectComponent;
			}
			VolumeEffectComponent volumeEffectComponent2;
			if ((volumeEffectComponent2 = FindEffectComponent(string.Concat(c.GetType()))) != null)
			{
				volumeEffectComponent2.UpdateComponent(c, compFlags);
				return volumeEffectComponent2;
			}
			VolumeEffectComponent volumeEffectComponent3 = new VolumeEffectComponent(c, compFlags);
			components.Add(volumeEffectComponent3);
			return volumeEffectComponent3;
		}

		public void RemoveEffectComponent(VolumeEffectComponent comp)
		{
			components.Remove(comp);
		}

		public void UpdateVolume()
		{
			if (gameObject == null)
			{
				return;
			}
			foreach (VolumeEffectComponentFlags component2 in gameObject.EffectFlags.components)
			{
				if (component2.blendFlag)
				{
					Component component = gameObject.GetComponent(component2.componentName);
					if (component != null)
					{
						AddComponent(component, component2);
					}
				}
			}
		}

		public void SetValues(AmplifyColorBase targetColor)
		{
			VolumeEffectFlags effectFlags = targetColor.EffectFlags;
			GameObject gameObject = targetColor.gameObject;
			foreach (VolumeEffectComponentFlags component2 in effectFlags.components)
			{
				if (!component2.blendFlag)
				{
					continue;
				}
				Component component = gameObject.GetComponent(component2.componentName);
				VolumeEffectComponent volumeEffectComponent = FindEffectComponent(component2.componentName);
				if (component == null || volumeEffectComponent == null)
				{
					continue;
				}
				foreach (VolumeEffectFieldFlags componentField in component2.componentFields)
				{
					if (!componentField.blendFlag)
					{
						continue;
					}
					FieldInfo field = component.GetType().GetField(componentField.fieldName);
					VolumeEffectField volumeEffectField = volumeEffectComponent.FindEffectField(componentField.fieldName);
					if (!(field == null) && volumeEffectField != null)
					{
						switch (field.FieldType.FullName)
						{
						case "System.Single":
							field.SetValue(component, volumeEffectField.valueSingle);
							break;
						case "System.Boolean":
							field.SetValue(component, volumeEffectField.valueBoolean);
							break;
						case "UnityEngine.Vector2":
							field.SetValue(component, volumeEffectField.valueVector2);
							break;
						case "UnityEngine.Vector3":
							field.SetValue(component, volumeEffectField.valueVector3);
							break;
						case "UnityEngine.Vector4":
							field.SetValue(component, volumeEffectField.valueVector4);
							break;
						case "UnityEngine.Color":
							field.SetValue(component, volumeEffectField.valueColor);
							break;
						}
					}
				}
			}
		}

		public void BlendValues(AmplifyColorBase targetColor, VolumeEffect other, float blendAmount)
		{
			VolumeEffectFlags effectFlags = targetColor.EffectFlags;
			GameObject gameObject = targetColor.gameObject;
			for (int i = 0; i < effectFlags.components.Count; i++)
			{
				VolumeEffectComponentFlags volumeEffectComponentFlags = effectFlags.components[i];
				if (!volumeEffectComponentFlags.blendFlag)
				{
					continue;
				}
				Component component = gameObject.GetComponent(volumeEffectComponentFlags.componentName);
				VolumeEffectComponent volumeEffectComponent = FindEffectComponent(volumeEffectComponentFlags.componentName);
				VolumeEffectComponent volumeEffectComponent2 = other.FindEffectComponent(volumeEffectComponentFlags.componentName);
				if (component == null || volumeEffectComponent == null || volumeEffectComponent2 == null)
				{
					continue;
				}
				for (int j = 0; j < volumeEffectComponentFlags.componentFields.Count; j++)
				{
					VolumeEffectFieldFlags volumeEffectFieldFlags = volumeEffectComponentFlags.componentFields[j];
					if (!volumeEffectFieldFlags.blendFlag)
					{
						continue;
					}
					FieldInfo field = component.GetType().GetField(volumeEffectFieldFlags.fieldName);
					VolumeEffectField volumeEffectField = volumeEffectComponent.FindEffectField(volumeEffectFieldFlags.fieldName);
					VolumeEffectField volumeEffectField2 = volumeEffectComponent2.FindEffectField(volumeEffectFieldFlags.fieldName);
					if (!(field == null) && volumeEffectField != null && volumeEffectField2 != null)
					{
						switch (field.FieldType.FullName)
						{
						case "System.Single":
							field.SetValue(component, Mathf.Lerp(volumeEffectField.valueSingle, volumeEffectField2.valueSingle, blendAmount));
							break;
						case "System.Boolean":
							field.SetValue(component, volumeEffectField2.valueBoolean);
							break;
						case "UnityEngine.Vector2":
							field.SetValue(component, Vector2.Lerp(volumeEffectField.valueVector2, volumeEffectField2.valueVector2, blendAmount));
							break;
						case "UnityEngine.Vector3":
							field.SetValue(component, Vector3.Lerp(volumeEffectField.valueVector3, volumeEffectField2.valueVector3, blendAmount));
							break;
						case "UnityEngine.Vector4":
							field.SetValue(component, Vector4.Lerp(volumeEffectField.valueVector4, volumeEffectField2.valueVector4, blendAmount));
							break;
						case "UnityEngine.Color":
							field.SetValue(component, Color.Lerp(volumeEffectField.valueColor, volumeEffectField2.valueColor, blendAmount));
							break;
						}
					}
				}
			}
		}

		public VolumeEffectComponent FindEffectComponent(string compName)
		{
			for (int i = 0; i < components.Count; i++)
			{
				if (components[i].componentName == compName)
				{
					return components[i];
				}
			}
			return null;
		}

		public static Component[] ListAcceptableComponents(AmplifyColorBase go)
		{
			if (go == null)
			{
				return new Component[0];
			}
			return (from comp in go.GetComponents(typeof(Component))
				where comp != null && !string.Concat(comp.GetType()).StartsWith("UnityEngine.") && !(comp.GetType() == typeof(AmplifyColorBase))
				select comp).ToArray();
		}

		public string[] GetComponentNames()
		{
			return components.Select((VolumeEffectComponent r) => r.componentName).ToArray();
		}
	}
	[Serializable]
	public class VolumeEffectContainer
	{
		public List<VolumeEffect> volumes;

		public VolumeEffectContainer()
		{
			volumes = new List<VolumeEffect>();
		}

		public void AddColorEffect(AmplifyColorBase colorEffect)
		{
			VolumeEffect volumeEffect;
			if ((volumeEffect = FindVolumeEffect(colorEffect)) != null)
			{
				volumeEffect.UpdateVolume();
				return;
			}
			volumeEffect = new VolumeEffect(colorEffect);
			volumes.Add(volumeEffect);
			volumeEffect.UpdateVolume();
		}

		public VolumeEffect AddJustColorEffect(AmplifyColorBase colorEffect)
		{
			VolumeEffect volumeEffect = new VolumeEffect(colorEffect);
			volumes.Add(volumeEffect);
			return volumeEffect;
		}

		public VolumeEffect FindVolumeEffect(AmplifyColorBase colorEffect)
		{
			for (int i = 0; i < volumes.Count; i++)
			{
				if (volumes[i].gameObject == colorEffect)
				{
					return volumes[i];
				}
			}
			for (int j = 0; j < volumes.Count; j++)
			{
				if (volumes[j].gameObject != null && volumes[j].gameObject.SharedInstanceID == colorEffect.SharedInstanceID)
				{
					return volumes[j];
				}
			}
			return null;
		}

		public void RemoveVolumeEffect(VolumeEffect volume)
		{
			volumes.Remove(volume);
		}

		public AmplifyColorBase[] GetStoredEffects()
		{
			return volumes.Select((VolumeEffect r) => r.gameObject).ToArray();
		}
	}
	[Serializable]
	public class VolumeEffectFieldFlags
	{
		public string fieldName;

		public string fieldType;

		public bool blendFlag;

		public VolumeEffectFieldFlags(FieldInfo pi)
		{
			fieldName = pi.Name;
			fieldType = pi.FieldType.FullName;
		}

		public VolumeEffectFieldFlags(VolumeEffectField field)
		{
			fieldName = field.fieldName;
			fieldType = field.fieldType;
			blendFlag = true;
		}
	}
	[Serializable]
	public class VolumeEffectComponentFlags
	{
		public string componentName;

		public List<VolumeEffectFieldFlags> componentFields;

		public bool blendFlag;

		public VolumeEffectComponentFlags(string name)
		{
			componentName = name;
			componentFields = new List<VolumeEffectFieldFlags>();
		}

		public VolumeEffectComponentFlags(VolumeEffectComponent comp)
			: this(comp.componentName)
		{
			blendFlag = true;
			foreach (VolumeEffectField field in comp.fields)
			{
				if (VolumeEffectField.IsValidType(field.fieldType))
				{
					componentFields.Add(new VolumeEffectFieldFlags(field));
				}
			}
		}

		public VolumeEffectComponentFlags(Component c)
			: this(string.Concat(c.GetType()))
		{
			FieldInfo[] fields = c.GetType().GetFields();
			foreach (FieldInfo fieldInfo in fields)
			{
				if (VolumeEffectField.IsValidType(fieldInfo.FieldType.FullName))
				{
					componentFields.Add(new VolumeEffectFieldFlags(fieldInfo));
				}
			}
		}

		public void UpdateComponentFlags(VolumeEffectComponent comp)
		{
			foreach (VolumeEffectField field in comp.fields)
			{
				if (componentFields.Find((VolumeEffectFieldFlags s) => s.fieldName == field.fieldName) == null && VolumeEffectField.IsValidType(field.fieldType))
				{
					componentFields.Add(new VolumeEffectFieldFlags(field));
				}
			}
		}

		public void UpdateComponentFlags(Component c)
		{
			FieldInfo[] fields = c.GetType().GetFields();
			foreach (FieldInfo pi in fields)
			{
				if (!componentFields.Exists((VolumeEffectFieldFlags s) => s.fieldName == pi.Name) && VolumeEffectField.IsValidType(pi.FieldType.FullName))
				{
					componentFields.Add(new VolumeEffectFieldFlags(pi));
				}
			}
		}

		public string[] GetFieldNames()
		{
			return (from r in componentFields
				where r.blendFlag
				select r.fieldName).ToArray();
		}
	}
	[Serializable]
	public class VolumeEffectFlags
	{
		public List<VolumeEffectComponentFlags> components;

		public VolumeEffectFlags()
		{
			components = new List<VolumeEffectComponentFlags>();
		}

		public void AddComponent(Component c)
		{
			VolumeEffectComponentFlags volumeEffectComponentFlags;
			if ((volumeEffectComponentFlags = components.Find((VolumeEffectComponentFlags s) => s.componentName == string.Concat(c.GetType()))) != null)
			{
				volumeEffectComponentFlags.UpdateComponentFlags(c);
			}
			else
			{
				components.Add(new VolumeEffectComponentFlags(c));
			}
		}

		public void UpdateFlags(VolumeEffect effectVol)
		{
			foreach (VolumeEffectComponent comp in effectVol.components)
			{
				VolumeEffectComponentFlags volumeEffectComponentFlags = null;
				if ((volumeEffectComponentFlags = components.Find((VolumeEffectComponentFlags s) => s.componentName == comp.componentName)) == null)
				{
					components.Add(new VolumeEffectComponentFlags(comp));
				}
				else
				{
					volumeEffectComponentFlags.UpdateComponentFlags(comp);
				}
			}
		}

		public static void UpdateCamFlags(AmplifyColorBase[] effects, AmplifyColorVolumeBase[] volumes)
		{
			foreach (AmplifyColorBase amplifyColorBase in effects)
			{
				amplifyColorBase.EffectFlags = new VolumeEffectFlags();
				for (int j = 0; j < volumes.Length; j++)
				{
					VolumeEffect volumeEffect = volumes[j].EffectContainer.FindVolumeEffect(amplifyColorBase);
					if (volumeEffect != null)
					{
						amplifyColorBase.EffectFlags.UpdateFlags(volumeEffect);
					}
				}
			}
		}

		public VolumeEffect GenerateEffectData(AmplifyColorBase go)
		{
			VolumeEffect volumeEffect = new VolumeEffect(go);
			foreach (VolumeEffectComponentFlags component2 in components)
			{
				if (component2.blendFlag)
				{
					Component component = go.GetComponent(component2.componentName);
					if (component != null)
					{
						volumeEffect.AddComponent(component, component2);
					}
				}
			}
			return volumeEffect;
		}

		public VolumeEffectComponentFlags FindComponentFlags(string compName)
		{
			for (int i = 0; i < components.Count; i++)
			{
				if (components[i].componentName == compName)
				{
					return components[i];
				}
			}
			return null;
		}

		public string[] GetComponentNames()
		{
			return (from r in components
				where r.blendFlag
				select r.componentName).ToArray();
		}
	}
