namespace Landfall.AI
{
	public class Evolver
	{
		private float m_mutationRate = 0.1f;

		private int m_selectionSize = 5;

		private bool m_elitism = true;

		public Population Evolve(Population population)
		{
			Population population2 = new Population(population.Size, init: false);
			int num = 0;
			if (m_elitism)
			{
				num = population2.Size / 2;
				population.Sort();
				for (int i = 0; i < num; i++)
				{
					Genome genome = population.GetGenome(i);
					population2.SetGenome(i, genome);
					genome.Fitness = 0f;
				}
				for (int j = 0; j < population2.Size / 2; j++)
				{
					population2.SetGenome(j + num, new Genome(population.GetGenome(j)));
				}
			}
			else
			{
				for (int k = num; k < population2.Size; k++)
				{
					Genome parentA = Selection(population);
					Genome parentB = Selection(population);
					Genome g = Crossover(parentA, parentB);
					population2.SetGenome(k, g);
				}
			}
			for (int l = num; l < population2.Size; l++)
			{
				population2.GetGenome(l).Mutate(m_mutationRate);
			}
			return population2;
		}

		public Genome Crossover(Genome parentA, Genome parentB)
		{
			Genome genome = new Genome();
			int num = UnityEngine.Random.Range(0, parentA.Size - 1);
			int num2 = UnityEngine.Random.Range(0, parentA.Size - 1);
			for (int i = 0; i < genome.Size; i++)
			{
				if (num < num2 && i > num && i < num2)
				{
					genome.SetGene(i, parentA.GetGene(i));
				}
				else if (num > num2 && (i >= num || i <= num2))
				{
					genome.SetGene(i, parentA.GetGene(i));
				}
				else
				{
					genome.SetGene(i, parentB.GetGene(i));
				}
			}
			return genome;
		}

		public Genome Selection(Population population)
		{
			List<Genome> list = new List<Genome>(m_selectionSize);
			for (int i = 0; i < m_selectionSize; i++)
			{
				list.Add(population.GetGenome(i));
			}
			Genome genome = list[0];
			for (int j = 0; j < m_selectionSize; j++)
			{
				Genome genome2 = population.GetGenome(j);
				if (genome2.Fitness > genome.Fitness)
				{
					genome = genome2;
				}
			}
			return genome;
		}
	}
	public class Genome
	{
		private double[] m_genes;

		private float m_fitness;

		public double[] Genes
		{
			get
			{
				return m_genes;
			}
			set
			{
				m_genes = value;
			}
		}

		public float Fitness
		{
			get
			{
				return m_fitness;
			}
			set
			{
				m_fitness = value;
			}
		}

		public int Size => m_genes.Length;

		public Genome()
		{
		}

		public Genome(double[] genes)
		{
			SetGenes(genes);
		}

		public Genome(Genome other)
		{
			m_genes = other.m_genes;
			m_fitness = 0f;
		}

		public void GenerateIndividual()
		{
			NeuralNet neuralNet = new NeuralNet(PlayerAIDavid.topology);
			m_genes = neuralNet.GetWeights().ToArray();
		}

		public void Mutate(float mutationRate)
		{
			for (int i = 0; i < m_genes.Length; i++)
			{
				if (UnityEngine.Random.value < mutationRate)
				{
					System.Random r = new System.Random();
					m_genes[i] += r.NextGaussianDouble();
				}
			}
		}

		public double GetGene(int index)
		{
			return m_genes[index];
		}

		public void SetGene(int index, double value)
		{
			m_genes[index] = value;
			m_fitness = 0f;
		}

		public void SetGenes(double[] genes)
		{
			m_genes = genes;
		}
	}
	public class Population
	{
		private List<Genome> m_genomes = new List<Genome>();

		public int Size => m_genomes.Count;

		public Population(int size)
			: this(size, init: true)
		{
		}

		public Population(int size, bool init)
		{
			for (int i = 0; i < size; i++)
			{
				m_genomes.Add(null);
			}
			if (init)
			{
				for (int j = 0; j < size; j++)
				{
					Genome genome = new Genome();
					genome.GenerateIndividual();
					m_genomes[j] = genome;
				}
			}
		}

		public Genome GetGenome(int index)
		{
			return m_genomes[index];
		}

		public Genome GetRandomGenome()
		{
			return m_genomes[UnityEngine.Random.Range(0, m_genomes.Count)];
		}

		public void SetGenome(int index, Genome g)
		{
			m_genomes[index] = g;
		}

		public Genome GetFittest()
		{
			Genome genome = m_genomes[0];
			for (int i = 1; i < m_genomes.Count; i++)
			{
				Genome genome2 = m_genomes[i];
				if (genome2.Fitness > genome.Fitness)
				{
					genome = genome2;
				}
			}
			return genome;
		}

		public void Sort()
		{
			m_genomes.OrderBy((Genome g) => g.Fitness);
		}
	}
	public class NeuralNet
	{
		private Neuron[][] m_layers;

		private double m_bonusWeight = UnityEngine.Random.Range(0.2f, 1f);

		public NeuralNet(int[] topology)
		{
			int num = topology.Length;
			m_layers = new Neuron[num][];
			for (int i = 0; i < num; i++)
			{
				bool num2 = i == num - 1;
				int num3 = topology[i];
				if (num2)
				{
					m_layers[i] = new Neuron[num3];
				}
				else
				{
					m_layers[i] = new Neuron[num3 + 1];
				}
				int numOutputs = ((!num2) ? topology[i + 1] : 0);
				if (i < num - 1)
				{
					m_layers[i][num3] = new Neuron(topology[i + 1], num3);
					m_layers[i][num3].OutputValue = 1.0;
				}
				for (int j = 0; j < num3; j++)
				{
					if (i == 0)
					{
						m_layers[i][j] = new Neuron(numOutputs, j);
					}
					else
					{
						m_layers[i][j] = new Neuron(numOutputs, j, m_layers[i - 1]);
					}
				}
			}
		}

		public void FeedForward(double[] inputValues, double bonusInput)
		{
			for (int i = 0; i < inputValues.Length; i++)
			{
				m_layers[0][i].OutputValue = inputValues[i];
			}
			for (int j = 1; j < m_layers.Length; j++)
			{
				int num = ((j == m_layers.Length - 1) ? m_layers[j].Length : (m_layers[j].Length - 1));
				for (int k = 0; k < num; k++)
				{
					if (j == m_layers.Length - 1)
					{
						m_layers[j][k].FeedForward(bonusInput * m_bonusWeight);
					}
					else
					{
						m_layers[j][k].FeedForward();
					}
				}
			}
		}

		public double[] GetResults()
		{
			double[] array = new double[m_layers[m_layers.Length - 1].Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = m_layers[m_layers.Length - 1][i].OutputValue;
			}
			return array;
		}

		public List<double> GetWeights()
		{
			List<double> list = new List<double>();
			for (int i = 0; i < m_layers.Length; i++)
			{
				bool flag = i == m_layers.Length - 1;
				for (int j = 0; j < m_layers[i].Length - ((!flag) ? 1 : 0); j++)
				{
					list.AddRange(m_layers[i][j].GetWeights());
				}
			}
			list.Add(m_bonusWeight);
			return list;
		}

		public void SetWeights(double[] weights)
		{
			SetWeights(new List<double>(weights));
		}

		public void SetWeights(List<double> weights)
		{
			int num = 0;
			for (int i = 0; i < m_layers.Length; i++)
			{
				bool flag = i == m_layers.Length - 1;
				int num2 = m_layers[i].Length - ((!flag) ? 1 : 0);
				for (int j = 0; j < num2; j++)
				{
					num += m_layers[i][j].SetWeights(weights, num);
				}
			}
			m_bonusWeight = weights[num];
		}
	}
	public class Neuron
	{
		private class Connection
		{
			public double m_weight;

			public double m_deltaWeight;
		}

		private static double _ETA = 0.15;

		private static double _ALPHA = 0.5;

		private double m_outputValue;

		private double m_gradient;

		private int m_index;

		private Dictionary<int, Connection> m_outputWeights = new Dictionary<int, Connection>();

		private Neuron[] m_prevLayer;

		public double OutputValue
		{
			get
			{
				return m_outputValue;
			}
			set
			{
				m_outputValue = value;
			}
		}

		public Neuron(int numOutputs, int index, Neuron[] prevLayer)
			: this(numOutputs, index)
		{
			m_prevLayer = prevLayer;
		}

		public Neuron(int numOutputs, int index)
		{
			m_index = index;
			for (int i = 0; i < numOutputs; i++)
			{
				Connection value = new Connection
				{
					m_weight = UnityEngine.Random.Range(-0.5f, 0.5f)
				};
				m_outputWeights.Add(i, value);
			}
		}

		public void FeedForward()
		{
			double prevLayerSum = GetPrevLayerSum();
			m_outputValue = TransferFunction(prevLayerSum);
		}

		public void FeedForward(double bonusInput)
		{
			double prevLayerSum = GetPrevLayerSum();
			prevLayerSum += bonusInput;
			m_outputValue = TransferFunction(prevLayerSum);
		}

		private double GetPrevLayerSum()
		{
			double num = 0.0;
			if (m_prevLayer != null)
			{
				for (int i = 0; i < m_prevLayer.Length; i++)
				{
					Neuron neuron = m_prevLayer[i];
					num += neuron.OutputValue * neuron.m_outputWeights[m_index].m_weight;
				}
			}
			return num;
		}

		public List<double> GetWeights()
		{
			List<double> list = new List<double>();
			List<int> list2 = new List<int>(m_outputWeights.Keys);
			list2.Sort();
			for (int i = 0; i < list2.Count; i++)
			{
				list.Add(m_outputWeights[list2[i]].m_weight);
			}
			return list;
		}

		public int SetWeights(List<double> weights, int offset)
		{
			List<int> list = new List<int>(m_outputWeights.Keys);
			list.Sort();
			for (int i = 0; i < list.Count; i++)
			{
				m_outputWeights[list[i]].m_weight = weights[offset + i];
			}
			return list.Count;
		}

		private static double TransferFunction(double x)
		{
			return Math.Tanh(x);
		}

		private static double TransferFunctionDerivative(double x)
		{
			return 1.0 - x * x;
		}
	}
